ALTER TABLE entitlement_sources ADD COLUMN IF NOT EXISTS connection_metadata JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE entitlement_sources ADD COLUMN IF NOT EXISTS credential_secret_ref_id TEXT;

