CREATE INDEX IF NOT EXISTS idx_inbound_webhooks_project_created
  ON inbound_webhooks(project_id, created_at DESC);
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'fk_github_reconciliation_signal_inbound'
  ) THEN
