END
$$;

CREATE TABLE IF NOT EXISTS feature_catalog (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  label TEXT,
  slug TEXT NOT NULL,
  title TEXT NOT NULL,
  doc_path TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'Planned',
  source TEXT,
  implementation_files JSONB NOT NULL DEFAULT '[]'::jsonb,
  test_coverage JSONB NOT NULL DEFAULT '[]'::jsonb,
  source_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  needs_label BOOLEAN NOT NULL DEFAULT false,
  last_documented_event_id TEXT,
  last_documented_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, label),
  UNIQUE(project_id, slug)
);
CREATE INDEX IF NOT EXISTS idx_feature_catalog_project_status
  ON feature_catalog(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS agent_threads (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  actor TEXT NOT NULL,
  surface TEXT NOT NULL DEFAULT 'chat',
  external_ref TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  pending_plan_id TEXT REFERENCES plans(id) ON DELETE SET NULL,
  pending_plan_summary JSONB,
  -- WHOSE CONVERSATION THIS IS. Asking the Program Manager and asking QA are two different
  -- conversations, and the thread key had no room to say so: a thread resolved on
  -- (project, surface, external_ref) alone, so switching role inside one handed the second
  -- agent the first one's history as though it were its own. '' means the general agent,
  -- which is what every thread predating this column was.
  agent_role TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- 'agent': a domain agent's turns on a record (AgentService.decide, BOSSAPP-759) — the
  -- on-call agent on an incident, the inbox on a decision. Never on the chat rail.
  CHECK (surface IN ('chat', 'github', 'agent')),
  CHECK (status IN ('active', 'closed'))
);
DO $$ BEGIN
  ALTER TABLE agent_threads DROP CONSTRAINT IF EXISTS agent_threads_surface_check;
  ALTER TABLE agent_threads ADD CONSTRAINT agent_threads_surface_check
    CHECK (surface IN ('chat', 'github', 'agent'));
END $$;
CREATE INDEX IF NOT EXISTS idx_agent_threads_project_actor
  ON agent_threads(project_id, actor, updated_at DESC);
-- A SHARED TASK THREAD IS SHARED PER AGENT. Two agents discussing one task each keep their
-- own thread on it; without agent_role here the second to speak would adopt the first's.
CREATE UNIQUE INDEX IF NOT EXISTS idx_agent_threads_surface_external
  ON agent_threads(project_id, surface, external_ref, agent_role)
  WHERE external_ref IS NOT NULL;

CREATE TABLE IF NOT EXISTS agent_messages (
  id TEXT PRIMARY KEY,
  thread_id TEXT NOT NULL REFERENCES agent_threads(id) ON DELETE CASCADE,
  -- "user" or "assistant" — the SPEAKER, not the agent. Which agent answered was recorded
  -- nowhere at all, so an existing thread could not even be sorted out after the fact.
  role TEXT NOT NULL,
  -- WHICH AGENT PRODUCED THIS. Attribution that survives the thread it was said in.
  agent_role TEXT NOT NULL DEFAULT '',
  content TEXT NOT NULL,
  tool_calls JSONB NOT NULL DEFAULT '[]'::jsonb,
  actions JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- OFFERS THE OPERATOR NEVER GOT BACK. `actions` holds writes that RAN; the buttons a turn
  -- put above the reply lived only in the HTTP response, so reopening a conversation showed
  -- the sentence "I've put two buttons above" over no buttons, with no way to reach what was
  -- offered. Stored per message so a restored thread is the thread, not a transcript of it.
  proposed_actions JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (role IN ('user', 'assistant', 'tool'))
);
CREATE INDEX IF NOT EXISTS idx_agent_messages_thread_created
  ON agent_messages(thread_id, created_at, id);

-- WHAT THE OPERATOR BROUGHT WITH THEM: a screenshot of the error, a log too long to paste.
--
-- Deliberately a table and not the message body. An image is hundreds of kilobytes of base64
-- and the body is read on every thread load, rendered in the transcript, and re-sent as history
-- on every turn — inlining one would make all three worse forever. Here it is fetched only when
-- a turn actually needs it, and `ON DELETE CASCADE` means clearing a chat takes its files too.
CREATE TABLE IF NOT EXISTS agent_attachments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  thread_id TEXT NOT NULL REFERENCES agent_threads(id) ON DELETE CASCADE,
  message_id TEXT REFERENCES agent_messages(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  media_type TEXT NOT NULL,
  kind TEXT NOT NULL,                        -- image | text
  -- base64 for an image, the file's own text for a text file.
  data TEXT NOT NULL,
  bytes INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind IN ('image', 'text'))
);
CREATE INDEX IF NOT EXISTS idx_agent_attachments_message
  ON agent_attachments(message_id);
CREATE INDEX IF NOT EXISTS idx_agent_attachments_thread
  ON agent_attachments(thread_id, created_at DESC);

-- Metatron Captain: goals, durable memory, watch ticks (always-on oversight).
-- Chat persistence reuses agent_threads (surface=chat, external_ref=metatron:captain).
CREATE TABLE IF NOT EXISTS metatron_goals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  kind TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  target JSONB NOT NULL DEFAULT '{}'::jsonb,
  last_score NUMERIC,
  last_measured_at TIMESTAMPTZ,
  last_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  auto_drive BOOLEAN NOT NULL DEFAULT false,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind IN ('working_software', 'budget', 'queue', 'quality', 'custom')),
  CHECK (status IN ('active', 'paused', 'achieved', 'failed'))
);
CREATE INDEX IF NOT EXISTS idx_metatron_goals_project
  ON metatron_goals(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS metatron_memories (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  thread_id TEXT,
  kind TEXT NOT NULL DEFAULT 'fact',
  content TEXT NOT NULL,
  salience NUMERIC NOT NULL DEFAULT 0.5,
  source TEXT NOT NULL DEFAULT 'chat',
  refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind IN ('fact', 'decision', 'lesson', 'goal_note', 'watch')),
  CHECK (salience >= 0 AND salience <= 1)
);
CREATE INDEX IF NOT EXISTS idx_metatron_memories_project
  ON metatron_memories(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS metatron_watch_ticks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  observed JSONB NOT NULL DEFAULT '{}'::jsonb,
  findings JSONB NOT NULL DEFAULT '[]'::jsonb,
  proposed_moves JSONB NOT NULL DEFAULT '[]'::jsonb,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  cycle TEXT NOT NULL DEFAULT 'watch',
  verify JSONB NOT NULL DEFAULT '{}'::jsonb,
  applied JSONB NOT NULL DEFAULT '[]'::jsonb
);
CREATE INDEX IF NOT EXISTS idx_metatron_watch_project
  ON metatron_watch_ticks(project_id, created_at DESC);

-- Focused always-on agents (thin builder + duty loop; Studio stays the full registry).
CREATE TABLE IF NOT EXISTS focused_agents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_key TEXT NOT NULL,
  name TEXT NOT NULL,
  focus TEXT NOT NULL,
  kind TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft',
  mode TEXT NOT NULL DEFAULT 'hybrid',
  interval_seconds INTEGER NOT NULL DEFAULT 120,
  wake_on JSONB NOT NULL DEFAULT '[]'::jsonb,
  allowed_actions JSONB NOT NULL DEFAULT '[]'::jsonb,
  last_tick_at TIMESTAMPTZ,
  last_wake_at TIMESTAMPTZ,
  last_status TEXT,
  last_score NUMERIC,
  last_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, agent_key)
);
CREATE INDEX IF NOT EXISTS idx_focused_agents_project
  ON focused_agents(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS focused_agent_ticks (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL REFERENCES focused_agents(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  trigger TEXT NOT NULL,
  observed JSONB NOT NULL DEFAULT '{}'::jsonb,
  planned JSONB NOT NULL DEFAULT '[]'::jsonb,
  validation JSONB NOT NULL DEFAULT '{}'::jsonb,
  applied JSONB NOT NULL DEFAULT '[]'::jsonb,
  rejected JSONB NOT NULL DEFAULT '[]'::jsonb,
  verify JSONB NOT NULL DEFAULT '{}'::jsonb,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_focused_agent_ticks_agent
  ON focused_agent_ticks(agent_id, created_at DESC);

CREATE TABLE IF NOT EXISTS agent_process_templates (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  process_key TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  spec JSONB NOT NULL,
  status TEXT NOT NULL DEFAULT 'active',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, process_key)
);
CREATE INDEX IF NOT EXISTS idx_agent_process_templates_project
  ON agent_process_templates(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS agent_process_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  template_id TEXT NOT NULL REFERENCES agent_process_templates(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  actor TEXT NOT NULL,
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  context JSONB NOT NULL DEFAULT '{}'::jsonb,
  current_steps JSONB NOT NULL DEFAULT '[]'::jsonb,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_process_runs_project
  ON agent_process_runs(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS agent_process_steps (
  id TEXT PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES agent_process_runs(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  step_key TEXT NOT NULL,
  role_key TEXT NOT NULL,
  action TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending',
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  handoff_from TEXT,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_process_steps_run
  ON agent_process_steps(run_id, created_at);

-- A step a CUSTOMER defined, bound to something they already have: one of their skills, a
-- tool on one of their MCP servers, or an integration connection.
--
-- The eighteen built-in capabilities cover how software gets delivered; this is for the work
-- that is specific to one company — "file it in our tracker", "tell the compliance system",
-- "run our own scanner".
--
-- RISK IS NOT A FIELD A CUSTOMER FILLS IN. It is resolved from whatever the step is bound to,
-- every time the step is validated and every time it runs. A self-declared risk tier would be
-- the documented way around the approval floor: name your step "harmless", bind it to a tool
-- that deletes production, and the gate never fires.
CREATE TABLE IF NOT EXISTS mcp_servers (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  transport TEXT NOT NULL DEFAULT 'http',
  risk_tier INTEGER NOT NULL DEFAULT 1,
  data_boundary TEXT NOT NULL DEFAULT 'internal',
  enabled BOOLEAN NOT NULL DEFAULT true,
  description TEXT,
  publisher JSONB NOT NULL DEFAULT '{}'::jsonb,
  provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
  tool_risk_overrides JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- WHAT THE LAST PROBE FOUND. NULL reachable = never checked, which is not the same as down.
  -- The seeded servers point at 127.0.0.1 ports the community compose never starts, and every
  -- screen called them enabled and healthy; these columns are how a screen can say otherwise.
  reachable BOOLEAN,
  last_checked_at TIMESTAMPTZ,
  last_error TEXT,
  -- [{name, description, inputSchema}] from the last successful tools/list. Kept across a failed
  -- probe so an operator fixing a server can still see what it offered.
  tools JSONB NOT NULL DEFAULT '[]'::jsonb
);
CREATE INDEX IF NOT EXISTS idx_mcp_servers_project ON mcp_servers(project_id, enabled);
-- ONE NAME, ONE SERVER. The agent loop namespaces tools by the server's NAME, so a second
-- server with the same name silently replaced the first's tools; a double-pressed Register was
-- enough to cause it. Existing duplicates are renamed (the oldest keeps the name) so the
-- index below can be created on installs that already have them.
UPDATE mcp_servers m SET name = m.name || ' (' || m.id || ')'
WHERE EXISTS (
  SELECT 1 FROM mcp_servers o
  WHERE o.project_id = m.project_id AND lower(o.name) = lower(m.name)
    AND (o.created_at, o.id) < (m.created_at, m.id)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_mcp_servers_project_name
  ON mcp_servers (project_id, lower(name));

-- HOW BOSS SIGNS IN TO A SERVER (skills-mcp spec E2): {type: none|bearer|header, header_name?,
-- secret_ref_id?, last4?, headers?}. The token itself is written through to the secret store and
-- only its reference is kept here; mcp_registry resolves it to a header at call time and never
-- puts it in a list response. Every hosted MCP server (GitHub, Linear, Sentry, Context7 with a
-- key) needs one, and before this column BOSS had nowhere to keep it.
ALTER TABLE mcp_servers ADD COLUMN IF NOT EXISTS auth JSONB NOT NULL DEFAULT '{}'::jsonb;
-- ALLOW / ASK / OFF PER TOOL (spec E7): {tool_name: allow|ask|off} as the operator chose. The
-- runtime applies the floor (tier >= 2 always asks) and the defaults for tools not listed.
ALTER TABLE mcp_servers ADD COLUMN IF NOT EXISTS tool_policy JSONB NOT NULL DEFAULT '{}'::jsonb;

-- EVERY KIT TEST, KEPT (spec §6.4). An ability's status is "ready" only on a passing test within
-- freshness; the console shows the last one ("Tested 2m ago · 12 tools") and its error.
CREATE TABLE IF NOT EXISTS kit_tests (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  ability TEXT NOT NULL,
  ok BOOLEAN NOT NULL,
  latency_ms INTEGER NOT NULL DEFAULT 0,
  fact TEXT,
  error TEXT,
  field TEXT,
  actor TEXT NOT NULL DEFAULT 'system',
  at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kit_tests_latest ON kit_tests(project_id, ability, at DESC);

CREATE TABLE IF NOT EXISTS workflow_custom_steps (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  step_key TEXT NOT NULL,
  label TEXT NOT NULL,
  summary TEXT,
  -- Two kinds, because two things are independently callable. An integration is deliberately
  -- NOT a third: in BOSS an integration connection grants authority to a skill, it is not
  -- something you can invoke on its own. To use one, bind the skill that runs through it.
  binding_kind TEXT NOT NULL
    CHECK (binding_kind IN ('skill', 'mcp_tool')),
  -- Set per binding_kind. Checked in the service rather than by a constraint so the error an
  -- operator sees is a sentence rather than a violated check name.
  skill_id TEXT,
  mcp_server_id TEXT REFERENCES mcp_servers(id) ON DELETE SET NULL,
  mcp_tool_name TEXT,
  -- [{name, required, description}] — what the step asks for on the canvas.
  inputs JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- Names a later step can read out of this one.
  produces JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- WHAT THIS STEP KNOWS.
  --
  -- A binding says which skill or tool runs; it says nothing about the standard the step is
  -- meant to hold to — the ticket format your team uses, the compliance clauses that matter,
  -- the internal doc that explains the system it is touching. That knowledge lived in the head
  -- of whoever defined the step, so the step ran the tool and got the house style wrong.
  -- Carried into every execution as context, so the step behaves the same on its hundredth run
  -- as on the one where somebody was watching.
  knowledge TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, step_key)
);
CREATE INDEX IF NOT EXISTS idx_workflow_custom_steps_project
  ON workflow_custom_steps(project_id, enabled, label);

-- A SKILL AS A THING YOU CAN AUTHOR, not only an id you can enable.
--
-- `project_skills` says a project MAY use skill X; it never said what X does. Behaviour lived
-- in a registered Python executor, so every new capability a customer wanted was a pull request
-- against BOSS. That is the wrong boundary for the thing most worth customising: the operator
-- knows their house rules, their tools and their accounts, and BOSS does not.
--
-- Three behaviours, deliberately. `builtin` keeps every executor that already exists working
-- unchanged. `mcp_tool` covers anything reachable over a protocol BOSS already speaks.
-- `sandboxed_command` is the one that makes ffmpeg, pandoc, ImageMagick and a hundred others
-- authorable without writing Python — and the one that needs real isolation, which is why it
-- refuses to run without it rather than falling back to the API host.
CREATE TABLE IF NOT EXISTS skill_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  skill_key TEXT NOT NULL,
  label TEXT NOT NULL,
  summary TEXT NOT NULL DEFAULT '',
  behaviour_kind TEXT NOT NULL
    CHECK (behaviour_kind IN ('builtin', 'mcp_tool', 'sandboxed_command', 'agent_program',
                              'guide')),
  -- WHAT THIS SKILL KNOWS. The markdown body an operator writes: the house style, the format
  -- their team uses, the clauses that matter. Carried into every execution as context, so the
  -- skill behaves the same on its hundredth run as on the one somebody watched.
  knowledge TEXT NOT NULL DEFAULT '',
  -- [{name, required, description}] — what the skill asks for.
  inputs JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- Names a later step can read out of it.
  produces JSONB NOT NULL DEFAULT '[]'::jsonb,
  -- Per-behaviour settings: {image, command, timeout_seconds, network, outputs} for a
  -- sandboxed command; {mcp_server_id, tool_name} for an MCP tool; {executor_id} for a builtin.
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- 0 reads, 1 spends or writes something recoverable, 2+ changes the world irreversibly. Feeds
  -- the SAME forced-approval floor every capability obeys, so a publish cannot be set to auto.
  risk_tier INTEGER NOT NULL DEFAULT 1,
  -- Reviewed by a person who could judge it. `validate_custom_step` already refuses an
  -- untrusted skill at or above the approval floor, and this is the flag it reads.
  trusted BOOLEAN NOT NULL DEFAULT false,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, skill_key)
);

-- A FOURTH BEHAVIOUR: a program an AGENT wrote and a workflow kept.
--
-- The other three are authored by a person. This one is written by an agent mid-run, saved when
-- it worked, and offered back to the agent on the next run of the same workflow — so a customer's
-- second video project reuses the program the first one produced instead of paying a model to
-- rediscover it. The source lives in `config`, which is why this needed a constraint widened and
-- not a table added.
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'skill_definitions_behaviour_kind_check'
      AND pg_get_constraintdef(oid) NOT LIKE '%agent_program%'
  ) THEN
    ALTER TABLE skill_definitions DROP CONSTRAINT skill_definitions_behaviour_kind_check;
    ALTER TABLE skill_definitions
      ADD CONSTRAINT skill_definitions_behaviour_kind_check
      CHECK (behaviour_kind IN ('builtin', 'mcp_tool', 'sandboxed_command', 'agent_program'));
  END IF;
END $$;

-- A FIFTH BEHAVIOUR: a GUIDE (agent-loadout spec §4.6). A SKILL.md playbook an operator
-- uploads: it runs nothing, reaches nothing and is read by the agent only when it calls it.
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'skill_definitions_behaviour_kind_check'
      AND pg_get_constraintdef(oid) NOT LIKE '%guide%'
  ) THEN
    ALTER TABLE skill_definitions DROP CONSTRAINT skill_definitions_behaviour_kind_check;
    ALTER TABLE skill_definitions
      ADD CONSTRAINT skill_definitions_behaviour_kind_check
      CHECK (behaviour_kind IN ('builtin', 'mcp_tool', 'sandboxed_command', 'agent_program',
                                'guide'));
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_skill_definitions_project
  ON skill_definitions(project_id, enabled, skill_key);

CREATE TABLE IF NOT EXISTS project_skills (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  skill_id TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'tenant',
  enabled BOOLEAN NOT NULL DEFAULT true,
  on_demand BOOLEAN NOT NULL DEFAULT false,
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  publisher JSONB NOT NULL DEFAULT '{}'::jsonb,
  provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, skill_id),
  CHECK (source IN ('system', 'tenant', 'module'))
);
CREATE INDEX IF NOT EXISTS idx_project_skills_project
  ON project_skills(project_id, enabled, on_demand);

-- WHICH AGENT HOLDS WHICH SKILL.
--
-- A skill is one reusable unit of doing, and it attaches at two ends: a workflow step runs it
-- (workflow_custom_steps.skill_id) and an agent holds it. The step end already existed; this is
-- the agent end, and the two are independent — the same skill can be given to an agent, placed
-- in a step, both, or neither. An agent that holds a skill can use it in its own work without a
-- workflow being involved, which is the whole point of an admin-style agent that owns, say, a
-- YouTube account.
--
-- `skill_id` deliberately carries no foreign key: it names EITHER a project-authored skill
-- (skill_definitions.skill_key) OR one of the skills that ship with BOSS (project_skills.
-- skill_id, e.g. 'github.create_pr_real'), and those live in different tables. `source` records
-- which, so a reader does not have to guess from the shape of the key.
CREATE TABLE IF NOT EXISTS role_skills (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  role_key TEXT NOT NULL,
  skill_id TEXT NOT NULL,
  source TEXT NOT NULL DEFAULT 'authored',
  assigned_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, role_key, skill_id),
  CHECK (source IN ('authored', 'builtin'))
);
CREATE INDEX IF NOT EXISTS idx_role_skills_role
  ON role_skills(project_id, role_key);
CREATE INDEX IF NOT EXISTS idx_role_skills_skill
  ON role_skills(project_id, skill_id);

-- AN AGENT HOLDS MCP SERVERS THE WAY IT HOLDS SKILLS.
--
-- There was no way to give an agent an MCP server at all: no table, no API, no picker. The
-- wizard's "integrations" field was free text nothing enforced, and a bounded agent step was
-- handed no MCP tool whatever anyone had registered. So "this agent posts to our Mattermost" had
-- no answer short of authoring a skill per tool. This is the grant, cashed in by agent_loop: a
-- bounded run is offered exactly the tools of the servers its agent holds, filtered by `tools`
-- when that list is non-empty (empty = every tool the server offers). The server's own risk tier
-- and per-tool overrides still decide whether a call waits for a person.
CREATE TABLE IF NOT EXISTS role_mcp_servers (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  role_key TEXT NOT NULL,
  mcp_server_id TEXT NOT NULL REFERENCES mcp_servers(id) ON DELETE CASCADE,
  tools JSONB NOT NULL DEFAULT '[]'::jsonb,
  assigned_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, role_key, mcp_server_id)
);
CREATE INDEX IF NOT EXISTS idx_role_mcp_servers_role
  ON role_mcp_servers(project_id, role_key);

-- WHAT AN OPERATOR TOOK AWAY, so a seed does not give it back. Every install and upgrade
-- re-ran a converging seed that re-granted unassigned skills, re-registered deleted MCP servers
-- and rewrote edited role specs (boss-1: 48 assignment events for 16 grants). The seed is
-- additive only; see engine/boss_engine/services/seed_exclusions.py for the kinds.
CREATE TABLE IF NOT EXISTS seed_exclusions (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  subject TEXT NOT NULL,
  excluded_by TEXT NOT NULL DEFAULT 'system',
  reason TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, kind, subject),
  CHECK (kind IN ('role_skill', 'mcp_server', 'role', 'role_spec'))
);

-- Model-agnostic agent toolchain intake. Third-party prompts, hooks, MCP
-- configuration, commands, and scripts are untrusted supply-chain inputs.
-- BOSS records immutable provenance and scan evidence but never stores or
-- executes raw imported source from this registry.
CREATE TABLE IF NOT EXISTS toolchain_sources (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  source_key TEXT NOT NULL,
  display_name TEXT NOT NULL,
  repository_url TEXT NOT NULL,
  pinned_revision TEXT NOT NULL,
  license_id TEXT NOT NULL,
  license_status TEXT NOT NULL
    CHECK (license_status IN ('allowed', 'mixed', 'missing', 'restricted')),
  integration_mode TEXT NOT NULL
    CHECK (integration_mode IN (
      'pattern_only', 'selective_import', 'catalog_only', 'blocked'
    )),
  status TEXT NOT NULL DEFAULT 'declared'
    CHECK (status IN ('declared', 'active', 'quarantined', 'blocked')),
  capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,
  adopted_components JSONB NOT NULL DEFAULT '[]'::jsonb,
  provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT 'bootstrap',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, source_key)
);
CREATE INDEX IF NOT EXISTS idx_toolchain_sources_project
  ON toolchain_sources(project_id, status, source_key);

CREATE TABLE IF NOT EXISTS toolchain_import_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL REFERENCES toolchain_sources(id) ON DELETE CASCADE,
  revision TEXT NOT NULL,
  snapshot_hash TEXT NOT NULL,
  status TEXT NOT NULL
    CHECK (status IN ('approved', 'review_required', 'quarantined', 'rejected')),
  file_count INTEGER NOT NULL CHECK (file_count >= 0),
  total_bytes BIGINT NOT NULL CHECK (total_bytes >= 0),
  inventory JSONB NOT NULL DEFAULT '{}'::jsonb,
  findings JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reviewed_by TEXT,
  reviewed_at TIMESTAMPTZ,
  review_note TEXT,
  UNIQUE(project_id, source_id, snapshot_hash)
);
CREATE INDEX IF NOT EXISTS idx_toolchain_import_runs_project
  ON toolchain_import_runs(project_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS toolchain_candidates (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  import_run_id TEXT NOT NULL REFERENCES toolchain_import_runs(id) ON DELETE CASCADE,
  source_path TEXT NOT NULL,
  candidate_kind TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  status TEXT NOT NULL
    CHECK (status IN (
      'metadata_only', 'review_required', 'quarantined', 'approved', 'rejected'
    )),
  risk_tier INTEGER NOT NULL DEFAULT 0 CHECK (risk_tier BETWEEN 0 AND 3),
  findings JSONB NOT NULL DEFAULT '[]'::jsonb,
  normalized_spec JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  reviewed_by TEXT,
  reviewed_at TIMESTAMPTZ,
  review_note TEXT,
  UNIQUE(import_run_id, source_path)
);
CREATE INDEX IF NOT EXISTS idx_toolchain_candidates_project
  ON toolchain_candidates(project_id, status, risk_tier, created_at DESC);

CREATE TABLE IF NOT EXISTS agent_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_id TEXT,
  status TEXT NOT NULL DEFAULT 'running',
  messages JSONB NOT NULL DEFAULT '[]'::jsonb,
  transcript JSONB NOT NULL DEFAULT '[]'::jsonb,
  usage JSONB NOT NULL DEFAULT '{}'::jsonb,
  step INTEGER NOT NULL DEFAULT 0,
  pending JSONB,
  finalize_ctx JSONB,
  output_text TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_runs_project ON agent_runs(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS meeting_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_id TEXT,
  status TEXT NOT NULL DEFAULT 'running',     -- running | completed | failed
  phase TEXT NOT NULL DEFAULT 'research',      -- research|round1|round2|synthesis|draft|finalize|done
  directive TEXT NOT NULL,
  url TEXT,
  role_keys JSONB NOT NULL DEFAULT '[]'::jsonb,
  constraints JSONB NOT NULL DEFAULT '{}'::jsonb,
  state JSONB NOT NULL DEFAULT '{}'::jsonb,     -- {research, round1, round2, synthesis, prd_markdown}
  usage JSONB NOT NULL DEFAULT '{}'::jsonb,     -- {cost_usd_micros, model}
  finalize_ctx JSONB NOT NULL DEFAULT '{}'::jsonb,
  meeting_id TEXT,
  minutes_artifact_id TEXT,
  decision_id TEXT,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_meeting_runs_project ON meeting_runs(project_id, status, updated_at DESC);
-- What the meeting is called, kept apart from the directive: workflow framing prepended to the
-- directive became every meeting's title on boss-1 ('PRD meeting: --- WHAT THIS PANEL IS FOR ---').
ALTER TABLE meeting_runs ADD COLUMN IF NOT EXISTS title TEXT;

-- ARCHITECTURE APPROVAL (workflow capability `architecture`, services/architecture_docs.py).
-- An architect agent turns the run's APPROVED PRD into an architecture document; each version
-- is an `architecture_document` artifact, and a person approves, sends back with a note (the
-- architect writes the next version) or rejects it. The workflow step waits on this row.
CREATE TABLE IF NOT EXISTS architecture_reviews (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  workflow_run_id TEXT NOT NULL,
  step_id TEXT NOT NULL,
  -- drafting | awaiting_approval | revision_requested | approved | rejected | cancelled | failed
  status TEXT NOT NULL DEFAULT 'drafting',
  architect TEXT NOT NULL DEFAULT 'chief_architect',
  title TEXT,
  prd_source JSONB NOT NULL DEFAULT '{}'::jsonb,   -- where the approved PRD came from, who approved it
  current_version INTEGER NOT NULL DEFAULT 0,
  current_artifact_id TEXT,
  decision_id TEXT,
  notes JSONB NOT NULL DEFAULT '[]'::jsonb,        -- [{version, note, by, at}] changes a person asked for
  approved_by TEXT,
  approved_at TIMESTAMPTZ,
  approved_version INTEGER,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_architecture_reviews_run ON architecture_reviews(workflow_run_id, step_id);
CREATE INDEX IF NOT EXISTS idx_architecture_reviews_project ON architecture_reviews(project_id, status, updated_at DESC);

-- Durable coding-agent task: clone -> edit -> build/test -> open PR (gated).
-- Unlike meeting_runs (pure-data phases), a code task's working tree is
-- filesystem-ephemeral, so the whole pipeline runs in ONE job execution;
-- crash-resumability comes from job lease-reclaim + the PR receipt dedupe
-- (no double-open). The row tracks status/phase for observability + idempotency.
CREATE TABLE IF NOT EXISTS code_task_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_id TEXT,
  status TEXT NOT NULL DEFAULT 'running',     -- running | completed | failed | blocked
  phase TEXT NOT NULL DEFAULT 'queued',       -- queued|provisioning|coding|validating|opening_pr|done
  title TEXT NOT NULL,
  spec JSONB NOT NULL DEFAULT '{}'::jsonb,     -- {instructions, acceptance_criteria, test_commands, owner, repo, base_branch}
  state JSONB NOT NULL DEFAULT '{}'::jsonb,    -- {summary, diff_summary, tests, tests_passed, turns}
  usage JSONB NOT NULL DEFAULT '{}'::jsonb,    -- {cost_usd_micros, model}
  finalize_ctx JSONB NOT NULL DEFAULT '{}'::jsonb,
  reservation_id TEXT,
  pull_request_url TEXT,
  pull_request_number INTEGER,
  decision_id TEXT,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_code_task_runs_project ON code_task_runs(project_id, status, updated_at DESC);

-- Append-only human usefulness reviews of a recorded delivery. No execution authority.
CREATE TABLE IF NOT EXISTS deliverable_reviews (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  run_id TEXT NOT NULL REFERENCES code_task_runs(id) ON DELETE CASCADE,
  actor TEXT NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('accepted', 'changes_requested')),
  note TEXT NOT NULL DEFAULT '',
  snapshot_hash TEXT NOT NULL,
  snapshot JSONB NOT NULL,
  submission_id TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, run_id, submission_id)
);
CREATE INDEX IF NOT EXISTS idx_deliverable_reviews_run ON deliverable_reviews(project_id, run_id, created_at DESC);

-- Durable, versioned measurements derived from terminal QA benchmark runs.  These are
-- analysis snapshots only: a low score may trigger a visible recommendation, but cannot
-- alter a routing/workflow baseline or create an applied change by itself.
CREATE TABLE IF NOT EXISTS qa_benchmark_evaluations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  code_task_run_id TEXT NOT NULL REFERENCES code_task_runs(id) ON DELETE CASCADE,
  benchmark_id TEXT NOT NULL,
  scorecard_version TEXT NOT NULL,
  status TEXT NOT NULL, -- ready_for_candidate | not_ready
  overall_score DOUBLE PRECISION,
  observed_weight INTEGER NOT NULL DEFAULT 0,
  report JSONB NOT NULL DEFAULT '{}'::jsonb,
  recommendation JSONB NOT NULL DEFAULT '{}'::jsonb,
  source_hash TEXT NOT NULL,
  evaluated_by TEXT NOT NULL DEFAULT 'qa_benchmark_scheduler',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(code_task_run_id, scorecard_version)
);
CREATE INDEX IF NOT EXISTS idx_qa_benchmark_evaluations_project_created
  ON qa_benchmark_evaluations(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_qa_benchmark_evaluations_benchmark_status
  ON qa_benchmark_evaluations(project_id, benchmark_id, status, updated_at DESC);

-- Governed autonomous-improvement programs pin a known-good measurement contract.
-- Programs and trials are evidence/control records only: a winning trial may create a
-- normal self-improvement proposal, but it cannot apply its candidate or move a baseline.
CREATE TABLE IF NOT EXISTS improvement_programs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  objective TEXT NOT NULL,
  benchmark_id TEXT NOT NULL,
  baseline_evaluation_id TEXT NOT NULL REFERENCES qa_benchmark_evaluations(id),
  metric_contract JSONB NOT NULL DEFAULT '{}'::jsonb,
  metric_contract_hash TEXT NOT NULL,
  minimum_evidence_weight INTEGER NOT NULL DEFAULT 50 CHECK (minimum_evidence_weight BETWEEN 1 AND 100),
  minimum_overall_delta DOUBLE PRECISION NOT NULL DEFAULT 1,
  maximum_dimension_regression DOUBLE PRECISION NOT NULL DEFAULT 0,
  hard_gates JSONB NOT NULL DEFAULT '{"functionality": 100}'::jsonb,
  status TEXT NOT NULL DEFAULT 'active', -- active | paused | retired
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_improvement_programs_project_status
  ON improvement_programs(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS improvement_trials (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  program_id TEXT NOT NULL REFERENCES improvement_programs(id) ON DELETE CASCADE,
  control_evaluation_id TEXT NOT NULL REFERENCES qa_benchmark_evaluations(id),
  candidate_evaluation_id TEXT NOT NULL REFERENCES qa_benchmark_evaluations(id),
  candidate_change_ref TEXT NOT NULL,
  candidate_diff_summary TEXT NOT NULL,
  changed_variable TEXT NOT NULL,
  control_configuration JSONB NOT NULL DEFAULT '{}'::jsonb,
  candidate_configuration JSONB NOT NULL DEFAULT '{}'::jsonb,
  isolation_evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  status TEXT NOT NULL, -- candidate_wins | rejected | inconclusive | proposed | adopted | superseded
  verdict JSONB NOT NULL DEFAULT '{}'::jsonb,
  verdict_hash TEXT NOT NULL,
  proposal_id TEXT REFERENCES self_improvement_proposals(id),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (control_evaluation_id <> candidate_evaluation_id),
  UNIQUE(program_id, candidate_evaluation_id, candidate_change_ref)
);
CREATE INDEX IF NOT EXISTS idx_improvement_trials_program_status
  ON improvement_trials(program_id, status, updated_at DESC);

-- Fail-closed quality evidence for a governed coding-pipeline run (see QualityGate ObjectSpec).
CREATE TABLE IF NOT EXISTS quality_gates (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_id TEXT,
  code_task_run_id TEXT,
  risk_tier INTEGER NOT NULL DEFAULT 2,
  test_author_independent BOOLEAN NOT NULL DEFAULT false,
  reviewer_independent BOOLEAN NOT NULL DEFAULT false,
  tests_passed BOOLEAN NOT NULL DEFAULT false,
  adversarial_verdict TEXT NOT NULL DEFAULT 'not_run',  -- survived | refuted | not_run
  status TEXT NOT NULL DEFAULT 'fail',                  -- pass | fail | waived
  fail_closed BOOLEAN NOT NULL DEFAULT true,
  gates_passed JSONB NOT NULL DEFAULT '[]'::jsonb,
  gates_failed JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by_job_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_quality_gates_run ON quality_gates(code_task_run_id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_quality_gates_run ON quality_gates(project_id, code_task_run_id);
-- Phase 3 (factory scale-up): explicit lint + CI-green gates, second-model cross-check, a numeric
-- merge-confidence score, and a stored review packet artifact.
ALTER TABLE quality_gates ADD COLUMN IF NOT EXISTS lint_passed BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE quality_gates ADD COLUMN IF NOT EXISTS ci_green BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE quality_gates ADD COLUMN IF NOT EXISTS cross_check_agreement BOOLEAN;
ALTER TABLE quality_gates ADD COLUMN IF NOT EXISTS confidence DOUBLE PRECISION NOT NULL DEFAULT 0;
ALTER TABLE quality_gates ADD COLUMN IF NOT EXISTS review_packet_artifact_id TEXT;

-- Custom pipeline cost/rigor profiles per project (presets live in code; these are overrides
-- and customer-defined profiles). is_default marks the project's chosen profile.
CREATE TABLE IF NOT EXISTS pipeline_profiles (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  label TEXT,
  tier_floor INTEGER NOT NULL DEFAULT 0,
  tier_cap INTEGER NOT NULL DEFAULT 3,
  model_routing JSONB NOT NULL DEFAULT '{}'::jsonb,
  caching BOOLEAN NOT NULL DEFAULT true,
  parallel_checks BOOLEAN NOT NULL DEFAULT true,
  is_default BOOLEAN NOT NULL DEFAULT false,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_pipeline_profiles_name ON pipeline_profiles(project_id, name);

CREATE TABLE IF NOT EXISTS meeting_roles (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  role_key TEXT NOT NULL,
  title TEXT NOT NULL,
  lens TEXT NOT NULL,
  risk_tier INTEGER NOT NULL DEFAULT 1,
  data_boundary TEXT NOT NULL DEFAULT 'internal',
  is_default BOOLEAN NOT NULL DEFAULT false,
  enabled BOOLEAN NOT NULL DEFAULT true,
  sort_order INTEGER NOT NULL DEFAULT 100,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, role_key)
);

CREATE TABLE IF NOT EXISTS canary_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  status TEXT NOT NULL,            -- pass | fail
  results JSONB NOT NULL,          -- per-canary {canary, status, detail}
  passed INTEGER NOT NULL,
  failed INTEGER NOT NULL,
  skipped INTEGER NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_canary_runs_project ON canary_runs (project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS policy_eval_log (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  boundary TEXT NOT NULL,        -- budget.reserve | comms.delivery | data_boundary | approval | ...
  action TEXT,                   -- what was being attempted
  decision TEXT NOT NULL,        -- allow | deny | defer
  reason TEXT,
  detail JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_policy_eval_log_project ON policy_eval_log (project_id, created_at DESC);

-- Phase 2: eval-harness regression suites (routing/policy/factory/autonomy quality). Run on demand
-- or nightly; results gate self-improvement rollouts. Mirrors canary_runs but carries a suite label.
CREATE TABLE IF NOT EXISTS eval_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  suite TEXT NOT NULL,             -- regression suite name (e.g. 'all', 'routing', 'policy')
  status TEXT NOT NULL,            -- pass | fail
  results JSONB NOT NULL,          -- per-eval {eval, status, detail, metrics}
  passed INTEGER NOT NULL,
  failed INTEGER NOT NULL,
  skipped INTEGER NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_eval_runs_project ON eval_runs (project_id, created_at DESC);

-- Phase 2: staged rollout state for the self-improvement runtime (stages, current index, history,
-- auto-rollback thresholds). Empty {} until a staged rollout begins.
ALTER TABLE self_improvement_proposals
  ADD COLUMN IF NOT EXISTS rollout_state JSONB NOT NULL DEFAULT '{}'::jsonb;

-- Phase 2: skill-invocation framework records. Every invocation through the runtime (mock or real)
-- records the permission decision, cost estimate, retry attempts, and outcome. Mock mode runs the
-- full governance gauntlet with no real side effects (used by canaries).
CREATE TABLE IF NOT EXISTS skill_invocations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  created_by_job_id TEXT REFERENCES jobs(id),
  skill_id TEXT NOT NULL,
  caller TEXT NOT NULL,
  mode TEXT NOT NULL,                       -- mock | real
  status TEXT NOT NULL,                     -- succeeded | denied | failed
  permission_decision TEXT NOT NULL,        -- allow | deny
  attempts INTEGER NOT NULL DEFAULT 0,
  max_attempts INTEGER NOT NULL DEFAULT 1,
  cost_estimate_usd_micros BIGINT NOT NULL DEFAULT 0,
  actual_cost_usd_micros BIGINT,
  cost_receipt_id TEXT REFERENCES cost_receipts(id),
  reservation_id TEXT,
  reason TEXT,
  result JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE skill_invocations
  ADD COLUMN IF NOT EXISTS actual_cost_usd_micros BIGINT;
ALTER TABLE skill_invocations
  ADD COLUMN IF NOT EXISTS cost_receipt_id TEXT REFERENCES cost_receipts(id);
ALTER TABLE skill_invocations
  ADD COLUMN IF NOT EXISTS created_by_job_id TEXT REFERENCES jobs(id);
CREATE INDEX IF NOT EXISTS idx_skill_invocations_project
  ON skill_invocations (project_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_skill_invocations_real_job
  ON skill_invocations(created_by_job_id)
  WHERE created_by_job_id IS NOT NULL AND mode = 'real';

-- Phase 3 (comms robustness): inbound acknowledgment ledger — one row per inbox message, advanced
-- through received → parsed → routed → (actioned | deadlettered | acknowledged). The durable proof
-- of "no silent drops": every inbound reaches a terminal ack state, with the full transition history.
CREATE TABLE IF NOT EXISTS ack_state (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id),
  inbox_message_id TEXT NOT NULL,
  channel TEXT NOT NULL,
  state TEXT NOT NULL,             -- received | parsed | routed | actioned | deadlettered | acknowledged
  terminal BOOLEAN NOT NULL DEFAULT false,
  route_kind TEXT,                 -- decision | informational | ...
  target_ref TEXT,                 -- e.g. decision_id the command routed to
  reason TEXT,
  remediation TEXT,
  history JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(inbox_message_id)
);
CREATE INDEX IF NOT EXISTS idx_ack_state_project
  ON ack_state (project_id, state, updated_at DESC);

-- Phase 4 (testing depth): chaos/load fault-injection runs. Each row records a controlled fault
-- injected against the live primitives and whether the system recovered/detected it.
CREATE TABLE IF NOT EXISTS chaos_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  scenario TEXT NOT NULL,          -- lease_reclaim | worker_crash | deadletter_storm
  injected BOOLEAN NOT NULL DEFAULT true,
  recovered BOOLEAN NOT NULL DEFAULT false,
  detail TEXT,
  evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_chaos_runs_project ON chaos_runs (project_id, created_at DESC);

-- Phase 4 (finops): InfraCommitment reconciler output — committed spend vs actual usage per
-- commitment period, with a verdict (on_track | under_utilized | over_utilized) and any review decision.
CREATE TABLE IF NOT EXISTS commitment_reconciliations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  commitment_id TEXT NOT NULL,
  provider TEXT NOT NULL,
  committed_usd_micros BIGINT NOT NULL,
  actual_usd_micros BIGINT NOT NULL,
  utilization DOUBLE PRECISION NOT NULL,
  verdict TEXT NOT NULL,
  decision_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_commitment_reconciliations_project
  ON commitment_reconciliations (project_id, created_at DESC);

-- Tier-1 "1-box" app previews: ephemeral local runs of a code-task's built app, so an
-- operator can see the working website before merge. Process-based, auto-expiring (TTL).
-- CONTAINER LOGS, WHERE AN OPERATOR CAN READ THEM.
-- BOSS logged which command ran and for how long, how long a stage queued for a model lane,
-- why a preview refused — all of it to a container log nobody outside the box can open. So
-- "Engineer implementing — 27m46s — no model call" was accurate and unhelpful. The Activity
-- Log reads this as one more source.
CREATE TABLE IF NOT EXISTS app_logs (
  id TEXT PRIMARY KEY,
  project_id TEXT,          -- NULL when a record is raised outside any project's work
  run_id TEXT,              -- attributed from the LLM context when there is one
  service TEXT,             -- api | worker
  level TEXT NOT NULL,      -- info | warning | error | critical
  logger TEXT NOT NULL,
  message TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_app_logs_project ON app_logs (project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_logs_run ON app_logs (run_id, created_at DESC);

-- Every start of a BOSS service, with the commit it runs (services/install_history.py): a start
-- whose commit differs from the one before it is an upgrade. Install-wide, not secret.
CREATE TABLE IF NOT EXISTS boss_starts (
  id TEXT PRIMARY KEY,
  service TEXT NOT NULL,        -- api | worker
  source_commit TEXT,           -- BOSS_SOURCE_SHA (NULL when the image carries no stamp)
  previous_commit TEXT,         -- the same service's commit at its previous start
  built_at TEXT,                -- BOSS_BUILT_AT
  host TEXT,                    -- container hostname: new on recreate, kept on restart
  oom_kills INTEGER,            -- the cgroup's OOM-kill count at boot
  install_method TEXT,          -- BOSS_INSTALL_METHOD
  started_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_boss_starts_service ON boss_starts (service, started_at DESC);

CREATE TABLE IF NOT EXISTS app_previews (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  run_id TEXT,
  repo TEXT,
  branch TEXT,
  command TEXT,
  port INTEGER,
  url TEXT,
  pid INTEGER,
  mode TEXT NOT NULL DEFAULT 'process',       -- process | docker | rootfs
  container_id TEXT,                           -- docker container id (mode=docker)
  substrate TEXT NOT NULL DEFAULT 'preview_host', -- preview_host|preview_docker|preview_rootfs
  build_substrate TEXT,                        -- local_subprocess|microvm
  sandbox_task_id TEXT,                        -- retained rootfs backing a rootfs preview
  status TEXT NOT NULL DEFAULT 'starting',   -- starting|running|failed|stopped|expired
  failure_kind TEXT,                           -- clone_failed|command_missing|boot_crash|port_timeout
  error TEXT,
  log_path TEXT,
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS substrate TEXT NOT NULL DEFAULT 'preview_host';
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS build_substrate TEXT;
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS sandbox_task_id TEXT;
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS failure_kind TEXT;
-- What the preview has DONE and what is still pending, in the same shape a deployment records.
-- Starting a preview clones, installs, builds and launches; without a ledger it is a spinner
-- with no detail, and when it fails there is nothing to say how far it got.
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS steps JSONB NOT NULL DEFAULT '[]'::jsonb;
CREATE INDEX IF NOT EXISTS idx_app_previews_project ON app_previews (project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_previews_run ON app_previews (run_id);
-- When the preview last served a proxied request: a preview nobody has looked at for N minutes
-- is stopped (stability spec §4a.6 idle-stop), not left running to its TTL.
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ;
-- The app's demo logins this preview signs in with (names only: DEMO_PASSWORD…). BOSS generated
-- the password; its reviewer reads it in the app's Setup › Demo logins (templates.secrets).
ALTER TABLE app_previews ADD COLUMN IF NOT EXISTS demo_logins JSONB NOT NULL DEFAULT '[]'::jsonb;

-- EVERYTHING A BUILD MAKES IS OWNED AND REAPED (stability spec §4a.1). One row per resource BOSS
-- creates — a process tree, a container, an image, a directory — written BEFORE it is created
-- and closed (released_at) when it is gone. The reaper (resource_reaper) works from both sides:
-- an open row whose owner has ended is released by ending its resource, and a labelled
-- resource on the host with no open row is removed. `handle` is what the resource is found by:
-- `token:<owner token>` for a process tree (the token every descendant carries), a container
-- id or name, an image tag, a path. `node` is the container/host that can see the handle.
CREATE TABLE IF NOT EXISTS owned_resources (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  owner_kind TEXT NOT NULL,      -- code_run|preview|sandbox|review_seat|deploy|api
  owner_id TEXT NOT NULL,
  owner_chain TEXT[] NOT NULL DEFAULT '{}',
  resource_kind TEXT NOT NULL,   -- process_group|container|image|dir|port
  handle TEXT NOT NULL,
  pgid INTEGER,
  node TEXT,
  meta JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  released_at TIMESTAMPTZ,
  release_reason TEXT
);
CREATE INDEX IF NOT EXISTS idx_owned_resources_open ON owned_resources (resource_kind, created_at)
  WHERE released_at IS NULL;
CREATE INDEX IF NOT EXISTS idx_owned_resources_owner ON owned_resources (owner_id);

-- What a kind of work costs the machine (stability spec §4b.2): the memory it must find free to
-- start (request) and the most it may take (limit), seeded from measured footprints and moved by
-- the observed peaks of real runs (EWMA of memory.peak). Admission at lease reads this.
CREATE TABLE IF NOT EXISTS workload_profiles (
  kind TEXT PRIMARY KEY,
  request_mb INTEGER NOT NULL,
  limit_mb INTEGER NOT NULL,
  observed_peak_mb INTEGER,
  samples INTEGER NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The system doctor's diagnoses (stability spec §4c): one row per finding, kept open while its
-- signal holds and resolved when the signal has been clear for two minutes. A finding that
-- needs a person's choice is a `system_health` card in What needs you; one BOSS fixed itself is
-- only a line in the action log.
CREATE TABLE IF NOT EXISTS system_findings (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  kind TEXT NOT NULL,
  severity TEXT NOT NULL DEFAULT 'warn',   -- info|warn|critical
  status TEXT NOT NULL DEFAULT 'open',     -- open|resolved|dismissed|snoozed
  title TEXT NOT NULL,
  detail TEXT,
  evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  options JSONB NOT NULL DEFAULT '[]'::jsonb,
  needs_choice BOOLEAN NOT NULL DEFAULT false,
  first_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  clear_since TIMESTAMPTZ,
  snoozed_until TIMESTAMPTZ,
  resolved_at TIMESTAMPTZ,
  chosen_option TEXT,
  chosen_by TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_system_findings_open_kind ON system_findings (kind)
  WHERE status IN ('open', 'snoozed');

-- Every action the doctor took or a person chose (stability spec §4c Audit): before and after
-- metrics, whether the signal improved, who acted. Also the rate limit's and the circuit
-- breaker's memory.
CREATE TABLE IF NOT EXISTS system_doctor_actions (
  id TEXT PRIMARY KEY,
  finding_id TEXT,
  finding_kind TEXT,
  action TEXT NOT NULL,
  target TEXT,
  actor TEXT NOT NULL,                      -- boss | <member>
  automatic BOOLEAN NOT NULL DEFAULT true,
  outcome TEXT,
  detail TEXT,
  before_metrics JSONB NOT NULL DEFAULT '{}'::jsonb,
  after_metrics JSONB,
  improved BOOLEAN,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  verified_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_system_doctor_actions_recent ON system_doctor_actions (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_system_doctor_actions_target ON system_doctor_actions (action, target, created_at DESC);

-- Install-wide state the doctor and admission share: the install id containers are labelled
-- with, the degradation level, "Builds at once" (auto or pinned), deploy hold, a host sample
-- pushed by the optional Mac helper.
CREATE TABLE IF NOT EXISTS system_state (
  key TEXT PRIMARY KEY,
  value JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Durable, per-lineage feedback conversation.  Dispatch is confirmation-gated;
-- messages preserve the operator request, clarification, proposal and retry link.
CREATE TABLE IF NOT EXISTS feedback_threads (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  root_run_id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL DEFAULT 'open',
  pending_proposal JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS feedback_messages (
  id TEXT PRIMARY KEY,
  thread_id TEXT NOT NULL REFERENCES feedback_threads(id) ON DELETE CASCADE,
  role TEXT NOT NULL,
  kind TEXT NOT NULL,
  content TEXT NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  resulting_run_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_feedback_messages_thread
  ON feedback_messages (thread_id, created_at);

-- Discovery pipeline: research-driven outcome discovery (signal sweep -> synthesize -> vet ->
-- shape -> evidence gate). state holds the cited Discovery Dossier + candidate outcomes.
CREATE TABLE IF NOT EXISTS discovery_runs (
    id TEXT PRIMARY KEY,
    project_id TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'running',   -- running | completed | failed
    phase TEXT NOT NULL DEFAULT 'queued',     -- queued|signal_sweep|synthesize|vet|shape|gate|done
    title TEXT NOT NULL,
    seed TEXT,                                 -- the raw idea / problem / signal
    context TEXT,                              -- operator context (ICP, market, constraints)
    state JSONB NOT NULL DEFAULT '{}',         -- the Discovery Dossier (brief/findings/analysis/critique/outcomes/gate)
    usage JSONB,
    error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_discovery_runs_project ON discovery_runs (project_id, created_at DESC);

-- VAG Phase 0 (docs/product/BOSS_VERIFICATION_AMPLIFIED_GENERATION.md): one row per LLM
-- invocation, so $/verified-outcome, pass-rate, and escalation rate can be measured per
-- (model, stage, task type). Written best-effort by services/llm_telemetry.py — a failed
-- insert never fails the pipeline.
CREATE TABLE IF NOT EXISTS llm_calls (
    id TEXT PRIMARY KEY,
    project_id TEXT,
    code_task_run_id TEXT,
    stage TEXT,                                -- standards|spec|plan|review_plan|write_tests|implement|review_code|security_check|consistency_check|check_tests|solo|simple|guest|research|...
    engine TEXT,                               -- claude_code | native | guest engine name
    model TEXT,
    prompt_tokens BIGINT NOT NULL DEFAULT 0,
    completion_tokens BIGINT NOT NULL DEFAULT 0,
    total_tokens BIGINT NOT NULL DEFAULT 0,
    cost_usd_micros BIGINT NOT NULL DEFAULT 0,
    price_estimated BOOLEAN NOT NULL DEFAULT false,  -- true = model missing from the price map (DEFAULT_PRICE used)
    latency_ms INTEGER NOT NULL DEFAULT 0,
    retries INTEGER NOT NULL DEFAULT 0,
    turns INTEGER NOT NULL DEFAULT 0,
    ok BOOLEAN NOT NULL DEFAULT true,
    error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    -- The call ran on a subscription or a local model: cost_usd_micros is its API-equivalent
    -- value, not money, and no budget settlement charges it (included_spend.py).
    included_in_subscription BOOLEAN NOT NULL DEFAULT false
);
CREATE INDEX IF NOT EXISTS idx_llm_calls_run ON llm_calls (code_task_run_id);
CREATE INDEX IF NOT EXISTS idx_llm_calls_model ON llm_calls (model, stage, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_llm_calls_project ON llm_calls (project_id, created_at DESC);

-- One row per TURN of the conversation between an agent and its model.
--
-- `llm_calls` above records one row per INVOCATION: "solo, claude-sonnet-5, 45 turns,
-- 516183 ms". That is the right ledger for spend, and it is useless for the question an
-- operator actually asks during a 40-90 minute build — "what is it doing right now?".  Forty-
-- five turns of reasoning, file edits and test runs collapsed into a single number, so the
-- longest phase of every project was the least observable thing in the system.
--
-- Captured from the CLI's streaming output, so a turn is written as it happens rather than
-- reconstructed afterwards. Content is REDACTED and TRUNCATED on the way in (prompts carry the
-- customer's source code) and the whole table is retention-bound -- see activity_retention.
CREATE TABLE IF NOT EXISTS agent_turns (
    id TEXT PRIMARY KEY,
    project_id TEXT,
    code_task_run_id TEXT,
    stage TEXT,                                -- implement | review_code | check_tests | ...
    role_key TEXT,                             -- the AGENT: software_engineer, adversarial_reviewer, ...
    engine TEXT,
    model TEXT,
    turn_index INTEGER NOT NULL DEFAULT 0,     -- ordinal within the invocation
    -- What KIND of turn. The four are genuinely different things to read: what the agent was
    -- told, what it said back, what it decided to run, and what came back from running it.
    direction TEXT NOT NULL,                   -- prompt | completion | tool_call | tool_result
    tool_name TEXT,
    content TEXT,                              -- redacted + truncated
    content_bytes INTEGER NOT NULL DEFAULT 0,  -- size BEFORE truncation, so a clipped turn says so
    truncated BOOLEAN NOT NULL DEFAULT false,
    tokens INTEGER NOT NULL DEFAULT 0,
    latency_ms INTEGER NOT NULL DEFAULT 0,
    level TEXT NOT NULL DEFAULT 'verbose',     -- verbose | info | warn | error
    ok BOOLEAN NOT NULL DEFAULT true,
    error TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- The reader's two questions: "this run, in order" and "this project, newest first".
CREATE INDEX IF NOT EXISTS idx_agent_turns_run
    ON agent_turns (code_task_run_id, turn_index, created_at);
CREATE INDEX IF NOT EXISTS idx_agent_turns_project
    ON agent_turns (project_id, created_at DESC);
-- Filter before searching: level and agent are the two facets that cut the set down most.
CREATE INDEX IF NOT EXISTS idx_agent_turns_level
    ON agent_turns (project_id, level, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_turns_role
    ON agent_turns (project_id, role_key, created_at DESC);
-- FULL-TEXT, not ILIKE. Searching a month of turns with a scan is how a log viewer becomes
-- unusable at exactly the moment it matters. to_tsvector + GIN keeps it an index lookup.
-- `translate` splits dotted and underscored identifiers into words BEFORE indexing.
-- Without it "shepherd.proposed" is a single token, so a search for "shepherd" matches
-- nothing and the log reports no results for an event it is holding. The query in
-- activity_log.py applies the identical expression, or the index cannot be used.
CREATE INDEX IF NOT EXISTS idx_agent_turns_fts
    ON agent_turns USING GIN (
        to_tsvector('english', translate(coalesce(content, ''), '._-', '   ')));

-- Search indexes for the log sources that already existed. `events` carried ONE index --
-- (project_id, created_at) -- so every text search was a sequential scan of the project's
-- whole history, filtered in Python afterwards.
CREATE INDEX IF NOT EXISTS idx_events_fts
    ON events USING GIN (to_tsvector('english', translate(
        coalesce(event_type, '') || ' ' || coalesce(actor, '') || ' ' ||
        coalesce(entity_type, '') || ' ' || coalesce(entity_id, ''), '._-', '   ')));
CREATE INDEX IF NOT EXISTS idx_events_entity
    ON events (project_id, entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_type
    ON events (project_id, event_type, created_at DESC);

-- Reusable mapped workflow runtime (WFL-001 / Plane BOSS-134..143).  Definitions
-- are stable identities; published versions are immutable content-addressed
-- graphs.  Mappings deterministically select a version for a class of work and
-- runs/steps retain the exact version, policy snapshot, leases, and evidence.
CREATE TABLE IF NOT EXISTS workflow_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_key TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'retired')),
  -- WHOSE WORKFLOW THIS IS.
  --
  -- 'system' is BOSS's own machinery -- the governed coding pipeline, meeting consensus,
  -- adversarial verification and thirty others. 'product' is a customer's delivery workflow.
  -- They share this runtime because leasing, retries, evidence, approval and compensation are
  -- the hard parts and are already correct here; they must never share an editing surface,
  -- because a customer-facing builder pointed at this table could otherwise rewrite the
  -- pipeline that governs every build in the system.
  --
  -- Defaults to 'system' so every existing row keeps its meaning without a data migration, and
  -- a customer workflow has to say what it is.
  namespace TEXT NOT NULL DEFAULT 'system'
    CHECK (namespace IN ('system', 'product')),
  -- Catalogue workflows BOSS ships are read-only: a customer forks one to change it, which is
  -- what keeps "reset to the standard" possible and the diff against it visible.
  is_catalogue BOOLEAN NOT NULL DEFAULT false,
  forked_from_version_id TEXT,
  active_version_id TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, workflow_key)
);
CREATE INDEX IF NOT EXISTS idx_workflow_definitions_project
  ON workflow_definitions(project_id, status, updated_at DESC);
-- The customer-facing list is always namespace-scoped, so it gets its own index rather than
-- filtering the system rows out of the one above.
CREATE INDEX IF NOT EXISTS idx_workflow_definitions_namespace
  ON workflow_definitions(project_id, namespace, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS workflow_versions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_definition_id TEXT NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'published'
    CHECK (status IN ('published', 'retired')),
  spec JSONB NOT NULL,
  content_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(workflow_definition_id, version),
  UNIQUE(workflow_definition_id, content_hash)
);
-- `definition_id` mirrors `workflow_definition_id` so callers (and the KG investigation
-- pipeline's publish checks) can reference the version's definition by the short name without
-- a rename; it is generated, so inserts keep writing `workflow_definition_id` only.
ALTER TABLE workflow_versions
  ADD COLUMN IF NOT EXISTS definition_id TEXT
  GENERATED ALWAYS AS (workflow_definition_id) STORED;
CREATE INDEX IF NOT EXISTS idx_workflow_versions_project
  ON workflow_versions(project_id, workflow_definition_id, version DESC);

CREATE TABLE IF NOT EXISTS workflow_mappings (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_version_id TEXT NOT NULL REFERENCES workflow_versions(id),
  selector_kind TEXT NOT NULL,
  selector_value TEXT NOT NULL,
  scope_type TEXT NOT NULL CHECK (scope_type IN ('org', 'workspace', 'project')),
  scope_id TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 100,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_workflow_mappings_resolve
  ON workflow_mappings(project_id, selector_kind, selector_value, enabled, priority DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_workflow_mappings_active_selector
  ON workflow_mappings(project_id, selector_kind, selector_value, scope_type, scope_id, priority)
  WHERE enabled = true;

-- A workflow that starts because it is Monday, rather than because somebody asked.
--
-- NOT CRON. A cadence, a minute, an hour and a weekday — see
-- engine/boss_engine/services/workflow_schedules.py for why five positional fields were the
-- wrong trade here. The TIME ZONE is stored with it because "Monday 8am" means 8am where the
-- person reading the report lives; next_run_at is UTC because an instant is an instant.
CREATE TABLE IF NOT EXISTS workflow_schedules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  -- The workflow by KEY, not by version: a schedule is "run this workflow", and pinning a
  -- version would quietly keep running the one that was current when it was created.
  workflow_key TEXT NOT NULL,
  name TEXT NOT NULL,
  cadence TEXT NOT NULL CHECK (cadence IN ('hourly', 'daily', 'weekly')),
  minute INTEGER NOT NULL CHECK (minute BETWEEN 0 AND 59),
  hour INTEGER NOT NULL DEFAULT 0 CHECK (hour BETWEEN 0 AND 23),
  weekday INTEGER CHECK (weekday BETWEEN 0 AND 6),
  timezone TEXT NOT NULL DEFAULT 'UTC',
  -- What each run is started with. The same every time: a schedule that needed different
  -- input per run would be a queue, not a schedule.
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  actor TEXT NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  next_run_at TIMESTAMPTZ NOT NULL,
  last_run_at TIMESTAMPTZ,
  last_run_id TEXT,
  last_error TEXT,
  -- The fuse. A schedule that fires and fails forever spends money forever, so it is disabled
  -- after a run of failures rather than left to keep trying.
  consecutive_failures INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, name)
);
-- What the operator accepted this schedule may start without ("I will add the deployment host
-- before the release"), and what was missing the last time it was refused. A schedule has
-- nobody at the keyboard to press Start anyway, so the choice is stored with it; a refusal is
-- kept as the missing items and their fixes, not as a sentence cut at 500 characters.
ALTER TABLE workflow_schedules
  ADD COLUMN IF NOT EXISTS start_anyway JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE workflow_schedules ADD COLUMN IF NOT EXISTS last_missing JSONB;
-- The only query the tick makes, on every tick.
CREATE INDEX IF NOT EXISTS idx_workflow_schedules_due
  ON workflow_schedules(next_run_at) WHERE enabled;

-- WEBHOOK TRIGGERS (#512): another system starts a workflow by POSTing signed JSON to an
-- unguessable URL. The signing secret is NOT here: it lives in the secret backend and this row
-- holds only the secret_refs id and its last four characters (services/workflow_webhooks.py).
CREATE TABLE IF NOT EXISTS workflow_webhook_triggers (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  -- By KEY, like a schedule: a delivery runs whatever version is current when it arrives.
  workflow_key TEXT NOT NULL,
  name TEXT NOT NULL,
  -- The URL's capability part. Random, never derived from the id or the name.
  path_token TEXT NOT NULL UNIQUE,
  secret_ref_id TEXT NOT NULL,
  secret_last4 TEXT,
  secret_rotated_at TIMESTAMPTZ,
  actor TEXT NOT NULL,
  -- THE STANDING GRANT a delivery runs under, linked at creation exactly as a schedule's is
  -- (identity/consent.require_for_schedule) and re-checked at every delivery (schedule_acting).
  on_behalf_of TEXT,
  grant_id TEXT,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  -- Why BOSS turned the trigger off ("Renew authority"), cleared when the owner turns it on.
  last_error TEXT,
  -- Refused deliveries past the per-minute recording limit, counted rather than itemised so a
  -- flood of bad signatures cannot fill the table and still shows up on the owner's screen.
  refused_unrecorded INTEGER NOT NULL DEFAULT 0,
  last_delivery_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, name)
);
CREATE INDEX IF NOT EXISTS idx_workflow_webhook_triggers_workflow
  ON workflow_webhook_triggers(project_id, workflow_key);

-- One row per delivery that reached a trigger: started, duplicate, or refused with its reason.
-- The body is never stored, only its size and hash.
CREATE TABLE IF NOT EXISTS workflow_webhook_deliveries (
  id TEXT PRIMARY KEY,
  trigger_id TEXT NOT NULL REFERENCES workflow_webhook_triggers(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  delivery_id TEXT,
  dedupe_key TEXT,
  status TEXT NOT NULL CHECK (status IN ('started', 'duplicate', 'refused')),
  reason TEXT,
  run_id TEXT,
  body_bytes INTEGER,
  body_sha256 TEXT,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- THE RECEIPT: one started delivery per dedupe key per trigger, whoever retries it.
CREATE UNIQUE INDEX IF NOT EXISTS uq_workflow_webhook_deliveries_started
  ON workflow_webhook_deliveries(trigger_id, dedupe_key) WHERE status = 'started';
CREATE INDEX IF NOT EXISTS idx_workflow_webhook_deliveries_recent
  ON workflow_webhook_deliveries(trigger_id, received_at DESC);

CREATE TABLE IF NOT EXISTS workflow_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_definition_id TEXT NOT NULL REFERENCES workflow_definitions(id),
  workflow_version_id TEXT NOT NULL REFERENCES workflow_versions(id),
  workflow_mapping_id TEXT REFERENCES workflow_mappings(id),
  parent_run_id TEXT REFERENCES workflow_runs(id),
  root_run_id TEXT,
  actor TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN (
      'queued', 'validating', 'running', 'waiting', 'paused', 'blocked',
      'completed', 'failed', 'deadlettered', 'cancelled', 'compensating', 'compensated'
    )),
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  context JSONB NOT NULL DEFAULT '{}'::jsonb,
  policy_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  current_frontier JSONB NOT NULL DEFAULT '[]'::jsonb,
  dedupe_key TEXT,
  blocked_reason TEXT,
  error TEXT,
  paused_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_workflow_runs_dedupe
  ON workflow_runs(project_id, dedupe_key) WHERE dedupe_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_workflow_runs_project_state
  ON workflow_runs(project_id, status, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_workflow_runs_parent
  ON workflow_runs(parent_run_id, created_at);

CREATE TABLE IF NOT EXISTS workflow_step_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
  step_id TEXT NOT NULL,
  step_kind TEXT NOT NULL,
  iteration INTEGER NOT NULL DEFAULT 0 CHECK (iteration >= 0),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN (
      'pending', 'ready', 'leased', 'running', 'waiting', 'succeeded',
      'skipped', 'failed', 'deadlettered', 'cancelled'
    )),
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  binding_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,
  attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
  run_after TIMESTAMPTZ NOT NULL DEFAULT now(),
  lease_owner TEXT,
  lease_expires_at TIMESTAMPTZ,
  heartbeat_at TIMESTAMPTZ,
  decision_id TEXT REFERENCES decisions(id),
  child_workflow_run_id TEXT REFERENCES workflow_runs(id),
  last_error TEXT,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(workflow_run_id, step_id, iteration)
);
CREATE INDEX IF NOT EXISTS idx_workflow_steps_claim
  ON workflow_step_runs(project_id, status, run_after, lease_expires_at);
CREATE INDEX IF NOT EXISTS idx_workflow_steps_run
  ON workflow_step_runs(workflow_run_id, iteration, created_at);
-- WHEN THE CURRENT ATTEMPT RUNS OUT OF TIME (#512). Set when a step with `timeout_seconds` is
-- leased (the attempt's clock starts then) and read only while the step is leased or running:
-- past it, the attempt is ended as failed with reason `step_timeout` and counts as an attempt.
-- NULL for a step with no timeout, which is every step written before this column existed.
ALTER TABLE workflow_step_runs ADD COLUMN IF NOT EXISTS attempt_timeout_at TIMESTAMPTZ;
-- TEST RUNS AND RE-RUNS (#512, services/workflow_test_runs.py). `mode` 'test' marks a run
-- started as a test: its `pins` ({step_id: {output, source}}) stand in for those steps' work,
-- and a step that could spend or reach outside BOSS is refused unless pinned or named in
-- `allow_live`. Test runs are left out of run lists and scorecards unless asked for.
-- `rerun_of` ({run_id, from_step}) marks a run started from a step of an earlier run, whose
-- earlier steps are pinned to what that run produced. Every run before these columns is
-- 'normal' with no pins.
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS mode TEXT NOT NULL DEFAULT 'normal'
  CHECK (mode IN ('normal', 'test'));
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS pins JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS allow_live JSONB NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS rerun_of JSONB;
CREATE INDEX IF NOT EXISTS idx_workflow_runs_project_mode
  ON workflow_runs(project_id, mode, updated_at DESC);

-- A STEP WHOSE WORK FAILED WAS NEVER SUCCEEDED. Until 2026-10-02 the runner recorded research
-- that died as status 'succeeded' with output.status 'failed_continued' (boss-1: research failed,
-- the step went green, and the run walked on into a panel, a spec and a build). The runner no
-- longer does that, but the rows it wrote still say 'succeeded' — so every reader that is not
-- the console's one masking function (the API, describe_workflow_run, steps_done, the console's
-- "Build on this research" check) went on treating that dead research as done. Rewritten to what
-- happened, keeping the output as evidence. Idempotent: a rewritten row no longer matches.
UPDATE workflow_step_runs
   SET status = 'failed',
       last_error = COALESCE(NULLIF(last_error, ''),
                             output->>'note',
                             'its work failed; recorded as succeeded by the runner before 2026-10-02'),
       output = output || jsonb_build_object('status', 'failed',
                                             'recorded_as', 'failed_continued')
 WHERE status = 'succeeded' AND output->>'status' = 'failed_continued';

CREATE TABLE IF NOT EXISTS workflow_migrations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
  from_version_id TEXT NOT NULL REFERENCES workflow_versions(id),
  to_version_id TEXT NOT NULL REFERENCES workflow_versions(id),
  status TEXT NOT NULL CHECK (status IN ('completed', 'rolled_back', 'failed')),
  compatibility JSONB NOT NULL DEFAULT '{}'::jsonb,
  rollback_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  reason TEXT NOT NULL,
  created_by TEXT NOT NULL,
  rolled_back_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  rolled_back_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_workflow_migrations_run
  ON workflow_migrations(workflow_run_id, created_at DESC);

CREATE TABLE IF NOT EXISTS workflow_compensation_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  workflow_run_id TEXT NOT NULL REFERENCES workflow_runs(id) ON DELETE CASCADE,
  workflow_step_run_id TEXT NOT NULL REFERENCES workflow_step_runs(id) ON DELETE CASCADE,
  sequence INTEGER NOT NULL CHECK (sequence >= 0),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'ready', 'leased', 'running', 'succeeded', 'failed', 'deadlettered', 'cancelled')),
  action JSONB NOT NULL,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  dedupe_key TEXT NOT NULL,
  attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts > 0),
  lease_owner TEXT,
  lease_expires_at TIMESTAMPTZ,
  heartbeat_at TIMESTAMPTZ,
  last_error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_workflow_compensation_claim
  ON workflow_compensation_runs(project_id, workflow_run_id, status, sequence);

-- Agent Studio, executable panels, and the global agent-to-agent coordination
-- fabric (BOSS-256..266). Stable definitions point at immutable versions.
-- Runtime authority is still resolved from RoleSpecs, Agent Modules, Skills,
-- Integrations, policies, budgets, leases and data boundaries at execution time.
CREATE TABLE IF NOT EXISTS agent_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_key TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  owner TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'active', 'retired')),
  active_version_id TEXT,
  source TEXT NOT NULL DEFAULT 'operator',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, agent_key)
);
CREATE INDEX IF NOT EXISTS idx_agent_definitions_project
  ON agent_definitions(project_id, status, updated_at DESC);
DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'delivery_bot_identities_agent_definition_id_fkey'
  ) THEN
    ALTER TABLE delivery_bot_identities
      ADD CONSTRAINT delivery_bot_identities_agent_definition_id_fkey
      FOREIGN KEY (agent_definition_id) REFERENCES agent_definitions(id);
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS agent_versions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_definition_id TEXT NOT NULL REFERENCES agent_definitions(id) ON DELETE CASCADE,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'published', 'retired')),
  role_key TEXT NOT NULL,
  agent_module_id TEXT,
  model_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  prompts JSONB NOT NULL DEFAULT '{}'::jsonb,
  rules JSONB NOT NULL DEFAULT '[]'::jsonb,
  requested_skills JSONB NOT NULL DEFAULT '[]'::jsonb,
  requested_integrations JSONB NOT NULL DEFAULT '[]'::jsonb,
  scopes JSONB NOT NULL DEFAULT '{}'::jsonb,
  limits JSONB NOT NULL DEFAULT '{}'::jsonb,
  output_contract JSONB NOT NULL DEFAULT '{}'::jsonb,
  a2a_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
  validation JSONB NOT NULL DEFAULT '{}'::jsonb,
  content_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at TIMESTAMPTZ,
  retired_at TIMESTAMPTZ,
  UNIQUE(agent_definition_id, version),
  UNIQUE(agent_definition_id, content_hash)
);
CREATE INDEX IF NOT EXISTS idx_agent_versions_project
  ON agent_versions(project_id, agent_definition_id, version DESC);
CREATE INDEX IF NOT EXISTS idx_agent_versions_role
  ON agent_versions(project_id, role_key, status);

CREATE TABLE IF NOT EXISTS agent_test_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_version_id TEXT NOT NULL REFERENCES agent_versions(id) ON DELETE CASCADE,
  scenario JSONB NOT NULL DEFAULT '{}'::jsonb,
  compiled_context JSONB NOT NULL DEFAULT '{}'::jsonb,
  assertions JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'passed', 'failed', 'blocked', 'cancelled')),
  result JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_agent_test_runs_version
  ON agent_test_runs(project_id, agent_version_id, created_at DESC);

CREATE TABLE IF NOT EXISTS panel_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  panel_key TEXT NOT NULL,
