  agent_group_run_id TEXT,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN (
      'queued', 'resolving', 'running', 'waiting_member', 'waiting_decision',
      'blocked', 'completed', 'failed', 'deadlettered', 'cancelled'
    )),
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
