  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,
  consolidation JSONB NOT NULL DEFAULT '{}'::jsonb,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  dedupe_key TEXT,
  blocked_reason TEXT,
