);
CREATE INDEX IF NOT EXISTS idx_panel_dissent_run
  ON panel_dissent(panel_run_id, status, created_at);

-- The A2A ledger is deliberately normalized around immutable envelopes and
-- per-subscriber deliveries. Redis stream IDs are transport cursors only.
CREATE TABLE IF NOT EXISTS a2a_channels (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  channel_key TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT,
  allowed_message_kinds JSONB NOT NULL DEFAULT '[]'::jsonb,
  allowed_schema_versions JSONB NOT NULL DEFAULT '{}'::jsonb,
  retention_seconds INTEGER NOT NULL DEFAULT 604800 CHECK (retention_seconds > 0),
  max_payload_bytes INTEGER NOT NULL DEFAULT 65536 CHECK (max_payload_bytes > 0),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'paused', 'retired')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, channel_key)
);
CREATE INDEX IF NOT EXISTS idx_a2a_channels_project
  ON a2a_channels(project_id, status, channel_key);

CREATE TABLE IF NOT EXISTS a2a_subscriptions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  channel_id TEXT NOT NULL REFERENCES a2a_channels(id) ON DELETE CASCADE,
  subscriber_kind TEXT NOT NULL
    CHECK (subscriber_kind IN ('agent', 'panel', 'workflow', 'worker', 'system', 'operator')),
  subscriber_id TEXT NOT NULL,
  consumer_group TEXT NOT NULL,
  recipient_filter JSONB NOT NULL DEFAULT '{}'::jsonb,
  ack_mode TEXT NOT NULL DEFAULT 'processed'
    CHECK (ack_mode IN ('none', 'accepted', 'processed')),
  visibility_timeout_seconds INTEGER NOT NULL DEFAULT 60
    CHECK (visibility_timeout_seconds BETWEEN 5 AND 3600),
  max_attempts INTEGER NOT NULL DEFAULT 3 CHECK (max_attempts BETWEEN 1 AND 20),
  data_boundaries JSONB NOT NULL DEFAULT '["public","internal"]'::jsonb,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'paused', 'revoked')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(channel_id, consumer_group, subscriber_kind, subscriber_id)
);
CREATE INDEX IF NOT EXISTS idx_a2a_subscriptions_project
  ON a2a_subscriptions(project_id, channel_id, status);

CREATE TABLE IF NOT EXISTS a2a_envelopes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  channel_id TEXT NOT NULL REFERENCES a2a_channels(id),
  message_kind TEXT NOT NULL,
  schema_name TEXT NOT NULL,
  schema_version INTEGER NOT NULL DEFAULT 1 CHECK (schema_version > 0),
  sender_kind TEXT NOT NULL,
  sender_id TEXT NOT NULL,
  sender_version_id TEXT,
  recipient JSONB NOT NULL,
  data_boundary TEXT NOT NULL DEFAULT 'internal',
  priority INTEGER NOT NULL DEFAULT 100,
  ttl_seconds INTEGER NOT NULL DEFAULT 3600 CHECK (ttl_seconds BETWEEN 1 AND 604800),
  not_before TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  ack_mode TEXT NOT NULL DEFAULT 'processed'
    CHECK (ack_mode IN ('none', 'accepted', 'processed')),
  conversation_id TEXT,
  correlation_id TEXT NOT NULL,
  causation_id TEXT REFERENCES a2a_envelopes(id),
  trace_id TEXT NOT NULL,
  reply_to_id TEXT REFERENCES a2a_envelopes(id),
  lineage JSONB NOT NULL DEFAULT '{}'::jsonb,
  payload JSONB NOT NULL,
  payload_hash TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN (
      'draft', 'queued', 'dispatching', 'published', 'delivering',
      'acknowledged', 'partially_acknowledged', 'expired', 'cancelled', 'deadlettered'
    )),
  receipt_id TEXT REFERENCES receipts(id),
  redis_stream_id TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_a2a_envelopes_project
  ON a2a_envelopes(project_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_a2a_envelopes_correlation
  ON a2a_envelopes(project_id, correlation_id, created_at);
CREATE INDEX IF NOT EXISTS idx_a2a_envelopes_conversation
  ON a2a_envelopes(project_id, conversation_id, created_at);

CREATE TABLE IF NOT EXISTS a2a_deliveries (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  envelope_id TEXT NOT NULL REFERENCES a2a_envelopes(id) ON DELETE CASCADE,
  subscription_id TEXT NOT NULL REFERENCES a2a_subscriptions(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN (
      'pending', 'published', 'claimed', 'processing', 'retry_wait',
      'acknowledged', 'rejected', 'deadlettered', 'expired', 'cancelled'
    )),
  attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  redis_stream_id TEXT,
  consumer_name TEXT,
  lease_owner TEXT,
  visibility_expires_at TIMESTAMPTZ,
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_error JSONB,
  claimed_at TIMESTAMPTZ,
  acknowledged_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(envelope_id, subscription_id)
);
CREATE INDEX IF NOT EXISTS idx_a2a_deliveries_claim
  ON a2a_deliveries(project_id, subscription_id, status, next_attempt_at, visibility_expires_at);

CREATE TABLE IF NOT EXISTS a2a_acknowledgements (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  delivery_id TEXT NOT NULL REFERENCES a2a_deliveries(id) ON DELETE CASCADE,
  acknowledgement TEXT NOT NULL
    CHECK (acknowledgement IN ('accepted', 'processed', 'rejected', 'deferred')),
  actor_kind TEXT NOT NULL,
  actor_id TEXT NOT NULL,
  result JSONB NOT NULL DEFAULT '{}'::jsonb,
  evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  reason TEXT,
  receipt_id TEXT REFERENCES receipts(id),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE a2a_acknowledgements
  ADD COLUMN IF NOT EXISTS receipt_id TEXT REFERENCES receipts(id);
CREATE INDEX IF NOT EXISTS idx_a2a_acknowledgements_delivery
  ON a2a_acknowledgements(delivery_id, created_at);

CREATE TABLE IF NOT EXISTS a2a_transport_attempts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  envelope_id TEXT REFERENCES a2a_envelopes(id) ON DELETE CASCADE,
  delivery_id TEXT REFERENCES a2a_deliveries(id) ON DELETE CASCADE,
  operation TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('started', 'succeeded', 'failed')),
  attempt INTEGER NOT NULL DEFAULT 1 CHECK (attempt > 0),
  redis_stream_id TEXT,
  consumer_group TEXT,
  latency_ms INTEGER,
  error JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_a2a_transport_attempts_project
  ON a2a_transport_attempts(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS a2a_outbox (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  envelope_id TEXT NOT NULL REFERENCES a2a_envelopes(id) ON DELETE CASCADE,
  job_id TEXT REFERENCES jobs(id),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'dispatching', 'published', 'retry_wait', 'deadlettered', 'cancelled')),
  attempt INTEGER NOT NULL DEFAULT 0 CHECK (attempt >= 0),
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_error JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(envelope_id)
);
CREATE INDEX IF NOT EXISTS idx_a2a_outbox_pending
  ON a2a_outbox(project_id, status, next_attempt_at);

-- ── AI SRE knowledge graph (RB-15) ────────────────────────────────────────────
-- A layered service/infra topology used to (a) build root-cause CONTEXT (the
-- subgraph around a failing service) and (b) capture LEARNING — confirmed causes
-- are written back as `caused_by` edges so future investigations start smarter.
-- `layer` = 'deterministic' (walked from k8s/cloud/infra_resources) or 'inferred'
-- (derived from traces/heuristics, carries a confidence < 1).
CREATE TABLE IF NOT EXISTS kg_nodes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,               -- service|resource|repo|deployment|datastore|external|incident|root_cause
  node_key TEXT NOT NULL,           -- stable natural key within (project, kind)
  name TEXT NOT NULL,
  attrs JSONB NOT NULL DEFAULT '{}'::jsonb,
  layer TEXT NOT NULL DEFAULT 'deterministic'
    CHECK (layer IN ('deterministic', 'inferred')),
  source TEXT NOT NULL DEFAULT 'manual',  -- provenance source (manual|infra_resources|investigation|walk|…)
  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0 CHECK (confidence >= 0 AND confidence <= 1),
  valid_from TIMESTAMPTZ,           -- temporal validity window start (NULL = unbounded)
  valid_to TIMESTAMPTZ,             -- temporal validity window end (NULL = unbounded)
  -- BOSSAPP-622. Common knowledge fields. trust_tier is enforced by the store
  -- (an agent cannot write governed or approved). search_tsv is the retrieval
  -- full-text column; pgvector HNSW waits on the Debian image, so embeddings
  -- live in kg_embeddings as double precision[].
  org_id TEXT,
  scope TEXT,
  trust_tier TEXT NOT NULL DEFAULT 'observed'
    CHECK (trust_tier IN ('observed', 'governed', 'inferred', 'approved')),
  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  created_by TEXT NOT NULL DEFAULT 'system',
  content_hash TEXT,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  body TEXT NOT NULL DEFAULT '',
  search_tsv TSVECTOR,
  first_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- BOSSAPP-622 code graph: the repository ('' when unnamed) and file a code node comes from,
  -- so a re-index closes exactly what a file no longer defines. NULL on project-wide nodes
  -- (tables, queues, config keys), which two repositories share.
  repo TEXT,
  path TEXT,
  UNIQUE (project_id, kind, node_key)
);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_project
  ON kg_nodes(project_id, kind, last_seen DESC);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_source
  ON kg_nodes(project_id, source);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_confidence
  ON kg_nodes(project_id, confidence);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_valid
  ON kg_nodes(project_id, valid_from, valid_to);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_project_kind_valid
  ON kg_nodes(project_id, kind, valid_to);
CREATE INDEX IF NOT EXISTS idx_kg_nodes_search
  ON kg_nodes USING GIN (search_tsv);

CREATE TABLE IF NOT EXISTS kg_edges (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  src_id TEXT NOT NULL REFERENCES kg_nodes(id) ON DELETE CASCADE,
  dst_id TEXT NOT NULL REFERENCES kg_nodes(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,               -- depends_on|runs_on|deployed_from|owns|emits|caused_by|correlates_with
  attrs JSONB NOT NULL DEFAULT '{}'::jsonb,
  layer TEXT NOT NULL DEFAULT 'deterministic'
    CHECK (layer IN ('deterministic', 'inferred')),
  source TEXT NOT NULL DEFAULT 'manual',
  confidence DOUBLE PRECISION NOT NULL DEFAULT 1.0 CHECK (confidence >= 0 AND confidence <= 1),
  valid_from TIMESTAMPTZ,
  valid_to TIMESTAMPTZ,
  org_id TEXT,
  scope TEXT,
  trust_tier TEXT NOT NULL DEFAULT 'observed'
    CHECK (trust_tier IN ('observed', 'governed', 'inferred', 'approved')),
  weight DOUBLE PRECISION NOT NULL DEFAULT 1.0,
  created_by TEXT NOT NULL DEFAULT 'system',
  content_hash TEXT,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  first_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, src_id, dst_id, kind)
);
CREATE INDEX IF NOT EXISTS idx_kg_edges_src ON kg_edges(src_id, kind);
CREATE INDEX IF NOT EXISTS idx_kg_edges_dst ON kg_edges(dst_id, kind);
-- BOSSAPP-622: the lookups the code indexer and the graph reads make (the planner traps the
-- earlier stack's 1M-node benchmark found: a missing (project_id, node_key) index, and scans of
-- closed rows).
CREATE INDEX IF NOT EXISTS idx_kg_nodes_repo_path ON kg_nodes(project_id, repo, path) WHERE repo IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_key ON kg_nodes(project_id, node_key) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_name ON kg_nodes(project_id, name) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS idx_kg_edges_src_valid ON kg_edges(src_id) WHERE valid_to IS NULL;

-- KG P7a: deleting a project drops its knowledge graph with it. kg_nodes/kg_edges predate the
-- ON DELETE CASCADE every other KG table carries on project_id; add it idempotently so an
-- existing database gets it too (a fresh one is built with it by the CREATE TABLEs above).
ALTER TABLE kg_nodes DROP CONSTRAINT IF EXISTS kg_nodes_project_id_fkey;
ALTER TABLE kg_nodes ADD CONSTRAINT kg_nodes_project_id_fkey
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE;
ALTER TABLE kg_edges DROP CONSTRAINT IF EXISTS kg_edges_project_id_fkey;
ALTER TABLE kg_edges ADD CONSTRAINT kg_edges_project_id_fkey
  FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE;

-- BOSS-357: knowledge retrieval evaluation snapshots (coverage + regression alarms)
CREATE TABLE IF NOT EXISTS kg_eval_snapshots (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  coverage_score DOUBLE PRECISION NOT NULL,
  metrics JSONB NOT NULL DEFAULT '{}'::jsonb,
  alarm BOOLEAN NOT NULL DEFAULT FALSE,
  threshold DOUBLE PRECISION NOT NULL DEFAULT 0.35,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kg_eval_snapshots_project
  ON kg_eval_snapshots(project_id, created_at DESC);

-- BOSSAPP-622. One embedding space per (model, dimension). HNSW needs pgvector,
-- which the Alpine image does not have; exact cosine over this array is the
-- Phase 0 retrieval path. A later image can add the index without a new table.
CREATE TABLE IF NOT EXISTS kg_embeddings (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  node_id TEXT NOT NULL REFERENCES kg_nodes(id) ON DELETE CASCADE,
  model_id TEXT NOT NULL,
  dimensions INTEGER NOT NULL CHECK (dimensions > 0),
  embedding DOUBLE PRECISION[] NOT NULL,
  content_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (node_id, model_id, content_hash)
);
CREATE INDEX IF NOT EXISTS idx_kg_embeddings_project_model
  ON kg_embeddings(project_id, model_id);

-- BOSSAPP-622: record -> changed-symbol links, in their own durable table (ported from PR #12).
-- A pull request names the symbols it changed by their natural keys, not by node ids: a
-- re-index closes or replaces symbol nodes, and a forget deletes them with their edges, but the
-- link stays and `changed` edges are derived from it again once the symbol is in the graph.
CREATE TABLE IF NOT EXISTS kg_change_links (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL,
  source_id TEXT NOT NULL,
  symbol_key TEXT NOT NULL,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, source_kind, source_id, symbol_key)
);
CREATE INDEX IF NOT EXISTS idx_kg_change_links_symbol ON kg_change_links(project_id, symbol_key);

-- Procedural priors (BOSSAPP-1031, services/knowledge/procedural_priors.py): the scorekeeper
-- behind RANKED MOVES. One row per (org, situation fingerprint, canonical tool): how often
-- that first move led to progress in replayed agent_turns. Content-blind by construction —
-- example_excerpt holds ONE short scrubbed ARGS-SHAPE (key names and value sizes), never the
-- arguments. The UNIQUE constraint is also the lookup index (org, fingerprint prefix).
CREATE TABLE IF NOT EXISTS kg_action_priors (
  id TEXT PRIMARY KEY,
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE CASCADE,
  fingerprint_key TEXT NOT NULL,             -- deterministic: v1|<stage>|<language>|<situation>
  action TEXT NOT NULL,                      -- engine_contract.canonical_tool_name vocabulary
  success_count INTEGER NOT NULL DEFAULT 0,  -- progress credit (procedural_priors._credit)
  failure_count INTEGER NOT NULL DEFAULT 0,
  last_seen_at TIMESTAMPTZ,
  example_run_id TEXT,
  example_excerpt TEXT,
  UNIQUE(org_id, fingerprint_key, action)
);

-- BOSSAPP-622: the database image carries pgvector and Apache AGE (scripts/install/db-image).
-- This is the schema step of the upgrade: an existing data directory gets the extensions on its
-- first boot on the new image. A server without them (a stock postgres image, a test database)
-- skips this and keeps exact-cosine search and the recursive CTE.
DO $kg_ext$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'vector') THEN
    CREATE EXTENSION IF NOT EXISTS vector;
  END IF;
  IF EXISTS (SELECT 1 FROM pg_available_extensions WHERE name = 'age') THEN
    CREATE EXTENSION IF NOT EXISTS age;
  END IF;
END $kg_ext$;
-- BOSSAPP-622 stage knowledge scopes (services/knowledge/scopes.py): every node is in one layer
-- (code, lifecycle, ops, knowledge), generated from its kind so every writer agrees. A stage
-- reads only its layers; the partial GIN index lets a non-code text search skip code rows, so
-- its cost does not grow with the code graph. Kept in step with scopes.layer_sql_case() by
-- test_knowledge_stage_scopes_db.
ALTER TABLE kg_nodes ADD COLUMN IF NOT EXISTS knowledge_layer TEXT
  GENERATED ALWAYS AS (CASE WHEN kind IN ('config_key', 'endpoint', 'file', 'module', 'queue', 'symbol', 'table') THEN 'code' WHEN kind IN ('agent', 'decision', 'person', 'pull_request', 'release', 'review_finding', 'run', 'spec', 'team') THEN 'lifecycle' WHEN kind IN ('alert_rule', 'datastore', 'deployment', 'external', 'incident', 'repo', 'resource', 'root_cause', 'runbook', 'service') THEN 'ops' WHEN kind IN ('rule') THEN 'rules' WHEN kind IN ('agent_decision', 'coverage_gap') THEN 'context' ELSE 'knowledge' END) STORED;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_layer
  ON kg_nodes(project_id, knowledge_layer, kind) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_search_noncode
  ON kg_nodes USING GIN (search_tsv) WHERE knowledge_layer <> 'code';
-- BOSSAPP-622 capture, usage, and audit. Tenancy is project_id on every row.
CREATE TABLE IF NOT EXISTS kg_captures (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL,
  source_id TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  body TEXT NOT NULL,
  scrub_counts JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'captured',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, source_kind, source_id, content_hash)
);
CREATE TABLE IF NOT EXISTS kg_usage (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  run_id TEXT NOT NULL,
  step TEXT NOT NULL,
  fact_id TEXT NOT NULL REFERENCES kg_nodes(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_kg_usage_run ON kg_usage(project_id, run_id);
CREATE TABLE IF NOT EXISTS kg_fact_stats (
  fact_id TEXT PRIMARY KEY REFERENCES kg_nodes(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  success_count INTEGER NOT NULL DEFAULT 0,
  failure_count INTEGER NOT NULL DEFAULT 0,
  last_used_at TIMESTAMPTZ,
  archived BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE IF NOT EXISTS kg_audit (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  action TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  actor_kind TEXT NOT NULL,
  detail JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ── AI SRE reliability pipeline (RB-3/RB-4) ───────────────────────────────────
-- A telemetry source (a connected observability tool). Scan can also run against an
-- inline/ephemeral source, in which case anomaly_signals.source_id is NULL.
CREATE TABLE IF NOT EXISTS telemetry_sources (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  kind TEXT NOT NULL,                       -- memory|log_export|grafana|splunk|datadog|...
  name TEXT NOT NULL,
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  secret_ref TEXT,                          -- scoped read-only creds (never inlined)
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, kind, name)
);

-- One distilled anomaly signal from a scan (the mine() output, persisted).
CREATE TABLE IF NOT EXISTS anomaly_signals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  source_id TEXT REFERENCES telemetry_sources(id) ON DELETE SET NULL,
  incident_id TEXT,                         -- set once clustered
  kind TEXT NOT NULL,                       -- new_template|template_spike|error_surge|metric_spike
  signature TEXT NOT NULL,                  -- the template / metric name
  service TEXT NOT NULL DEFAULT '',
  score DOUBLE PRECISION,
  count INTEGER NOT NULL DEFAULT 0,
  sample JSONB NOT NULL DEFAULT '{}'::jsonb,
  ts TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_anomaly_signals_incident ON anomaly_signals(incident_id);
CREATE INDEX IF NOT EXISTS idx_anomaly_signals_project ON anomaly_signals(project_id, ts DESC);

-- A named incident: recurring signals with the same dedupe_key collapse into one.
CREATE TABLE IF NOT EXISTS incidents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  dedupe_key TEXT NOT NULL,
  title TEXT NOT NULL,
  service TEXT NOT NULL DEFAULT '',
  severity TEXT NOT NULL DEFAULT 'warning'
    CHECK (severity IN ('info', 'warning', 'critical')),
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'triaged', 'diagnosing', 'remediating', 'resolved', 'dismissed')),
  confidence DOUBLE PRECISION NOT NULL DEFAULT 0.0,
  signal_count INTEGER NOT NULL DEFAULT 0,
  first_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen TIMESTAMPTZ NOT NULL DEFAULT now(),
  finalize_ctx JSONB NOT NULL DEFAULT '{}'::jsonb,
  UNIQUE (project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_incidents_project ON incidents(project_id, status, last_seen DESC);

-- Evidence attached to an incident (templates, subgraph context, RCA hypotheses, traces).
CREATE TABLE IF NOT EXISTS incident_evidence (
  id TEXT PRIMARY KEY,
  incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,                       -- signal|rca_hypothesis|context|trace|remediation
  ref TEXT NOT NULL DEFAULT '',
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_incident_evidence_incident ON incident_evidence(incident_id, created_at);
-- Insertion order, the tie-break for rows written with the same created_at (an alert and the
-- release it fired on are recorded at one instant): a timeline reads the same order every time.
ALTER TABLE incident_evidence ADD COLUMN IF NOT EXISTS seq BIGINT GENERATED BY DEFAULT AS IDENTITY;

-- ── Native LearningLoop primitive (RB-6) ──────────────────────────────────────
-- A BOSS-wide learning corpus: any agent appends labeled examples + outcomes; the
-- primitive computes metrics and suggests tuning. The SRE agent is the first heavy
-- consumer (incident feedback), generalizing the VAG verifier ratchet (#107).
CREATE TABLE IF NOT EXISTS learning_examples (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  agent TEXT NOT NULL,                       -- sre | verifier | ...
  kind TEXT NOT NULL,                        -- incident_feedback | remediation_outcome | ...
  label TEXT NOT NULL DEFAULT '',            -- verdict / class
  outcome TEXT NOT NULL DEFAULT '',          -- confirmed | dismissed | fix_good | fix_bad | ...
  ref TEXT NOT NULL DEFAULT '',              -- e.g. incident_id
  source TEXT NOT NULL DEFAULT 'manual',
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_learning_examples_project
  ON learning_examples(project_id, agent, kind, created_at DESC);

-- ── Remediation linkage (RB-7) ────────────────────────────────────────────────
-- Links a diagnosed incident to the governed code task that fixes it (and, on success,
-- the gated PR). The fix runs through the SAME governed pipeline as any code task —
-- design → tests → implement → review panel → security → fail-closed gate → PR.
CREATE TABLE IF NOT EXISTS remediations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  code_task_run_id TEXT,
  decision_id TEXT,
  status TEXT NOT NULL DEFAULT 'queued',     -- queued|running|blocked|completed|failed
  pull_request_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_remediations_incident ON remediations(incident_id, created_at DESC);

-- Has an app recovered after its incident's fix shipped? Judged by BOSS's own scrapes of the
-- app's /metrics (incident_response.look_at_recovery), never by what the fixing agent says:
-- `status` waiting -> recovered | timed_out once the error rate has stayed at the pre-incident
-- `baseline` on enough traffic for `stable_minutes`. A workflow's verify_recovery step parks on
-- the row like a CI wait.
CREATE TABLE IF NOT EXISTS incident_recovery_checks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  target_id TEXT NOT NULL,
  workflow_run_id TEXT,
  since TIMESTAMPTZ NOT NULL,
  deadline TIMESTAMPTZ NOT NULL,
  stable_minutes DOUBLE PRECISION NOT NULL DEFAULT 3,
  baseline JSONB NOT NULL DEFAULT '{}'::jsonb,
  rule JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'waiting'
    CHECK (status IN ('waiting', 'recovered', 'timed_out', 'failed')),
  summary TEXT NOT NULL DEFAULT '',
  checks INTEGER NOT NULL DEFAULT 0,
  first_clear_at TIMESTAMPTZ,
  last_window JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_incident_recovery_checks_incident
  ON incident_recovery_checks(incident_id, created_at DESC);

-- An app's reports of a suspected incident (incident_signals): one row per signal the app sent
-- or BOSS read, deduplicated by the app's own id, linked to the incident it created or joined.
-- `received_at` is also the per-app rate limit's clock.
CREATE TABLE IF NOT EXISTS app_signal_receipts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  reporter_target_id TEXT NOT NULL,
  signal_id TEXT NOT NULL,
  incident_id TEXT REFERENCES incidents(id) ON DELETE CASCADE,
  via TEXT NOT NULL CHECK (via IN ('pull', 'push')),
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  received_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (reporter_target_id, signal_id)
);
CREATE INDEX IF NOT EXISTS idx_app_signal_receipts_incident
  ON app_signal_receipts(incident_id);
CREATE INDEX IF NOT EXISTS idx_app_signal_receipts_rate
  ON app_signal_receipts(reporter_target_id, received_at DESC);
-- When BOSS last read an app's signals page and what it found, in words.
CREATE TABLE IF NOT EXISTS app_signal_channels (
  target_id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  last_polled_at TIMESTAMPTZ,
  last_word TEXT NOT NULL DEFAULT ''
);

-- ── App alerts (BOSSAPP-598; services/app_alerts.py) ──────────────────────────────────────
-- An app's alert rules, in the Prometheus alerting-rule shape: `alert`, `expr` (PromQL), `for`,
-- labels.severity and annotations summary / description / runbook_url. BOSS's built-in rules
-- (`kind` error_rate | latency_p95 | health_check | no_traffic | deploy_health) are PromQL over
-- the platform-standard metrics; `kind` custom is a person's own PromQL. The app's
-- boss.deploy.yaml gives the starting values (`source` yaml, or builtin with none); an edit in
-- the console wins (`source` console) and is recorded in app_alert_rule_changes. Respond
-- automatically runs on the standing grant of the person who switched it on (`respond_link`:
-- {on_behalf_of, grant_id}), the rule a workflow subscription follows.
CREATE TABLE IF NOT EXISTS app_alert_rules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  -- A rule watches a deployment target (v1) or a monitored service BOSS did not deploy (P1).
  target_id TEXT REFERENCES deployment_targets(id) ON DELETE CASCADE,
  service_id TEXT,
  group_id TEXT,
  -- threshold | absence | heartbeat | synthetic | external_mirror (the rule's kind of check;
  -- `kind` stays the built-in name or custom).
  rule_type TEXT NOT NULL DEFAULT 'threshold',
  keep_firing_for_s INTEGER NOT NULL DEFAULT 0,
  -- What no data does to a FIRING alert: keep (default: never a false resolution), ok, alert.
  no_data TEXT NOT NULL DEFAULT 'keep',
  urgency TEXT,
  -- builtin | code (boss.deploy.yaml) | console | slo.
  managed_by TEXT NOT NULL DEFAULT 'builtin',
  -- Pre-approved tier-1 actions (Phase 1b) and who granted them.
  response_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  kind TEXT NOT NULL,
  alert TEXT NOT NULL,
  expr TEXT NOT NULL,
  for_seconds INTEGER NOT NULL DEFAULT 0,
  params JSONB NOT NULL DEFAULT '{}'::jsonb,
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  annotations JSONB NOT NULL DEFAULT '{}'::jsonb,
  enabled BOOLEAN NOT NULL DEFAULT true,
  triage BOOLEAN NOT NULL DEFAULT true,
  auto_respond BOOLEAN NOT NULL DEFAULT false,
  respond_link JSONB,
  notify TEXT NOT NULL DEFAULT 'console',
  source TEXT NOT NULL DEFAULT 'builtin' CHECK (source IN ('builtin', 'yaml', 'console')),
  yaml_params JSONB,
  changed_by TEXT,
  changed_at TIMESTAMPTZ,
  -- The last evaluation, in words: state ok | firing | pending | no_data | too_little | off |
  -- silenced | inhibited | error, the value of the rule's measure, and who evaluated it
  -- (boss: BOSS's own scrapes; prometheus: the deployed stack).
  last_eval_at TIMESTAMPTZ,
  last_state TEXT,
  last_value DOUBLE PRECISION,
  last_word TEXT,
  last_source TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_alert_rules_builtin
  ON app_alert_rules(target_id, kind) WHERE kind <> 'custom';
CREATE INDEX IF NOT EXISTS idx_app_alert_rules_project ON app_alert_rules(project_id, target_id);

-- Who changed a rule (or any monitoring object: a source, a contact point, a policy, a silence,
-- a maintenance window, an inhibit rule), when, from what to what, and why. Never updated,
-- never deleted. Was app_alert_rule_changes (a view by that name reads the rule rows).
DO $$ BEGIN
  IF to_regclass('app_alert_rule_changes') IS NOT NULL AND to_regclass('monitoring_changes') IS NULL
     AND (SELECT relkind FROM pg_class WHERE oid = to_regclass('app_alert_rule_changes')) = 'r' THEN
    ALTER TABLE app_alert_rule_changes RENAME TO monitoring_changes;
  END IF;
END $$;
CREATE TABLE IF NOT EXISTS monitoring_changes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  object_kind TEXT NOT NULL DEFAULT 'rule',
  object_id TEXT,
  rule_id TEXT,
  target_id TEXT,
  change TEXT NOT NULL,                     -- edited | created | deleted | silenced | unsilenced
  before JSONB,
  after JSONB,
  reason TEXT NOT NULL DEFAULT '',
  changed_by TEXT NOT NULL,
  changed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE monitoring_changes ADD COLUMN IF NOT EXISTS object_kind TEXT NOT NULL DEFAULT 'rule';
ALTER TABLE monitoring_changes ADD COLUMN IF NOT EXISTS object_id TEXT;
ALTER TABLE monitoring_changes ALTER COLUMN rule_id DROP NOT NULL;
ALTER TABLE monitoring_changes ALTER COLUMN target_id DROP NOT NULL;
CREATE INDEX IF NOT EXISTS idx_app_alert_rule_changes_rule
  ON monitoring_changes(rule_id, changed_at DESC);
CREATE INDEX IF NOT EXISTS idx_monitoring_changes_project
  ON monitoring_changes(project_id, changed_at DESC);
CREATE OR REPLACE VIEW app_alert_rule_changes AS
  SELECT id, project_id, rule_id, target_id, change, before, after, reason, changed_by, changed_at
  FROM monitoring_changes WHERE object_kind = 'rule';

-- A person silenced a rule until `ends_at`, with a reason. `expired_at` when ended early.
CREATE TABLE IF NOT EXISTS app_alert_silences (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  rule_id TEXT NOT NULL REFERENCES app_alert_rules(id) ON DELETE CASCADE,
  target_id TEXT NOT NULL,
  starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at TIMESTAMPTZ NOT NULL,
  reason TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expired_at TIMESTAMPTZ,
  expired_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_app_alert_silences_rule ON app_alert_silences(rule_id, ends_at DESC);

-- Every alert that fired, Alertmanager-style. `fingerprint` (the rule's identity + the result's
-- labels) dedupes: a re-firing alert updates its row (`fire_count`), one that resolved and
-- fires again within the resolve window reopens it. `group_key` (labels.group_key, else the
-- runbook) puts breaches with one resolution in one incident. `inhibited_by` names the firing
-- availability alert (health check, deploy) that suppresses this symptom; `silenced_by` the
-- silence. `triage` is the agent's decision, word for word (agent_decision); `value` the
-- expression's value at breach. `source_kind` signal: an app reported it (incident_signals).
CREATE TABLE IF NOT EXISTS app_alerts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  target_id TEXT,
  service_id TEXT,
  -- signal_sources.id for an external alert (Alertmanager, PagerDuty-shaped, ...) or a heartbeat.
  source_id TEXT,
  -- The source's own key (Alertmanager fingerprint, dedup_key, AlarmArn): mirrored by it.
  external_ref TEXT,
  external_last_at TIMESTAMPTZ,
  links JSONB NOT NULL DEFAULT '[]'::jsonb,
  rule_id TEXT,
  rule_kind TEXT NOT NULL,
  source_kind TEXT NOT NULL DEFAULT 'rule'
    CHECK (source_kind IN ('rule', 'signal', 'external', 'synthetic', 'heartbeat')),
  -- keep_firing_for: when the series went missing while firing (held firing until it ends).
  missing_since TIMESTAMPTZ,
  -- no data while firing, under the rule's no_data policy `keep`: still firing, said so.
  no_data_since TIMESTAMPTZ,
  flapping BOOLEAN NOT NULL DEFAULT false,
  flap_score DOUBLE PRECISION NOT NULL DEFAULT 0,
  -- the last 21 evaluations' presence (1/0), newest last: what flap_score is computed from.
  flap_history TEXT NOT NULL DEFAULT '',
  flap_tuning_asked_at TIMESTAMPTZ,
  acked_by TEXT,
  acked_at TIMESTAMPTZ,
  ack_expires_at TIMESTAMPTZ,
  urgency TEXT NOT NULL DEFAULT 'high',
  notified_at TIMESTAMPTZ,
  -- every reason a notification is held: [{kind: silence|maintenance|deploy_hold|inhibit, id}]
  suppressed_by JSONB NOT NULL DEFAULT '[]'::jsonb,
  reporter_target_id TEXT,
  fingerprint TEXT NOT NULL,
  alertname TEXT NOT NULL,
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  annotations JSONB NOT NULL DEFAULT '{}'::jsonb,
  expr TEXT NOT NULL DEFAULT '',
  value DOUBLE PRECISION,                   -- at breach
  last_value DOUBLE PRECISION,
  threshold DOUBLE PRECISION,
  unit TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL CHECK (state IN ('pending', 'firing', 'resolved')),
  active_at TIMESTAMPTZ NOT NULL,
  fired_at TIMESTAMPTZ,
  last_eval_at TIMESTAMPTZ,
  cleared_at TIMESTAMPTZ,
  cleared_reason TEXT,
  fire_count INTEGER NOT NULL DEFAULT 1,
  eval_source TEXT NOT NULL DEFAULT 'boss',
  release JSONB,
  group_key TEXT NOT NULL DEFAULT '',
  incident_id TEXT REFERENCES incidents(id) ON DELETE SET NULL,
  inhibited_by TEXT,
  silenced_by TEXT,
  triage JSONB,
  triage_state TEXT NOT NULL DEFAULT 'pending'
    CHECK (triage_state IN ('pending', 'done', 'no_model', 'off', 'skipped')),
  triage_attempt_at TIMESTAMPTZ,
  response_run_id TEXT,
  response_word TEXT,
  backfilled BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- One OPEN alert per fingerprint: the dedupe, held by the database.
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_alerts_open_fingerprint
  ON app_alerts(fingerprint) WHERE state IN ('pending', 'firing');
CREATE INDEX IF NOT EXISTS idx_app_alerts_target ON app_alerts(target_id, active_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_alerts_project ON app_alerts(project_id, state, active_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_alerts_incident ON app_alerts(incident_id);

-- Did Grafana / Prometheus answer when BOSS last asked? A console link to Grafana is shown only
-- from an `answering` row (observability_stack.check_endpoint): a link built by concatenation
-- to a host that does not answer looked exactly like a working one.
CREATE TABLE IF NOT EXISTS observability_endpoint_checks (
  project_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('grafana', 'prometheus')),
  base_url TEXT NOT NULL,
  state TEXT NOT NULL CHECK (state IN ('answering', 'not_answering')),
  reason TEXT NOT NULL DEFAULT '',
  detail JSONB NOT NULL DEFAULT '{}'::jsonb,
  checked_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, kind)
);

-- THE ALERT HISTORY STARTS WITH WHAT ALREADY HAPPENED. Every app error-rate alert the monitor
-- raised before app_alerts existed is in incident_evidence (`alert`, then `monitor_resolved`);
-- each becomes an alert here, once (`alrt_bf_<first evidence id>`): its value at breach, the
-- release that was serving, the incident, and the investigation's finding as its triage. A
-- re-fire within five minutes of clearing is the same alert again (the resolve window
-- app_alerts.RESOLVE_WINDOW applies live). The expression is the built-in error-rate rule as
-- app_alerts.render_expr writes it (test_the_backfill_writes_the_rule_the_engine_writes).
CREATE OR REPLACE FUNCTION boss_promql_quote(v TEXT) RETURNS TEXT LANGUAGE SQL IMMUTABLE AS
$$ SELECT '"' || replace(replace(COALESCE(v, ''), '\', '\\'), '"', '\"') || '"' $$;
CREATE OR REPLACE FUNCTION boss_promql_num(v DOUBLE PRECISION) RETURNS TEXT LANGUAGE SQL IMMUTABLE AS
$$ SELECT CASE WHEN v = trunc(v) THEN trunc(v)::bigint::text ELSE v::text END $$;
CREATE OR REPLACE FUNCTION boss_promql_window(minutes DOUBLE PRECISION) RETURNS TEXT
  LANGUAGE SQL IMMUTABLE AS
$$ SELECT CASE WHEN minutes = trunc(minutes) THEN trunc(minutes)::bigint::text || 'm'
               ELSE round(minutes * 60)::bigint::text || 's' END $$;

INSERT INTO app_alerts (id, project_id, target_id, rule_kind, fingerprint, alertname, labels,
                        annotations, expr, value, threshold, unit, state, active_at, fired_at,
                        last_eval_at, cleared_at, cleared_reason, fire_count, eval_source,
                        release, group_key, incident_id, triage, triage_state, backfilled,
                        created_at, updated_at)
WITH alerts AS (
  SELECT e.id, e.incident_id, e.created_at, e.seq, e.payload, i.project_id, i.status AS inc_status,
         i.last_seen AS inc_last_seen, substring(i.dedupe_key FROM 16) AS target_id,
         i.finalize_ctx->'app' AS app,
         lead(e.created_at) OVER (PARTITION BY e.incident_id ORDER BY e.created_at, e.seq)
           AS next_alert_at
  FROM incident_evidence e JOIN incidents i ON i.id = e.incident_id
  WHERE e.kind = 'alert' AND i.dedupe_key LIKE 'app_error_rate:%'
), cleared AS (
  SELECT a.*, (SELECT min(r.created_at) FROM incident_evidence r
               WHERE r.incident_id = a.incident_id AND r.kind = 'monitor_resolved'
                 AND r.created_at > a.created_at
                 AND (a.next_alert_at IS NULL OR r.created_at < a.next_alert_at)) AS cleared_at
  FROM alerts a
), occurrences AS (
  SELECT c.*, sum(CASE WHEN prev_cleared IS NOT NULL
                        AND c.created_at - prev_cleared <= interval '5 minutes' THEN 0 ELSE 1 END)
                OVER (PARTITION BY c.incident_id ORDER BY c.created_at, c.seq) AS occurrence
  FROM (SELECT c0.*, lag(c0.cleared_at) OVER (PARTITION BY c0.incident_id
                                              ORDER BY c0.created_at, c0.seq) AS prev_cleared
        FROM cleared c0) c
), grouped AS (
  SELECT incident_id, occurrence,
         (array_agg(id ORDER BY created_at, seq))[1] AS first_id,
         (array_agg(payload ORDER BY created_at, seq))[1] AS payload,
         min(created_at) AS fired_at, max(created_at) AS last_at,
         (array_agg(cleared_at ORDER BY created_at DESC, seq DESC))[1] AS cleared_at,
         count(*) AS fire_count, max(project_id) AS project_id, max(target_id) AS target_id,
         max(inc_status) AS inc_status, max(inc_last_seen) AS inc_last_seen,
         (array_agg(app))[1] AS app
  FROM occurrences GROUP BY incident_id, occurrence
)
SELECT 'alrt_bf_' || g.first_id, g.project_id, g.target_id, 'error_rate',
       left(encode(sha256(convert_to(g.target_id || '|AppErrorRate|', 'UTF8')), 'hex'), 16),
       'AppErrorRate',
       '{"severity": "critical", "layer": "symptom"}'::jsonb,
       jsonb_build_object(
         'summary', 'Error rate on ' || (g.app->>'app_name'),
         'description', 'More than ' || boss_promql_num((g.payload->'rule'->>'error_rate_percent')::float8)
           || '% of requests failed (5xx) over ' || boss_promql_num((g.payload->'rule'->>'window_minutes')::float8)
           || ' min, on at least ' || boss_promql_num((g.payload->'rule'->>'min_requests')::float8) || ' requests.',
         'runbook_url', 'boss:runbook/app-serving'),
       '100 * sum(increase(http_requests_total{app=' || boss_promql_quote(g.app->>'app_name')
         || ',environment=' || boss_promql_quote(g.app->>'environment') || ',status=~"5.."}['
         || boss_promql_window((g.payload->'rule'->>'window_minutes')::float8)
         || '])) / sum(increase(http_requests_total{app=' || boss_promql_quote(g.app->>'app_name')
         || ',environment=' || boss_promql_quote(g.app->>'environment') || '}['
         || boss_promql_window((g.payload->'rule'->>'window_minutes')::float8) || '])) > '
         || boss_promql_num((g.payload->'rule'->>'error_rate_percent')::float8)
         || ' and sum(increase(http_requests_total{app=' || boss_promql_quote(g.app->>'app_name')
         || ',environment=' || boss_promql_quote(g.app->>'environment') || '}['
         || boss_promql_window((g.payload->'rule'->>'window_minutes')::float8) || '])) >= '
         || boss_promql_num((g.payload->'rule'->>'min_requests')::float8),
       round(((g.payload->>'error_rate')::float8 * 100)::numeric, 2)::float8,
       (g.payload->'rule'->>'error_rate_percent')::float8, '%',
       CASE WHEN g.cleared_at IS NOT NULL OR g.inc_status IN ('resolved', 'dismissed')
            THEN 'resolved' ELSE 'firing' END,
       g.fired_at, g.fired_at, g.last_at,
       COALESCE(g.cleared_at, CASE WHEN g.inc_status IN ('resolved', 'dismissed')
                                   THEN g.inc_last_seen END),
       CASE WHEN g.cleared_at IS NOT NULL THEN 'recovered'
            WHEN g.inc_status IN ('resolved', 'dismissed') THEN 'incident_closed' END,
       g.fire_count, 'boss',
       (SELECT jsonb_build_object('commit_sha', d.payload->>'commit_sha', 'ref', d.payload->>'ref',
                                  'deployed_at', d.payload->>'deployed_at')
        FROM incident_evidence d WHERE d.incident_id = g.incident_id AND d.kind = 'deployment'
          AND d.created_at = g.fired_at LIMIT 1),
       'serving', g.incident_id,
       (SELECT jsonb_build_object(
                 'status', 'decided', 'action', 'open_incident', 'outcome', 'opened',
                 'incident_id', g.incident_id, 'reason', h.payload->>'root_cause',
                 'confidence', (h.payload->>'confidence')::float8,
                 'by', jsonb_build_object('backend', 'investigation',
                                          'word', 'Incident Response''s investigation'),
                 'at', h.created_at, 'backfilled', true)
        FROM incident_evidence h WHERE h.incident_id = g.incident_id AND h.kind = 'rca_hypothesis'
          AND h.created_at >= g.fired_at
          AND (g.cleared_at IS NULL OR h.created_at <= g.cleared_at)
        ORDER BY h.created_at LIMIT 1),
       CASE WHEN EXISTS (SELECT 1 FROM incident_evidence h WHERE h.incident_id = g.incident_id
                           AND h.kind = 'rca_hypothesis' AND h.created_at >= g.fired_at
                           AND (g.cleared_at IS NULL OR h.created_at <= g.cleared_at))
            THEN 'done' ELSE 'skipped' END,
       true, g.fired_at, now()
FROM grouped g
WHERE g.target_id IS NOT NULL AND g.app IS NOT NULL AND g.payload ? 'rule'
  -- an alert the live monitor recorded carries its own id; only what came before is backfilled
  AND NOT (g.payload ? 'alert_id')
  AND EXISTS (SELECT 1 FROM deployment_targets t WHERE t.id = g.target_id)
ON CONFLICT DO NOTHING;

-- ...and every report an app sent about it (app_signal_receipts): an alert from a signal
-- source, under the incident it created or joined.
INSERT INTO app_alerts (id, project_id, target_id, rule_kind, source_kind, reporter_target_id,
                        fingerprint, alertname, labels, annotations, value, unit, state,
                        active_at, fired_at, last_eval_at, cleared_at, cleared_reason,
                        group_key, incident_id, triage_state, backfilled, created_at, updated_at)
SELECT 'alrt_sg_' || r.id, r.project_id, substring(i.dedupe_key FROM 16), 'signal', 'signal',
       r.reporter_target_id,
       left(encode(sha256(convert_to(r.reporter_target_id || '|AppSignal|' || r.signal_id, 'UTF8')), 'hex'), 16),
       'AppSignal',
       jsonb_build_object('severity', COALESCE(NULLIF(r.payload->>'severity', ''), 'warning'),
                          'layer', 'symptom'),
       jsonb_build_object('summary', COALESCE(r.payload->>'title', 'Reported by the app'),
                          'description', COALESCE(r.payload->>'summary', ''),
                          'runbook_url', 'boss:runbook/app-serving'),
       COALESCE((r.payload->>'count')::float8, 1), 'reports',
       CASE WHEN done.at IS NOT NULL OR i.status IN ('resolved', 'dismissed') THEN 'resolved'
            ELSE 'firing' END,
       r.received_at, r.received_at, r.received_at,
       COALESCE(done.at, CASE WHEN i.status IN ('resolved', 'dismissed') THEN i.last_seen END),
       CASE WHEN done.at IS NOT NULL OR i.status IN ('resolved', 'dismissed')
            THEN 'incident_closed' END,
       'serving', r.incident_id, 'skipped', true, r.received_at, now()
FROM app_signal_receipts r JOIN incidents i ON i.id = r.incident_id
-- the occurrence the report joined ended when its recovery was verified (a later occurrence
-- of the same incident is not this report's)
LEFT JOIN LATERAL (SELECT min(v.created_at) AS at FROM incident_evidence v
                   WHERE v.incident_id = r.incident_id AND v.kind = 'verification'
                     AND v.ref = 'recovered' AND v.created_at > r.received_at) done ON true
WHERE i.dedupe_key LIKE 'app_error_rate:%'
  AND EXISTS (SELECT 1 FROM deployment_targets t WHERE t.id = substring(i.dedupe_key FROM 16))
  AND NOT EXISTS (SELECT 1 FROM app_alerts x WHERE x.fingerprint = left(encode(sha256(convert_to(
        r.reporter_target_id || '|AppSignal|' || r.signal_id, 'UTF8')), 'hex'), 16))
ON CONFLICT DO NOTHING;

-- Evidence-only AI SRE postmortems (not break-glass). One artifact per incident.
CREATE TABLE IF NOT EXISTS sre_postmortems (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  incident_id TEXT NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (incident_id)
);
CREATE INDEX IF NOT EXISTS idx_sre_postmortems_project
  ON sre_postmortems(project_id, created_at DESC);

-- ── Reliability autonomy policy (RB-19) ───────────────────────────────────────
-- Governed autonomy spectrum per project: how far the SRE agent may go on its own.
-- Tier-0 auto_remediate: auto-launch the (still fail-closed, gated) remediation PR when
-- confidence/severity/blast-radius bounds hold. Tier-1: remediation only on operator request.
-- Tier-2: notify/handoff only. Every action remains receipted + gated by the pipeline.
CREATE TABLE IF NOT EXISTS reliability_policies (
  project_id TEXT PRIMARY KEY REFERENCES projects(id),
  auto_remediate BOOLEAN NOT NULL DEFAULT FALSE,
  min_confidence DOUBLE PRECISION NOT NULL DEFAULT 0.8,
  max_blast_radius INTEGER NOT NULL DEFAULT 5,      -- subgraph size cap for autonomous action
  max_auto_severity TEXT NOT NULL DEFAULT 'critical'
    CHECK (max_auto_severity IN ('info', 'warning', 'critical')),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ── Cost governance P1 (BOSS-280): per-agent attribution + cache-aware pricing ─
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS role TEXT;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS cache_read_tokens INTEGER NOT NULL DEFAULT 0;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS cache_write_tokens INTEGER NOT NULL DEFAULT 0;
CREATE INDEX IF NOT EXISTS idx_llm_calls_role ON llm_calls(project_id, role, created_at DESC);

-- ── BOSS-280 P1 backfill: attribute historical llm_calls to agent roles ───────
-- role is derived from stage; rows written before the column existed are backfilled once
-- (idempotent — only touches NULL roles), so $/agent covers history, not just new spend.
UPDATE llm_calls SET role = CASE
    WHEN stage IN ('standards','spec','plan','review_plan','design') THEN 'architect'
    WHEN stage = 'write_tests' THEN 'qa'
    WHEN stage IN ('check_tests','run_all_tests') THEN 'qa'
    WHEN stage IN ('implement','repair','guest','solo') THEN 'software_engineer'
    WHEN stage IN ('review_code','consistency_check') THEN 'reviewer'
    WHEN stage = 'security_check' THEN 'security_reviewer'
    ELSE NULL END
WHERE role IS NULL AND stage IS NOT NULL;

-- Advisory gate (nullable on purpose). NULL means "use the preset's value", so adding this
-- column cannot silently redefine a preset that predates it. Lean sets it true: the adversarial
-- panel still runs and still records every verdict, but a reviewer's opinion cannot withhold
-- the PR + preview. Regressions are exempt (_ADVISORY_HARD_FLOOR).
ALTER TABLE pipeline_profiles ADD COLUMN IF NOT EXISTS advisory_gate BOOLEAN;
-- Which adversarial seats sit on the panel (NULL -> the preset's list -> the full panel).
-- `lean` narrows this to ["regression"]: tests are still written first and the suite still
-- runs, but the three LLM seats that argue about the code are not convened.
ALTER TABLE pipeline_profiles ADD COLUMN IF NOT EXISTS panel_checks JSONB;

-- FENCING FOR RUN EXECUTION. A job lease only means something if the holder stops when it
-- loses it. Nothing enforced that, so a reclaimed job ran in two workers at once and both
-- wrote this table (phase moved backwards; stages re-ran; 89 min and $4.44 for no code).
-- owner_token is the sha256 of the executing worker's lease token: a reclaiming worker
-- overwrites it and thereby fences the previous executor, whose writes then match 0 rows.
-- state_version makes contention visible after the fact — it jumps in bursts under a race.
ALTER TABLE code_task_runs ADD COLUMN IF NOT EXISTS owner_token TEXT;
ALTER TABLE code_task_runs ADD COLUMN IF NOT EXISTS state_version INTEGER NOT NULL DEFAULT 0;
-- fence_epoch (BOSSAPP-986) closes the one hole the token left: claim_run was unconditional,
-- so a STALE executor whose claim landed late could take the token back from the worker that
-- legitimately reclaimed the job. The epoch is stamped from the job lease at claim/reclaim and
-- only ever moves forward; an older epoch can neither re-claim the run nor write to it.
-- Additive and safe on upgrade: rows start at 0, the next claim stamps the current epoch.
ALTER TABLE code_task_runs ADD COLUMN IF NOT EXISTS fence_epoch BIGINT NOT NULL DEFAULT 0;

-- ===========================================================================
-- TASK SHEPHERD (docs/product/TASK_SHEPHERD_DESIGN.md)
-- An internal AI developer that owns a task from "asked for" to "merged, or a
-- human has been asked one clear question". Grounded in the 2026-08-03/04
-- session where 58% of spend ($38.37 of $66.65) went to runs producing nothing,
-- all of it operational rather than coding failure.
-- ===========================================================================

-- What has been tried for a task, and what remains. THIS is what bounds the
-- shepherd: a remedy may be used once per task, so termination is a property of
-- the ledger rather than of the model's judgement.
CREATE TABLE IF NOT EXISTS shepherd_ledger (
  id             TEXT PRIMARY KEY,
  project_id     TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_ref       TEXT NOT NULL,              -- crun_... the shepherd is shepherding
  failure_class  INTEGER NOT NULL,
  remedy_id      TEXT NOT NULL,
  status         TEXT NOT NULL DEFAULT 'available',  -- available|used|blocked
  used_at        TIMESTAMPTZ,
  cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  outcome        TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (task_ref, failure_class, remedy_id)
);
CREATE INDEX IF NOT EXISTS idx_shepherd_ledger_task ON shepherd_ledger(task_ref, status);

-- The reasoning itself — the primary artifact, and what the console renders.
-- predicted_* and actual_* are both stored so "is it actually reasoning?" is a
-- measurable question (calibration) rather than an impression.
CREATE TABLE IF NOT EXISTS shepherd_reasoning (
  id                TEXT PRIMARY KEY,
  project_id        TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_ref          TEXT NOT NULL,
  step_no           INTEGER NOT NULL,
  observe           TEXT NOT NULL,
  signals           JSONB NOT NULL DEFAULT '[]'::jsonb,
  hypothesis        TEXT,
  confidence        NUMERIC(3,2),
  check_result      TEXT,                    -- a hypothesis must be CHECKED, not asserted
  check_confirmed   BOOLEAN,
  failure_class     INTEGER,
  remedy_chosen     TEXT,
  rationale         TEXT,
  predicted_cost_usd_micros BIGINT,
  predicted_outcome TEXT,
  actual_cost_usd_micros    BIGINT,
  actual_outcome    TEXT,
  stopped_because   TEXT,                    -- success|ledger|loop|budget|human|deadline
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (task_ref, step_no)
);
CREATE INDEX IF NOT EXISTS idx_shepherd_reasoning_task ON shepherd_reasoning(task_ref, step_no);

-- Every judgement the in-flight shepherd makes, whether or not it acted on it.
--
-- Exists so a capability held back for safety cannot quietly rot. Shadow mode without a
-- ledger is a promise to review something later that nobody reviews: the flag stays off, the
-- evidence never accumulates anywhere visible, and re-enabling it months later reintroduces
-- exactly the bugs it was switched off for. Recording every verdict makes readiness a
-- MEASUREMENT — "this class judged 40 runs and was never overruled" — instead of a memory.
--
-- `mode` is what the shepherd was allowed to do at the time, not what it wanted to do:
-- shadow means it recorded and stood back; live means it acted. Keeping both in one table is
-- what makes "would this have been right?" answerable after the fact.
CREATE TABLE IF NOT EXISTS shepherd_watch_observations (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  run_id        TEXT NOT NULL,
  watch_class   INTEGER NOT NULL,
  class_name    TEXT NOT NULL,
  action        TEXT NOT NULL,               -- none|cancel|requeue|fail|escalate
  mode          TEXT NOT NULL,               -- shadow|live
  acted         BOOLEAN NOT NULL DEFAULT FALSE,
  reason        TEXT NOT NULL,
  evidence      JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- Filled in later by a human or by the run's own outcome: was the shepherd right?
  -- NULL means nobody has judged it yet, which is different from "it was fine".
  verdict_correct BOOLEAN,
  judged_by     TEXT,
  judged_at     TIMESTAMPTZ,
  note          TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_shepherd_watch_obs_class
  ON shepherd_watch_observations(project_id, watch_class, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_shepherd_watch_obs_run
  ON shepherd_watch_observations(run_id, created_at DESC);

-- One decision-shaped question for a human. Never a log dump: options are
-- concrete and each carries its cost.
CREATE TABLE IF NOT EXISTS shepherd_escalations (
  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_ref     TEXT NOT NULL,
  question     TEXT NOT NULL,
  options      JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence     JSONB NOT NULL DEFAULT '{}'::jsonb,
  status       TEXT NOT NULL DEFAULT 'open',   -- open|answered|withdrawn
  answered_by  TEXT,
  answer       TEXT,
  answered_at  TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_shepherd_escalations_open ON shepherd_escalations(project_id, status);

-- Why a shepherd was told to wait. Cross-task interference is the coordinator's
-- job: merging PR #66 made #67 and #68 CONFLICTING instantly, which no per-task
-- shepherd could have seen.
CREATE TABLE IF NOT EXISTS coordinator_rulings (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  subject     JSONB NOT NULL DEFAULT '[]'::jsonb,   -- task refs the ruling covers
  ruling      TEXT NOT NULL,                        -- proceed|hold|sequence|block
  rationale   TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- ===========================================================================
-- GROUND-TRUTH AND ASSURANCE RUNTIME (BOSS-123..128, BOSS-131)
-- These records move measured truth, settled conclusions, evidence, claims,
-- and enforcement decisions out of model memory and into the durable plane.
-- ===========================================================================

CREATE TABLE IF NOT EXISTS ground_truth_metric_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  metric_key TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'superseded', 'retired')),
  metric_kind TEXT NOT NULL
    CHECK (metric_kind IN ('coverage', 'freshness', 'correctness', 'completeness', 'custom')),
  unit TEXT NOT NULL DEFAULT 'count',
  comparator TEXT NOT NULL DEFAULT 'gte'
    CHECK (comparator IN ('gte', 'lte', 'eq', 'between')),
  baseline DOUBLE PRECISION NOT NULL,
  threshold DOUBLE PRECISION NOT NULL,
  threshold_upper DOUBLE PRECISION,
  cadence_seconds INTEGER NOT NULL CHECK (cadence_seconds > 0),
  alert_sla_seconds INTEGER NOT NULL CHECK (alert_sla_seconds > 0),
  owner_ref TEXT NOT NULL,
  evidence_query JSONB NOT NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, metric_key, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_ground_truth_metric_current
  ON ground_truth_metric_definitions(project_id, metric_key)
  WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_ground_truth_metrics_project
  ON ground_truth_metric_definitions(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS ground_truth_observations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  metric_definition_id TEXT NOT NULL REFERENCES ground_truth_metric_definitions(id),
  metric_definition_version INTEGER NOT NULL CHECK (metric_definition_version > 0),
  value DOUBLE PRECISION NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('healthy', 'breached', 'inconclusive')),
  evaluator_job_id TEXT NOT NULL REFERENCES jobs(id),
  evaluator_worker_id TEXT NOT NULL,
  lease_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  evidence JSONB NOT NULL,
  dedupe_key TEXT NOT NULL,
  observed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_ground_truth_observations_metric
  ON ground_truth_observations(project_id, metric_definition_id, observed_at DESC);

CREATE TABLE IF NOT EXISTS regression_signals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  metric_definition_id TEXT NOT NULL REFERENCES ground_truth_metric_definitions(id),
  first_observation_id TEXT NOT NULL REFERENCES ground_truth_observations(id),
  latest_observation_id TEXT NOT NULL REFERENCES ground_truth_observations(id),
  decision_id TEXT REFERENCES decisions(id),
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'acknowledged', 'recovered', 'dismissed')),
  dedupe_key TEXT NOT NULL,
  breach_started_at TIMESTAMPTZ NOT NULL,
  recovered_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_regression_signals_open
  ON regression_signals(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS settled_conclusions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  conclusion_key TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'current'
    CHECK (status IN ('draft', 'current', 'superseded', 'reopened', 'expired', 'retired')),
  conclusion TEXT NOT NULL,
  scope JSONB NOT NULL DEFAULT '{}'::jsonb,
  owner_ref TEXT NOT NULL,
  tell_patterns JSONB NOT NULL,
  cause_menu JSONB NOT NULL,
  evidence_refs JSONB NOT NULL,
  reopen_conditions JSONB NOT NULL DEFAULT '[]'::jsonb,
  effective_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  review_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, conclusion_key, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_settled_conclusion_current
  ON settled_conclusions(project_id, conclusion_key)
  WHERE status = 'current';
CREATE INDEX IF NOT EXISTS idx_settled_conclusions_scope
  ON settled_conclusions(project_id, status, effective_at DESC);

CREATE TABLE IF NOT EXISTS closed_question_matches (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  settled_conclusion_id TEXT NOT NULL REFERENCES settled_conclusions(id),
  settled_conclusion_version INTEGER NOT NULL CHECK (settled_conclusion_version > 0),
  publication_boundary TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  matched_patterns JSONB NOT NULL,
  context_classification TEXT NOT NULL
    CHECK (context_classification IN ('actionable', 'quoted', 'historical', 'negated')),
  status TEXT NOT NULL CHECK (status IN ('blocked', 'allowed_context', 'overridden')),
  stop_response JSONB NOT NULL DEFAULT '{}'::jsonb,
  decision_id TEXT REFERENCES decisions(id),
  dedupe_key TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_closed_question_matches_project
  ON closed_question_matches(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS assurance_cases (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  subject_type TEXT NOT NULL,
  subject_ref TEXT NOT NULL,
  title TEXT NOT NULL,
  risk_tier INTEGER NOT NULL DEFAULT 1 CHECK (risk_tier BETWEEN 0 AND 3),
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'evaluating', 'accepted', 'blocked', 'refuted', 'inconclusive', 'reopened')),
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  policy_snapshot JSONB NOT NULL DEFAULT '{}'::jsonb,
  metric_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  settled_conclusion_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  surface_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  agent_group_run_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  workflow_run_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  skill_invocation_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  integration_connection_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  decision_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  final_reason JSONB NOT NULL DEFAULT '{}'::jsonb,
  dedupe_key TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_assurance_cases_project
  ON assurance_cases(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS assurance_policy_snapshots (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  assurance_case_id TEXT NOT NULL REFERENCES assurance_cases(id) ON DELETE CASCADE,
  assurance_case_version INTEGER NOT NULL,
  org_rules JSONB NOT NULL DEFAULT '{}'::jsonb,
  project_rules JSONB NOT NULL DEFAULT '{}'::jsonb,
  effective_rules JSONB NOT NULL,
  conflicts JSONB NOT NULL DEFAULT '[]'::jsonb,
  content_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(assurance_case_id, assurance_case_version, content_hash)
);

CREATE TABLE IF NOT EXISTS assurance_claims (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  assurance_case_id TEXT NOT NULL REFERENCES assurance_cases(id) ON DELETE CASCADE,
  claim_type TEXT NOT NULL
    CHECK (claim_type IN ('solved', 'fixed', 'regressed', 'caused_by', 'healthy', 'status')),
  statement TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('draft', 'pending', 'authoritative', 'blocked', 'inconclusive', 'refuted', 'invalidated')),
  evidence_contract JSONB NOT NULL DEFAULT '{}'::jsonb,
  producer_ref TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_assurance_claims_case
  ON assurance_claims(assurance_case_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS assurance_evidence (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  assurance_case_id TEXT NOT NULL REFERENCES assurance_cases(id) ON DELETE CASCADE,
  claim_id TEXT REFERENCES assurance_claims(id) ON DELETE CASCADE,
  evidence_type TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  uri TEXT,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  provenance JSONB NOT NULL,
  reproduction JSONB NOT NULL,
  produced_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  valid_until TIMESTAMPTZ,
  invalidated_at TIMESTAMPTZ,
  invalidation_reason TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, claim_id, content_hash, evidence_type)
);
CREATE INDEX IF NOT EXISTS idx_assurance_evidence_claim
  ON assurance_evidence(project_id, claim_id, created_at DESC);

CREATE TABLE IF NOT EXISTS claim_verifications (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  assurance_case_id TEXT NOT NULL REFERENCES assurance_cases(id) ON DELETE CASCADE,
  claim_id TEXT NOT NULL REFERENCES assurance_claims(id) ON DELETE CASCADE,
  claim_version INTEGER NOT NULL,
  outcome TEXT NOT NULL CHECK (outcome IN ('passed', 'refuted', 'inconclusive')),
  reasons JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  policy_snapshot_id TEXT REFERENCES assurance_policy_snapshots(id),
  dedupe_key TEXT NOT NULL,
  verified_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_claim_verifications_claim
  ON claim_verifications(claim_id, created_at DESC);

CREATE TABLE IF NOT EXISTS surface_ownerships (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  surface_key TEXT NOT NULL,
  environment TEXT NOT NULL,
  owner_ref TEXT NOT NULL,
  coordination_route TEXT NOT NULL,
  version INTEGER NOT NULL DEFAULT 1 CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'transferring', 'relinquished', 'expired')),
  expires_at TIMESTAMPTZ,
  acquired_by TEXT NOT NULL,
  acquired_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, surface_key, environment)
);
CREATE INDEX IF NOT EXISTS idx_surface_ownerships_project
  ON surface_ownerships(project_id, status, updated_at DESC);

CREATE TABLE IF NOT EXISTS ownership_transitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  surface_ownership_id TEXT NOT NULL REFERENCES surface_ownerships(id) ON DELETE CASCADE,
  transition_kind TEXT NOT NULL
    CHECK (transition_kind IN ('acquire', 'transfer', 'relinquish', 'expire', 'emergency_takeover', 'preflight')),
  from_owner_ref TEXT,
  to_owner_ref TEXT,
  from_version INTEGER,
  to_version INTEGER NOT NULL,
  reason TEXT NOT NULL,
  decision_id TEXT REFERENCES decisions(id),
  actor TEXT NOT NULL,
  dedupe_key TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_ownership_transitions_surface
  ON ownership_transitions(surface_ownership_id, created_at DESC);

CREATE TABLE IF NOT EXISTS verification_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  policy_key TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'superseded', 'retired')),
  surface_patterns JSONB NOT NULL DEFAULT '[]'::jsonb,
  claim_types JSONB NOT NULL DEFAULT '[]'::jsonb,
  risk_tiers JSONB NOT NULL DEFAULT '[]'::jsonb,
  cadence_seconds INTEGER NOT NULL CHECK (cadence_seconds > 0),
  sample_rate DOUBLE PRECISION NOT NULL DEFAULT 1 CHECK (sample_rate >= 0 AND sample_rate <= 1),
  verification_method JSONB NOT NULL,
  independence_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  escalation_target TEXT NOT NULL,
  estimated_cost_usd_micros BIGINT NOT NULL DEFAULT 0 CHECK (estimated_cost_usd_micros >= 0),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, policy_key, version)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_verification_policy_current
  ON verification_policies(project_id, policy_key) WHERE status = 'active';

CREATE TABLE IF NOT EXISTS verification_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  assurance_case_id TEXT NOT NULL REFERENCES assurance_cases(id) ON DELETE CASCADE,
  claim_id TEXT NOT NULL REFERENCES assurance_claims(id) ON DELETE CASCADE,
  verification_policy_id TEXT NOT NULL REFERENCES verification_policies(id),
  job_id TEXT REFERENCES jobs(id),
  budget_reservation_id TEXT REFERENCES budget_reservations(id),
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'leased', 'running', 'passed', 'refuted', 'inconclusive', 'failed', 'deadlettered', 'cancelled')),
  producer_path JSONB NOT NULL DEFAULT '{}'::jsonb,
  verifier_path JSONB NOT NULL DEFAULT '{}'::jsonb,
  evidence_bundle JSONB NOT NULL DEFAULT '[]'::jsonb,
  receipt_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  result JSONB NOT NULL DEFAULT '{}'::jsonb,
  dedupe_key TEXT NOT NULL,
  scheduled_for TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_verification_runs_queue
  ON verification_runs(project_id, status, scheduled_for);

-- BOSS-130: typed integration definitions, tenant-scoped connections, and the
-- durable explanation of every capability resolution decision.
CREATE TABLE IF NOT EXISTS integration_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  integration_key TEXT NOT NULL,
  version INTEGER NOT NULL CHECK (version > 0),
  name TEXT NOT NULL,
  category TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('draft', 'active', 'superseded', 'retired')),
  skill_contracts JSONB NOT NULL,
  executor_bindings JSONB NOT NULL DEFAULT '[]'::jsonb,
  provenance JSONB NOT NULL,
  content_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, integration_key, version),
  UNIQUE(project_id, content_hash)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_integration_definition_current
  ON integration_definitions(project_id, integration_key) WHERE status = 'active';

CREATE TABLE IF NOT EXISTS integration_connections (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  integration_definition_id TEXT NOT NULL REFERENCES integration_definitions(id),
  connection_key TEXT NOT NULL,
  scope_type TEXT NOT NULL CHECK (scope_type IN ('org', 'workspace', 'project')),
  scope_id TEXT NOT NULL,
  owner_ref TEXT NOT NULL,
  secret_ref_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  granted_capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,
  data_boundaries JSONB NOT NULL DEFAULT '[]'::jsonb,
  max_risk_tier INTEGER NOT NULL DEFAULT 1 CHECK (max_risk_tier BETWEEN 0 AND 3),
  health_status TEXT NOT NULL DEFAULT 'pending'
    CHECK (health_status IN ('pending', 'healthy', 'degraded', 'stale', 'failed', 'revoked')),
  health_checked_at TIMESTAMPTZ,
  freshness_seconds INTEGER NOT NULL DEFAULT 3600 CHECK (freshness_seconds > 0),
  rate_limit_state JSONB NOT NULL DEFAULT '{}'::jsonb,
  provenance JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'active', 'disabled', 'revoked')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, connection_key)
);
CREATE INDEX IF NOT EXISTS idx_integration_connections_project
  ON integration_connections(project_id, status, health_status, updated_at DESC);

CREATE TABLE IF NOT EXISTS capability_resolutions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  integration_connection_id TEXT REFERENCES integration_connections(id),
  skill_id TEXT NOT NULL,
  actor_ref TEXT NOT NULL,
  workflow_step_ref TEXT,
  agent_group_version_ref TEXT,
  requested_data_boundary TEXT NOT NULL,
  risk_tier INTEGER NOT NULL CHECK (risk_tier BETWEEN 0 AND 3),
  authority_inputs JSONB NOT NULL,
  decision TEXT NOT NULL CHECK (decision IN ('allowed', 'denied')),
  denial_reasons JSONB NOT NULL DEFAULT '[]'::jsonb,
  resolved_contract JSONB NOT NULL DEFAULT '{}'::jsonb,
  dedupe_key TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_capability_resolutions_project
  ON capability_resolutions(project_id, created_at DESC);

-- BOSS-129: reusable collaboration protocols. Panels may reference this
-- runtime, but consensus remains advisory unless evidence/policy gates pass.
CREATE TABLE IF NOT EXISTS agent_group_specs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  group_key TEXT NOT NULL,
  name TEXT NOT NULL,
  purpose TEXT NOT NULL,
  owner_ref TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'active', 'retired')),
  active_version_id TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, group_key)
);

CREATE TABLE IF NOT EXISTS agent_group_versions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_group_spec_id TEXT NOT NULL REFERENCES agent_group_specs(id) ON DELETE CASCADE,
  version INTEGER NOT NULL CHECK (version > 0),
  status TEXT NOT NULL DEFAULT 'draft'
    CHECK (status IN ('draft', 'published', 'retired')),
  topology TEXT NOT NULL
    CHECK (topology IN ('panel', 'producer_reviewer', 'bounded_debate', 'swarm', 'fan_out', 'sequential_handoff')),
  members JSONB NOT NULL,
  collaboration_protocol JSONB NOT NULL,
  allowed_capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,
  context_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  independence_policy JSONB NOT NULL DEFAULT '{}'::jsonb,
  bounds JSONB NOT NULL,
  completion_rule JSONB NOT NULL,
  escalation_target TEXT NOT NULL,
  content_hash TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  published_at TIMESTAMPTZ,
  UNIQUE(agent_group_spec_id, version),
  UNIQUE(agent_group_spec_id, content_hash)
);
CREATE INDEX IF NOT EXISTS idx_agent_group_versions_project
  ON agent_group_versions(project_id, status, created_at DESC);

CREATE TABLE IF NOT EXISTS agent_group_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_group_version_id TEXT NOT NULL REFERENCES agent_group_versions(id),
  assurance_case_id TEXT REFERENCES assurance_cases(id),
  workflow_run_id TEXT REFERENCES workflow_runs(id),
  task_id TEXT REFERENCES tasks(id),
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'running', 'waiting', 'blocked', 'completed', 'failed', 'deadlettered', 'cancelled')),
  input JSONB NOT NULL,
  context JSONB NOT NULL DEFAULT '{}'::jsonb,
  policy_snapshot JSONB NOT NULL,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  dissent JSONB NOT NULL DEFAULT '[]'::jsonb,
  total_cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  budget_reservation_id TEXT REFERENCES budget_reservations(id),
  receipt_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  dedupe_key TEXT NOT NULL,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  deadline_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  UNIQUE(project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_agent_group_runs_project
  ON agent_group_runs(project_id, status, updated_at DESC);
ALTER TABLE agent_group_runs ADD COLUMN IF NOT EXISTS budget_reservation_id TEXT REFERENCES budget_reservations(id);
ALTER TABLE agent_group_runs ADD COLUMN IF NOT EXISTS deadline_at TIMESTAMPTZ;

CREATE TABLE IF NOT EXISTS agent_group_member_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_group_run_id TEXT NOT NULL REFERENCES agent_group_runs(id) ON DELETE CASCADE,
  member_key TEXT NOT NULL,
  role_key TEXT NOT NULL,
  job_id TEXT REFERENCES jobs(id),
  status TEXT NOT NULL DEFAULT 'queued'
    CHECK (status IN ('queued', 'leased', 'running', 'completed', 'failed', 'blocked', 'timed_out', 'deadlettered', 'cancelled')),
  independent BOOLEAN NOT NULL DEFAULT true,
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  artifacts JSONB NOT NULL DEFAULT '[]'::jsonb,
  messages JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  receipt_refs JSONB NOT NULL DEFAULT '[]'::jsonb,
  cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  error JSONB NOT NULL DEFAULT '{}'::jsonb,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(agent_group_run_id, member_key)
);
CREATE INDEX IF NOT EXISTS idx_agent_group_member_runs_group
  ON agent_group_member_runs(agent_group_run_id, status, created_at);

-- Durable Worker Fabric inventory. Registration is informational; leases remain
-- the execution fence in jobs and cannot be granted by this registry.
CREATE TABLE IF NOT EXISTS worker_registrations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  worker_id TEXT NOT NULL,
  capabilities JSONB NOT NULL DEFAULT '[]'::jsonb,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'offline', 'draining')),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, worker_id)
);
CREATE INDEX IF NOT EXISTS idx_worker_registrations_liveness
  ON worker_registrations(project_id, status, last_seen_at DESC);

CREATE TABLE IF NOT EXISTS provider_slo_definitions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  provider TEXT NOT NULL,
  provider_account_id TEXT REFERENCES provider_accounts(id),
  metric_key TEXT NOT NULL,
  -- availability | healthy_ratio | api_available | cost_usd_micros | sample_count
  target DOUBLE PRECISION NOT NULL,
  window_seconds INTEGER NOT NULL DEFAULT 3600,
  comparator TEXT NOT NULL DEFAULT 'gte',
  -- gte | lte | gt | lt | eq
  status TEXT NOT NULL DEFAULT 'unknown',
  -- cached last evaluation: ok | breached | unknown
  last_value DOUBLE PRECISION,
  evaluated_at TIMESTAMPTZ,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- Expression unique index so NULL provider_account_id still dedupes correctly.
CREATE UNIQUE INDEX IF NOT EXISTS uq_provider_slo_definitions_key
  ON provider_slo_definitions (
    project_id,
    provider,
    COALESCE(provider_account_id, ''),
    metric_key,
    window_seconds
  );
CREATE INDEX IF NOT EXISTS idx_provider_slo_definitions_project
  ON provider_slo_definitions(project_id, provider, status);

CREATE TABLE IF NOT EXISTS provider_slo_evaluations (
  id TEXT PRIMARY KEY,
  definition_id TEXT NOT NULL REFERENCES provider_slo_definitions(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id),
  provider TEXT NOT NULL,
  provider_account_id TEXT REFERENCES provider_accounts(id),
  metric_key TEXT NOT NULL,
  target DOUBLE PRECISION NOT NULL,
  window_seconds INTEGER NOT NULL,
  comparator TEXT NOT NULL,
  status TEXT NOT NULL,
  -- ok | breached | unknown
  last_value DOUBLE PRECISION,
  evaluated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_provider_slo_evaluations_def
  ON provider_slo_evaluations(definition_id, evaluated_at DESC);
CREATE INDEX IF NOT EXISTS idx_provider_slo_evaluations_project
  ON provider_slo_evaluations(project_id, provider, status, evaluated_at DESC);

-- Platform ops: on-call SRE
CREATE TABLE IF NOT EXISTS oncall_schedules (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  layers JSONB NOT NULL DEFAULT '[]'::jsonb,
  enabled BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
CREATE INDEX IF NOT EXISTS idx_oncall_schedules_project
  ON oncall_schedules(project_id, enabled);

CREATE TABLE IF NOT EXISTS oncall_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  schedule_id TEXT,
  steps JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
CREATE INDEX IF NOT EXISTS idx_oncall_policies_project
  ON oncall_policies(project_id);

CREATE TABLE IF NOT EXISTS oncall_pages (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  reliability_incident_id TEXT,
  dedupe_key TEXT NOT NULL,
  title TEXT NOT NULL,
  severity TEXT NOT NULL DEFAULT 'warning',
  status TEXT NOT NULL DEFAULT 'open',
  schedule_id TEXT,
  policy_id TEXT,
  current_step INTEGER NOT NULL DEFAULT 0,
  assignee TEXT NOT NULL DEFAULT '',
  service TEXT NOT NULL DEFAULT '',
  kg_node_id TEXT,
  kg_node_key TEXT,
  adapter TEXT NOT NULL DEFAULT 'slack_webhook',
  notify_result JSONB NOT NULL DEFAULT '{}'::jsonb,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  acked_at TIMESTAMPTZ,
  resolved_at TIMESTAMPTZ,
  UNIQUE (project_id, dedupe_key)
);
CREATE INDEX IF NOT EXISTS idx_oncall_pages_project
  ON oncall_pages(project_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_oncall_pages_incident
  ON oncall_pages(project_id, reliability_incident_id);

-- AI SRE runbooks (validate + Decision; not GA)
CREATE TABLE IF NOT EXISTS sre_runbooks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  steps JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
CREATE INDEX IF NOT EXISTS idx_sre_runbooks_project
  ON sre_runbooks(project_id, name);

CREATE TABLE IF NOT EXISTS sre_runbook_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  runbook_id TEXT NOT NULL REFERENCES sre_runbooks(id),
  incident_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'queued',
  decision_id TEXT,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_sre_runbook_runs_project
  ON sre_runbook_runs(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sre_runbook_runs_runbook
  ON sre_runbook_runs(project_id, runbook_id, created_at DESC);


-- Platform ops: release planning
CREATE TABLE IF NOT EXISTS release_plans (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  target_date DATE,
  status TEXT NOT NULL DEFAULT 'planned',
  item_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  issue_links JSONB NOT NULL DEFAULT '[]'::jsonb,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_release_plans_project
  ON release_plans(project_id, target_date NULLS LAST, created_at DESC);

CREATE TABLE IF NOT EXISTS release_board_items (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  column_key TEXT NOT NULL,
  source_type TEXT NOT NULL,
  source_id TEXT NOT NULL,
  title TEXT NOT NULL,
  status TEXT,
  external_url TEXT,
  tracker TEXT,
  issue_key TEXT,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, source_type, source_id),
  CHECK (column_key IN ('built', 'building', 'planned', 'blocked'))
);
CREATE INDEX IF NOT EXISTS idx_release_board_items_project_col
  ON release_board_items(project_id, column_key, sort_order, updated_at DESC);


-- Platform ops: worker autoscaling
CREATE TABLE IF NOT EXISTS worker_autoscaling_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  pool_key TEXT NOT NULL DEFAULT 'default',
  enabled BOOLEAN NOT NULL DEFAULT true,
  min_workers INTEGER NOT NULL DEFAULT 0,
  max_workers INTEGER NOT NULL DEFAULT 8,
  scale_up_threshold INTEGER NOT NULL DEFAULT 1,
  cooldown_seconds INTEGER NOT NULL DEFAULT 30,
  max_queue_depth_per_worker INTEGER NOT NULL DEFAULT 5,
  kind TEXT NOT NULL DEFAULT 'local',
  provider_account_id TEXT REFERENCES provider_accounts(id) ON DELETE SET NULL,
  metadata JSONB NOT NULL DEFAULT '{}'::jsonb,
  last_applied_at TIMESTAMPTZ,
  last_scale_direction TEXT,
  created_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, pool_key)
);
CREATE INDEX IF NOT EXISTS idx_worker_autoscaling_policies_project
  ON worker_autoscaling_policies(project_id, enabled, pool_key);

CREATE TABLE IF NOT EXISTS worker_autoscaling_history (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  pool_key TEXT NOT NULL,
  action TEXT NOT NULL,
  status TEXT NOT NULL,
  queue_depth INTEGER NOT NULL DEFAULT 0,
  leased_jobs INTEGER NOT NULL DEFAULT 0,
  running_jobs INTEGER NOT NULL DEFAULT 0,
  desired_workers INTEGER NOT NULL DEFAULT 0,
  actual_workers INTEGER NOT NULL DEFAULT 0,
  previous_desired INTEGER NOT NULL DEFAULT 0,
  receipt_id TEXT REFERENCES receipts(id) ON DELETE SET NULL,
  elastic_result JSONB NOT NULL DEFAULT '{}'::jsonb,
  reason TEXT,
  actor TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_worker_autoscaling_history_project
  ON worker_autoscaling_history(project_id, pool_key, created_at DESC);


-- Platform ops: token efficiency policies
CREATE TABLE IF NOT EXISTS token_budget_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  stage TEXT NOT NULL DEFAULT '*',
  max_prompt_tokens INTEGER,
  max_completion_tokens INTEGER,
  max_total_tokens_per_call INTEGER,
  max_tokens_per_day BIGINT,
  max_cost_usd_micros_per_day BIGINT,
  alert_at_pct NUMERIC NOT NULL DEFAULT 0.80,
  preferred_model_class TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  version INTEGER NOT NULL DEFAULT 1,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, stage),
  CHECK (preferred_model_class IS NULL
         OR preferred_model_class IN ('low_cost', 'strong')),
  CHECK (alert_at_pct > 0 AND alert_at_pct <= 1)
);
CREATE INDEX IF NOT EXISTS idx_token_budget_policies_project
  ON token_budget_policies (project_id, stage);


-- BOSS-11: durable persistent preview sandbox reservations (Workload B)
CREATE TABLE IF NOT EXISTS preview_sandboxes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  app_id TEXT NOT NULL,
  run_id TEXT,
  repo TEXT,
  branch TEXT,
  image_or_build TEXT,
  run_cmd TEXT,
  env_json JSONB NOT NULL DEFAULT '{}'::jsonb,
  port INTEGER,
  status TEXT NOT NULL DEFAULT 'pending',
  host_ref TEXT,
  url TEXT,
  internal_url TEXT,
  error TEXT,
  simulate BOOLEAN NOT NULL DEFAULT false,
  ttl_seconds INTEGER NOT NULL DEFAULT 3600,
  expires_at TIMESTAMPTZ,
  last_heartbeat_at TIMESTAMPTZ,
  reserved_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, app_id)
);
CREATE INDEX IF NOT EXISTS idx_preview_sandboxes_project
  ON preview_sandboxes (project_id, created_at DESC);

-- Agent KMS (agent ownership, grants, leases)
CREATE TABLE IF NOT EXISTS agent_key_entries (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  secret_ref_id TEXT NOT NULL,
  owner_agent TEXT NOT NULL,
  purpose TEXT NOT NULL DEFAULT 'general',
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'active',
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
CREATE INDEX IF NOT EXISTS idx_agent_key_entries_project
  ON agent_key_entries(project_id, owner_agent, status);

CREATE TABLE IF NOT EXISTS agent_key_grants (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  key_entry_id TEXT NOT NULL REFERENCES agent_key_entries(id) ON DELETE CASCADE,
  grantee_agent TEXT NOT NULL,
  permissions JSONB NOT NULL DEFAULT '[]'::jsonb,
  granted_by TEXT NOT NULL,
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (key_entry_id, grantee_agent)
);
CREATE INDEX IF NOT EXISTS idx_agent_key_grants_grantee
  ON agent_key_grants(project_id, grantee_agent);

CREATE TABLE IF NOT EXISTS agent_key_leases (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  key_entry_id TEXT NOT NULL,
  secret_ref_id TEXT NOT NULL,
  agent_id TEXT NOT NULL,
  purpose TEXT NOT NULL DEFAULT '',
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  reveal_count INT NOT NULL DEFAULT 0,
  max_reveals INT NOT NULL DEFAULT 1,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_key_leases_agent
  ON agent_key_leases(project_id, agent_id, expires_at);

-- BOSS-378 slice 6: Project Manager steward (operate / test / validate / propose)
CREATE TABLE IF NOT EXISTS process_managers (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'active',
  last_tick_at TIMESTAMPTZ,
  last_metrics JSONB NOT NULL DEFAULT '{}'::jsonb,
  last_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id)
);
CREATE INDEX IF NOT EXISTS idx_process_managers_project
  ON process_managers(project_id, status);

CREATE TABLE IF NOT EXISTS process_manager_ticks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  observed JSONB NOT NULL DEFAULT '{}'::jsonb,
  planned JSONB NOT NULL DEFAULT '[]'::jsonb,
  applied JSONB NOT NULL DEFAULT '[]'::jsonb,
  rejected JSONB NOT NULL DEFAULT '[]'::jsonb,
  metrics JSONB NOT NULL DEFAULT '{}'::jsonb,
  receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_process_manager_ticks_project
  ON process_manager_ticks(project_id, created_at DESC);

CREATE TABLE IF NOT EXISTS process_manager_proposals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  status TEXT NOT NULL DEFAULT 'proposed',
  spec_diff JSONB NOT NULL DEFAULT '{}'::jsonb,
  reason TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_process_manager_proposals_project
  ON process_manager_proposals(project_id, created_at DESC);

-- ─────────────────────────────────────────────────────────────────────────────
-- Fleet: a VM is a first-class object.
--
-- Before this, the host lived as a string inside every deployment_target's
-- `target_ref` ("root@192.0.2.202:22"). Ten apps on one VM meant ten copies of that
-- string and ten secret bindings to the SAME key, nowhere to ask "what runs on this
-- box?", and a key rotation that meant editing ten rows. The host is the thing that
-- has credentials, an architecture and a port budget — not the app.
--
-- `target_ref` is NOT dropped. It stays as a derived projection of the host so every
-- existing connector, `_split_ref` call and test keeps working untouched; host_id
-- becomes the source of truth and target_ref is written from it.
-- Design: docs/product/DEPLOYMENT_FLEET_AND_APPROVAL_FLOW.md
CREATE TABLE IF NOT EXISTS deployment_hosts (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  address TEXT NOT NULL,
  ssh_user TEXT NOT NULL DEFAULT 'root',
  ssh_port INTEGER NOT NULL DEFAULT 22,
  -- ONE key per host. This is the whole point of the table.
  key_secret_ref TEXT REFERENCES secret_refs(id),
  -- Not decoration: hetzner-tenant-01 is arm64 and hetzner-ci-01 is amd64. An image
  -- built for the wrong one fails as a confusing runtime crash, not a deploy error,
  -- so the build step reads this.
  arch TEXT,
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- Port budget for apps co-located on this host. `bootstrap` already picks a free
  -- port; this bounds where it may look.
  port_min INTEGER NOT NULL DEFAULT 8000,
  port_max INTEGER NOT NULL DEFAULT 8999,
  max_apps INTEGER,
  -- registered: known, no verified credential yet
  -- verified:   preflight passed; selectable as a deploy destination
  -- degraded:   was verified, last preflight failed
  -- retired:    do not schedule here
  status TEXT NOT NULL DEFAULT 'registered',
  last_preflight_at TIMESTAMPTZ,
  last_preflight JSONB NOT NULL DEFAULT '{}'::jsonb,
  notes TEXT,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, name)
);
-- The host's PINNED key (services/host_key_pin.py): recorded by Verify (or, for a host verified
-- before pinning, by its first governed deploy) and enforced with StrictHostKeyChecking=yes.
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS host_key_known_hosts TEXT;
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS host_key_fingerprint TEXT;
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS host_key_pinned_at TIMESTAMPTZ;
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS host_key_pinned_by TEXT;
CREATE INDEX IF NOT EXISTS idx_deployment_hosts_project
  ON deployment_hosts(project_id, status, created_at DESC);

-- ADD A SERVER (agentic-factory 3-add-a-server.html; services/add_server.py): a server that sets
-- itself up. One row per host added through Add a server: what it is for (a ROLE, never an app),
-- how access was handed over, what to set up, and where the agent is — key landed, read, install,
-- verify, ready, watching — with a short log. The host itself stays in deployment_hosts; this is
-- the agent's progress on it and, once ready, the Infra agent's watch of its health.
CREATE TABLE IF NOT EXISTS server_setups (
  host_id TEXT PRIMARY KEY REFERENCES deployment_hosts(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL DEFAULT 'ssh',
  role TEXT NOT NULL DEFAULT 'staging',
  access TEXT NOT NULL DEFAULT 'boss_key',
  setup JSONB NOT NULL DEFAULT '{}'::jsonb,
  watch JSONB NOT NULL DEFAULT '{}'::jsonb,
  owner TEXT NOT NULL DEFAULT 'infra',
  phase TEXT NOT NULL DEFAULT 'key',
  blocked TEXT,
  facts JSONB NOT NULL DEFAULT '{}'::jsonb,
  steps JSONB NOT NULL DEFAULT '{}'::jsonb,
  log JSONB NOT NULL DEFAULT '[]'::jsonb,
  probe JSONB NOT NULL DEFAULT '{}'::jsonb,
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ,
  watch_next_at TIMESTAMPTZ,
  key_landed_at TIMESTAMPTZ,
  ready_at TIMESTAMPTZ,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_server_setups_due ON server_setups(phase, next_attempt_at);

-- The app -> VM edge. Nullable so existing targets keep working before backfill.
ALTER TABLE deployment_targets
  ADD COLUMN IF NOT EXISTS host_id TEXT REFERENCES deployment_hosts(id);
CREATE INDEX IF NOT EXISTS idx_deployment_targets_host
  ON deployment_targets(host_id);

-- Which repo paths belong to this app. [] means "the whole repo" so single-app repos
-- behave exactly as before. This is what lets ONE merge fan out to N apps on N hosts.
ALTER TABLE deployment_targets
  ADD COLUMN IF NOT EXISTS path_globs JSONB NOT NULL DEFAULT '[]'::jsonb;

-- The PUBLIC half of this host's key, kept so the install command can be shown again without
-- minting a new one. Losing the command on a page refresh left "Generate key" as the only
-- apparent way back — and that ROTATES, invalidating the command the operator was part-way
-- through running. A public key is not a secret; the private half stays in the backend.
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS key_public TEXT;

-- Where the OPERATOR's own admin key lives on their machine, so the install command can be
-- rendered with the right `-i`. BOSS cannot discover this — a laptop with no default identity
-- fails the push with "Permission denied (publickey)", which looks identical to BOSS's key not
-- being installed and sends people to debug the wrong machine. Optional; blank means "my
-- default SSH access works".
ALTER TABLE deployment_hosts ADD COLUMN IF NOT EXISTS admin_identity_file TEXT;

-- Encrypted secret material, so a generated credential survives the process that made it.
--
-- Every other local backend writes under BOSS_SECRETS_DIR — the CONTAINER's filesystem on a
-- containerised install. Deploying BOSS destroyed every host key it had generated: the
-- deployment_hosts row still claimed a bound credential, and the secret it referenced was
-- gone. Ciphertext only; the master key stays in the environment, so a database dump is not
-- a key compromise.
CREATE TABLE IF NOT EXISTS secret_material (
  ref_key TEXT PRIMARY KEY,
  ciphertext BYTEA NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The activity log unions five sources newest-first per project. `events` had the index for
-- that; the others did not, so bounding their queries would still have meant a sequential scan
-- and a sort. Same shape as idx_events_project_created, for the same reader.
CREATE INDEX IF NOT EXISTS idx_receipts_project_created
  ON receipts(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_process_steps_project_created
  ON agent_process_steps(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_deadletters_project_created
  ON deadletters(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_jobs_project_created
  ON jobs(project_id, created_at DESC);
-- The log reads every stream newest-first by keyset (activity_sql). A workflow step is dated
-- when it RAN, so its index is on that expression, not on created_at; deployments led with
-- `status`; app output with no project is half of app_logs' reads and had no index at all.
CREATE INDEX IF NOT EXISTS idx_workflow_step_runs_project_ran
  ON workflow_step_runs(project_id, (COALESCE(completed_at, started_at, created_at)) DESC);
CREATE INDEX IF NOT EXISTS idx_deployment_runs_project_created
  ON deployment_runs(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_app_logs_unowned_created
  ON app_logs(created_at DESC) WHERE project_id IS NULL;


-- Project-level gate autonomy: whether small, reversible, well-understood gates may approve
-- themselves. Distinct from `autonomy_changes`, which is per-ROLE capability.
--
-- Supervised is the default and is never implied: a project with no row here is supervised,
-- and Full auto has to be turned on, by someone, on purpose. The row records who and when,
-- because reducing human oversight is itself an act with an owner.
CREATE TABLE IF NOT EXISTS console_autonomy (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  mode TEXT NOT NULL DEFAULT 'supervised',
  threshold_usd DOUBLE PRECISION NOT NULL DEFAULT 500,
  max_risk_tier INTEGER NOT NULL DEFAULT 1,
  set_by TEXT,
  set_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Knobs an operator can turn WITHOUT a deploy.
--
-- Everything that governs how hard BOSS runs — how many agents at once, how much it may
-- spend, how long a lease lives — lived in environment variables, which means changing one is
-- an ops action with a container restart behind it. That is the right home for a secret and
-- the wrong home for a dial somebody wants to try at 20 and then at 5.
--
-- Per project, because two projects on one deployment should be able to run at different
-- intensities. Values are JSON so a knob can grow from a number into a shape without a
-- migration, and the runtime falls back to the environment when a project has said nothing.
CREATE TABLE IF NOT EXISTS project_settings (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  key TEXT NOT NULL,
  value JSONB NOT NULL,
  updated_by TEXT NOT NULL DEFAULT 'operator',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, key)
);

-- The same, for a setting that is the whole ORG's: set once, and every project of the org uses
-- it (the embedding model, knowledge/embedding_slot.py — "so all projects can use it").
CREATE TABLE IF NOT EXISTS org_settings (
  org_id TEXT NOT NULL REFERENCES orgs(id) ON DELETE CASCADE,
  key TEXT NOT NULL,
  value JSONB NOT NULL,
  updated_by TEXT NOT NULL DEFAULT 'operator',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, key)
);

-- ONE-TIME DATA STEPS, each run on the first apply that knows it and never again (the key is
-- recorded in the same statement). A schema re-applied on every deploy cannot otherwise tell
-- "an install that existed before this change" from "a project created since".
CREATE TABLE IF NOT EXISTS schema_once (
  key TEXT PRIMARY KEY,
  applied_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- THE CAPTAIN'S OWN IMPROVE PASSES ARE OPT-IN (first-run walk, 2026-10-10; Settings
-- .captain_auto_improve defaults to 0). Every project that already existed when this first ran
-- had them on, so it keeps them on: an upgrade changes nothing. A new install has no projects at
-- this point, records the key, and its projects start with the passes off (Govern turns them on).
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_once WHERE key = 'captain_auto_improve_kept_for_existing') THEN
    INSERT INTO project_settings (project_id, key, value, updated_by)
    SELECT id, 'captain_auto_improve', '1'::jsonb, 'upgrade' FROM projects
    ON CONFLICT (project_id, key) DO NOTHING;
    INSERT INTO schema_once (key) VALUES ('captain_auto_improve_kept_for_existing')
    ON CONFLICT (key) DO NOTHING;
  END IF;
END $$;

-- MODELS ARE THE ORG'S (engine/boss_engine/services/org_models.py, banking case study 2026-10-24:
-- projects created after boss-dogfood had no model and answered "none is answering"). An org with
-- no model configuration of its own adopts its most-configured project's (most model knobs, then
-- most connections, then the oldest): those knobs become the org's `models.<knob>` rows and leave
-- that project (they were never an override), and it becomes the org's model home, whose
-- connections the API mirrors into every project of the org at start (org_models.sync_all). Other
-- projects' own model knobs stay as their overrides. Runs once; an org that already has model
-- rows is left alone.
DO $$
DECLARE
  pick RECORD;
  model_keys TEXT[] := ARRAY['code_agent_engine', 'code_agent_model', 'code_review_engine',
    'code_review_model', 'code_agent_strong_engine', 'code_agent_strong_model',
    'code_agent_low_cost_engine', 'code_agent_low_cost_model', 'codex_cli_model',
    'claude_cli_model', 'chat_llm_engine', 'chat_model', 'model_routing_mode',
    'decision_backend', 'decision_model', 'anthropic_credential_order'];
BEGIN
  IF NOT EXISTS (SELECT 1 FROM schema_once WHERE key = 'org_models_adopted_from_project') THEN
    FOR pick IN
      SELECT DISTINCT ON (r.org_id) r.org_id, r.project_id
        FROM (SELECT w.org_id, p.id AS project_id, p.created_at,
                     (SELECT count(*) FROM project_settings s
                       WHERE s.project_id = p.id AND s.key = ANY(model_keys)) AS knobs,
                     (SELECT count(*) FROM entitlement_sources e
                       WHERE e.project_id = p.id AND e.source_id NOT LIKE 'proof-%'
                         AND (e.connection_status = 'connected'
                              OR (e.credential_secret_ref_id IS NOT NULL
                                  AND e.connection_status <> 'revoked'))) AS sources
                FROM projects p JOIN workspaces w ON w.id = p.workspace_id) r
       WHERE (r.knobs > 0 OR r.sources > 0)
         AND NOT EXISTS (SELECT 1 FROM org_settings o
                          WHERE o.org_id = r.org_id AND o.key LIKE 'models.%')
       ORDER BY r.org_id, r.knobs DESC, r.sources DESC, r.created_at, r.project_id
    LOOP
      INSERT INTO org_settings (org_id, key, value, updated_by)
      SELECT pick.org_id, 'models.' || s.key, s.value, 'upgrade'
        FROM project_settings s
       WHERE s.project_id = pick.project_id AND s.key = ANY(model_keys)
      ON CONFLICT (org_id, key) DO NOTHING;
      DELETE FROM project_settings
       WHERE project_id = pick.project_id AND key = ANY(model_keys);
      INSERT INTO org_settings (org_id, key, value, updated_by)
      VALUES (pick.org_id, 'models.home', jsonb_build_object('project_id', pick.project_id), 'upgrade')
      ON CONFLICT (org_id, key) DO NOTHING;
    END LOOP;
    INSERT INTO schema_once (key) VALUES ('org_models_adopted_from_project')
    ON CONFLICT (key) DO NOTHING;
  END IF;
END $$;

-- workflow_custom_steps.knowledge, for databases created before it existed. The CREATE above
-- covers a fresh install; this covers every deployment that already has the table.
ALTER TABLE workflow_custom_steps ADD COLUMN IF NOT EXISTS knowledge TEXT;

-- The org chart somebody DECIDED, as opposed to the one BOSS observed.
--
-- The chart was derived entirely from handoffs: who passed work to whom in the last week. That
-- is honest and it is useful, and it is also unchangeable — an operator looking at it could not
-- say "the QA lead reports to the captain" or "add a security reviewer", because the chart was
-- a measurement, not a structure. A measurement nobody can act on is a report.
--
-- Declared edges take precedence and observed ones remain visible underneath, so the chart
-- shows both what was intended and what actually happened. Where they disagree is the most
-- interesting thing on the page.
CREATE TABLE IF NOT EXISTS org_assignments (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  agent_id TEXT NOT NULL,                    -- role key: engineering_captain, qa, ...
  reports_to TEXT,                           -- another agent_id, or NULL for a root
  display_name TEXT,                         -- what this team calls the role
  sort INTEGER NOT NULL DEFAULT 0,
  updated_by TEXT NOT NULL DEFAULT 'operator',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, agent_id)
);
CREATE INDEX IF NOT EXISTS idx_org_assignments_reports_to
  ON org_assignments(project_id, reports_to);


-- A STANDARD A ROLE MANDATED, rather than one hardcoded in the platform.
--
-- `platform_standards` shipped as Python constants: observability, and nothing else. That is
-- right for rules the platform itself guarantees, and it means the Security role can sit in
-- every panel, conclude that ports must be checked for public exposure before they are
-- assigned, say so — and have it apply to precisely nothing. The conclusion lived in one
-- meeting's minutes and the next build never saw it.
--
-- A standard here is injected into every pipeline stage of every matching build, exactly like
-- the hardcoded ones. That is what makes an agent's mandate durable instead of advisory.
--
-- `project_id IS NULL` means EVERY project: the case the operator asked for — "something that
-- applies common to all projects". A row scoped to one project is the one-off.
CREATE TABLE IF NOT EXISTS engineering_standards (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,   -- NULL = all projects
  standard_key TEXT NOT NULL,
  title TEXT NOT NULL,
  body TEXT NOT NULL,
  -- Which builds it applies to. 'service' uses the same test as the observability standard;
  -- 'all' reaches libraries and CLIs too, which most operational rules should NOT.
  scope TEXT NOT NULL DEFAULT 'service' CHECK (scope IN ('service', 'all')),
  -- WHO MANDATED IT. A standard with no author cannot be argued with, and the first question
  -- about any rule is who decided it and why.
  mandated_by_role TEXT NOT NULL,
  rationale TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'retired')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, standard_key)
);
CREATE INDEX IF NOT EXISTS idx_engineering_standards_active
  ON engineering_standards(status, project_id);
-- UNIQUE (project_id, standard_key) does NOT constrain the all-projects rows: Postgres treats
-- NULLs as distinct, so 'mandate this everywhere' twice would insert twice and the rule would
-- appear in every prompt in duplicate. This index is what actually enforces one row per key.
CREATE UNIQUE INDEX IF NOT EXISTS idx_engineering_standards_global_key
  ON engineering_standards(standard_key) WHERE project_id IS NULL;

-- WHAT BOSS IS DOING RIGHT NOW, WHILE IT IS DOING IT.
--
-- A chat turn is ONE HTTP request: the tool calls are known only when it returns, so a turn
-- that chains eight lookups shows the operator a pulsing dot for two minutes and nothing else.
-- That was survivable when the average answer used 2.86 tools. The reliability work deliberately
-- raises that floor, which makes the silence longer — so the silence has to go first.
--
-- Written on its OWN connection and committed per row: the turn's transaction has not committed
-- yet, so anything written on it is invisible to the poller until the answer is already there,
-- which is precisely too late.
--
-- Deliberately tiny and disposable. It is a progress indicator, not a record — `agent_turns` and
-- the message trail are where the durable account lives.
CREATE TABLE IF NOT EXISTS agent_progress (
  id BIGSERIAL PRIMARY KEY,
  thread_id TEXT NOT NULL,
  project_id TEXT,
  label TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_progress_thread
  ON agent_progress(thread_id, id DESC);

-- BOSS debugging the way an engineer debugs: a real Claude Code session with a shell, the
-- app's repo, read-only SQL and a way onto the fleet. See services/investigation.py for why
-- the chat agent's 73 fixed-shape tools could not do this and never would.
CREATE TABLE IF NOT EXISTS investigations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  thread_id TEXT,
  run_id TEXT,
  question TEXT NOT NULL,
  actor TEXT NOT NULL,
  -- Read-only unless an operator pressed the button. A model cannot license this for itself:
  -- `investigate` with fix set is declared destroys_work, so it comes back as a confirmation.
  allow_fix BOOLEAN NOT NULL DEFAULT FALSE,
  status TEXT NOT NULL DEFAULT 'queued',
  summary TEXT,
  verdict JSONB NOT NULL DEFAULT '{}'::jsonb,
  turns INTEGER,
  duration_ms INTEGER,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  started_at TIMESTAMPTZ,
  finished_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_investigations_project_created
  ON investigations(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_investigations_status
  ON investigations(status) WHERE status IN ('queued', 'running');
-- The sandbox's own credential, minted per investigation and cleared when it finishes.
--
-- The alternative was baking the database URL and a console key into the working directory,
-- which hands a shell a permanent credential and drags the KMS master key along with it. This
-- token authorises exactly one investigation, for as long as it runs, and the endpoints it
-- reaches enforce that investigation's own read/fix mode server-side.
ALTER TABLE investigations ADD COLUMN IF NOT EXISTS token TEXT;
-- The `investigation.run` job it was queued as: only the worker holding that job's lease may spend
-- for it (debug_session.InvestigationSpend). NULL = opened before investigations were governed.
ALTER TABLE investigations ADD COLUMN IF NOT EXISTS job_id TEXT;
CREATE INDEX IF NOT EXISTS idx_investigations_token ON investigations(token)
  WHERE token IS NOT NULL;

-- Which agents are on which piece of work.
--
-- BOSS had no answer to "who is on this". `roles` says an agent EXISTS in a project; a workflow
-- step names an `approver_role` and nothing else; the only implicit assignment is
-- llm_telemetry.STAGE_ROLES, which maps a pipeline stage to a role for COST ATTRIBUTION at
-- write time and is never consulted for scheduling or permission. So the console could show 26
-- agents and not say which of them were working on the app in front of you.
--
-- Keyed on the APP rather than on a run id: an app is re-run, re-tried and re-deployed, and an
-- assignment that evaporated on the second run would be worse than none. `app_key` is
-- naming.identity_key of the app's name, which is how the rest of BOSS decides two names are
-- one app ('Lead‐Triage Inbox' carries a U+2010 hyphen and would not match by string equality).
CREATE TABLE IF NOT EXISTS project_agents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  app_key TEXT NOT NULL,
  app_name TEXT NOT NULL,
  role_key TEXT NOT NULL,
  -- `default` was seeded from the stages that would have run anyway; `operator` was chosen by a
  -- person. Kept apart so "nobody picked these" is answerable, and so re-seeding defaults never
  -- silently removes a human decision.
  source TEXT NOT NULL DEFAULT 'operator',
  assigned_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, app_key, role_key)
);
CREATE INDEX IF NOT EXISTS idx_project_agents_app ON project_agents (project_id, app_key);
CREATE INDEX IF NOT EXISTS idx_project_agents_role ON project_agents (project_id, role_key);

-- ── The memory plane (Kiro gap A0.1 / A0.2) ────────────────────────────────────
--
-- BOSS had 249 tables and not one of them remembered anything an agent was told. Every
-- session started cold, every correction was spent the moment it was given, and the same
-- guidance had to be repeated in each new thread. Kiro Crew's own claim — and the reason it
-- is the first thing in this plan — is that the memory step "is the one that pays".
--
-- THREE KINDS, ONE TABLE. Preferences (how this operator likes to work), project context
-- (what is going on here), and lessons (a rule they taught us). They share a lifecycle and a
-- scope model, so splitting them into three tables would triple the read path for no gain.
--
-- A LESSON IS A RULE, SO IT DOES NOT BIND UNTIL SOMEBODY SAYS SO. This is where BOSS should
-- be stricter than Kiro Crew, which writes lessons straight to disk: a wrong rule quietly
-- steering every future session is worse than having no memory at all. Lessons land as
-- `proposed` and are inert until reviewed; preferences and project notes are `active` on
-- arrival because they inform rather than bind.
CREATE TABLE IF NOT EXISTS agent_memory (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('preference', 'project', 'lesson')),
  -- Who it applies to. `actor`/`role` narrow it to one person or one seat; `project` is the
  -- default because that is the unit an operator thinks in.
  scope TEXT NOT NULL DEFAULT 'project'
    CHECK (scope IN ('org', 'project', 'actor', 'role')),
  -- EMPTY STRING, NOT NULL, and that is load-bearing. Postgres treats NULL as distinct from
  -- NULL in a unique constraint, so a nullable scope_ref would make the dedupe below silently
  -- never fire for project-scoped rows — which is most of them. Caught by a test that asserted
  -- the same correction twice produced one row.
  scope_ref TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL,
  -- Where it came from, so a surprising rule can be traced to the conversation that set it.
  source_thread_id TEXT,
  created_by TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('proposed', 'active', 'retired', 'rejected')),
  reviewed_by TEXT,
  reviewed_at TIMESTAMPTZ,
  -- DECAY, MEASURED RATHER THAN GUESSED. An unbounded memory store is a context-window bomb;
  -- Kiro Crew's answer is time-tiered fidelity. Ours is usage-aware: what gets injected and
  -- then actually mattered is what survives, and `last_used_at` is what the pruner reads.
  use_count INTEGER NOT NULL DEFAULT 0,
  last_used_at TIMESTAMPTZ,
  -- INJECTION IS OPPORTUNITY; USE IS VALUE — counted apart (BOSSAPP-960). `use_count` used to
  -- be bumped on every injection, so whatever got injected ranked higher, got injected again,
  -- and could never be pruned: the loop measured its own output. `injected_count` is how often
  -- a memory was put in front of a model; `use_count` moves only on a real signal of value
  -- (the same thing being taught again).
  injected_count INTEGER NOT NULL DEFAULT 0,
  last_injected_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ,
  -- Dedupe. The same correction said twice must not become two rules that both get injected.
  content_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE(project_id, kind, scope, scope_ref, content_hash)
);
CREATE INDEX IF NOT EXISTS idx_agent_memory_read
  ON agent_memory (project_id, status, kind);
CREATE INDEX IF NOT EXISTS idx_agent_memory_scope
  ON agent_memory (project_id, scope, scope_ref);

-- ── The session ledger (Kiro gap A0.4) ─────────────────────────────────────────
--
-- A durable record of what a long-running session is DOING: the goal, the phase it reached,
-- the concrete next step, the approaches already tried and rejected, and what it produced.
--
-- Its whole purpose is to outlive the conversation's own memory. A long thread has its early
-- turns compacted away, and the first thing to fall out is usually the objective — so the
-- session re-derives it from a transcript that no longer contains it. This is what it reads
-- instead.
--
-- Entries are written as INTENT, NOT STATUS. "add the Windows branch to the permission
-- helper, the test already fails" tells a cold resume what to do; "in progress" does not.
--
-- One row per thread, updated in place. `finished_at` stops a completed ledger being
-- re-injected — a stale ledger quietly steering a session that has moved on is the failure
-- this is built to avoid.
CREATE TABLE IF NOT EXISTS agent_session_ledger (
  thread_id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  goal TEXT NOT NULL,
  phase TEXT,
  next_step TEXT,
  -- What was tried and did not work, so a resume does not repeat it. The single most
  -- expensive thing a cold session does is re-run a failed approach.
  rejected JSONB NOT NULL DEFAULT '[]'::jsonb,
  artifact_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  finished_at TIMESTAMPTZ,
  updated_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_agent_session_ledger_open
  ON agent_session_ledger (project_id, finished_at);

-- ── Work that starts without anybody asking (Kiro gaps A1.2 / A1.3) ───────────
--
-- BOSS could only ever act when someone typed. A question like "keep an eye on this PR and
-- tell me when it is review-ready" had no answer except the operator remembering to come
-- back, and "every weekday at 9, summarise the open work" had none at all: `scheduling.py`
-- is about preemption between jobs, not about starting agent work on a clock.
--
-- ONE TABLE, TWO SHAPES, because they are the same mechanism pointed at different threads:
--
--   * `monitor` wakes IN an existing conversation. It carries the same context and history,
--     so it does not have to be re-briefed each round, and it stops on an exit condition.
--   * `schedule` opens a fresh conversation each time. Briefings, audits, sweeps.
--
-- EVERY WAKE SPENDS MODEL BUDGET, so nothing here starts by itself. A row exists only because
-- an operator asked for it, every row carries a cap, and the caps are backstops against
-- runaway rather than targets — a loop that reaches its cap ran out of rope, it did not finish.
CREATE TABLE IF NOT EXISTS agent_wakeups (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('monitor', 'schedule')),
  -- Set for a monitor: the conversation it wakes inside. Null for a schedule, which opens a
  -- new one per run so a daily briefing does not grow one thread forever.
  thread_id TEXT,
  actor TEXT NOT NULL,
  -- What to do on each wake, in the operator's own words.
  prompt TEXT NOT NULL,
  -- Monitors only. The condition that ENDS the loop, checked by the agent itself: "when the
  -- PR is approved", "when the deploy is healthy". Without one a monitor is just a cron job
  -- that never stops.
  exit_condition TEXT,
  interval_seconds INTEGER,
  -- Schedules only. Deliberately not a cron expression: a half-implemented cron parser is a
  -- worse answer than two explicit fields, and "every weekday at 9" is the shape people ask
  -- for. Days are lowercase three-letter names; an empty list means every day.
  at_time TEXT,
  days JSONB NOT NULL DEFAULT '[]'::jsonb,
  timezone TEXT NOT NULL DEFAULT 'UTC',
  next_wake_at TIMESTAMPTZ NOT NULL,
  cycle INTEGER NOT NULL DEFAULT 0,
  -- 0 means unlimited, which is worth asking for only deliberately.
  max_cycles INTEGER NOT NULL DEFAULT 24,
  -- A wall-clock bound, for a loop whose turns are slow or whose interval is long. Either
  -- bound ends the loop; neither is required.
  deadline_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('active', 'stopped', 'exhausted', 'completed', 'failed')),
  last_ran_at TIMESTAMPTZ,
  last_result TEXT,
  consecutive_failures INTEGER NOT NULL DEFAULT 0,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- The sweeper's only query: what is due. Partial, because a stopped loop is most of the table
-- after a while and none of it is ever due.
CREATE INDEX IF NOT EXISTS idx_agent_wakeups_due
  ON agent_wakeups (next_wake_at) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_agent_wakeups_thread
  ON agent_wakeups (project_id, thread_id);

-- Places an app can be installed. The default is the computer where the
-- community installer ran (`kind = local`). One hardware agent runs on that
-- machine and on every other machine BOSS connects. `agent_state` stays
-- `absent` until that agent install finishes, then `installed`. A machine
-- cannot be `ready` before then. A provider row is an account, not a machine.
-- Inserting a row does not open a socket, an SSH session, or a provider API.
-- `secret_ref` is a reference only. Enroll tokens are not stored; only
-- `hardware_agent_enroll_tokens.token_hash`.
CREATE TABLE IF NOT EXISTS hardware_places (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,
  name TEXT NOT NULL,
  provider_key TEXT,
  status TEXT NOT NULL,
  agent_state TEXT NOT NULL DEFAULT 'absent',
  is_default BOOLEAN NOT NULL DEFAULT false,
  endpoint TEXT,
  hostname TEXT,
  arch TEXT,
  os_name TEXT,
  dependency_report JSONB NOT NULL DEFAULT '{}'::jsonb,
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  secret_ref TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CONSTRAINT hardware_places_kind CHECK (kind IN ('local', 'agent', 'provider')),
  CONSTRAINT hardware_places_status CHECK (status IN ('ready', 'pending', 'retired')),
  CONSTRAINT hardware_places_agent_state CHECK (agent_state IN ('absent', 'installed')),
  CONSTRAINT hardware_places_ready_needs_agent CHECK (
    status <> 'ready' OR agent_state = 'installed'
  ),
  CONSTRAINT hardware_places_provider_key_value CHECK (
    provider_key IS NULL OR provider_key IN ('aws', 'digitalocean', 'generic')
  ),
  CONSTRAINT hardware_places_provider_key CHECK (
    (kind = 'provider') = (provider_key IS NOT NULL)
  ),
  CONSTRAINT hardware_places_local_is_default CHECK ((kind = 'local') = is_default),
  CONSTRAINT hardware_places_local_stays CHECK (kind <> 'local' OR status <> 'retired'),
  CONSTRAINT hardware_places_secret_ref CHECK (
    (kind = 'provider') = (secret_ref IS NOT NULL)
  )
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_hardware_places_one_local
  ON hardware_places (project_id) WHERE kind = 'local';
CREATE INDEX IF NOT EXISTS idx_hardware_places_project
  ON hardware_places (project_id, kind, status);

CREATE TABLE IF NOT EXISTS hardware_agent_enroll_tokens (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  place_id TEXT NOT NULL REFERENCES hardware_places(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  consumed_at TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_hardware_agent_enroll_tokens_place
  ON hardware_agent_enroll_tokens (place_id, consumed_at);

-- ONE PRESS, ONE EFFECT. Every POST/PUT/PATCH/DELETE under /v1/ that carries an
-- Idempotency-Key header is claimed here before its handler runs; a repeat of the same key
-- replays the stored response instead of running again. Keyed by the authenticated principal so
-- one caller's key can never answer for another's. See apps/api/app/idempotency.py for the
-- incidents (two runs from one "Stop and run again", a preview opened twice) and the rules.
CREATE TABLE IF NOT EXISTS api_idempotency_keys (
  principal TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  method TEXT NOT NULL,
  path TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'in_progress',
  status_code INTEGER,
  response_body BYTEA,
  content_type TEXT,
  -- The route's own headers ([[name, value], ...]) so a replayed download keeps its filename.
  response_headers JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  completed_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now() + interval '24 hours',
  PRIMARY KEY (principal, idempotency_key),
  CONSTRAINT api_idempotency_keys_state CHECK (state IN ('in_progress', 'completed')),
  CONSTRAINT api_idempotency_keys_completed_has_status CHECK (
    state <> 'completed' OR status_code IS NOT NULL
  )
);
ALTER TABLE api_idempotency_keys
  ADD COLUMN IF NOT EXISTS response_headers JSONB NOT NULL DEFAULT '[]'::jsonb;
-- A committed voice model intent stays fenced even after a disconnect or API restart.
-- Expiry of generic HTTP bookkeeping cannot prove an accepted provider call did not run.
ALTER TABLE api_idempotency_keys
  ADD COLUMN IF NOT EXISTS durable_effect BOOLEAN NOT NULL DEFAULT FALSE;
CREATE INDEX IF NOT EXISTS idx_api_idempotency_keys_expiry
  ON api_idempotency_keys (expires_at);

-- APPLICATION STACKS, DEPLOYED FROM THEIR OWN boss.deploy.yaml (services/stack_deploy.py).
--
-- A stack target is a deployment_targets row with target_kind 'stack', bound to a fleet host.
-- `manifest_path` overrides boss.deploy.yaml at the repository root; `public_url` is what
-- {target.public_url} fills in and what the console opens after a healthy deploy.
ALTER TABLE deployment_targets ADD COLUMN IF NOT EXISTS manifest_path TEXT;
ALTER TABLE deployment_targets ADD COLUMN IF NOT EXISTS public_url TEXT;

-- One row per planned deployment of a commit to a stack target. Governance lives where it
-- always does (changesets, budget_reservations, resource_receipts, decisions); this row is what
-- the console watches: the steps as they run, a redacted log tail, and the verdict in words.
CREATE TABLE IF NOT EXISTS stack_deployments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  target_id TEXT NOT NULL REFERENCES deployment_targets(id),
  host_id TEXT REFERENCES deployment_hosts(id),
  repository TEXT NOT NULL,
  ref TEXT NOT NULL,
  commit_sha TEXT NOT NULL,
  -- The manifest's summary (names only, never a value) and the text it was parsed from, so the
  -- apply runs exactly what was approved rather than re-reading a branch that has moved.
  manifest JSONB NOT NULL DEFAULT '{}'::jsonb,
  manifest_text TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'planned',
  decision_id TEXT REFERENCES decisions(id),
  changeset_id TEXT REFERENCES changesets(id),
  reservation_id TEXT,
  job_id TEXT,
  steps JSONB NOT NULL DEFAULT '[]'::jsonb,
  log_tail TEXT NOT NULL DEFAULT '',
  open_url TEXT,
  error JSONB,
  failure_reason TEXT,
  preflight JSONB NOT NULL DEFAULT '{}'::jsonb,
  workflow_run_id TEXT,
  code_task_run_id TEXT,
  rollback_of TEXT,
  -- Set the moment an apply begins. A replayed job that finds it set stops instead of
  -- installing twice.
  apply_started_at TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at TIMESTAMPTZ,
  CONSTRAINT stack_deployments_status CHECK (
    status IN ('planned', 'awaiting_approval', 'running', 'healthy', 'failed', 'rejected'))
);
CREATE INDEX IF NOT EXISTS idx_stack_deployments_target
  ON stack_deployments (target_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_stack_deployments_project
  ON stack_deployments (project_id, status, created_at DESC);
-- Where on the host the stack lives (the manifest's dir). Two targets on one host must never
-- share it: each mints its own generated secrets, so the second would rewrite the first's
-- deploy.env under a database initialised with another password. Checked at plan time; the
-- apply also serialises on (host_id, deploy_dir).
ALTER TABLE stack_deployments ADD COLUMN IF NOT EXISTS deploy_dir TEXT;
-- The apply that owns this row right now. Progress and the verdict are written only by the
-- request holding it, so a replay that failed the row cannot be overwritten by a stale apply.
ALTER TABLE stack_deployments ADD COLUMN IF NOT EXISTS apply_token TEXT;
-- Approved but queued behind another deployment writing the same host directory.
ALTER TABLE stack_deployments ADD COLUMN IF NOT EXISTS waiting_on TEXT;
CREATE INDEX IF NOT EXISTS idx_stack_deployments_host_dir
  ON stack_deployments (host_id, deploy_dir);
-- The same commit to the same target is ONE live deployment, however many clicks plan it.
CREATE UNIQUE INDEX IF NOT EXISTS uq_stack_deployments_live_commit
  ON stack_deployments (target_id, commit_sha)
  WHERE status IN ('planned', 'awaiting_approval', 'running');

-- THE PER-MINUTE BURST CAP MEASURES MONEY ACTUALLY SPENT. It sums the cost receipts settled in
-- the last minute (services/budget.py), not reservation estimates: a subscription or local
-- model settles at $0 and never fills the window. This index serves that trailing-window sum.
CREATE INDEX IF NOT EXISTS idx_cost_receipts_project_created
  ON cost_receipts (project_id, created_at);

-- Requests the burst cap made wait, so the longest-waiting one is served first when the
-- window has room again (FIFO, no starvation). One row per waiting request, keyed by its
-- category and reason (stable across the request's retries, even when each retry is a fresh
-- job), and also matched by its job when it has one. A row is live while its holder is
-- expected back (retry_at plus a grace); a granted request deletes its row.
CREATE TABLE IF NOT EXISTS budget_burst_waiters (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  waiter_key TEXT NOT NULL,
  job_id TEXT,
  first_refused_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  retry_at TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_budget_burst_waiters_project
  ON budget_burst_waiters (project_id, first_refused_at);

-- ── AGENT WORLD (docs: agent-world spec §4) ──────────────────────────────────────────────────
-- Phase 0 freezes these shapes so five streams can build against them at once. Nothing writes
-- to them yet; every statement is additive and safe to re-run.
--
-- WHO AN AGENT IS. Identity facts are columns because they are fixed, queryable and the future
-- subject of tokens and policies. The persona is spec JSON (roles.spec.persona), editable and
-- shipped in packs. Version history is not a table: seal_identity() emits `agent.sealed` events.
ALTER TABLE roles ADD COLUMN IF NOT EXISTS agent_id TEXT;           -- 'agt_' + 10 base32 chars, immutable
ALTER TABLE roles ADD COLUMN IF NOT EXISTS born_by TEXT;            -- human actor | 'agent:<agent_id>' | 'spec-pack'
ALTER TABLE roles ADD COLUMN IF NOT EXISTS born_from JSONB NOT NULL DEFAULT '{}'::jsonb;
  -- {kind: pack|template|archetype|blank|clone, module_id?, module_version?, template_key?, archetype?, parent_agent_id?}
ALTER TABLE roles ADD COLUMN IF NOT EXISTS sponsor TEXT;            -- accountable human; default born_by when human
ALTER TABLE roles ADD COLUMN IF NOT EXISTS lifecycle TEXT NOT NULL DEFAULT 'active'
  CHECK (lifecycle IN ('active','paused','retired'));
ALTER TABLE roles ADD COLUMN IF NOT EXISTS identity_version INT NOT NULL DEFAULT 1;
ALTER TABLE roles ADD COLUMN IF NOT EXISTS fingerprint TEXT;        -- sha256 of RFC 8785 canonical {spec, grants[], model_policy}
CREATE UNIQUE INDEX IF NOT EXISTS roles_agent_id_uq ON roles(agent_id) WHERE agent_id IS NOT NULL;

-- WHAT AN AGENT DID, AND WHO HANDED IT THE WORK. One row per unit of work (step, build stage,
-- panel seat, chat turn, approval). Lineage, the Work feed, presence and Credits all read this
-- one ledger instead of stitching eight tables at read time. Append-only, except status,
-- ended_at, tokens, cost and artifacts, which are written once on close.
CREATE TABLE IF NOT EXISTS agent_acts (
  act_id TEXT PRIMARY KEY,                 -- 'act_' + ulid
  project_id TEXT NOT NULL,
  role_key TEXT,                           -- NULL = a human did it ('You' / 'A person')
  agent_id TEXT,                           -- roles.agent_id at the time
  fingerprint TEXT, identity_version INT,  -- definition that acted
  kind TEXT NOT NULL CHECK (kind IN ('run','step','stage','seat','chat','approval','handoff')),
  status TEXT NOT NULL DEFAULT 'active'
    CHECK (status IN ('pending','active','awaiting_input','complete','error','stale','skipped')),
  parent_act_id TEXT REFERENCES agent_acts(act_id),
  root_act_id TEXT NOT NULL,
  handed_by_kind TEXT NOT NULL CHECK (handed_by_kind IN ('person','agent','boss')),
  handed_by_id TEXT,                       -- actor | role_key | NULL for boss
  how TEXT NOT NULL CHECK (how IN ('named','only_holder','only_candidate','model_pick','captain',
       'run_actor','next_stage','seated','asked_by_person','asked_by_agent','approved','started')),
  why TEXT, considered JSONB NOT NULL DEFAULT '[]'::jsonb,
  scope JSONB NOT NULL DEFAULT '{}'::jsonb,   -- {skills:[], mcp:[], tools:[]}
  scope_ok BOOLEAN,                           -- scope ⊆ parent scope (warn now, enforce later)
  accountable TEXT NOT NULL,                  -- the human at the root
  subject_kind TEXT, subject_id TEXT,         -- workflow_step_run | code_task_run | meeting_run | agent_thread | decision | conversation
  workflow_run_id TEXT, step_id TEXT, code_task_run_id TEXT, meeting_run_id TEXT, thread_id TEXT, decision_id TEXT,
  label TEXT NOT NULL,                        -- 'Build · Ship it #182' (precomputed, for feeds)
  artifacts JSONB NOT NULL DEFAULT '[]'::jsonb, -- [{kind: pr|commit|minutes|report, ref, url?}]
  tokens_in INT NOT NULL DEFAULT 0, tokens_out INT NOT NULL DEFAULT 0, cost_usd NUMERIC(12,6) NOT NULL DEFAULT 0,
  reconstructed BOOLEAN NOT NULL DEFAULT false,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(), ended_at TIMESTAMPTZ, receipt_id TEXT
);
CREATE INDEX IF NOT EXISTS agent_acts_role_time ON agent_acts(project_id, role_key, started_at DESC);
CREATE INDEX IF NOT EXISTS agent_acts_root ON agent_acts(root_act_id);
CREATE INDEX IF NOT EXISTS agent_acts_run ON agent_acts(workflow_run_id);
CREATE INDEX IF NOT EXISTS agent_acts_parent ON agent_acts(parent_act_id);
CREATE INDEX IF NOT EXISTS agent_acts_live ON agent_acts(project_id, status) WHERE ended_at IS NULL;
ALTER TABLE llm_calls   ADD COLUMN IF NOT EXISTS act_id TEXT;
ALTER TABLE agent_turns ADD COLUMN IF NOT EXISTS act_id TEXT;
ALTER TABLE agent_messages ADD COLUMN IF NOT EXISTS act_id TEXT;
ALTER TABLE agent_messages ADD COLUMN IF NOT EXISTS fingerprint TEXT;
-- THE OTHER STANDING OFFER. `proposed_actions` restores the buttons a turn put above itself;
-- a turn that stopped short instead ends with ONE resume press (RouterTurn.next_steps --
-- "Keep waiting", "Continue"). That lived only in the HTTP response, so a fresh process
-- (`boss metatron --print '/pick 1'`) or a reloaded console had nothing to press: the offer
-- was real on the server (the wait was really cut short) but nowhere a restored thread could
-- read it back from. Stored per message, exactly like `proposed_actions`.
ALTER TABLE agent_messages ADD COLUMN IF NOT EXISTS next_steps JSONB NOT NULL DEFAULT '[]'::jsonb;
-- A review panel's seats each sign their own work (factory spec §6.4): 1-based, NULL = no panel.
ALTER TABLE agent_acts ADD COLUMN IF NOT EXISTS seat INT;
-- A STOP IS RECORDED AT ONCE, NOT WHEN THE RUN ROW IS FREE (factory test D1). The worker holds
-- the run row while it checks; a Stop that waited on that lock spun for 30s+. The request is its
-- own row, written without touching code_task_runs; every reader says `Stopped by <actor>` from
-- it, and the worker honours it at its next stage boundary (honoured_at).
CREATE TABLE IF NOT EXISTS code_task_stop_requests (
  run_id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  actor TEXT NOT NULL,
  reason TEXT,
  phase TEXT,
  requested_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  honoured_at TIMESTAMPTZ
);
-- THE LEDGER'S HOT PATHS, each served by an index rather than a scan of a table kept forever.
-- close_act rolls up an act's calls on every close (each step settle, each build stage change
-- inside a model call's commit, each chat turn); _live_cost and the Act card read the same way.
CREATE INDEX IF NOT EXISTS idx_llm_calls_act ON llm_calls(act_id) WHERE act_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agent_turns_act ON agent_turns(act_id) WHERE act_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_agent_messages_act ON agent_messages(act_id) WHERE act_id IS NOT NULL;
-- stage_act runs on every model call a build makes; a panel's seats and its step; a subject's
-- acts (a build's root, a panel's root, a step's act by its row); an approval by its decision.
CREATE INDEX IF NOT EXISTS agent_acts_code_task ON agent_acts(code_task_run_id) WHERE code_task_run_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS agent_acts_meeting ON agent_acts(meeting_run_id) WHERE meeting_run_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS agent_acts_subject ON agent_acts(subject_kind, subject_id);
CREATE INDEX IF NOT EXISTS agent_acts_decision ON agent_acts(decision_id) WHERE decision_id IS NOT NULL;
-- Presence's idle line: each agent's last ended act, one probe per agent, never a sort of the
-- project's whole history.
CREATE INDEX IF NOT EXISTS agent_acts_role_ended ON agent_acts(project_id, role_key, ended_at DESC) WHERE ended_at IS NOT NULL;

-- TALKING WITH AGENTS (spec §0.2 A, stream S-converse). A conversation is a 1:1 talk, a "plan it
-- with <agent>" that ends in a start proposal, or a room of 2-5 SMEs. Its own tables rather than
-- agent_threads: that table's surface CHECK is ('chat','github') and its thread key is one
-- agent, and a room is neither. A 1:1 talk may still ride the dock's thread for tools, which is
-- what agent_thread_id records. Every agent turn is also an act (kind chat or seat,
-- thread_id = conversation_id, subject_kind 'conversation').
CREATE TABLE IF NOT EXISTS agent_conversations (
  conversation_id TEXT PRIMARY KEY,          -- 'cnv_' + ulid
  project_id TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('talk','plan','room')),
  title TEXT NOT NULL DEFAULT '',
  actor TEXT NOT NULL,                       -- the human who opened it; accountable for every turn
  seats JSONB NOT NULL DEFAULT '[]'::jsonb,  -- ordered role_keys: talk/plan exactly 1, room 2-5
  lead_role_key TEXT,                        -- who writes the room summary / the plan proposal (default seats[0])
  preset TEXT,                               -- room preset key, when one was used
  status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','summarized','started','closed')),
  context JSONB NOT NULL DEFAULT '{}'::jsonb, -- {from, act_id?, workflow_run_id?, step_id?}
  summary JSONB,                             -- room: RoomSummary
  agent_thread_id TEXT,                      -- talk only: the dock thread that carries tool use, if any
  root_act_id TEXT,                          -- the first agent turn's act; every later turn shares its root
  started_run_id TEXT,                       -- set when the operator presses Start on a proposal
  streaming_claim TEXT,                      -- the stream that holds the floor (one at a time); NULL = free
  streaming_until TIMESTAMPTZ,               -- when that claim lapses if its stream died unseen; renewed per speaker
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS agent_conversations_recent
  ON agent_conversations(project_id, actor, updated_at DESC);

CREATE TABLE IF NOT EXISTS agent_conversation_turns (
  turn_id TEXT PRIMARY KEY,                  -- 'trn_' + ulid
  conversation_id TEXT NOT NULL REFERENCES agent_conversations(conversation_id) ON DELETE CASCADE,
  seq INT NOT NULL,
  speaker_kind TEXT NOT NULL CHECK (speaker_kind IN ('person','agent','boss')),
  role_key TEXT,                             -- the agent speaking; NULL for a person or BOSS
  actor TEXT,                                -- the person speaking
  addressed_to JSONB NOT NULL DEFAULT '[]'::jsonb, -- @mentioned role_keys; [] = the whole room
  reply_to_turn_id TEXT,                     -- the turn this one answers (an SME answering another)
  kind TEXT NOT NULL DEFAULT 'message'
    CHECK (kind IN ('message','question','proposal','summary','error')),
  content TEXT NOT NULL DEFAULT '',
  payload JSONB NOT NULL DEFAULT '{}'::jsonb, -- proposal: StartProposal · summary: RoomSummary · error: model_failures.explain()
  status TEXT NOT NULL DEFAULT 'complete' CHECK (status IN ('streaming','complete','error')),
  act_id TEXT, fingerprint TEXT,
  cited_acts JSONB NOT NULL DEFAULT '[]'::jsonb,
  tokens_in INT NOT NULL DEFAULT 0, tokens_out INT NOT NULL DEFAULT 0,
  cost_usd NUMERIC(12,6) NOT NULL DEFAULT 0, receipt_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (conversation_id, seq)
);
CREATE INDEX IF NOT EXISTS agent_conversation_turns_act ON agent_conversation_turns(act_id);

-- SUBSCRIPTION CALLS ARE NOT MONEY (services/included_spend.py). Before this rule a call on a
-- subscription source settled at its API-list-price equivalent, and the money caps counted it:
-- boss-1 went red on a $10 cap with no API key at all. Receipts settled through the model
-- gateway name their source, so the ones a subscription, licensed seat or local model answered
-- are CLASSIFIED here — amounts untouched, history not rewritten — and every money total
-- (MONEY_SQL) stops counting them; their value is reported as included in the subscription.
-- Idempotent: only unclassified rows are touched. Receipts settled outside the gateway before
-- this change name no source and keep counting as money.
UPDATE cost_receipts cr
SET included_in_subscription = true,
    equivalent_usd_micros = COALESCE(cr.equivalent_usd_micros, cr.actual_usd_micros,
                                     cr.estimated_usd_micros)
FROM model_gateway_invocations mi
JOIN model_gateway_leases ml ON ml.id = mi.model_gateway_lease_id
JOIN entitlement_sources es ON es.id = ml.entitlement_source_id
WHERE mi.receipt_id = cr.receipt_id
  AND cr.project_id = mi.project_id
  AND NOT cr.included_in_subscription
  AND es.entitlement_kind IN ('subscription', 'licensed_seat', 'local_capacity');

-- AN AGENT'S INSTRUCTIONS (agent-loadout spec §4.1): operator-written text — a review
-- checklist, house rules — that goes into every prompt the agent gets, in the modes it is for.
-- It shapes HOW the agent works, never what it may do: tools still come only from role_skills
-- and role_mcp_servers, and the text is linted at save and again before each prompt
-- (services/agent_instructions.py). Kept out of roles.spec: bodies up to 16k characters would
-- ride on every roster read. Each change is a new agent version (agent_identity.canonical).
CREATE TABLE IF NOT EXISTS agent_instructions (
  id          TEXT PRIMARY KEY,
  project_id  TEXT NOT NULL,
  role_key    TEXT NOT NULL,
  name        TEXT NOT NULL,
  source      TEXT NOT NULL CHECK (source IN ('file', 'pasted', 'skill_md')),
  sha256      TEXT NOT NULL,
  size_chars  INTEGER NOT NULL,
  modes       TEXT[] NOT NULL DEFAULT ARRAY['work', 'chat', 'panel'],
  position    INTEGER NOT NULL DEFAULT 0,
  -- The agent version that first carried this text (set after the seal), for `Since v<n>`.
  since_version INTEGER,
  created_by  TEXT NOT NULL,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by  TEXT NOT NULL,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, role_key, name)
);
CREATE INDEX IF NOT EXISTS agent_instructions_role
  ON agent_instructions (project_id, role_key, position);

-- Content-addressed and immutable: every body any version ever used, so an old run can still
-- show exactly the instructions it acted on after they were edited or the agent deleted.
CREATE TABLE IF NOT EXISTS agent_instruction_bodies (
  project_id TEXT NOT NULL,
  sha256     TEXT NOT NULL,
  body       TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, sha256)
);

-- THE COMMAND CENTER'S READS (command-center spec §6.2), each served by an index rather than a
-- scan. The view polls every 10s while it is looked at, beside the pill (4s) and Live (8s).
-- Hand-offs started in the last hour (the Floor's edges):
CREATE INDEX IF NOT EXISTS agent_acts_started ON agent_acts(project_id, started_at DESC);
-- Work finished by hour, yesterday and today (Today's line):
CREATE INDEX IF NOT EXISTS agent_acts_ended ON agent_acts(project_id, ended_at DESC) WHERE ended_at IS NOT NULL;
-- Every run touched in the week, counted exactly (the week bars, the day strip):
CREATE INDEX IF NOT EXISTS idx_workflow_runs_project_updated ON workflow_runs(project_id, updated_at DESC);
-- The Queue dot: what is waiting, and since when.
CREATE INDEX IF NOT EXISTS idx_jobs_project_open ON jobs(project_id, created_at) WHERE status IN ('queued','leased');
-- command_center.read reads decisions by project and status with no LIMIT (the count has to
-- equal the inbox's), and nothing served it: the pill, Live and this view all hit it.
CREATE INDEX IF NOT EXISTS idx_decisions_project_status ON decisions(project_id, status);

-- ============================================================================================
-- RUN SCORECARDS, EXPERIMENTS, PERSON FEEDBACK AND "IMPROVE BOSS" (docs/product/RUN_SCORECARDS.md,
-- "Implementation"). Names, numbers and verdicts only: no prompts, code, briefs, paths or
-- secrets ever land in these tables (content stays where it already lives).
-- ============================================================================================

-- ONE ROW PER FINISHED UNIT, keyed by (unit_kind, unit_id). Written by
-- scorecards.record_scorecard() on the unit's terminal transition and again by the late-outcome
-- sweep (PR merged/reverted, 24h deploy health). Idempotent: a rerun rewrites the same row.
CREATE TABLE IF NOT EXISTS run_scorecards (
  unit_kind        TEXT NOT NULL CHECK (unit_kind IN
                     ('workflow_run','build','step','panel','research','quick_change')),
  unit_id          TEXT NOT NULL,
  project_id       TEXT NOT NULL,
  run_id           TEXT,             -- the workflow run this unit belongs to, when it has one
  -- what was tried (the variant)
  workflow_key     TEXT,
  workflow_version INTEGER,
  workflow_builtin BOOLEAN,
  step_key         TEXT,
  role_key         TEXT,
  role_builtin     BOOLEAN,
  prompt_version   TEXT,             -- a hash, never the text
  skills           JSONB NOT NULL DEFAULT '[]'::jsonb,   -- sorted keys
  mcp_tools        JSONB NOT NULL DEFAULT '[]'::jsonb,   -- sorted keys
  harness          TEXT,
  model            TEXT,
  provider         TEXT,
  review_lanes     INTEGER,
  review_rounds    INTEGER,
  turn_budget      INTEGER,
  retry_max        INTEGER,
  context_policy   JSONB NOT NULL DEFAULT '[]'::jsonb,   -- names of what was carried in
  experiment_id    TEXT,
  experiment_arm   TEXT,
  task_kind        TEXT,
  task_size        TEXT,
  -- how it went (the outcome)
  terminal_state   TEXT NOT NULL,
  tests_passed     INTEGER,
  tests_total      INTEGER,
  existing_tests_intact BOOLEAN,
  gates_passed     INTEGER,
  gates_failed     INTEGER,
  failed_gates     JSONB NOT NULL DEFAULT '[]'::jsonb,   -- gate names
  review_approved  BOOLEAN,
  review_rounds_used INTEGER,
  approvals        INTEGER NOT NULL DEFAULT 0,
  rejections       INTEGER NOT NULL DEFAULT 0,
  decide_wait_s    INTEGER,
  steers           INTEGER NOT NULL DEFAULT 0,
  pr_opened        BOOLEAN,
  pr_merged        BOOLEAN,
  pr_reverted      BOOLEAN,
  deploy_healthy   BOOLEAN,
  deploy_healthy_24h BOOLEAN,
  rolled_back      BOOLEAN,
  research_verdict TEXT,
  confidence       NUMERIC,
  panel_agreed     BOOLEAN,
  prd_approved     BOOLEAN,
  cost_usd         NUMERIC NOT NULL DEFAULT 0,
  tokens_in        BIGINT NOT NULL DEFAULT 0,
  tokens_out       BIGINT NOT NULL DEFAULT 0,
  model_calls      INTEGER NOT NULL DEFAULT 0,
  tool_calls       INTEGER NOT NULL DEFAULT 0,
  turns            INTEGER NOT NULL DEFAULT 0,
  wall_time_s      INTEGER,
  wait_on_person_s INTEGER,
  retries          INTEGER NOT NULL DEFAULT 0,
  shepherd_interventions INTEGER NOT NULL DEFAULT 0,
  error_class      TEXT,
  -- the person's own one-tap verdict on this unit, mirrored from person_feedback
  rating           TEXT,
  -- the score (0..1) and the parts it was made from; weights are versioned
  over_median      JSONB NOT NULL DEFAULT '{}'::jsonb,  -- {"cost":bool,"turns":bool,"steers":bool}
  score            NUMERIC,
  score_version    TEXT,
  started_at       TIMESTAMPTZ,
  ended_at         TIMESTAMPTZ,
  computed_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  late_outcomes_at TIMESTAMPTZ,
  source           TEXT NOT NULL DEFAULT 'live' CHECK (source IN ('live','backfill')),
  PRIMARY KEY (unit_kind, unit_id)
);
CREATE INDEX IF NOT EXISTS run_scorecards_project_ended
  ON run_scorecards (project_id, ended_at DESC);
CREATE INDEX IF NOT EXISTS run_scorecards_computed ON run_scorecards (computed_at);
CREATE INDEX IF NOT EXISTS run_scorecards_experiment
  ON run_scorecards (experiment_id, experiment_arm) WHERE experiment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS run_scorecards_late
  ON run_scorecards (unit_kind, ended_at) WHERE late_outcomes_at IS NULL;

-- AN A/B ON ONE SETTING of a role or a workflow. Off by default; started by the operator.
-- Only allow-listed knobs (experiments.ARM_KNOBS), none of which decides what needs approval.
CREATE TABLE IF NOT EXISTS experiments (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL,
  name          TEXT NOT NULL,
  target_kind   TEXT NOT NULL CHECK (target_kind IN ('role','workflow')),
  target_key    TEXT NOT NULL,
  knob          TEXT NOT NULL,
  arm_a         JSONB NOT NULL,
  arm_b         JSONB NOT NULL,
  split_b       NUMERIC NOT NULL DEFAULT 0.5 CHECK (split_b > 0 AND split_b < 1),
  target_units  INTEGER NOT NULL DEFAULT 20 CHECK (target_units BETWEEN 2 AND 1000),
  arm_cost_cap_usd NUMERIC NOT NULL DEFAULT 25 CHECK (arm_cost_cap_usd > 0),
  status        TEXT NOT NULL DEFAULT 'running'
                  CHECK (status IN ('running','stopped','finished','promoted')),
  stop_reason   TEXT,
  capped_arms   JSONB NOT NULL DEFAULT '[]'::jsonb,
  promoted_arm  TEXT,
  created_by    TEXT NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at      TIMESTAMPTZ,
  ended_by      TEXT
);
CREATE INDEX IF NOT EXISTS experiments_project_status ON experiments (project_id, status);

-- Which arm a unit got, chosen once when the unit starts. The scorecard copies it.
CREATE TABLE IF NOT EXISTS experiment_assignments (
  experiment_id TEXT NOT NULL,
  unit_kind     TEXT NOT NULL,
  unit_id       TEXT NOT NULL,
  arm           TEXT NOT NULL CHECK (arm IN ('a','b')),
  assigned_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (unit_kind, unit_id)
);
CREATE INDEX IF NOT EXISTS experiment_assignments_exp ON experiment_assignments (experiment_id, arm);

-- WHAT THE PERSON SAID: one-tap ratings, reason chips on rejects and steers, edit amounts and the
-- monthly check-in. Stored locally ALWAYS, whether or not "Improve BOSS" is on. One row per
-- (subject, person) for ratings (a second tap changes it); rejects/steers/edits append.
CREATE TABLE IF NOT EXISTS person_feedback (
  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN
                 ('build','research','panel','answer','deploy','reject','steer','edit','checkin')),
  subject_id   TEXT NOT NULL,
  actor        TEXT NOT NULL,
  rating       TEXT,
  chips        TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[],
  decision_kind TEXT,             -- plan / spec / merge / deploy for a reject; doc kind for an edit
  edit_ratio   NUMERIC,           -- 0..1, how much a brief/PRD/plan changed before approval
  one_liner    TEXT,              -- the check-in's optional line; local unless share_line
  share_line   BOOLEAN NOT NULL DEFAULT false,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS person_feedback_one_rating
  ON person_feedback (subject_kind, subject_id, actor)
  WHERE subject_kind IN ('build','research','panel','answer','deploy');
CREATE INDEX IF NOT EXISTS person_feedback_created ON person_feedback (created_at);

-- Never nag: when each person was last asked, per kind of ask.
CREATE TABLE IF NOT EXISTS person_prompt_state (
  actor        TEXT NOT NULL,
  prompt       TEXT NOT NULL,     -- 'checkin' | 'rate'
  last_shown_at TIMESTAMPTZ,
  last_answered_at TIMESTAMPTZ,
  last_dismissed_at TIMESTAMPTZ,
  shown_today  INTEGER NOT NULL DEFAULT 0,
  shown_day    DATE,
  PRIMARY KEY (actor, prompt)
);

-- THE CLIENT'S OUTBOX: one row per send attempt (the exact gzip bytes), the last 30 kept as the
-- local log Govern › Sharing shows. Batches cut but not yet delivered ride along in the next
-- day's single POST, at most 7 of them; older ones are dropped and the drop is recorded.
CREATE TABLE IF NOT EXISTS telemetry_sends (
  id           TEXT PRIMARY KEY,
  day          DATE NOT NULL,
  kind         TEXT NOT NULL CHECK (kind IN ('daily','share','delete','export')),
  status       TEXT NOT NULL CHECK (status IN ('pending','sent','failed','dropped','exported')),
  body_gz      BYTEA,
  bytes_raw    INTEGER NOT NULL DEFAULT 0,
  bytes_gz     INTEGER NOT NULL DEFAULT 0,
  batch_days   JSONB NOT NULL DEFAULT '[]'::jsonb,
  aggregated   JSONB NOT NULL DEFAULT '{}'::jsonb,
  http_status  INTEGER,
  error        TEXT,
  cut_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_at      TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS telemetry_sends_cut ON telemetry_sends (cut_at DESC);

-- A day's "Improve BOSS" batch (content-free aggregates), cut once and frozen until delivered.
CREATE TABLE IF NOT EXISTS telemetry_batches (
  day          DATE PRIMARY KEY,
  body         JSONB NOT NULL,
  since_at     TIMESTAMPTZ,
  until_at     TIMESTAMPTZ NOT NULL,
  status       TEXT NOT NULL DEFAULT 'unsent' CHECK (status IN ('unsent','sent','dropped')),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- THE COLLECTOR (collector mode only). Keyed by the random install id; no IP
-- address, hostname or name is ever stored. 18 months, then rolled into tm_rollups and deleted.
CREATE TABLE IF NOT EXISTS tm_installs (
  install_id     TEXT PRIMARY KEY,
  secret_hash    TEXT,
  first_seen_day DATE NOT NULL,
  last_seen_day  DATE NOT NULL,
  version        TEXT,
  edition        TEXT,
  install_method TEXT,
  os             TEXT,
  arch           TEXT,
  improve_on     BOOLEAN NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS tm_heartbeats (
  install_id     TEXT NOT NULL,
  day            DATE NOT NULL,
  version        TEXT,
  edition        TEXT,
  install_method TEXT,
  os             TEXT,
  arch           TEXT,
  age_bucket     TEXT,
  worked_24h     BOOLEAN NOT NULL DEFAULT false,
  received_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (install_id, day)
);
CREATE INDEX IF NOT EXISTS tm_heartbeats_day ON tm_heartbeats (day);
CREATE TABLE IF NOT EXISTS tm_batches (
  install_id     TEXT NOT NULL,
  day            DATE NOT NULL,
  body           JSONB NOT NULL,
  received_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (install_id, day)
);
CREATE INDEX IF NOT EXISTS tm_batches_day ON tm_batches (day);
CREATE TABLE IF NOT EXISTS tm_shares (
  id             TEXT PRIMARY KEY,
  install_id     TEXT NOT NULL,
  body           JSONB NOT NULL,
  received_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS tm_rollups (
  month          DATE NOT NULL,
  metric         TEXT NOT NULL,
  dims           TEXT NOT NULL DEFAULT '',
  value          NUMERIC NOT NULL,
  PRIMARY KEY (month, metric, dims)
);

-- P3 (2026-10-05 fixes): the consent moment a batch was cut under, so a rebuilt batch (size cap)
-- keeps excluding everything from before the switch went on.
ALTER TABLE telemetry_batches ADD COLUMN IF NOT EXISTS consent_at TIMESTAMPTZ;
-- An install id introduced by an address that already introduced too many new ids that day:
-- stored, but kept out of every count on the dashboard (defect 10).
ALTER TABLE tm_installs ADD COLUMN IF NOT EXISTS suspicious BOOLEAN NOT NULL DEFAULT false;
-- A shared run carries its install's secret hash, so an id that only ever shared a run can still
-- be deleted (re-check item 2).
ALTER TABLE tm_shares ADD COLUMN IF NOT EXISTS secret_hash TEXT;

-- =================================================================================================
-- BOSS IDENTITY (docs/product/IDENTITY.md §11; frozen in Phase 0, docs/product/IDENTITY_BUILD.md).
-- Every table is identity_-prefixed so nothing collides with the AGENT `roles` table, and every
-- row is scoped by org_id (one org per install in v1, D24). Additive only. The catalogue rows
-- (identity_permissions, built-in identity_access_roles) are seeded by db/identity_seed.sql, which
-- is GENERATED from packages/identity/catalogue.yaml and applied right after this file.
-- No email is stored in a case-sensitive unique column: uniqueness is on lower(email).
-- No secret is stored in plaintext: credentials are hashes (SHA-256 for 256-bit tokens, argon2id
-- PHC for passwords and recovery codes) or vault ciphertext (identity_vault_items).
-- =================================================================================================

CREATE TABLE IF NOT EXISTS identity_principals (
  id                TEXT PRIMARY KEY,                    -- usr_ / sva_ / agt_ / sys_
  org_id            TEXT NOT NULL REFERENCES orgs(id),
  kind              TEXT NOT NULL CHECK (kind IN ('user','service_account','agent','system')),
  status            TEXT NOT NULL CHECK (status IN ('pending','active','disabled','suspended','revoked')),
  display_name      TEXT NOT NULL,
  network_bound     BOOLEAN NOT NULL DEFAULT false,      -- the network-mode migration bridge principal
  legacy_member_ids TEXT[] NOT NULL DEFAULT '{}',        -- 'ceo','executive_console',... for history
  created_by        TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  status_changed_at TIMESTAMPTZ,
  status_changed_by TEXT,
  status_reason     TEXT
);
CREATE INDEX IF NOT EXISTS identity_principals_org_kind ON identity_principals (org_id, kind, status);

CREATE TABLE IF NOT EXISTS identity_users (
  principal_id        TEXT PRIMARY KEY REFERENCES identity_principals(id),
  email               TEXT NOT NULL,
  email_verified_at   TIMESTAMPTZ,
  password_hash       TEXT,                              -- argon2id PHC; NULL = no password
  password_changed_at TIMESTAMPTZ,
  mfa_required        BOOLEAN NOT NULL DEFAULT false,    -- per-user override; role policy also applies
  self_signed_up      BOOLEAN NOT NULL DEFAULT false,    -- created by self sign-up (off by default)
  last_login_at       TIMESTAMPTZ,
  avatar_seed         TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS identity_users_email ON identity_users (lower(email));

CREATE TABLE IF NOT EXISTS identity_user_identities (    -- SSO and social links, by (issuer, subject)
  id            TEXT PRIMARY KEY,
  principal_id  TEXT NOT NULL REFERENCES identity_principals(id),
  provider_id   TEXT NOT NULL,
  issuer        TEXT NOT NULL,
  subject       TEXT NOT NULL,
  email_at_link TEXT,                                    -- display only; NEVER used to link
  linked_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at  TIMESTAMPTZ,
  UNIQUE (issuer, subject)
);
CREATE INDEX IF NOT EXISTS identity_user_identities_principal ON identity_user_identities (principal_id);

CREATE TABLE IF NOT EXISTS identity_providers (           -- OIDC / SAML / OAuth sign-in providers
  id                         TEXT PRIMARY KEY,          -- idp_
  org_id                     TEXT NOT NULL REFERENCES orgs(id),
  protocol                   TEXT NOT NULL CHECK (protocol IN ('oidc','saml','oauth2')),
  preset                     TEXT NOT NULL DEFAULT 'generic', -- google|github|microsoft|apple|okta|entra|keycloak|generic
  name                       TEXT NOT NULL,
  issuer                     TEXT,                      -- OIDC issuer / SAML IdP entityID
  client_id                  TEXT,
  client_secret_vault_item_id TEXT,                     -- secret lives in the vault
  scopes                     TEXT[] NOT NULL DEFAULT '{}',
  allowed_algs               TEXT[] NOT NULL DEFAULT '{RS256,ES256,EdDSA}',
  saml_sp_entity_id          TEXT,
  saml_certificates          TEXT[] NOT NULL DEFAULT '{}', -- PEM, up to two for rollover
  domains                    TEXT[] NOT NULL DEFAULT '{}',
  jit_mode                   TEXT NOT NULL DEFAULT 'off' CHECK (jit_mode IN ('off','domain')),
  trust_idp_mfa              BOOLEAN NOT NULL DEFAULT false,
  enforce_sso                BOOLEAN NOT NULL DEFAULT false,
  groups_claim               TEXT,
  status                     TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  imported_from              TEXT,                      -- enterprise_identity_providers.id (migration)
  created_by                 TEXT,
  created_at                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at                 TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS identity_provider_group_mappings (
  provider_id    TEXT NOT NULL REFERENCES identity_providers(id) ON DELETE CASCADE,
  external_group TEXT NOT NULL,
  group_id       TEXT NOT NULL,
  PRIMARY KEY (provider_id, external_group)
);

CREATE TABLE IF NOT EXISTS identity_totp (
  principal_id  TEXT PRIMARY KEY REFERENCES identity_principals(id),
  vault_item_id TEXT NOT NULL,                           -- the secret is vault ciphertext, AAD-bound
  last_step     BIGINT NOT NULL DEFAULT 0,               -- replay guard
  enrolled_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS identity_webauthn_credentials (
  id              TEXT PRIMARY KEY,                      -- pky_
  principal_id    TEXT NOT NULL REFERENCES identity_principals(id),
  credential_id   BYTEA NOT NULL UNIQUE,
  public_key      BYTEA NOT NULL,
  sign_count      BIGINT NOT NULL DEFAULT 0,
  aaguid          UUID,
  transports      TEXT[],
  backup_eligible BOOLEAN,
  backup_state    BOOLEAN,
  name            TEXT NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at    TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS identity_webauthn_principal ON identity_webauthn_credentials (principal_id);

CREATE TABLE IF NOT EXISTS identity_recovery_codes (
  id           TEXT PRIMARY KEY,
  principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  code_hash    TEXT NOT NULL,                            -- argon2id (small profile)
  used_at      TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS identity_recovery_codes_principal ON identity_recovery_codes (principal_id) WHERE used_at IS NULL;

-- Every short-lived, single-use secret of a sign-in flow. Only its hash is stored; each is bound to
-- the pre-auth (state) cookie of the browser that asked for it (binding_hash).
CREATE TABLE IF NOT EXISTS identity_auth_challenges (
  id_hash      TEXT PRIMARY KEY,
  kind         TEXT NOT NULL CHECK (kind IN ('preauth','mfa','webauthn','step_up','oidc_state',
                 'saml_request','password_reset','invitation','setup','magic_link','email_code',
                 'self_signup_verify')),
  principal_id TEXT,
  binding_hash TEXT,
  payload_enc  BYTEA,                                    -- nonce / PKCE verifier / request id, encrypted
  attempts     INT NOT NULL DEFAULT 0,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ NOT NULL,
  consumed_at  TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS identity_auth_challenges_expiry ON identity_auth_challenges (expires_at);

CREATE TABLE IF NOT EXISTS identity_sessions (
  id                  TEXT PRIMARY KEY,                  -- ses_ (public id; never the token)
  token_hash          TEXT NOT NULL UNIQUE,              -- SHA-256 of the bss_ token
  principal_id        TEXT NOT NULL REFERENCES identity_principals(id),
  auth_methods        TEXT[] NOT NULL,                   -- pwd, totp, passkey, sso:<provider>, magic_link, email_code, legacy_password, network
  mfa_at              TIMESTAMPTZ,
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  idle_expires_at     TIMESTAMPTZ NOT NULL,
  absolute_expires_at TIMESTAMPTZ NOT NULL,
  ip                  INET,
  user_agent          TEXT,
  device_id_hash      TEXT,
  revoked_at          TIMESTAMPTZ,
  revoked_by          TEXT,
  revoked_reason      TEXT,
  replaced_by         TEXT
);
CREATE INDEX IF NOT EXISTS identity_sessions_live ON identity_sessions (principal_id) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS identity_invitations (
  id                    TEXT PRIMARY KEY,                -- inv_
  org_id                TEXT NOT NULL REFERENCES orgs(id),
  email                 TEXT NOT NULL,
  token_hash            TEXT NOT NULL UNIQUE,
  bindings              JSONB NOT NULL DEFAULT '[]',     -- [{role_key, scope_type, scope_id}]
  group_ids             TEXT[] NOT NULL DEFAULT '{}',
  invited_by            TEXT NOT NULL,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at            TIMESTAMPTZ NOT NULL,
  accepted_at           TIMESTAMPTZ,
  accepted_principal_id TEXT,
  revoked_at            TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS identity_groups (
  id          TEXT PRIMARY KEY,                          -- grp_
  org_id      TEXT NOT NULL REFERENCES orgs(id),
  key         TEXT NOT NULL,
  name        TEXT NOT NULL,
  description TEXT,
  source      TEXT NOT NULL CHECK (source IN ('manual','scim','oidc')),
  external_id TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (org_id, key)
);
CREATE TABLE IF NOT EXISTS identity_group_members (
  group_id     TEXT NOT NULL REFERENCES identity_groups(id),
  principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  source       TEXT NOT NULL CHECK (source IN ('manual','scim','oidc')),
  added_by     TEXT,
  added_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (group_id, principal_id)
);
CREATE INDEX IF NOT EXISTS identity_group_members_principal ON identity_group_members (principal_id);

CREATE TABLE IF NOT EXISTS identity_permissions (        -- seeded from the catalogue; never written otherwise
  key               TEXT PRIMARY KEY CHECK (key ~ '^[a-z][a-z_]*:[a-z][a-z_]*$'),
  resource          TEXT NOT NULL,
  action            TEXT NOT NULL,
  title             TEXT NOT NULL,
  description       TEXT NOT NULL,
  category          TEXT NOT NULL,
  scope_kind        TEXT NOT NULL CHECK (scope_kind IN ('org','project')),
  step_up           BOOLEAN NOT NULL,
  delegable         BOOLEAN NOT NULL,
  critical          BOOLEAN NOT NULL,
  system_only       BOOLEAN NOT NULL,
  readonly_post     BOOLEAN NOT NULL DEFAULT false,
  catalogue_version INT NOT NULL
);
CREATE TABLE IF NOT EXISTS identity_access_roles (
  id              TEXT PRIMARY KEY,                      -- arl_<key> for built-ins
  org_id          TEXT,                                  -- NULL = built-in
  key             TEXT NOT NULL,
  name            TEXT NOT NULL,
  description     TEXT NOT NULL DEFAULT '',
  builtin         BOOLEAN NOT NULL,
  system          BOOLEAN NOT NULL DEFAULT false,
  bindable_scopes TEXT[] NOT NULL,
  mfa_required    BOOLEAN NOT NULL DEFAULT false,
  version         INT NOT NULL DEFAULT 1,
  cloned_from     TEXT,
  created_by      TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (org_id, key)
);
CREATE TABLE IF NOT EXISTS identity_access_role_permissions (
  role_id        TEXT NOT NULL REFERENCES identity_access_roles(id) ON DELETE CASCADE,
  permission_key TEXT NOT NULL REFERENCES identity_permissions(key),
  PRIMARY KEY (role_id, permission_key)
);
CREATE TABLE IF NOT EXISTS identity_access_role_versions (
  role_id     TEXT NOT NULL,
  version     INT NOT NULL,
  permissions TEXT[] NOT NULL,
  changed_by  TEXT NOT NULL,
  changed_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (role_id, version)
);
CREATE TABLE IF NOT EXISTS identity_role_bindings (
  id           TEXT PRIMARY KEY,                         -- rbd_
  org_id       TEXT NOT NULL REFERENCES orgs(id),
  subject_type TEXT NOT NULL CHECK (subject_type IN ('principal','group')),
  subject_id   TEXT NOT NULL,
  role_id      TEXT NOT NULL REFERENCES identity_access_roles(id),
  scope_type   TEXT NOT NULL CHECK (scope_type IN ('org','project')),
  scope_id     TEXT NOT NULL,                            -- org id or project id
  granted_by   TEXT NOT NULL,
  granted_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ,                              -- break-glass bindings are time-boxed
  reason       TEXT,
  UNIQUE (subject_type, subject_id, role_id, scope_type, scope_id)
);
CREATE INDEX IF NOT EXISTS identity_role_bindings_subject ON identity_role_bindings (subject_type, subject_id);
CREATE INDEX IF NOT EXISTS identity_role_bindings_role ON identity_role_bindings (org_id, role_id);

CREATE TABLE IF NOT EXISTS identity_approval_seats (       -- governance seats (ceo, cao, ...) -> people
  org_id       TEXT NOT NULL REFERENCES orgs(id),
  seat_key     TEXT NOT NULL,
  principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  assigned_by  TEXT NOT NULL,
  assigned_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, seat_key, principal_id)
);
-- §6.13 condition 4: the approvals a tier-3 decision has collected (two distinct people).
CREATE TABLE IF NOT EXISTS identity_decision_approvals (
  decision_id  TEXT NOT NULL,
  org_id       TEXT NOT NULL REFERENCES orgs(id),
  principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  seat_key     TEXT,
  approved_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  content_hash TEXT,                                     -- C-3: the preview hash this person approved
  PRIMARY KEY (decision_id, principal_id)
);
ALTER TABLE identity_decision_approvals ADD COLUMN IF NOT EXISTS content_hash TEXT;


CREATE TABLE IF NOT EXISTS identity_service_accounts (
  principal_id        TEXT PRIMARY KEY REFERENCES identity_principals(id),
  description         TEXT,
  owner_principal_ids TEXT[] NOT NULL CHECK (cardinality(owner_principal_ids) >= 1)
);

-- API keys: boss_pat_ / boss_sak_ / boss_scim_ (prefix + 32 random bytes + CRC32 checksum, §5.1).
-- Only SHA-256(token) is stored; no part of the key is ever stored or shown after creation.
CREATE TABLE IF NOT EXISTS identity_api_credentials (
  id           TEXT PRIMARY KEY,                         -- key_<random public id>
  principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  kind         TEXT NOT NULL CHECK (kind IN ('pat','sak','scim','legacy_env')),
  name         TEXT NOT NULL,
  token_hash   TEXT NOT NULL UNIQUE,
  scopes       TEXT[] NOT NULL,                          -- catalogue permissions; effective = owner's live set ∩ scopes
  project_ids  TEXT[],
  cidrs        CIDR[],
  expires_at   TIMESTAMPTZ,
  created_by   TEXT NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at TIMESTAMPTZ,
  last_used_ip INET,
  last_used_ua TEXT,
  rotated_from TEXT,
  grace_until  TIMESTAMPTZ,
  suspended_at TIMESTAMPTZ,
  revoked_at   TIMESTAMPTZ,
  revoked_by   TEXT
);
CREATE INDEX IF NOT EXISTS identity_api_credentials_principal ON identity_api_credentials (principal_id);

CREATE TABLE IF NOT EXISTS identity_agent_passports (
  agent_id             TEXT PRIMARY KEY REFERENCES identity_principals(id), -- = roles.agent_id
  role_key             TEXT NOT NULL,
  sponsor_principal_id TEXT NOT NULL,
  ceiling_preset       TEXT,
  version              INT NOT NULL DEFAULT 1,
  can_spawn            BOOLEAN NOT NULL DEFAULT false,
  allowed_children     TEXT[] NOT NULL DEFAULT '{}',
  max_depth            INT NOT NULL DEFAULT 3 CHECK (max_depth BETWEEN 0 AND 5),
  autonomous           BOOLEAN NOT NULL DEFAULT false,
  external_ceiling     JSONB NOT NULL DEFAULT '{}',
  reissued_from        TEXT,
  sealed_fingerprint   TEXT,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS identity_agent_ceilings (
  agent_id       TEXT NOT NULL REFERENCES identity_agent_passports(agent_id),
  permission_key TEXT NOT NULL REFERENCES identity_permissions(key),   -- trigger: must be delegable
  PRIMARY KEY (agent_id, permission_key)
);

-- APPROVAL DELEGATIONS (IDENTITY.md §6.15; identity/approval_delegations.py): a person's named
-- delegate (a service account with one boss_sak_ key) approves or rejects the decisions the grant
-- covers, unattended. Its authority is this row, read at every request; the hard limits are code.
CREATE TABLE IF NOT EXISTS identity_approval_delegations (
  id                    TEXT PRIMARY KEY,                -- apd_…
  org_id                TEXT NOT NULL REFERENCES orgs(id),
  person_principal_id   TEXT NOT NULL REFERENCES identity_principals(id),
  delegate_principal_id TEXT NOT NULL REFERENCES identity_principals(id),
  credential_id         TEXT UNIQUE REFERENCES identity_api_credentials(id),
  decision_kinds        TEXT[] NOT NULL CHECK (cardinality(decision_kinds) >= 1),
  project_ids           TEXT[] NOT NULL CHECK (cardinality(project_ids) >= 1),
  extra_risk_tiers      INTEGER[] NOT NULL DEFAULT '{}',  -- tiers above the configured one, listed explicitly
  daily_cap             INTEGER CHECK (daily_cap IS NULL OR daily_cap >= 1),
  status                TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  purpose               TEXT,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at            TIMESTAMPTZ NOT NULL,
  revoked_at            TIMESTAMPTZ,
  revoked_by            TEXT,
  last_used_at          TIMESTAMPTZ,
  CHECK (expires_at <= created_at + interval '90 days 1 minute')
);
CREATE INDEX IF NOT EXISTS identity_approval_delegations_person
  ON identity_approval_delegations (person_principal_id, created_at DESC);
CREATE TABLE IF NOT EXISTS identity_approval_delegation_uses (
  delegation_id TEXT NOT NULL REFERENCES identity_approval_delegations(id),
  decision_id   TEXT NOT NULL,
  action        TEXT NOT NULL CHECK (action IN ('approve', 'reject')),
  used_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS identity_approval_delegation_uses_day
  ON identity_approval_delegation_uses (delegation_id, used_at);
-- Who answered a decision FOR its approver: the delegate and the grant (approved_by stays the person).
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS via_delegate TEXT;
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS via_delegation TEXT;

CREATE TABLE IF NOT EXISTS identity_delegation_grants (
  id                  TEXT PRIMARY KEY,                  -- dlg_
  org_id              TEXT NOT NULL REFERENCES orgs(id),
  user_principal_id   TEXT NOT NULL REFERENCES identity_principals(id),
  agent_ids           TEXT[] NOT NULL,                   -- the may_act analogue
  project_ids         TEXT[] NOT NULL,
  resources           JSONB NOT NULL DEFAULT '{}',       -- {github: {repos: [...], contents: write, ...}}
  allow_subdelegation BOOLEAN NOT NULL DEFAULT false,
  allowed_children    TEXT[] NOT NULL DEFAULT '{}',
  max_depth           INT NOT NULL DEFAULT 3 CHECK (max_depth BETWEEN 0 AND 5),
  task_run_id         TEXT,                              -- set = task-bound ("this build only")
  purpose             TEXT,
  parent_grant_id     TEXT,
  status              TEXT NOT NULL CHECK (status IN ('active','suspended','revoked','expired')),
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at          TIMESTAMPTZ,
  last_used_at        TIMESTAMPTZ,
  revoked_at          TIMESTAMPTZ,
  revoked_by          TEXT,
  revoke_reason       TEXT
);
CREATE INDEX IF NOT EXISTS identity_delegation_grants_user ON identity_delegation_grants (user_principal_id, status);
-- §7.3: "BOSS reminds the user 3 days before expiry" — once per grant (extending clears it).
ALTER TABLE identity_delegation_grants ADD COLUMN IF NOT EXISTS reminded_at TIMESTAMPTZ;
-- THE PROJECT'S CAPTAIN AUTHORITY (identity/captain_authority.py): a standing authority BOSS
-- creates for every project, sponsored by the project's Owner, so always-on squads' builds run as
-- the project's Captain without a person's grant. 'captain' marks it (NULL: a person's own grant);
-- build and pull-request permissions only, never merge, production deploy, secrets or admin.
-- One per project, whatever its status: one a person revoked stays revoked.
ALTER TABLE identity_delegation_grants ADD COLUMN IF NOT EXISTS authority_kind TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS identity_delegation_grants_one_captain
  ON identity_delegation_grants ((project_ids[1])) WHERE authority_kind = 'captain';
-- §7.3 2, ASKED WHERE NO SHEET CAN OPEN: a consent request raised in an agent turn, an MCP call or
-- a key-authenticated start, kept for an hour so the console can open the same sheet from a link
-- (/account/agents?consent=<id>). The link carries only this id; only the person it names reads it.
CREATE TABLE IF NOT EXISTS identity_pending_consents (
  id           TEXT PRIMARY KEY,                         -- pcn_
  org_id       TEXT NOT NULL,
  principal_id TEXT NOT NULL,
  body         JSONB NOT NULL,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ NOT NULL
);
CREATE INDEX IF NOT EXISTS identity_pending_consents_expiry ON identity_pending_consents (expires_at);
CREATE TABLE IF NOT EXISTS identity_delegation_grant_permissions (
  grant_id       TEXT NOT NULL REFERENCES identity_delegation_grants(id),
  permission_key TEXT NOT NULL REFERENCES identity_permissions(key),   -- trigger: must be delegable
  PRIMARY KEY (grant_id, permission_key)
);

-- One row per minted run token (never the token): the jti ledger that revocation and lineage walk.
CREATE TABLE IF NOT EXISTS identity_run_credentials (
  jti                  TEXT PRIMARY KEY,                 -- rt_
  parent_jti           TEXT,
  org_id               TEXT NOT NULL,
  run_id               TEXT NOT NULL,
  grant_id             TEXT,
  subject_principal_id TEXT NOT NULL,
  mode                 TEXT NOT NULL CHECK (mode IN ('obo','autonomous')),
  chain                JSONB NOT NULL,                   -- ["agt_atlas#run_8811","agt_forge#run_8812"]
  depth                INT NOT NULL,
  aud                  TEXT NOT NULL CHECK (aud IN ('boss:api','boss:mcp','boss:egress','boss:token')),
  scope_hash           TEXT NOT NULL,
  cnf_jkt              TEXT NOT NULL,
  issued_at            TIMESTAMPTZ NOT NULL,
  expires_at           TIMESTAMPTZ NOT NULL,
  revoked_at           TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS identity_run_credentials_run ON identity_run_credentials (run_id);
CREATE INDEX IF NOT EXISTS identity_run_credentials_grant ON identity_run_credentials (grant_id) WHERE grant_id IS NOT NULL;
CREATE UNLOGGED TABLE IF NOT EXISTS identity_dpop_replay (  -- DPoP proof jti cache (A42)
  jkt        TEXT NOT NULL,
  jti        TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (jkt, jti)
);

CREATE TABLE IF NOT EXISTS identity_egress_credentials (  -- boss_egr_ per-run sandbox credential, hash only
  id         TEXT PRIMARY KEY,
  token_hash TEXT NOT NULL UNIQUE,
  run_id     TEXT NOT NULL,
  sandbox_id TEXT NOT NULL,
  jti        TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ
);
-- A revocation cascade's runs, by id: the NOTIFY payload carries only this row's id (a payload is
-- capped at 8000 bytes and a cascade can halt thousands of runs), and a listener that was away
-- catches up from the last id it processed.
CREATE TABLE IF NOT EXISTS identity_revocation_notices (
  id         BIGSERIAL PRIMARY KEY,
  trigger    TEXT NOT NULL,
  target_id  TEXT NOT NULL,
  runs       TEXT[] NOT NULL DEFAULT '{}',
  reason     TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS identity_egress_log (
  id            BIGSERIAL,
  ts            TIMESTAMPTZ NOT NULL DEFAULT now(),
  org_id        TEXT NOT NULL,
  run_id        TEXT NOT NULL,
  jti           TEXT,
  chain         JSONB,
  provider      TEXT NOT NULL,
  method        TEXT NOT NULL,
  path_template TEXT NOT NULL,
  status        INT,
  bytes_out     BIGINT,
  bytes_in      BIGINT,
  decision      TEXT NOT NULL CHECK (decision IN ('allowed','denied')),
  deny_reason   TEXT,
  PRIMARY KEY (id, ts)
) PARTITION BY RANGE (ts);
CREATE TABLE IF NOT EXISTS identity_egress_log_default PARTITION OF identity_egress_log DEFAULT;

-- The vault: envelope encryption. Each row has its own DEK (wrapped by the KEK named in kek_id);
-- AAD = item_id || owner_principal_id || provider || kind, so a ciphertext moved to another row
-- fails to decrypt. Only boss_engine/identity/vault.py decrypts.
CREATE TABLE IF NOT EXISTS identity_vault_keks (
  kek_id     TEXT PRIMARY KEY,
  kcv        BYTEA NOT NULL,                             -- key check value; boot refuses on mismatch
  source     TEXT NOT NULL,                              -- file | env | kms:<provider>
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  retired_at TIMESTAMPTZ
);
CREATE TABLE IF NOT EXISTS identity_vault_items (
  id                 TEXT PRIMARY KEY,                   -- vlt_
  org_id             TEXT NOT NULL REFERENCES orgs(id),
  owner_principal_id TEXT,                               -- NULL = org-level (GitHub App key)
  kind               TEXT NOT NULL CHECK (kind IN ('oauth_user','app_private_key','provider_credential',
                       'oidc_client_secret','totp_secret','signing_key','legacy_pat','app_secret')),
  provider           TEXT,
  provider_subject   TEXT,
  connection_name    TEXT,
  granted_scopes     TEXT[],
  dek_wrapped        BYTEA NOT NULL,
  kek_id             TEXT NOT NULL,
  secret_enc         BYTEA NOT NULL,
  secret_nonce       BYTEA NOT NULL,
  refresh_enc        BYTEA,
  refresh_nonce      BYTEA,
  access_expires_at  TIMESTAMPTZ,
  refresh_expires_at TIMESTAMPTZ,
  status             TEXT NOT NULL CHECK (status IN ('active','needs_reauth','revoked')),
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at       TIMESTAMPTZ,
  last_refreshed_at  TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS identity_vault_items_owner ON identity_vault_items (owner_principal_id, provider);
-- Revoked here but not yet at the provider (it was unreachable): kept, unusable, until a retry
-- succeeds; only then is the ciphertext shredded.
ALTER TABLE identity_vault_items ADD COLUMN IF NOT EXISTS provider_revoke_pending BOOLEAN NOT NULL DEFAULT false;
-- AMENDMENT (APP_TEMPLATES_AND_SECURITY_LOOP.md §2.4, stream S2): kind `app_secret`, an app's
-- secret per environment (app_secret_bindings in the F2 block). Widened in place on an install
-- whose table predates it; the AAD binds such an item to (org, project, app, env, name) through
-- its `provider` column (identity/vault.py app_secret_provider).
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'identity_vault_items_kind_check'
      AND pg_get_constraintdef(oid) NOT LIKE '%app_secret%'
  ) THEN
    ALTER TABLE identity_vault_items DROP CONSTRAINT identity_vault_items_kind_check;
    ALTER TABLE identity_vault_items
      ADD CONSTRAINT identity_vault_items_kind_check
      CHECK (kind IN ('oauth_user','app_private_key','provider_credential','oidc_client_secret',
                      'totp_secret','signing_key','legacy_pat','app_secret'));
  END IF;
END $$;

CREATE TABLE IF NOT EXISTS identity_signing_keys (        -- JWKS for run and actor tokens; two published at a time
  kid                   TEXT PRIMARY KEY,
  family                TEXT NOT NULL CHECK (family IN ('run','actor')),
  alg                   TEXT NOT NULL CHECK (alg = 'EdDSA'),
  public_jwk            JSONB NOT NULL,
  private_vault_item_id TEXT NOT NULL,
  status                TEXT NOT NULL CHECK (status IN ('next','active','retiring','retired')),
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  activated_at          TIMESTAMPTZ,
  retire_after          TIMESTAMPTZ
);

-- Per-org policy (MFA by role, sessions, self sign-up, email sign-in, delegation limits, legacy
-- cutoff, ...) and the identity epoch every mutation bumps (cache invalidation, §6.6).
CREATE TABLE IF NOT EXISTS identity_settings (
  org_id     TEXT PRIMARY KEY REFERENCES orgs(id),
  policy     JSONB NOT NULL DEFAULT '{}',
  epoch      BIGINT NOT NULL DEFAULT 0,
  updated_by TEXT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- The console banners a person has closed (GET /v1/identity/me `banners`, POST
-- /v1/identity/me/banners/{id}/dismiss; identity/banner_policy.py). banner_id is kind.instance:
-- a new event (another new device) is a new id, so it shows again.
CREATE TABLE IF NOT EXISTS identity_banner_dismissals (
  principal_id TEXT NOT NULL REFERENCES identity_principals(id) ON DELETE CASCADE,
  banner_id    TEXT NOT NULL,
  kind         TEXT NOT NULL,
  dismissed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  hidden_until TIMESTAMPTZ,                              -- NULL: closed while this instance lasts
  PRIMARY KEY (principal_id, banner_id)
);
CREATE UNLOGGED TABLE IF NOT EXISTS identity_rate_limits (
  bucket       TEXT NOT NULL,
  key_hash     TEXT NOT NULL,                            -- HMAC(server key, lowercased identifier)
  window_start TIMESTAMPTZ NOT NULL,
  count        INT NOT NULL,
  PRIMARY KEY (bucket, key_hash, window_start)
);

-- The org's GitHub App (Setup › Repo › Connect a GitHub App, created from a manifest). Secrets are
-- in the vault (app_private_key, the OAuth client secret); this row holds only what names the App.
CREATE TABLE IF NOT EXISTS identity_github_app (
  org_id          TEXT PRIMARY KEY REFERENCES orgs(id),
  app_id          TEXT NOT NULL,
  slug            TEXT,
  html_url        TEXT,
  client_id       TEXT,
  installation_id TEXT,
  account_login   TEXT,
  created_by      TEXT,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- Which settings tree each GitHub link goes to (identity/github_urls.py): the App's OWNER and the
-- installation's ACCOUNT, each "User" or "Organization", as GitHub's API reports them. And what
-- GitHub last said the installation was actually granted (permissions, repositories), so Setup
-- shows what GitHub accepted rather than what BOSS asked for.
ALTER TABLE identity_github_app ADD COLUMN IF NOT EXISTS owner_login TEXT;
ALTER TABLE identity_github_app ADD COLUMN IF NOT EXISTS owner_type TEXT;
ALTER TABLE identity_github_app ADD COLUMN IF NOT EXISTS account_type TEXT;
ALTER TABLE identity_github_app ADD COLUMN IF NOT EXISTS verified JSONB;
ALTER TABLE identity_github_app ADD COLUMN IF NOT EXISTS verified_at TIMESTAMPTZ;
-- EVERY ACCOUNT THE APP IS INSTALLED ON (BOSSAPP-945, Add a GitHub account): one row per
-- installation of the org's App, as GitHub's own API reported it (GET /app/installations). The
-- installation on identity_github_app stays the first one (the default); a token for a repository
-- is minted on the installation of that repository's owner (github_app.mint_installation_token).
CREATE TABLE IF NOT EXISTS identity_github_installations (
  org_id               TEXT NOT NULL REFERENCES orgs(id),
  installation_id      TEXT NOT NULL,
  account_login        TEXT,
  account_type         TEXT,
  account_id           TEXT,
  repository_selection TEXT,
  created_by           TEXT,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (org_id, installation_id)
);
CREATE INDEX IF NOT EXISTS identity_github_installations_login
  ON identity_github_installations (lower(account_login));

-- "Request access" from a refusal (amendment A13): who asked for which permission where, kept so
-- an admin can see open requests and the requester is never asked twice. Decided by a binding.
CREATE TABLE IF NOT EXISTS identity_access_requests (
  id                     TEXT PRIMARY KEY,                 -- acr_…
  org_id                 TEXT NOT NULL REFERENCES orgs(id),
  requester_principal_id TEXT NOT NULL REFERENCES identity_principals(id) ON DELETE CASCADE,
  permission_key         TEXT NOT NULL REFERENCES identity_permissions(key),
  project_id             TEXT,                             -- NULL = org scope
  reason                 TEXT,
  status                 TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','granted','declined','withdrawn')),
  created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at            TIMESTAMPTZ,
  resolved_by            TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS identity_access_requests_one_open
  ON identity_access_requests (org_id, requester_principal_id, permission_key, coalesce(project_id, ''))
  WHERE status = 'open';

-- Legacy credential and identity paths, each mapped to a real principal (§12). One row per path
-- in use; last_used_at/use_count feed the "legacy credentials still in use" posture item and the
-- 30-day retirement countdown (operator decision 1).
CREATE TABLE IF NOT EXISTS identity_legacy_mappings (
  org_id          TEXT NOT NULL REFERENCES orgs(id),
  legacy_kind     TEXT NOT NULL CHECK (legacy_kind IN ('member_id','shared_password','console_api_key',
                    'env_api_key','network_mode','claimed_actor','scim_bearer','oidc_bearer')),
  legacy_ref      TEXT NOT NULL,                         -- member id, or an HMAC of a key; never a secret
  principal_id    TEXT NOT NULL REFERENCES identity_principals(id),
  access_role_key TEXT,                                  -- role the legacy path maps to (operator by default)
  retire_after    TIMESTAMPTZ,                           -- the path stops working after this
  first_used_at   TIMESTAMPTZ,
  last_used_at    TIMESTAMPTZ,
  use_count       BIGINT NOT NULL DEFAULT 0,
  retired_at      TIMESTAMPTZ,
  PRIMARY KEY (org_id, legacy_kind, legacy_ref)
);

-- Shadow-mode decisions, AGGREGATED (one row per route x permission x reason x principal kind per
-- day), so shadow mode never floods the hash-chained security log (amendment A5).
CREATE TABLE IF NOT EXISTS identity_authz_shadow (
  day            DATE NOT NULL,
  router_key     TEXT NOT NULL,
  method         TEXT NOT NULL,
  path_template  TEXT NOT NULL,
  permission     TEXT NOT NULL DEFAULT '',
  reason         TEXT NOT NULL,
  principal_kind TEXT NOT NULL DEFAULT '',
  count          BIGINT NOT NULL DEFAULT 0,
  first_seen     TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen      TIMESTAMPTZ NOT NULL DEFAULT now(),
  sample_request TEXT,
  PRIMARY KEY (day, router_key, method, path_template, permission, reason, principal_kind)
);

-- The security event log: append-only, hash-chained per org (§8). hash = SHA-256(prev_hash ||
-- canonical_json(row minus id, hash)). Written in the same transaction as the change it describes.
CREATE TABLE IF NOT EXISTS identity_security_events (
  id                 BIGSERIAL PRIMARY KEY,
  org_id             TEXT NOT NULL,
  seq                BIGINT NOT NULL,
  ts                 TIMESTAMPTZ NOT NULL DEFAULT now(),
  stream             TEXT NOT NULL CHECK (stream IN ('security','lineage')),
  event_type         TEXT NOT NULL,
  outcome            TEXT NOT NULL CHECK (outcome IN ('success','failure','denied','info')),
  actor_principal_id TEXT,
  actor_kind         TEXT,
  on_behalf_of       TEXT,
  grant_id           TEXT,
  chain              JSONB,
  token_jti          TEXT,
  credential_id      TEXT,
  session_ref        TEXT,                               -- the session's public id, never its token
  target_type        TEXT,
  target_id          TEXT,
  permission         TEXT,
  scope              TEXT,
  ip                 INET,
  user_agent         TEXT,
  request_id         TEXT,
  details            JSONB NOT NULL DEFAULT '{}',
  prev_hash          BYTEA NOT NULL,
  hash               BYTEA NOT NULL,
  UNIQUE (org_id, seq)
);
CREATE INDEX IF NOT EXISTS identity_security_events_ts ON identity_security_events (org_id, ts DESC);
CREATE INDEX IF NOT EXISTS identity_security_events_actor ON identity_security_events (org_id, actor_principal_id, ts DESC);
CREATE INDEX IF NOT EXISTS identity_security_events_grant ON identity_security_events (org_id, grant_id) WHERE grant_id IS NOT NULL;

-- APPEND-ONLY, BY PRIVILEGE AND BY TRIGGER (§8.1, #13).
--  * hash_alg: 2 = HMAC-SHA-256 keyed with the identity server key (a row's hash cannot be
--    recomputed by anyone holding only the database); 1 = the old unkeyed SHA-256, re-keyed once at
--    boot by identity_audit_rekey after the old chain verifies. Verification refuses alg 1.
--  * UPDATE, DELETE and TRUNCATE raise for every session — the only exceptions run INSIDE the two
--    SECURITY DEFINER functions below, as the NOLOGIN role boss_audit_owner, which owns the table,
--    the trigger function and those functions. An app session cannot become it, and no GUC an app
--    session can set opens the table (the old boss.identity_audit_prune switch is gone).
--  * The app's role holds INSERT and SELECT on the table, and EXECUTE on the two functions, only.
--    When the app's role is a SUPERUSER (a stock compose install), privileges cannot bind it: the
--    triggers still refuse, and the keyed chain still makes any tampering detectable. Posture says so.
ALTER TABLE identity_security_events ADD COLUMN IF NOT EXISTS hash_alg SMALLINT NOT NULL DEFAULT 1;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'boss_audit_owner') THEN
    BEGIN
      CREATE ROLE boss_audit_owner NOLOGIN;
    EXCEPTION WHEN insufficient_privilege THEN
      RAISE NOTICE 'boss_audit_owner not created (needs CREATEROLE): audit prune is unavailable';
    END;
  END IF;
END $$;
CREATE OR REPLACE FUNCTION identity_security_events_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF current_user = 'boss_audit_owner' AND TG_OP IN ('DELETE', 'UPDATE') THEN
    IF TG_OP = 'UPDATE' THEN
      -- re-keying only: the row's content never changes
      IF (to_jsonb(NEW) - 'prev_hash' - 'hash' - 'hash_alg') <> (to_jsonb(OLD) - 'prev_hash' - 'hash' - 'hash_alg')
         OR OLD.hash_alg <> 1 OR NEW.hash_alg <> 2 THEN
        RAISE EXCEPTION 'identity_security_events is append-only (re-key changes only hashes)' USING ERRCODE = 'P0001';
      END IF;
      RETURN NEW;
    END IF;
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'identity_security_events is append-only (%)', TG_OP USING ERRCODE = 'P0001';
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_security_events_append_only'
                 AND tgrelid = 'identity_security_events'::regclass) THEN
    CREATE TRIGGER identity_security_events_append_only BEFORE UPDATE OR DELETE
      ON identity_security_events FOR EACH ROW EXECUTE FUNCTION identity_security_events_append_only();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_security_events_no_truncate'
                 AND tgrelid = 'identity_security_events'::regclass) THEN
    CREATE TRIGGER identity_security_events_no_truncate BEFORE TRUNCATE
      ON identity_security_events FOR EACH STATEMENT EXECUTE FUNCTION identity_security_events_append_only();
  END IF;
END $$;
-- N3: a CHECKPOINT licenses a prune, so only the table's owner writes one — in practice only the
-- SECURITY DEFINER identity_audit_checkpoint below. An app session that may INSERT events cannot
-- forge `audit.checkpoint {pruned_through_seq}` and then prune with it.
CREATE OR REPLACE FUNCTION identity_security_events_checkpoint_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.event_type = 'audit.checkpoint'
     AND current_user <> (SELECT pg_get_userbyid(relowner) FROM pg_class WHERE oid = TG_RELID) THEN
    RAISE EXCEPTION 'identity_security_events: a checkpoint is written only by identity_audit_checkpoint'
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_security_events_checkpoint_guard'
                 AND tgrelid = 'identity_security_events'::regclass) THEN
    CREATE TRIGGER identity_security_events_checkpoint_guard BEFORE INSERT
      ON identity_security_events FOR EACH ROW EXECUTE FUNCTION identity_security_events_checkpoint_guard();
  END IF;
END $$;
-- The audit log's retention FLOOR, in SQL: nothing younger than this is ever checkpointed for
-- pruning or pruned, whatever the caller (the API's own floor, identity_admin.MIN_PRUNE_DAYS, is
-- the same; a test keeps them equal).
CREATE OR REPLACE FUNCTION identity_audit_min_prune_age() RETURNS INTERVAL
LANGUAGE sql IMMUTABLE AS $$ SELECT interval '30 days' $$;
-- The one way to append a checkpoint: it must extend the org's chain (next seq, prev_hash = the
-- newest row's hash) and name a range whose prunable rows are all older than the floor. The row's
-- HMAC is computed by the API (the key is not in the database); verify_chain checks it.
CREATE OR REPLACE FUNCTION identity_audit_checkpoint(p_row JSONB, p_prev BYTEA, p_hash BYTEA) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_org TEXT := p_row->>'org_id';
  v_seq BIGINT := (p_row->>'seq')::BIGINT;
  v_upper BIGINT := (p_row->'details'->>'pruned_through_seq')::BIGINT;
  v_last RECORD;
  v_id BIGINT;
BEGIN
  IF p_row->>'event_type' IS DISTINCT FROM 'audit.checkpoint' THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: not a checkpoint' USING ERRCODE = 'P0001';
  END IF;
  SELECT seq, hash INTO v_last FROM identity_security_events WHERE org_id = v_org ORDER BY seq DESC LIMIT 1;
  IF v_last IS NULL OR v_seq IS DISTINCT FROM v_last.seq + 1 OR p_prev IS DISTINCT FROM v_last.hash THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: a checkpoint extends the chain' USING ERRCODE = 'P0001';
  END IF;
  IF v_upper IS NULL OR v_upper < 1 OR v_upper >= v_seq THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: no range' USING ERRCODE = 'P0001';
  END IF;
  -- D3: the fields verify_chain reads, validated: last_pruned_hash is the hash of the range's last
  -- row (which exists now: the prune comes after), and retained maps kept seqs in the range to
  -- 64 hex digits. A malformed checkpoint is refused here and is a chain break in verify_chain.
  IF NOT COALESCE((p_row->'details'->>'last_pruned_hash') ~ '^[0-9a-f]{64}$', false)
     OR NOT EXISTS (SELECT 1 FROM identity_security_events WHERE org_id = v_org AND seq = v_upper
                    AND encode(hash, 'hex') = p_row->'details'->>'last_pruned_hash') THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: last_pruned_hash must be the hash of the range''s last row'
      USING ERRCODE = 'P0001';
  END IF;
  IF COALESCE(jsonb_typeof(p_row->'details'->'retained'), 'null') NOT IN ('object', 'null') THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: retained must be an object' USING ERRCODE = 'P0001';
  END IF;
  IF jsonb_typeof(p_row->'details'->'retained') = 'object' AND EXISTS (
       SELECT 1 FROM jsonb_each(p_row->'details'->'retained') e
       WHERE CASE WHEN e.key ~ '^[0-9]{1,18}$' THEN e.key::BIGINT NOT BETWEEN 1 AND v_upper ELSE true END
          OR CASE WHEN jsonb_typeof(e.value) = 'string' THEN (e.value #>> '{}') !~ '^[0-9a-f]{64}$'
                  ELSE true END) THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: retained maps seqs in the range to hashes'
      USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM identity_security_events WHERE org_id = v_org AND seq <= v_upper
             AND event_type NOT IN ('audit.checkpoint', 'bootstrap.claimed', 'owner.recovered_by_host')
             AND ts > now() - identity_audit_min_prune_age()) THEN
    RAISE EXCEPTION 'identity_audit_checkpoint: events younger than the retention floor are kept'
      USING ERRCODE = 'P0001';
  END IF;
  INSERT INTO identity_security_events (org_id, seq, ts, stream, event_type, outcome, actor_principal_id,
      actor_kind, on_behalf_of, grant_id, chain, token_jti, credential_id, session_ref, target_type,
      target_id, permission, scope, ip, user_agent, request_id, details, prev_hash, hash, hash_alg)
  VALUES (v_org, v_seq, (p_row->>'ts')::TIMESTAMPTZ, p_row->>'stream', 'audit.checkpoint',
      p_row->>'outcome', p_row->>'actor_principal_id', p_row->>'actor_kind', p_row->>'on_behalf_of',
      p_row->>'grant_id', CASE WHEN jsonb_typeof(p_row->'chain') = 'null' THEN NULL ELSE p_row->'chain' END,
      p_row->>'token_jti', p_row->>'credential_id', p_row->>'session_ref', p_row->>'target_type',
      p_row->>'target_id', p_row->>'permission', p_row->>'scope', (p_row->>'ip')::INET,
      p_row->>'user_agent', p_row->>'request_id', COALESCE(p_row->'details', '{}'::jsonb), p_prev, p_hash,
      COALESCE((p_row->>'hash_alg')::SMALLINT, 2))
  RETURNING id INTO v_id;
  RETURN v_id;
END $$;
-- The prune (Owner, step-up, via audit.prune): deletes ONLY a range that the newest event of the
-- org already checkpoints (an audit.checkpoint naming exactly this upper bound), never the kept
-- event types, and never a row younger than the retention floor. Runs as boss_audit_owner.
CREATE OR REPLACE FUNCTION identity_audit_prune(p_org TEXT, p_upper BIGINT, p_keep TEXT[]) RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_last RECORD;
  v_n BIGINT;
BEGIN
  SELECT seq, event_type, details INTO v_last FROM identity_security_events
   WHERE org_id = p_org ORDER BY seq DESC LIMIT 1;
  IF v_last IS NULL OR v_last.event_type <> 'audit.checkpoint'
     OR (v_last.details->>'pruned_through_seq')::BIGINT IS DISTINCT FROM p_upper
     OR p_upper >= v_last.seq
     OR NOT (p_keep @> ARRAY['audit.checkpoint', 'bootstrap.claimed']) THEN
    RAISE EXCEPTION 'identity_audit_prune: no checkpoint for this range' USING ERRCODE = 'P0001';
  END IF;
  IF EXISTS (SELECT 1 FROM identity_security_events WHERE org_id = p_org AND seq <= p_upper
             AND event_type <> ALL(p_keep) AND ts > now() - identity_audit_min_prune_age()) THEN
    RAISE EXCEPTION 'identity_audit_prune: events younger than the retention floor are kept'
      USING ERRCODE = 'P0001';
  END IF;
  DELETE FROM identity_security_events WHERE org_id = p_org AND seq <= p_upper AND event_type <> ALL(p_keep);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $$;
-- One-time re-keying of rows written before the keyed chain (hash_alg 1 -> 2). Only alg-1 rows,
-- only their hash columns (the trigger checks it). The new hashes are HMACs only the API can make.
CREATE OR REPLACE FUNCTION identity_audit_rekey(p_org TEXT, p_seqs BIGINT[], p_prev BYTEA[], p_hash BYTEA[])
RETURNS BIGINT
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $$
DECLARE
  v_n BIGINT := 0;
  i INT;
BEGIN
  IF array_length(p_seqs, 1) IS DISTINCT FROM array_length(p_hash, 1)
     OR array_length(p_seqs, 1) IS DISTINCT FROM array_length(p_prev, 1) THEN
    RAISE EXCEPTION 'identity_audit_rekey: arrays differ' USING ERRCODE = 'P0001';
  END IF;
  -- N4: one re-key of a WHOLE unkeyed chain, once: every row of the org is alg 1, the arrays name
  -- exactly seq 1..n, and the new chain links (genesis, then each prev = the previous hash). No
  -- picking single rows to overwrite; after it, no alg-1 row is left to re-key.
  IF EXISTS (SELECT 1 FROM identity_security_events WHERE org_id = p_org AND hash_alg <> 1)
     OR (SELECT count(*) FROM identity_security_events WHERE org_id = p_org) <> coalesce(array_length(p_seqs, 1), 0)
     OR p_seqs IS DISTINCT FROM ARRAY(SELECT generate_series(1::BIGINT, coalesce(array_length(p_seqs, 1), 0)::BIGINT))
     OR p_prev[1] IS DISTINCT FROM decode(repeat('00', 32), 'hex') THEN
    RAISE EXCEPTION 'identity_audit_rekey: only a whole unkeyed chain is re-keyed' USING ERRCODE = 'P0001';
  END IF;
  FOR i IN 2 .. coalesce(array_length(p_seqs, 1), 0) LOOP
    IF p_prev[i] IS DISTINCT FROM p_hash[i - 1] THEN
      RAISE EXCEPTION 'identity_audit_rekey: the new chain does not link' USING ERRCODE = 'P0001';
    END IF;
  END LOOP;
  FOR i IN 1 .. coalesce(array_length(p_seqs, 1), 0) LOOP
    UPDATE identity_security_events SET prev_hash = p_prev[i], hash = p_hash[i], hash_alg = 2
     WHERE org_id = p_org AND seq = p_seqs[i] AND hash_alg = 1;
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END $$;
-- Ownership and privileges, when this session may set them (a superuser or the table's owner with
-- membership): the table, its trigger function and the two functions belong to boss_audit_owner;
-- the app's role keeps INSERT, SELECT and EXECUTE.
DO $$
DECLARE
  v_app TEXT := current_user;
BEGIN
  IF v_app = 'boss_audit_owner' OR NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'boss_audit_owner') THEN
    RETURN;
  END IF;
  BEGIN
    ALTER TABLE identity_security_events OWNER TO boss_audit_owner;
    ALTER FUNCTION identity_security_events_append_only() OWNER TO boss_audit_owner;
    ALTER FUNCTION identity_audit_prune(TEXT, BIGINT, TEXT[]) OWNER TO boss_audit_owner;
    ALTER FUNCTION identity_audit_rekey(TEXT, BIGINT[], BYTEA[], BYTEA[]) OWNER TO boss_audit_owner;
    ALTER FUNCTION identity_audit_checkpoint(JSONB, BYTEA, BYTEA) OWNER TO boss_audit_owner;
    ALTER FUNCTION identity_security_events_checkpoint_guard() OWNER TO boss_audit_owner;
    REVOKE ALL ON identity_security_events FROM PUBLIC;
    EXECUTE format('REVOKE ALL ON identity_security_events FROM %I', v_app);
    EXECUTE format('GRANT SELECT, INSERT ON identity_security_events TO %I', v_app);
    EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE identity_security_events_id_seq TO %I', v_app);
    REVOKE ALL ON FUNCTION identity_audit_prune(TEXT, BIGINT, TEXT[]) FROM PUBLIC;
    REVOKE ALL ON FUNCTION identity_audit_rekey(TEXT, BIGINT[], BYTEA[], BYTEA[]) FROM PUBLIC;
    REVOKE ALL ON FUNCTION identity_audit_checkpoint(JSONB, BYTEA, BYTEA) FROM PUBLIC;
    EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_checkpoint(JSONB, BYTEA, BYTEA) TO %I', v_app);
    EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_prune(TEXT, BIGINT, TEXT[]) TO %I', v_app);
    EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_rekey(TEXT, BIGINT[], BYTEA[], BYTEA[]) TO %I', v_app);
  EXCEPTION WHEN insufficient_privilege THEN
    RAISE NOTICE 'identity audit privileges not changed (run as a superuser once to separate the roles)';
  END;
END $$;

-- Grant the app role explicitly (an install whose API connects as a role other than the one that
-- ran the schema): SELECT identity_audit_grant_app('boss_app'), as a superuser.
CREATE OR REPLACE FUNCTION identity_audit_grant_app(p_role TEXT) RETURNS VOID
LANGUAGE plpgsql AS $$
BEGIN
  EXECUTE format('REVOKE ALL ON identity_security_events FROM %I', p_role);
  EXECUTE format('GRANT SELECT, INSERT ON identity_security_events TO %I', p_role);
  EXECUTE format('GRANT USAGE, SELECT ON SEQUENCE identity_security_events_id_seq TO %I', p_role);
  EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_prune(TEXT, BIGINT, TEXT[]) TO %I', p_role);
  EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_rekey(TEXT, BIGINT[], BYTEA[], BYTEA[]) TO %I', p_role);
  EXECUTE format('GRANT EXECUTE ON FUNCTION identity_audit_checkpoint(JSONB, BYTEA, BYTEA) TO %I', p_role);
END $$;

-- Ceilings and grants hold delegable permissions only (D12): a second, independent check.
CREATE OR REPLACE FUNCTION identity_require_delegable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM identity_permissions WHERE key = NEW.permission_key AND delegable) THEN
    RAISE EXCEPTION 'identity: % is not delegable', NEW.permission_key USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_agent_ceilings_delegable'
                 AND tgrelid = 'identity_agent_ceilings'::regclass) THEN
    CREATE TRIGGER identity_agent_ceilings_delegable BEFORE INSERT OR UPDATE
      ON identity_agent_ceilings FOR EACH ROW EXECUTE FUNCTION identity_require_delegable();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_grant_permissions_delegable'
                 AND tgrelid = 'identity_delegation_grant_permissions'::regclass) THEN
    CREATE TRIGGER identity_grant_permissions_delegable BEFORE INSERT OR UPDATE
      ON identity_delegation_grant_permissions FOR EACH ROW EXECUTE FUNCTION identity_require_delegable();
  END IF;
END $$;

-- Amendment A3 in the database (R2 #8): a role every one of whose permissions is org-only (or
-- system-only) does nothing at a project, so no binding of it is ever written at project scope —
-- whatever its stored bindable_scopes say (an import or an older version could have written
-- them wrong). The engine refuses first with words (bindings.refuse_org_only_at_project); this is
-- the backstop for every other writer.
CREATE OR REPLACE FUNCTION identity_refuse_org_only_project_binding() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.scope_type <> 'project' THEN RETURN NEW; END IF;
  IF EXISTS (SELECT 1 FROM identity_access_role_permissions rp WHERE rp.role_id = NEW.role_id)
     AND NOT EXISTS (SELECT 1 FROM identity_access_role_permissions rp
                     JOIN identity_permissions p ON p.key = rp.permission_key
                     WHERE rp.role_id = NEW.role_id AND p.scope_kind = 'project' AND NOT p.system_only) THEN
    RAISE EXCEPTION 'identity_org_only_role: role % holds only org-wide permissions and binds at org only',
      NEW.role_id USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_org_only_project_binding'
                 AND tgrelid = 'identity_role_bindings'::regclass) THEN
    CREATE TRIGGER identity_org_only_project_binding BEFORE INSERT OR UPDATE OF role_id, scope_type
      ON identity_role_bindings FOR EACH ROW EXECUTE FUNCTION identity_refuse_org_only_project_binding();
  END IF;
END $$;

-- Last-Owner protection (§6.12): deferred to commit, so two concurrent demotions cannot both land.
-- Fires only when a change REMOVES Owner reach from a real person: an owner binding deleted or
-- retargeted, an active owner leaving `active`, or a member leaving a group that carries Owner (SCIM,
-- OIDC group sync, a person's deletion, any path). An org that has not recorded its claim
-- (bootstrap.claimed) is not protected yet. It takes the SAME advisory lock as the
-- application (bindings.lock_owners: hashtext('identity_owner:' || org)), so two transactions that each
-- remove one of two Owners serialise and the second sees the first's commit. Only a PERMANENT Owner
-- binding counts as an Owner remaining: one with expires_at lapses with nothing to refuse it.
-- Kept in step with boss_engine.identity.bindings.active_owners (one definition).
CREATE OR REPLACE FUNCTION identity_assert_an_owner_remains() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_org TEXT;
BEGIN
  IF TG_TABLE_NAME = 'identity_role_bindings' THEN
    IF OLD.role_id <> 'arl_owner' OR OLD.scope_type <> 'org' THEN RETURN NULL; END IF;
    IF TG_OP = 'UPDATE' AND NEW.role_id = 'arl_owner' AND NEW.subject_id = OLD.subject_id
       AND NEW.scope_type = OLD.scope_type AND NEW.expires_at IS NOT DISTINCT FROM OLD.expires_at THEN
      RETURN NULL;
    END IF;
    v_org := OLD.org_id;
  ELSIF TG_TABLE_NAME = 'identity_group_members' THEN
    SELECT b.org_id INTO v_org FROM identity_role_bindings b
     WHERE b.subject_type = 'group' AND b.subject_id = OLD.group_id AND b.role_id = 'arl_owner'
       AND b.scope_type = 'org' LIMIT 1;
    IF v_org IS NULL THEN RETURN NULL; END IF;
    IF TG_OP = 'UPDATE' AND NEW.group_id = OLD.group_id AND NEW.principal_id = OLD.principal_id THEN
      RETURN NULL;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM identity_principals p WHERE p.id = OLD.principal_id
                   AND p.kind = 'user' AND p.status = 'active' AND NOT p.network_bound) THEN
      RETURN NULL;
    END IF;
  ELSE
    IF OLD.status <> 'active' OR NEW.status = 'active' THEN RETURN NULL; END IF;
    v_org := OLD.org_id;
    -- only a person who held Owner reach leaving `active` can leave the org ownerless
    IF NOT EXISTS (
      SELECT 1 FROM identity_role_bindings b
       WHERE b.org_id = v_org AND b.role_id = 'arl_owner' AND b.scope_type = 'org'
         AND ((b.subject_type = 'principal' AND b.subject_id = OLD.id)
           OR (b.subject_type = 'group' AND b.subject_id IN (SELECT m.group_id FROM identity_group_members m
                                                             WHERE m.principal_id = OLD.id)))
    ) THEN
      RETURN NULL;
    END IF;
  END IF;
  -- an org that never had a real Owner (pre-claim) is not protected yet
  IF NOT EXISTS (SELECT 1 FROM identity_security_events e
                 WHERE e.org_id = v_org AND e.event_type = 'bootstrap.claimed') THEN
    RETURN NULL;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('identity_owner:' || v_org));
  IF NOT EXISTS (
    SELECT 1 FROM identity_role_bindings b
    JOIN identity_principals p
      ON (b.subject_type = 'principal' AND p.id = b.subject_id)
      OR (b.subject_type = 'group' AND p.id IN (SELECT m.principal_id FROM identity_group_members m
                                                WHERE m.group_id = b.subject_id))
    WHERE b.org_id = v_org AND b.role_id = 'arl_owner' AND b.scope_type = 'org'
      AND b.expires_at IS NULL
      AND p.kind = 'user' AND p.status = 'active' AND NOT p.network_bound
  ) THEN
    RAISE EXCEPTION 'identity_last_owner: org % would have no active Owner', v_org USING ERRCODE = 'P0001';
  END IF;
  RETURN NULL;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_last_owner_bindings'
                 AND tgrelid = 'identity_role_bindings'::regclass) THEN
    CREATE CONSTRAINT TRIGGER identity_last_owner_bindings AFTER UPDATE OR DELETE
      ON identity_role_bindings DEFERRABLE INITIALLY DEFERRED
      FOR EACH ROW EXECUTE FUNCTION identity_assert_an_owner_remains();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_last_owner_principals'
                 AND tgrelid = 'identity_principals'::regclass) THEN
    CREATE CONSTRAINT TRIGGER identity_last_owner_principals AFTER UPDATE OF status
      ON identity_principals DEFERRABLE INITIALLY DEFERRED
      FOR EACH ROW EXECUTE FUNCTION identity_assert_an_owner_remains();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_last_owner_group_members'
                 AND tgrelid = 'identity_group_members'::regclass) THEN
    CREATE CONSTRAINT TRIGGER identity_last_owner_group_members AFTER UPDATE OR DELETE
      ON identity_group_members DEFERRABLE INITIALLY DEFERRED
      FOR EACH ROW EXECUTE FUNCTION identity_assert_an_owner_remains();
  END IF;
END $$;
-- The identity epoch (S5, IDENTITY.md §6.6): one number that moves on ANY identity change, bumped in
-- the changing transaction by a statement-level trigger, with NOTIFY identity_epoch for the push stream.
-- High-churn bookkeeping columns (last_used_at, sign_count, session last_seen) are not watched, so a
-- request never moves it. Generated from boss_engine.identity.change_feed.WATCHED (a test pins it).
CREATE OR REPLACE FUNCTION identity_epoch_bump() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v BIGINT;
BEGIN
  UPDATE identity_settings SET epoch = epoch + 1;
  SELECT max(epoch) INTO v FROM identity_settings;
  PERFORM pg_notify('identity_epoch', coalesce(v, 0)::text);
  RETURN NULL;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_principals'
                 AND tgrelid = 'identity_principals'::regclass) THEN
    CREATE TRIGGER identity_epoch_principals AFTER INSERT OR DELETE OR UPDATE OF status, kind, display_name, network_bound, legacy_member_ids, org_id
      ON identity_principals FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_users'
                 AND tgrelid = 'identity_users'::regclass) THEN
    CREATE TRIGGER identity_epoch_users AFTER INSERT OR DELETE OR UPDATE OF email, mfa_required, principal_id
      ON identity_users FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_user_identities'
                 AND tgrelid = 'identity_user_identities'::regclass) THEN
    CREATE TRIGGER identity_epoch_user_identities AFTER INSERT OR DELETE OR UPDATE OF principal_id, issuer, subject
      ON identity_user_identities FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_providers'
                 AND tgrelid = 'identity_providers'::regclass) THEN
    CREATE TRIGGER identity_epoch_providers AFTER INSERT OR DELETE OR UPDATE
      ON identity_providers FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_provider_group_mappings'
                 AND tgrelid = 'identity_provider_group_mappings'::regclass) THEN
    CREATE TRIGGER identity_epoch_provider_group_mappings AFTER INSERT OR DELETE OR UPDATE
      ON identity_provider_group_mappings FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_totp'
                 AND tgrelid = 'identity_totp'::regclass) THEN
    CREATE TRIGGER identity_epoch_totp AFTER INSERT OR DELETE OR UPDATE OF principal_id, vault_item_id
      ON identity_totp FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_webauthn_credentials'
                 AND tgrelid = 'identity_webauthn_credentials'::regclass) THEN
    CREATE TRIGGER identity_epoch_webauthn_credentials AFTER INSERT OR DELETE OR UPDATE OF principal_id, name
      ON identity_webauthn_credentials FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_groups'
                 AND tgrelid = 'identity_groups'::regclass) THEN
    CREATE TRIGGER identity_epoch_groups AFTER INSERT OR DELETE OR UPDATE
      ON identity_groups FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_group_members'
                 AND tgrelid = 'identity_group_members'::regclass) THEN
    CREATE TRIGGER identity_epoch_group_members AFTER INSERT OR DELETE OR UPDATE
      ON identity_group_members FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_access_roles'
                 AND tgrelid = 'identity_access_roles'::regclass) THEN
    CREATE TRIGGER identity_epoch_access_roles AFTER INSERT OR DELETE OR UPDATE
      ON identity_access_roles FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_access_role_permissions'
                 AND tgrelid = 'identity_access_role_permissions'::regclass) THEN
    CREATE TRIGGER identity_epoch_access_role_permissions AFTER INSERT OR DELETE OR UPDATE
      ON identity_access_role_permissions FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_role_bindings'
                 AND tgrelid = 'identity_role_bindings'::regclass) THEN
    CREATE TRIGGER identity_epoch_role_bindings AFTER INSERT OR DELETE OR UPDATE
      ON identity_role_bindings FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_approval_seats'
                 AND tgrelid = 'identity_approval_seats'::regclass) THEN
    CREATE TRIGGER identity_epoch_approval_seats AFTER INSERT OR DELETE OR UPDATE
      ON identity_approval_seats FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_service_accounts'
                 AND tgrelid = 'identity_service_accounts'::regclass) THEN
    CREATE TRIGGER identity_epoch_service_accounts AFTER INSERT OR DELETE OR UPDATE
      ON identity_service_accounts FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_api_credentials'
                 AND tgrelid = 'identity_api_credentials'::regclass) THEN
    CREATE TRIGGER identity_epoch_api_credentials AFTER INSERT OR DELETE OR UPDATE OF principal_id, scopes, project_ids, cidrs, expires_at, grace_until, suspended_at, revoked_at
      ON identity_api_credentials FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_agent_passports'
                 AND tgrelid = 'identity_agent_passports'::regclass) THEN
    CREATE TRIGGER identity_epoch_agent_passports AFTER INSERT OR DELETE OR UPDATE
      ON identity_agent_passports FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_agent_ceilings'
                 AND tgrelid = 'identity_agent_ceilings'::regclass) THEN
    CREATE TRIGGER identity_epoch_agent_ceilings AFTER INSERT OR DELETE OR UPDATE
      ON identity_agent_ceilings FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_delegation_grants'
                 AND tgrelid = 'identity_delegation_grants'::regclass) THEN
    CREATE TRIGGER identity_epoch_delegation_grants AFTER INSERT OR DELETE OR UPDATE OF status, expires_at, revoked_at, agent_ids, project_ids, resources, allow_subdelegation, max_depth
      ON identity_delegation_grants FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_delegation_grant_permissions'
                 AND tgrelid = 'identity_delegation_grant_permissions'::regclass) THEN
    CREATE TRIGGER identity_epoch_delegation_grant_permissions AFTER INSERT OR DELETE OR UPDATE
      ON identity_delegation_grant_permissions FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'identity_epoch_settings'
                 AND tgrelid = 'identity_settings'::regclass) THEN
    CREATE TRIGGER identity_epoch_settings AFTER INSERT OR DELETE OR UPDATE OF policy
      ON identity_settings FOR EACH STATEMENT EXECUTE FUNCTION identity_epoch_bump();
  END IF;
END $$;
-- ---- Who work acts for, as real columns (IDENTITY.md §7.14 R8, §7.3 3, §7.5; int-a) -------------------
-- Jobs, workflow runs and schedules carry their authority in columns the cascade can index, not only
-- in JSON a caller-shaped payload sits next to. `payload._identity` / `policy_snapshot._identity` /
-- `input._identity` are read as a fallback for rows written before these columns existed, never
-- preferred over them. Written only by the server (lineage.stamp_job, consent.record_on_run,
-- consent.require_for_schedule); a client-supplied value is always stripped.
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS on_behalf_of TEXT;            -- usr_/agt_/sys_ the job acts for
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS grant_id TEXT;                -- dlg_ (NULL: not delegated)
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS chain JSONB;                  -- boss_chain, ["agt_x#run_…", …]
ALTER TABLE jobs ADD COLUMN IF NOT EXISTS on_behalf_system BOOLEAN NOT NULL DEFAULT false; -- BOSS's own background work (sys_worker)
CREATE INDEX IF NOT EXISTS jobs_identity_grant ON jobs (grant_id) WHERE grant_id IS NOT NULL;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS on_behalf_of TEXT;   -- the run's authority, decided at start
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS grant_id TEXT;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS authority_org_id TEXT;
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS authority_run_id TEXT; -- run_wf:<id>[/wf:<child>]
CREATE INDEX IF NOT EXISTS workflow_runs_identity_grant ON workflow_runs (grant_id) WHERE grant_id IS NOT NULL;
ALTER TABLE workflow_schedules ADD COLUMN IF NOT EXISTS on_behalf_of TEXT; -- the schedule's standing grant link
ALTER TABLE workflow_schedules ADD COLUMN IF NOT EXISTS grant_id TEXT;
CREATE INDEX IF NOT EXISTS workflow_schedules_identity_grant ON workflow_schedules (grant_id) WHERE grant_id IS NOT NULL;

-- What a run token SAID, on its ledger row (the console's "Show token claims"): the task binding,
-- the token's own scope, and the redacted claim set (no signature, no cnf key, nothing secret).
ALTER TABLE identity_run_credentials ADD COLUMN IF NOT EXISTS task JSONB;
ALTER TABLE identity_run_credentials ADD COLUMN IF NOT EXISTS scope TEXT[];
ALTER TABLE identity_run_credentials ADD COLUMN IF NOT EXISTS claims JSONB;

-- SAML (amendment S1-5): the IdP's SSO endpoint (until now carried in client_id) and the
-- AuthnContextClassRef set that counts as MFA under "trust IdP MFA" (NULL: BOSS's default list).
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS saml_sso_url TEXT;
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS trusted_authn_contexts TEXT[];
-- §4.8 OIDC client authentication: a vaulted client secret, or private_key_jwt (RFC 7523): BOSS
-- signs a client assertion with a vaulted private key (generated by BOSS or uploaded, e.g. Apple's).
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS client_auth TEXT NOT NULL DEFAULT 'client_secret';
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS client_key_vault_item_id TEXT;
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS client_key_kid TEXT;
ALTER TABLE identity_providers ADD COLUMN IF NOT EXISTS client_assertion_issuer TEXT;
-- F3 (authentication security fixes). H1: a session of a person whose roles need MFA and who has
-- no second factor is ENROLMENT-ONLY; enrolling the FIRST factor needs this session-bound grant
-- (set at the claim, an invitation acceptance, the first sign-in ever, or the first sign-in after an
-- admin's MFA reset; 15 minutes). identity_users.first_factor_grant_until is the reset's pending grant.
ALTER TABLE identity_sessions ADD COLUMN IF NOT EXISTS enrol_grant_until TIMESTAMPTZ;
ALTER TABLE identity_users ADD COLUMN IF NOT EXISTS first_factor_grant_until TIMESTAMPTZ;
-- M2: an invitation that was EMAILED proves the mailbox: accepting it verifies the address.
ALTER TABLE identity_invitations ADD COLUMN IF NOT EXISTS emailed BOOLEAN NOT NULL DEFAULT false;
-- M1: a federated identity is keyed by its PROVIDER plus (issuer, subject), and an issuer names one
-- provider per org (a second provider claiming the same issuer could sign in as the first's people).
CREATE UNIQUE INDEX IF NOT EXISTS identity_providers_issuer_per_org ON identity_providers (org_id, lower(issuer))
  WHERE issuer IS NOT NULL AND issuer <> '';
CREATE UNIQUE INDEX IF NOT EXISTS identity_user_identities_provider_subject
  ON identity_user_identities (provider_id, issuer, subject);
-- L3: a passkey whose sign counter went backwards is flagged (and, when device-bound, refused).
ALTER TABLE identity_webauthn_credentials ADD COLUMN IF NOT EXISTS counter_regressed_at TIMESTAMPTZ;
-- L4: an org is claimed once. The advisory lock serialises claims; this makes a second
-- `bootstrap.claimed` impossible even if a code path forgets the lock.
CREATE UNIQUE INDEX IF NOT EXISTS identity_one_claim_per_org ON identity_security_events (org_id)
  WHERE event_type = 'bootstrap.claimed';
-- ================================ end BOSS IDENTITY ===============================================

-- ============================================================================================
-- THE MODEL ROUTER (docs/product/MODEL_ROUTER.md). One policy document per project, one route
-- record per decision at a boundary, the route id on every llm_calls row of that boundary, and
-- OpenRouter's catalogue with prices. Names, tiers and reasons only: no prompts, no secrets.
-- ============================================================================================
CREATE TABLE IF NOT EXISTS model_routing_policies (
  project_id   TEXT PRIMARY KEY,
  policy       JSONB NOT NULL DEFAULT '{}'::jsonb,
  version      INTEGER NOT NULL DEFAULT 1,
  updated_by   TEXT,
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS model_routes (
  id                TEXT PRIMARY KEY,
  project_id        TEXT,
  unit_kind         TEXT NOT NULL,     -- build_stage | workflow_step | agent | chat | decision | panel | research
  unit_id           TEXT,              -- code task run, workflow run, thread or meeting
  step              TEXT NOT NULL,
  ref               TEXT,              -- the workflow step id / panel phase this route served
  role              TEXT,
  mode              TEXT NOT NULL,     -- fixed | smart
  tier              TEXT,
  classified_tier   TEXT,
  classifier        TEXT,
  confidence        NUMERIC,
  engine            TEXT,
  model             TEXT,
  source_id         TEXT,
  source_kind       TEXT,
  rules             JSONB NOT NULL DEFAULT '[]'::jsonb,
  why               JSONB NOT NULL DEFAULT '[]'::jsonb,
  reason            TEXT,
  escalation        TEXT,
  escalation_signal TEXT,
  fallback          BOOLEAN NOT NULL DEFAULT false,
  moved_by_headroom BOOLEAN NOT NULL DEFAULT false,
  budget_lite       BOOLEAN NOT NULL DEFAULT false,
  latency_ms        NUMERIC,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS model_routes_unit ON model_routes (unit_id, created_at);
CREATE INDEX IF NOT EXISTS model_routes_project ON model_routes (project_id, created_at DESC);

ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS route_id TEXT;
ALTER TABLE run_scorecards ADD COLUMN IF NOT EXISTS route_mode TEXT;
ALTER TABLE run_scorecards ADD COLUMN IF NOT EXISTS route_tier TEXT;
ALTER TABLE run_scorecards ADD COLUMN IF NOT EXISTS routing JSONB NOT NULL DEFAULT '{}'::jsonb;

CREATE TABLE IF NOT EXISTS provider_model_catalog (
  provider                 TEXT NOT NULL,
  model_id                 TEXT NOT NULL,
  name                     TEXT,
  prompt_usd_per_mtok      NUMERIC,
  completion_usd_per_mtok  NUMERIC,
  context_length           INTEGER,
  tools                    BOOLEAN NOT NULL DEFAULT false,
  fetched_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (provider, model_id)
);

-- A subscription's windows belong to the ACCOUNT that spends, not to a project: two projects on
-- one Claude login share one week (model_router.accounts). Keyed by the credential's identity —
-- a secret ref id, a hash prefix of an install token, or the host's CLI login; never a secret.
CREATE TABLE IF NOT EXISTS subscription_accounts (
  account_key                   TEXT PRIMARY KEY,
  engine                        TEXT NOT NULL,
  windows                       JSONB NOT NULL DEFAULT '{}'::jsonb,
  learned_weekly_allowance_usd  NUMERIC,
  updated_at                    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- =================================================================================================
-- APP PLATFORM (docs/product/APP_TEMPLATES_AND_SECURITY_LOOP.md). One delimited block per feature,
-- created by stream S0 on day 1 (§8.2): each stream edits ONLY inside its own block, so no two
-- streams touch the same lines. F1 (toolchains) and F3 (templates) define no tables.
-- =================================================================================================

-- BEGIN F2 (template system; owner: stream S2; spec §2.4, §2.7) --------------------------------
-- A template version known to an org: a built-in (templates/apps/<id>/) or an import pinned to a
-- commit SHA and digest (§2.5). `manifest` is the validated boss-template.yaml
-- (engine/boss_engine/templates/manifest.py, schema boss.template/v1).
CREATE TABLE IF NOT EXISTS app_templates (
  id            TEXT PRIMARY KEY,
  org_id        TEXT NOT NULL REFERENCES orgs(id),
  template_key  TEXT NOT NULL,
  version       TEXT NOT NULL,
  source        TEXT NOT NULL CHECK (source IN ('builtin', 'git')),
  git_url       TEXT,
  commit_sha    TEXT,
  digest        TEXT,
  manifest      JSONB NOT NULL DEFAULT '{}'::jsonb,
  status        TEXT NOT NULL DEFAULT 'pending_review'
                CHECK (status IN ('active', 'pending_review', 'rejected', 'hidden')),
  validation    JSONB NOT NULL DEFAULT '{}'::jsonb,
  trial         JSONB,
  imported_by   TEXT,
  approved_by   TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  approved_at   TIMESTAMPTZ,
  UNIQUE (org_id, template_key, version)
);

-- One apply of a template to an app: a governed build (§2.3).
CREATE TABLE IF NOT EXISTS app_template_applications (
  id                TEXT PRIMARY KEY,
  project_id        TEXT NOT NULL REFERENCES projects(id),
  app_key           TEXT NOT NULL,
  template_id       TEXT NOT NULL REFERENCES app_templates(id),
  version           TEXT NOT NULL,
  stack             TEXT NOT NULL,
  framework         TEXT,
  workflow_run_id   TEXT,
  code_task_run_id  TEXT,
  status            TEXT NOT NULL DEFAULT 'building'
                    CHECK (status IN ('building', 'pr_open', 'applied', 'failed', 'blocked', 'abandoned')),
  created_by        TEXT,
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at        TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS app_template_applications_app ON app_template_applications (project_id, app_key);
-- A build a template gate stopped is BLOCKED (not "building" for ever, not "failed"): the reason
-- and the next step are on the row. Widened in place on an install whose table predates it.
ALTER TABLE app_template_applications ADD COLUMN IF NOT EXISTS blocked_reason TEXT;
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'app_template_applications_status_check'
      AND pg_get_constraintdef(oid) NOT LIKE '%blocked%'
  ) THEN
    ALTER TABLE app_template_applications DROP CONSTRAINT app_template_applications_status_check;
    ALTER TABLE app_template_applications
      ADD CONSTRAINT app_template_applications_status_check
      CHECK (status IN ('building', 'pr_open', 'applied', 'failed', 'blocked', 'abandoned'));
  END IF;
END $$;

-- An app's secret, per environment (§2.4). The value lives in the vault (kind app_secret); this row
-- holds presence and mode only. `live` is never handed to a build sandbox or a preview.
CREATE TABLE IF NOT EXISTS app_secret_bindings (
  id             TEXT PRIMARY KEY,
  project_id     TEXT NOT NULL REFERENCES projects(id),
  app_key        TEXT NOT NULL,
  env            TEXT NOT NULL CHECK (env IN ('build', 'preview', 'deploy')),
  name           TEXT NOT NULL,
  vault_item_id  TEXT,
  mode           TEXT NOT NULL,
  set_by         TEXT,
  set_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at   TIMESTAMPTZ,
  UNIQUE (project_id, app_key, env, name),
  -- table-level, not inline: the column reconcile (db._safe_add_column_def) cuts a column
  -- definition at the word GENERATED, so an inline CHECK naming 'generated' would not parse.
  CONSTRAINT app_secret_bindings_mode CHECK (mode IN ('test', 'live', 'generated', 'stub'))
);
-- S2: the files of a template version (built-in or imported), so the API, the worker and the
-- build gate read the SAME pinned content without a shared volume. Imported content is
-- untrusted: it is read as data (the brief enveloped, the tests run only inside a build).
CREATE TABLE IF NOT EXISTS app_template_files (
  template_id  TEXT NOT NULL REFERENCES app_templates(id) ON DELETE CASCADE,
  path         TEXT NOT NULL,
  content      BYTEA NOT NULL,
  PRIMARY KEY (template_id, path)
);
-- S2: a live binding is usable for deploy only once a person holding app_secret:live approved
-- this decision (§2.4).
ALTER TABLE app_secret_bindings ADD COLUMN IF NOT EXISTS live_decision_id TEXT;
-- S2: the shape verdict computed when the value was written (matches_test_pattern |
-- matches_live_pattern | unknown), so reading presence never decrypts.
ALTER TABLE app_secret_bindings ADD COLUMN IF NOT EXISTS shape TEXT;
-- END F2 ------------------------------------------------------------------------------------------

-- BEGIN F4 (security review; owner: stream S4; spec §4.4) -----------------------------------------
CREATE TABLE IF NOT EXISTS security_scans (
  id               TEXT PRIMARY KEY,
  project_id       TEXT NOT NULL REFERENCES projects(id),
  app_key          TEXT NOT NULL,
  commit_sha       TEXT,
  workflow_run_id  TEXT,
  target           JSONB NOT NULL DEFAULT '{}'::jsonb,
  tools            JSONB NOT NULL DEFAULT '[]'::jsonb,  -- [{name, version, image_digest, rules_digest, exit, duration_ms}]
  status           TEXT NOT NULL DEFAULT 'queued' CHECK (status IN ('queued', 'running', 'done', 'failed')),
  counts           JSONB NOT NULL DEFAULT '{}'::jsonb,
  triggered_by     TEXT,
  started_at       TIMESTAMPTZ,
  ended_at         TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS security_scans_app ON security_scans (project_id, app_key);

-- fingerprint = sha256(tool | rule_id | normalised location | normalised snippet) (§4.4).
CREATE TABLE IF NOT EXISTS security_findings (
  id                  TEXT PRIMARY KEY,
  scan_id             TEXT NOT NULL REFERENCES security_scans(id),
  fingerprint         TEXT NOT NULL,
  tool                TEXT NOT NULL,
  rule_id             TEXT NOT NULL,
  title               TEXT NOT NULL,
  severity            TEXT NOT NULL CHECK (severity IN ('critical', 'high', 'medium', 'low', 'info')),
  confidence          TEXT,
  cwe                 TEXT,
  owasp               TEXT,
  location            JSONB NOT NULL DEFAULT '{}'::jsonb,  -- {file, line} | {url, method, param}
  evidence            JSONB NOT NULL DEFAULT '{}'::jsonb   -- redacted
                      CHECK (octet_length(evidence::text) <= 4096),
  status              TEXT NOT NULL DEFAULT 'open'
                      CHECK (status IN ('open', 'fixed', 'accepted', 'false_positive')),
  triaged_by          TEXT,
  triage_reason       TEXT,
  first_seen_scan_id  TEXT,
  UNIQUE (scan_id, fingerprint)
);

CREATE TABLE IF NOT EXISTS security_recommendations (
  id               TEXT PRIMARY KEY,
  workflow_run_id  TEXT,
  meeting_id       TEXT,
  title            TEXT NOT NULL,
  fix              TEXT,
  priority         TEXT,
  effort           TEXT,
  fingerprints     TEXT[] NOT NULL DEFAULT '{}',
  selected         BOOLEAN NOT NULL DEFAULT false,
  decided_by       TEXT
);
-- The security_review workflow (S4-workflow): which project and scan a recommendation answers,
-- whether the Panel wrote it or BOSS derived it from findings the Panel left uncovered, the
-- Panel's risk and false-positive notes, its place in the list, and when a person decided.
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS project_id TEXT;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS scan_id TEXT;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'panel';
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS risk_if_unfixed TEXT;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS false_positive_reason TEXT;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS position INTEGER NOT NULL DEFAULT 0;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS decided_at TIMESTAMPTZ;
ALTER TABLE security_recommendations ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE INDEX IF NOT EXISTS security_recommendations_run ON security_recommendations (workflow_run_id);
-- END F4 ------------------------------------------------------------------------------------------

-- BEGIN F5 (cross-app links; owner: stream S5; spec §5.2) -----------------------------------------
-- Same-project only in v1 (D7). The consumer gets BOSS_LINK_<ALIAS>_* at build, preview and deploy.
-- One gateway port per active link (D8), from BOSS_LINK_PORTS. An alias is unique among a
-- consumer's ACTIVE links only, so a revoked link's alias can be linked again.
CREATE TABLE IF NOT EXISTS app_links (
  id                 TEXT PRIMARY KEY,
  project_id         TEXT NOT NULL REFERENCES projects(id),
  consumer_app_key   TEXT NOT NULL,
  provider_app_key   TEXT NOT NULL,
  alias              TEXT NOT NULL CHECK (alias ~ '^[A-Z][A-Z0-9_]{1,30}$'),
  env                TEXT NOT NULL CHECK (env IN ('preview', 'deploy')),
  credentials        TEXT NOT NULL DEFAULT 'none' CHECK (credentials IN ('none', 'test_users', 'client')),
  status             TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  gateway_port       INTEGER,
  created_by         TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at         TIMESTAMPTZ,
  revoked_by         TEXT,
  last_used_at       TIMESTAMPTZ,
  CHECK (consumer_app_key <> provider_app_key)
);
CREATE UNIQUE INDEX IF NOT EXISTS app_links_active_alias
  ON app_links (project_id, consumer_app_key, alias, env) WHERE status = 'active';
CREATE UNIQUE INDEX IF NOT EXISTS app_links_active_port ON app_links (gateway_port) WHERE status = 'active';
-- A link pass: what one consumer workload (a build run, or a preview) presents to the gateway as
-- X-Boss-Link. Only its hash is stored. Revoked with its link, expired with its workload.
CREATE TABLE IF NOT EXISTS app_link_passes (
  token_hash     TEXT PRIMARY KEY,
  link_id        TEXT NOT NULL REFERENCES app_links(id),
  project_id     TEXT NOT NULL,
  consumer_kind  TEXT NOT NULL CHECK (consumer_kind IN ('run', 'preview')),
  consumer_id    TEXT NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at     TIMESTAMPTZ NOT NULL,
  revoked_at     TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS app_link_passes_link ON app_link_passes (link_id);
-- A provider app's generated test users (BOSS_TEST_USERS), per env: the values are in the vault
-- (identity_vault_items, provider 'boss_test_users'); this row is presence, count and rotation.
CREATE TABLE IF NOT EXISTS app_test_users (
  project_id     TEXT NOT NULL,
  app_key        TEXT NOT NULL,
  env            TEXT NOT NULL CHECK (env IN ('preview', 'deploy')),
  vault_item_id  TEXT NOT NULL,
  user_count     INTEGER NOT NULL,
  generation     INTEGER NOT NULL DEFAULT 1,
  rotated_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, app_key, env)
);
-- A link a NEW app asked for when it was started (the composer's "Talks to", §5.5): the app does
-- not exist until its first build, so the start records the request (checked then: app_link:manage,
-- the provider in this project, the alias) and that build creates the link. Written only by
-- POST /v1/delivery-workflows/start, never from a run's input, so no caller can forge one.
CREATE TABLE IF NOT EXISTS app_link_requests (
  id                 TEXT PRIMARY KEY,
  project_id         TEXT NOT NULL REFERENCES projects(id),
  workflow_run_id    TEXT NOT NULL,
  provider_app_key   TEXT NOT NULL,
  alias              TEXT NOT NULL CHECK (alias ~ '^[A-Z][A-Z0-9_]{1,30}$'),
  env                TEXT NOT NULL CHECK (env IN ('preview', 'deploy')),
  credentials        TEXT NOT NULL DEFAULT 'none' CHECK (credentials IN ('none', 'test_users')),
  requested_by       TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  outcome            TEXT CHECK (outcome IN ('created', 'refused')),
  outcome_detail     TEXT,
  link_id            TEXT,
  resolved_at        TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS app_link_requests_run ON app_link_requests (workflow_run_id);
-- END F5 ------------------------------------------------------------------------------------------

-- BEGIN F6 (BOSS as an OIDC provider; owner: stream S6; spec §6.3) --------------------------------
CREATE TABLE IF NOT EXISTS oidc_user_pools (
  id               TEXT PRIMARY KEY,
  org_id           TEXT NOT NULL REFERENCES orgs(id),
  name             TEXT NOT NULL,
  kind             TEXT NOT NULL CHECK (kind IN ('workforce', 'customer')),
  signup           TEXT NOT NULL DEFAULT 'closed' CHECK (signup IN ('closed', 'invite', 'open', 'domain')),
  signup_domains   TEXT[] NOT NULL DEFAULT '{}',
  mfa              TEXT NOT NULL DEFAULT 'optional' CHECK (mfa IN ('off', 'optional', 'required')),
  passkeys         BOOLEAN NOT NULL DEFAULT true,
  password_policy  JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- The pool's pairwise-subject key (§6.2): random, in the vault (kind signing_key), made with the pool.
  subject_key_vault_item_id TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- id IS the client_id. The secret lives in the vault; the API returns presence only (§6.5).
-- id_token_alg: RS256 by default, EdDSA opt-in per client (D10; the IDENTITY.md amendment).
CREATE TABLE IF NOT EXISTS oidc_clients (
  id                          TEXT PRIMARY KEY,
  org_id                      TEXT NOT NULL REFERENCES orgs(id),
  project_id                  TEXT NOT NULL REFERENCES projects(id),   -- a client is one app's
  app_key                     TEXT NOT NULL,
  pool_id                     TEXT NOT NULL REFERENCES oidc_user_pools(id),
  name                        TEXT NOT NULL,
  type                        TEXT NOT NULL CHECK (type IN ('confidential', 'public')),
  redirect_uris               TEXT[] NOT NULL DEFAULT '{}',
  post_logout_redirect_uris   TEXT[] NOT NULL DEFAULT '{}',
  allowed_scopes              TEXT[] NOT NULL DEFAULT '{openid}',
  token_endpoint_auth_method  TEXT NOT NULL,
  jwks                        JSONB,
  secret_vault_item_id        TEXT,
  id_token_alg                TEXT NOT NULL DEFAULT 'RS256' CHECK (id_token_alg IN ('RS256', 'EdDSA')),
  subject_type                TEXT NOT NULL DEFAULT 'pairwise' CHECK (subject_type IN ('pairwise', 'public')),
  require_mfa                 BOOLEAN NOT NULL DEFAULT false,
  first_party                 BOOLEAN NOT NULL DEFAULT false,
  -- The access token's `aud` (RFC 9068): the app's resource identifier; NULL means the client_id.
  resource                    TEXT,
  status                      TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled', 'deleted')),
  created_by                  TEXT,
  created_at                  TIMESTAMPTZ NOT NULL DEFAULT now(),
  rotated_at                  TIMESTAMPTZ
);

-- Customer pools only: a separate principal kind that can never hold a BOSS permission.
CREATE TABLE IF NOT EXISTS oidc_pool_users (
  id               TEXT PRIMARY KEY,
  pool_id          TEXT NOT NULL REFERENCES oidc_user_pools(id),
  email            TEXT NOT NULL,
  email_verified   BOOLEAN NOT NULL DEFAULT false,
  name             TEXT,
  status           TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('pending', 'active', 'disabled')),
  password_hash    TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_sign_in_at  TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS oidc_pool_users_email ON oidc_pool_users (pool_id, lower(email));

CREATE TABLE IF NOT EXISTS oidc_app_roles (
  pool_id    TEXT NOT NULL REFERENCES oidc_user_pools(id),
  client_id  TEXT NOT NULL REFERENCES oidc_clients(id),
  role_key   TEXT NOT NULL,
  name       TEXT NOT NULL,
  PRIMARY KEY (pool_id, client_id, role_key)
);

CREATE TABLE IF NOT EXISTS oidc_role_assignments (
  pool_id      TEXT NOT NULL REFERENCES oidc_user_pools(id),
  subject_ref  TEXT NOT NULL,
  client_id    TEXT NOT NULL REFERENCES oidc_clients(id),
  role_key     TEXT NOT NULL,
  PRIMARY KEY (pool_id, subject_ref, client_id, role_key)
);

CREATE TABLE IF NOT EXISTS oidc_consents (
  subject_ref  TEXT NOT NULL,
  client_id    TEXT NOT NULL REFERENCES oidc_clients(id),
  scopes       TEXT[] NOT NULL DEFAULT '{}',
  granted_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at   TIMESTAMPTZ,
  PRIMARY KEY (subject_ref, client_id)
);

-- Codes and refresh tokens are stored hashed only; a code is single-use, 60 s.
-- A grant is one sign-in of one subject to one client: the code, every access token (claim `sid`)
-- and the refresh family hang off it, so revoking it (code replay, refresh reuse, logout, consent
-- revoke, user disable) ends all of them at once.
CREATE TABLE IF NOT EXISTS oidc_grants (
  id              TEXT PRIMARY KEY,
  org_id          TEXT NOT NULL REFERENCES orgs(id),
  client_id       TEXT NOT NULL REFERENCES oidc_clients(id),
  pool_id         TEXT NOT NULL REFERENCES oidc_user_pools(id),
  subject_ref     TEXT NOT NULL,             -- usr_ (workforce) or opu_ (customer); never sent to an app
  session_ref     TEXT,                      -- the BOSS console session (workforce) or app session
  scopes          TEXT[] NOT NULL DEFAULT '{}',
  acr             TEXT,
  amr             TEXT[] NOT NULL DEFAULT '{}',
  auth_time       TIMESTAMPTZ NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at      TIMESTAMPTZ,
  revoked_reason  TEXT
);
CREATE INDEX IF NOT EXISTS oidc_grants_subject ON oidc_grants (client_id, subject_ref) WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS oidc_auth_codes (
  code_hash       TEXT PRIMARY KEY,
  client_id       TEXT NOT NULL REFERENCES oidc_clients(id),
  grant_id        TEXT NOT NULL REFERENCES oidc_grants(id),
  subject_ref     TEXT NOT NULL,
  redirect_uri    TEXT NOT NULL,
  code_challenge  TEXT NOT NULL,
  nonce           TEXT,
  scopes          TEXT[] NOT NULL DEFAULT '{}',
  acr             TEXT,
  auth_time       TIMESTAMPTZ NOT NULL,
  expires_at      TIMESTAMPTZ NOT NULL,
  used_at         TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS oidc_refresh_tokens (
  token_hash   TEXT PRIMARY KEY,
  family_id    TEXT NOT NULL,             -- = the grant id: one rotating family per grant
  client_id    TEXT NOT NULL REFERENCES oidc_clients(id),
  subject_ref  TEXT NOT NULL,
  scopes       TEXT[] NOT NULL DEFAULT '{}',
  expires_at   TIMESTAMPTZ NOT NULL,
  rotated_at   TIMESTAMPTZ,
  revoked_at   TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS oidc_refresh_tokens_family ON oidc_refresh_tokens (family_id);

-- Pending authorization requests (sign-in, consent): the browser carries only the id (hashed here).
CREATE TABLE IF NOT EXISTS oidc_interactions (
  id_hash      TEXT PRIMARY KEY,
  org_id       TEXT NOT NULL REFERENCES orgs(id),
  client_id    TEXT NOT NULL REFERENCES oidc_clients(id),
  params       JSONB NOT NULL,             -- the validated authorization request
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at   TIMESTAMPTZ NOT NULL,
  used_at      TIMESTAMPTZ
);

-- The `oidc` signing-key family (D10, IDENTITY.md D35): per org, RS256 (default) and EdDSA, in its
-- own table so no BOSS-internal verifier (identity_signing_keys) can ever find one of these keys.
CREATE TABLE IF NOT EXISTS oidc_signing_keys (
  kid                    TEXT PRIMARY KEY,
  org_id                 TEXT NOT NULL REFERENCES orgs(id),
  alg                    TEXT NOT NULL CHECK (alg IN ('RS256', 'EdDSA')),
  public_jwk             JSONB NOT NULL,
  private_vault_item_id  TEXT NOT NULL,
  status                 TEXT NOT NULL CHECK (status IN ('next', 'active', 'retiring', 'retired')),
  created_at             TIMESTAMPTZ NOT NULL DEFAULT now(),
  activated_at           TIMESTAMPTZ,
  retire_after           TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS oidc_signing_keys_one_active ON oidc_signing_keys (org_id, alg) WHERE status = 'active';

-- private_key_jwt client assertions are single-use (RFC 7523 §3): the jti, hashed, until it expires.
CREATE TABLE IF NOT EXISTS oidc_client_assertion_jtis (
  jti_hash    TEXT PRIMARY KEY,
  client_id   TEXT NOT NULL REFERENCES oidc_clients(id),
  expires_at  TIMESTAMPTZ NOT NULL
);

-- Customer pools (phase 2): a pool user's factors, the same shapes as identity's TOTP and WebAuthn.
CREATE TABLE IF NOT EXISTS oidc_pool_user_factors (
  id                    TEXT PRIMARY KEY,
  pool_user_id          TEXT NOT NULL REFERENCES oidc_pool_users(id),
  kind                  TEXT NOT NULL CHECK (kind IN ('totp', 'webauthn', 'recovery_code')),
  secret_vault_item_id  TEXT,              -- totp
  credential_id         BYTEA,             -- webauthn
  public_key            BYTEA,             -- webauthn (COSE)
  sign_count            BIGINT NOT NULL DEFAULT 0,
  last_used_step        BIGINT,            -- totp replay prevention
  code_hash             TEXT,              -- recovery_code
  label                 TEXT,
  created_at            TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_used_at          TIMESTAMPTZ,
  used_at               TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS oidc_pool_user_factors_cred ON oidc_pool_user_factors (credential_id) WHERE credential_id IS NOT NULL;

-- Customer-pool sessions (phase 2): cookie __Host-boss_app_session, Path=/oidc/; never identity_sessions.
CREATE TABLE IF NOT EXISTS oidc_sessions (
  id                   TEXT PRIMARY KEY,
  token_hash           TEXT NOT NULL UNIQUE,
  pool_id              TEXT NOT NULL REFERENCES oidc_user_pools(id),
  pool_user_id         TEXT NOT NULL REFERENCES oidc_pool_users(id),
  auth_methods         TEXT[] NOT NULL DEFAULT '{}',
  mfa_at               TIMESTAMPTZ,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  idle_expires_at      TIMESTAMPTZ NOT NULL,
  absolute_expires_at  TIMESTAMPTZ NOT NULL,
  revoked_at           TIMESTAMPTZ,
  ip                   INET,
  user_agent           TEXT
);

-- Customer-pool challenges, bound to the pre-auth cookie __Host-boss_app_preauth (hashed here):
-- the second factor after a password, a pending TOTP enrolment, a passkey ceremony, an emailed
-- code (verification, reset). Never identity_auth_challenges: a pool user is not a principal.
CREATE TABLE IF NOT EXISTS oidc_app_challenges (
  id_hash       TEXT PRIMARY KEY,
  binding_hash  TEXT NOT NULL,
  pool_id       TEXT NOT NULL REFERENCES oidc_user_pools(id),
  pool_user_id  TEXT REFERENCES oidc_pool_users(id),
  purpose       TEXT NOT NULL CHECK (purpose IN ('mfa', 'enrol_totp', 'passkey', 'verify_email', 'reset')),
  payload       JSONB NOT NULL DEFAULT '{}'::jsonb,
  attempts      INTEGER NOT NULL DEFAULT 0,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at    TIMESTAMPTZ NOT NULL,
  used_at       TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS oidc_app_challenges_binding ON oidc_app_challenges (binding_hash);
-- END F6 ------------------------------------------------------------------------------------------

-- MULTI-REPO APPS (docs/product/MULTIREPO.md) -----------------------------------------------------
-- The org's repository registry: every repository the GitHub App installation (or the org's
-- token) reaches, and whether BOSS may use it (the operator's tick). A project chooses only from
-- allowed rows; unticking removes the repository from every project and from the next token mint.
CREATE TABLE IF NOT EXISTS github_repos (
  id               TEXT PRIMARY KEY,
  org_id           TEXT NOT NULL,
  source           TEXT NOT NULL DEFAULT 'app',
  github_repo_id   BIGINT,
  full_name        TEXT NOT NULL,
  description      TEXT,
  default_branch   TEXT,
  language         TEXT,
  private          BOOLEAN,
  archived         BOOLEAN NOT NULL DEFAULT false,
  allowed          BOOLEAN NOT NULL DEFAULT false,
  allowed_by       TEXT,
  allowed_at       TIMESTAMPTZ,
  -- {read, write, pull_requests: {ok, state, at}, state} from setup_checks.probe_repository
  checks           JSONB NOT NULL DEFAULT '{}'::jsonb,
  checked_at       TIMESTAMPTZ,
  -- false: the installation no longer lists it (removed from the App, or deleted on GitHub).
  reachable        BOOLEAN NOT NULL DEFAULT true,
  -- GitHub's last push (Add a project lists repos with how long ago: "3h", "12d").
  pushed_at        TIMESTAMPTZ,
  last_seen_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  -- 'binding': registered by a project binding its own connection to it (BOSSAPP-1030) — no
  -- installation lists it, so the refresh gone-sweep never marks it gone.
  CHECK (source IN ('app', 'token', 'binding'))
);
CREATE UNIQUE INDEX IF NOT EXISTS github_repos_org_full_name ON github_repos (org_id, lower(full_name));
-- Widened in place on an install whose table predates the 'binding' source (BOSSAPP-1030).
DO $$ BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'github_repos_source_check'
      AND pg_get_constraintdef(oid) NOT LIKE '%binding%'
  ) THEN
    ALTER TABLE github_repos DROP CONSTRAINT github_repos_source_check;
    ALTER TABLE github_repos
      ADD CONSTRAINT github_repos_source_check
      CHECK (source IN ('app', 'token', 'binding'));
  END IF;
END $$;
-- BOSSAPP-1030 backfill: a repository the add-account flow bound while the org's registry was in
-- use has no row here, so egress refused every mint for it (repo_not_allowed). The operator
-- explicitly picking it was the allow action; give each one its row once. Idempotent: the id is
-- derived, ON CONFLICT leaves every existing row — and so every operator decision — exactly as
-- it is, and a registry not in use (no rows for the org) stays ungoverned.
INSERT INTO github_repos (id, org_id, source, full_name, allowed, allowed_by, allowed_at, reachable)
SELECT DISTINCT ON (w.org_id, lower(b.full_name))
       'ghr_' || substr(md5(w.org_id || ':' || lower(b.full_name)), 1, 20), w.org_id, 'binding',
       b.full_name, true, b.created_by, now(), true
FROM github_repository_bindings b
JOIN projects p ON p.id = b.project_id
JOIN workspaces w ON w.id = p.workspace_id
WHERE b.status = 'active' AND position('/' in b.full_name) > 0
  AND lower(b.full_name) NOT LIKE 'local\_%'
  AND EXISTS (SELECT 1 FROM github_repos g WHERE g.org_id = w.org_id)
ON CONFLICT (org_id, lower(full_name)) DO NOTHING;
-- A project's repositories are its github_repository_bindings (one row per repository); these
-- columns carry the multi-repo role hint and the registry row the binding was chosen from.
ALTER TABLE github_repository_bindings ADD COLUMN IF NOT EXISTS role_hint TEXT;
ALTER TABLE github_repository_bindings ADD COLUMN IF NOT EXISTS registry_repo_id TEXT;
-- One repo or several: a project's mode (app_key '') and each app's (app_key = the app's key).
-- Absent = 'single', today's behaviour: one implicit component in the project's default repo.
CREATE TABLE IF NOT EXISTS repo_layouts (
  project_id  TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  app_key     TEXT NOT NULL DEFAULT '',
  repo_mode   TEXT NOT NULL DEFAULT 'single',
  updated_by  TEXT,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, app_key),
  CHECK (repo_mode IN ('single', 'multi'))
);
-- An app's components, each in a repository of its project (a binding) and a folder of it.
-- Order = the topological sort of depends_on (component names of the same app); cycles are
-- refused on save. kind deploy_config is read only: BOSS plans deploys from it, never builds it.
CREATE TABLE IF NOT EXISTS app_components (
  id           TEXT PRIMARY KEY,
  project_id   TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  app_key      TEXT NOT NULL,
  app_name     TEXT,
  name         TEXT NOT NULL,
  binding_id   TEXT NOT NULL REFERENCES github_repository_bindings(id),
  path         TEXT NOT NULL DEFAULT '/',
  access       TEXT NOT NULL DEFAULT 'write',
  kind         TEXT NOT NULL DEFAULT 'code',
  depends_on   TEXT[] NOT NULL DEFAULT '{}',
  ship_target  JSONB NOT NULL DEFAULT '{}'::jsonb,
  position     INTEGER NOT NULL DEFAULT 0,
  created_by   TEXT,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, app_key, name),
  CHECK (access IN ('write', 'read')),
  CHECK (kind IN ('code', 'deploy_config'))
);
CREATE INDEX IF NOT EXISTS app_components_app ON app_components (project_id, app_key);
-- What a run of a multi-repo app may touch: EXACTLY its app's repositories, recorded when the
-- person consents (who, which repositories, which access) and checked at every token mint.
CREATE TABLE IF NOT EXISTS repo_run_grants (
  id                 TEXT PRIMARY KEY,
  project_id         TEXT NOT NULL,
  app_key            TEXT NOT NULL,
  change_set_id      TEXT,
  identity_grant_id  TEXT,
  repos              JSONB NOT NULL DEFAULT '[]'::jsonb,
  permissions        JSONB NOT NULL DEFAULT '{}'::jsonb,
  consented_by       TEXT,
  remember           BOOLEAN NOT NULL DEFAULT false,
  expires_at         TIMESTAMPTZ,
  ended_at           TIMESTAMPTZ,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS repo_run_grants_change_set ON repo_run_grants (change_set_id);
-- ONE CHANGE ACROSS N REPOSITORIES (SPEC.md `change_sets`; named repo_change_sets because
-- `changesets` is the resource plane's deploy change set). A single-repo run gets a one-PR set.
CREATE TABLE IF NOT EXISTS repo_change_sets (
  id               TEXT PRIMARY KEY,
  project_id       TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  app_key          TEXT NOT NULL,
  app_name         TEXT,
  title            TEXT NOT NULL,
  directive        TEXT,
  mode             TEXT NOT NULL DEFAULT 'multi',
  state            TEXT NOT NULL DEFAULT 'planned',
  -- {components: [{name, change, unchanged, interface}], summary, by}
  plan             JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- the authority the set was started under: {principal_id, org_id, grant_id, run_id}
  acting           JSONB,
  workflow_run_id  TEXT,
  task_id          TEXT,
  decision_id      TEXT,
  -- the exact head SHAs the approval covers: {full_name: sha}; any later push re-asks
  approved_shas    JSONB,
  approved_by      TEXT,
  approved_at      TIMESTAMPTZ,
  blocked_reason   TEXT,
  error            TEXT,
  -- the release: {waves, status, steps, rolled_back}
  release          JSONB NOT NULL DEFAULT '{}'::jsonb,
  options          JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by       TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (mode IN ('single', 'multi')),
  CHECK (state IN ('planned', 'building', 'blocked', 'in_review', 'approved', 'merging', 'merged',
                   'deploying', 'live', 'rolled_back', 'failed', 'rejected', 'cancelled'))
);
CREATE INDEX IF NOT EXISTS repo_change_sets_app ON repo_change_sets (project_id, app_key, created_at DESC);
CREATE INDEX IF NOT EXISTS repo_change_sets_state ON repo_change_sets (state);
-- One row per repository of the set (a monorepo's components share one row, one PR).
CREATE TABLE IF NOT EXISTS change_set_prs (
  id                 TEXT PRIMARY KEY,
  change_set_id      TEXT NOT NULL REFERENCES repo_change_sets(id) ON DELETE CASCADE,
  binding_id         TEXT,
  full_name          TEXT NOT NULL,
  components         TEXT[] NOT NULL DEFAULT '{}',
  wave               INTEGER NOT NULL DEFAULT 1,
  -- waiting | building | ready | failed | unchanged | merged | reverted
  lane_state         TEXT NOT NULL DEFAULT 'waiting',
  code_task_run_id   TEXT,
  base_branch        TEXT,
  branch             TEXT,
  pr_number          INTEGER,
  pr_url             TEXT,
  head_sha           TEXT,
  additions          INTEGER,
  deletions          INTEGER,
  changed_files      INTEGER,
  ci_state           TEXT,
  review_state       TEXT,
  review             JSONB NOT NULL DEFAULT '{}'::jsonb,
  merged_sha         TEXT,
  merged_at          TIMESTAMPTZ,
  revert_pr_number   INTEGER,
  revert_sha         TEXT,
  error              TEXT,
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (change_set_id, full_name)
);
CREATE INDEX IF NOT EXISTS change_set_prs_run ON change_set_prs (code_task_run_id);
-- The set gate: do the PRs fit together? Re-run on every push to any PR of the set.
CREATE TABLE IF NOT EXISTS cross_repo_checks (
  id             TEXT PRIMARY KEY,
  change_set_id  TEXT NOT NULL REFERENCES repo_change_sets(id) ON DELETE CASCADE,
  head_shas      JSONB NOT NULL DEFAULT '{}'::jsonb,
  results        JSONB NOT NULL DEFAULT '[]'::jsonb,
  verdict        TEXT NOT NULL DEFAULT 'pending',
  at             TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS cross_repo_checks_set ON cross_repo_checks (change_set_id, at DESC);

-- Infrastructure platform (boss.plugin/v1, engine/boss_engine/platform). Install-wide plugin
-- state: enable/disable, an operator's version pin, and the tree checksum the operator approved
-- when enabling (a community plugin whose files change is disabled again until re-approved).
CREATE TABLE IF NOT EXISTS infra_plugin_state (
  plugin_id          TEXT PRIMARY KEY,
  enabled            BOOLEAN NOT NULL DEFAULT false,
  pinned_version     TEXT,
  approved_checksum  TEXT,
  updated_by         TEXT,
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- A resolved declarative plan for an app's `resources:`. `digest` is what the deploy approval
-- pins (action_preview content hash); the apply refuses a plan whose digest moved.
CREATE TABLE IF NOT EXISTS infra_plans (
  id             TEXT PRIMARY KEY,
  project_id     TEXT NOT NULL REFERENCES projects(id),
  app_key        TEXT NOT NULL,
  environment    TEXT NOT NULL,
  digest         TEXT NOT NULL,
  plan           JSONB NOT NULL,
  status         TEXT NOT NULL DEFAULT 'awaiting_approval',
  decision_id    TEXT,
  deployment_id  TEXT,
  created_by     TEXT,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS infra_plans_app ON infra_plans (project_id, app_key, created_at DESC);
CREATE INDEX IF NOT EXISTS infra_plans_deployment ON infra_plans (deployment_id);
-- The resources BOSS provisioned (owned) or connected to (attached). Ownership decides what
-- destroy may touch: an attached resource is never destroyed. `bindings` holds secret
-- REFERENCES by env name, never a value; `state` is the plugin's non-secret observed state.
CREATE TABLE IF NOT EXISTS infra_platform_resources (
  id                 TEXT PRIMARY KEY,
  project_id         TEXT NOT NULL REFERENCES projects(id),
  resource_id        TEXT NOT NULL,
  app_key            TEXT NOT NULL,
  name               TEXT NOT NULL,
  environment        TEXT NOT NULL,
  capability         TEXT NOT NULL,
  plugin_id          TEXT NOT NULL,
  plugin_version     TEXT NOT NULL,
  plugin_checksum    TEXT,
  mode               TEXT NOT NULL CHECK (mode IN ('owned', 'attached')),
  status             TEXT NOT NULL DEFAULT 'planned',
  public_access      BOOLEAN NOT NULL DEFAULT false,
  state              JSONB NOT NULL DEFAULT '{}'::jsonb,
  bindings           JSONB NOT NULL DEFAULT '{}'::jsonb,
  evidence           JSONB NOT NULL DEFAULT '[]'::jsonb,
  last_plan_digest   TEXT,
  last_operation_id  TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  destroyed_at       TIMESTAMPTZ,
  UNIQUE (project_id, resource_id)
);
CREATE INDEX IF NOT EXISTS infra_platform_resources_app ON infra_platform_resources (project_id, app_key);

-- WHAT BOSS SHOULD CHANGE IN ITS OWN CODE (services/boss_recommendations.py). A step's recovery
-- agent that concludes a failure is BOSS's own (wiring, planner, a missing capability, the
-- image's tooling) records it here, once per distinct cause: the evidence, the hypothesis and the
-- proposed change, for a developer to implement. Rendered as RECOMMENDATIONS.md (console, API).
CREATE TABLE IF NOT EXISTS boss_recommendations (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  signature TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'open',          -- open | done | wont_fix
  title TEXT NOT NULL,
  symptom TEXT NOT NULL DEFAULT '',
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,  -- redacted log lines / citations
  root_cause TEXT NOT NULL DEFAULT '',
  proposed_change TEXT NOT NULL DEFAULT '',
  files JSONB NOT NULL DEFAULT '[]'::jsonb,     -- files/functions, when known
  refs JSONB NOT NULL DEFAULT '[]'::jsonb,      -- [{run_id, step_id, build_id, deployment_id, at}]
  occurrences INTEGER NOT NULL DEFAULT 1,
  boss_version TEXT,
  created_by TEXT,
  -- BOSS fixes itself (services/self_fix.py): the self-fix working on this cause, the cause
  -- with its install parameters stripped (deploy:port_held), and every self-fix that was tried
  -- for it and did not hold, with what was learned (refused, rejected, rolled back).
  self_fix_id TEXT,
  class_signature TEXT,
  attempts JSONB NOT NULL DEFAULT '[]'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, signature)
);
-- A gap an agent filed from a diagnosis (tools: file_platform_gap) says what "fixed" means: the
-- acceptance tests a self-fix must make pass.
ALTER TABLE boss_recommendations ADD COLUMN IF NOT EXISTS acceptance_tests JSONB NOT NULL
  DEFAULT '[]'::jsonb;

-- BOSS FIXES ITSELF (BOSSAPP-571, docs/product/BOSS_FIXES_ITSELF.md §11). A recovery decision
-- that places a failure on BOSS's own code starts a SELF-FIX: Mender re-diagnoses against the
-- code, writes a regression test that fails on the base, the smallest fix that makes it pass,
-- runs the mechanical gates and the reviewers, and a person approves the install. The host
-- self-installer installs it from a signed single-use ticket, and the parked step resumes: the
-- step passing is the proof. Statuses: services/self_fix.py STATUSES.
CREATE TABLE IF NOT EXISTS self_fixes (
  id TEXT PRIMARY KEY,                                   -- sfx_…
  org_id TEXT,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  recommendation_id TEXT,
  run_id TEXT,
  step_id TEXT,
  step_kind TEXT,
  signature TEXT NOT NULL,                               -- local, e.g. deploy:port_held:8000
  class_signature TEXT NOT NULL,                         -- e.g. deploy:port_held
  location TEXT,                                         -- file::function after diagnosis
  area TEXT NOT NULL DEFAULT 'engine',
  status TEXT NOT NULL,
  refusal TEXT,                                          -- protected_path|no_reproduction|tests|tests_weakened|scope|review|budget|…
  refusal_detail TEXT,
  confidence TEXT NOT NULL,                              -- low|medium|high
  confidence_reasons JSONB NOT NULL DEFAULT '[]'::jsonb,
  evidence JSONB NOT NULL DEFAULT '{}'::jsonb,           -- host-masked; never instructions
  diagnosis JSONB NOT NULL DEFAULT '{}'::jsonb,
  base_sha TEXT NOT NULL DEFAULT '',
  fix_commit_sha TEXT,
  fix_tree_sha TEXT,
  branch TEXT,
  tier INTEGER,
  flags JSONB NOT NULL DEFAULT '[]'::jsonb,
  paths JSONB NOT NULL DEFAULT '[]'::jsonb,
  diff_stat JSONB NOT NULL DEFAULT '{}'::jsonb,
  red_green JSONB NOT NULL DEFAULT '{}'::jsonb,
  gates JSONB NOT NULL DEFAULT '{}'::jsonb,
  review JSONB NOT NULL DEFAULT '{}'::jsonb,
  pr JSONB NOT NULL DEFAULT '{}'::jsonb,                 -- the local PR record: title, body, labels, trailers, diff
  bundle BYTEA,                                          -- the fix commit as a git bundle, for the host self-installer
  progress JSONB NOT NULL DEFAULT '{}'::jsonb,           -- the parked step's live line: {stage, sentence, at}
  decision_id TEXT,
  proposal_id TEXT,                                      -- self_improvement_proposals row of the install
  engine TEXT,
  harness TEXT,
  reviewer_engine TEXT,
  budget_reservation_id TEXT,
  budget_usd_micros BIGINT NOT NULL DEFAULT 0,
  cost_micros BIGINT NOT NULL DEFAULT 0,
  repair_rounds INTEGER NOT NULL DEFAULT 0,
  installed_stack_head TEXT,
  installed_at TIMESTAMPTZ,
  resumed_at TIMESTAMPTZ,
  verified_at TIMESTAMPTZ,
  rolled_back_at TIMESTAMPTZ,
  verification JSONB NOT NULL DEFAULT '{}'::jsonb,       -- {outcome, next_signature, step_attempt}
  stack_state TEXT,                                      -- on_stack|dropped_upstream|needs_rework|removed
  upstream_state TEXT NOT NULL DEFAULT 'local_only',
  upstream_url TEXT,
  created_by TEXT NOT NULL,
  started_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_self_fixes_project_status ON self_fixes (project_id, status);
CREATE INDEX IF NOT EXISTS idx_self_fixes_run ON self_fixes (run_id, step_id);
CREATE INDEX IF NOT EXISTS idx_self_fixes_class ON self_fixes (class_signature, created_at);

-- One live self-fix per class signature, INSTALL-WIDE (R19, F14): a second step that hits the
-- same cause waits on the fix being built instead of starting another.
CREATE TABLE IF NOT EXISTS self_fix_claims (
  class_signature TEXT PRIMARY KEY,
  self_fix_id TEXT NOT NULL REFERENCES self_fixes(id) ON DELETE CASCADE,
  claimed_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS self_fix_waiters (
  self_fix_id TEXT NOT NULL REFERENCES self_fixes(id) ON DELETE CASCADE,
  run_id TEXT NOT NULL,
  step_id TEXT NOT NULL,
  project_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (self_fix_id, run_id, step_id)
);

-- Install / remove orders for the HOST self-installer (scripts/install/self_fix.sh): signed with
-- the install's EdDSA key, bound to one approved decision, one commit and one tree, single use,
-- expiring in an hour. Nothing inside a container can install; only the host can, and only this.
CREATE TABLE IF NOT EXISTS self_fix_tickets (
  id TEXT PRIMARY KEY,                                   -- sft_…
  self_fix_id TEXT NOT NULL REFERENCES self_fixes(id) ON DELETE CASCADE,
  kind TEXT NOT NULL,                                    -- install|rollback|remove|remove_all
  body JSONB NOT NULL,
  token TEXT NOT NULL,                                   -- the signed ticket (JWS, EdDSA)
  status TEXT NOT NULL,                                  -- issued|taken|done|failed|rolled_back|revoked|expired
  phases JSONB NOT NULL DEFAULT '[]'::jsonb,
  taken_at TIMESTAMPTZ,
  finished_at TIMESTAMPTZ,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_self_fix_tickets_status ON self_fix_tickets (status, created_at);

-- What is installed, in order, on top of a release (R8): the local stack the upgrade carries.
CREATE TABLE IF NOT EXISTS self_fix_stack (
  release_ref TEXT NOT NULL,
  position INTEGER NOT NULL,
  self_fix_id TEXT NOT NULL REFERENCES self_fixes(id) ON DELETE CASCADE,
  commit_sha TEXT NOT NULL,
  installed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (release_ref, position)
);

-- BOSS FIXES ITSELF, UPSTREAM (BOSSAPP-571 spec §7, R9 R11 R18): the EXACT bytes a person
-- previewed for the BOSS team, and what happened when they sent them. `body_gz` is the payload
-- (title, labels, diff, body, evidence, trailers, machine block, target) gzipped; Send sends
-- these bytes and nothing else (the sha256 binds them). `meta` holds what BOSS found while
-- making the preview: the privacy check of the diff (checked, never masked), the scrub counts of
-- the prose, the dedupe search and the channel it chose. Channels: github_pr (from the person's
-- fork), github_comment (evidence on an open upstream PR for the same cause), collector (the
-- Improve-BOSS collector), patch_export (offline, or no way to send).
CREATE TABLE IF NOT EXISTS self_fix_upstream_sends (
  id TEXT PRIMARY KEY,                                   -- sfu_…
  self_fix_id TEXT NOT NULL REFERENCES self_fixes(id) ON DELETE CASCADE,
  channel TEXT NOT NULL,                                 -- github_pr|github_comment|collector|patch_export
  body_gz BYTEA NOT NULL,
  body_sha256 TEXT NOT NULL,
  meta JSONB NOT NULL DEFAULT '{}'::jsonb,
  checked_by TEXT,
  checked_at TIMESTAMPTZ,
  status TEXT NOT NULL,                                  -- previewed|sent|blocked|exported|failed|superseded
  result JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_self_fix_upstream_sends_fix ON self_fix_upstream_sends (self_fix_id, created_at);

-- ══ Monitoring and alerting, Phase 1a (BOSSAPP-598; docs/product/MONITORING_ALERTING_SPEC.md) ══
-- The v1 alert tables grow: a rule or alert belongs to a deployment target OR a monitored
-- service BOSS did not deploy. `subject_id` is the one key every per-app query reads.
ALTER TABLE app_alert_rules ALTER COLUMN target_id DROP NOT NULL;
ALTER TABLE app_alerts ALTER COLUMN target_id DROP NOT NULL;
ALTER TABLE app_alert_rules ADD COLUMN IF NOT EXISTS subject_id TEXT
  GENERATED ALWAYS AS (COALESCE(target_id, service_id)) STORED;
ALTER TABLE app_alerts ADD COLUMN IF NOT EXISTS subject_id TEXT
  GENERATED ALWAYS AS (COALESCE(target_id, service_id)) STORED;
DO $$ BEGIN
  ALTER TABLE app_alerts DROP CONSTRAINT IF EXISTS app_alerts_source_kind_check;
  ALTER TABLE app_alerts ADD CONSTRAINT app_alerts_source_kind_check
    CHECK (source_kind IN ('rule', 'signal', 'external', 'synthetic', 'heartbeat'));
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_alert_rules_service_builtin
  ON app_alert_rules(service_id, kind) WHERE target_id IS NULL AND kind <> 'custom';
CREATE INDEX IF NOT EXISTS idx_app_alert_rules_subject ON app_alert_rules(subject_id);
CREATE INDEX IF NOT EXISTS idx_app_alerts_subject ON app_alerts(subject_id, active_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS idx_app_alerts_open_external
  ON app_alerts(source_id, external_ref) WHERE state IN ('pending', 'firing')
  AND external_ref IS NOT NULL;
-- The incident lifecycle people see (status stays the back-compat projection).
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS service_id TEXT;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS urgency TEXT NOT NULL DEFAULT 'high';
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS lifecycle TEXT NOT NULL DEFAULT 'detected';
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS acked_by TEXT;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS acked_at TIMESTAMPTZ;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS mitigated_at TIMESTAMPTZ;
ALTER TABLE incidents ADD COLUMN IF NOT EXISTS resolved_at TIMESTAMPTZ;

-- A thing BOSS watches, deployed by BOSS or not. A deployment target gets one automatically.
-- `dialect` is how its HTTP metrics are named (boss: the platform standard; otel: OTel stable
-- semconv; otel_legacy: the pre-1.20 semconv names), detected from the first data.
CREATE TABLE IF NOT EXISTS monitored_services (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  name TEXT NOT NULL,
  environment TEXT NOT NULL DEFAULT 'production',
  deployment_target_id TEXT REFERENCES deployment_targets(id) ON DELETE CASCADE,
  owner TEXT,
  labels JSONB NOT NULL DEFAULT '{}'::jsonb,
  dialect TEXT NOT NULL DEFAULT 'boss',
  -- {paths: [otlp, remote_write, scrape, synthetic, alertmanager, ...], first_data_at,
  --  last_data_at, series, recognised, scrape_url}
  onboarding JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name, environment)
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_monitored_services_target
  ON monitored_services(deployment_target_id) WHERE deployment_target_id IS NOT NULL;

-- Everything that sends to BOSS, each with its OWN token: the project comes from the token,
-- never from the payload. Only a hash is kept (and a 2-character hint). A rotated token stays
-- valid for an hour (prev_*). An HMAC-signing source keeps its key in the secret store
-- (`signing_secret_ref`), never here.
CREATE TABLE IF NOT EXISTS signal_sources (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id),
  service_id TEXT REFERENCES monitored_services(id) ON DELETE SET NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('otlp', 'remote_write', 'alertmanager', 'grafana',
    'pagerduty_v2', 'sentry', 'datadog', 'cloudwatch_sns', 'generic', 'heartbeat')),
  token_hash TEXT NOT NULL,
  token_hint TEXT NOT NULL DEFAULT '',
  prev_token_hash TEXT,
  prev_valid_until TIMESTAMPTZ,
  -- The token is HMAC(server key, id + salt): BOSS can re-derive it to check a signature, a
  -- database read alone cannot. Rotation is a new salt.
  token_salt TEXT NOT NULL DEFAULT '',
  prev_token_salt TEXT,
  require_signature BOOLEAN NOT NULL DEFAULT false,
  mapping JSONB NOT NULL DEFAULT '{}'::jsonb,
  heartbeat_every_s INTEGER,
  last_seen_at TIMESTAMPTZ,
  last_refusal_word TEXT,
  last_refusal_at TIMESTAMPTZ,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  rotated_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_signal_sources_token ON signal_sources(token_hash);
CREATE INDEX IF NOT EXISTS idx_signal_sources_project ON signal_sources(project_id, kind);
-- Accepted and refused counts per source per hour (the console's 24 h numbers).
CREATE TABLE IF NOT EXISTS signal_source_counts (
  source_id TEXT NOT NULL REFERENCES signal_sources(id) ON DELETE CASCADE,
  hour TIMESTAMPTZ NOT NULL,
  accepted INTEGER NOT NULL DEFAULT 0,
  refused INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (source_id, hour)
);
-- A signed body seen in the last 10 minutes (replay refusal) and an event already applied
-- (idempotency on source, dedup_key, action, timestamp).
CREATE TABLE IF NOT EXISTS signal_receipts (
  source_id TEXT NOT NULL,
  receipt_key TEXT NOT NULL,
  alert_id TEXT,
  seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (source_id, receipt_key)
);
CREATE INDEX IF NOT EXISTS idx_signal_receipts_seen ON signal_receipts(seen_at);

-- THE POSTGRES FLOOR (T0): metrics pushed (OTLP, remote write) or scraped from a /metrics URL
-- or measured by a synthetic check, stamped with the project and service, kept 7 days. The
-- bundled Prometheus (T2) holds the same series when it is configured; this floor is what a
-- laptop install evaluates.
CREATE TABLE IF NOT EXISTS metric_series (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  service_id TEXT,
  name TEXT NOT NULL,
  labels JSONB NOT NULL,
  labels_hash TEXT NOT NULL,
  last_value DOUBLE PRECISION,
  last_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, labels_hash)
);
CREATE INDEX IF NOT EXISTS idx_metric_series_service ON metric_series(project_id, service_id, name);
CREATE TABLE IF NOT EXISTS metric_points (
  series_id TEXT NOT NULL REFERENCES metric_series(id) ON DELETE CASCADE,
  t TIMESTAMPTZ NOT NULL,
  v DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (series_id, t)
);
CREATE INDEX IF NOT EXISTS idx_metric_points_t ON metric_points(t);

-- Rule groups: the evaluation unit (Prometheus' model). One per watched app or service; a worker
-- claims a due group with FOR UPDATE SKIP LOCKED and a lease of twice the interval.
CREATE TABLE IF NOT EXISTS rule_groups (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  subject_id TEXT NOT NULL UNIQUE,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('target', 'service')),
  name TEXT NOT NULL,
  interval_s INTEGER NOT NULL DEFAULT 60 CHECK (interval_s >= 15),
  datasource TEXT NOT NULL DEFAULT 'auto',
  next_eval_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  lease_owner TEXT,
  lease_until TIMESTAMPTZ,
  last_eval_at TIMESTAMPTZ,
  last_duration_ms INTEGER,
  last_lag_ms INTEGER,
  last_error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_rule_groups_due ON rule_groups(next_eval_at);

-- Append-only: every state change of every alert, with why and who.
CREATE TABLE IF NOT EXISTS alert_transitions (
  id TEXT PRIMARY KEY,
  alert_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  at TIMESTAMPTZ NOT NULL,
  from_state TEXT,
  to_state TEXT NOT NULL,
  value DOUBLE PRECISION,
  reason TEXT NOT NULL DEFAULT '',
  actor TEXT NOT NULL DEFAULT 'evaluator'
);
CREATE INDEX IF NOT EXISTS idx_alert_transitions_alert ON alert_transitions(alert_id, at);

-- Label-matcher silences (Alertmanager's). kind manual | maintenance | deploy_hold. A silence
-- mutes NOTIFICATION and triage, never evaluation. The v1 per-rule silence is the matcher
-- {alert_rule_id="<id>"}.
CREATE TABLE IF NOT EXISTS silences (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  matchers JSONB NOT NULL,
  starts_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ends_at TIMESTAMPTZ NOT NULL,
  reason TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'manual' CHECK (kind IN ('manual', 'maintenance', 'deploy_hold')),
  source_ref TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expired_at TIMESTAMPTZ,
  expired_by TEXT
);
CREATE INDEX IF NOT EXISTS idx_silences_active ON silences(project_id, ends_at);
INSERT INTO silences (id, project_id, matchers, starts_at, ends_at, reason, kind, created_by,
                      created_at, expired_at, expired_by)
SELECT id, project_id, jsonb_build_array(jsonb_build_object('name', 'alert_rule_id', 'op', '=',
       'value', rule_id)), starts_at, ends_at, reason, 'manual', created_by, created_at,
       expired_at, expired_by
FROM app_alert_silences ON CONFLICT (id) DO NOTHING;

-- Recurring maintenance (an RRULE subset: FREQ=DAILY|WEEKLY, BYDAY, BYHOUR, BYMINUTE). mode
-- mute: notifications held; hold: alerts go to the agent first (a deploy window's rule).
CREATE TABLE IF NOT EXISTS maintenance_windows (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  matchers JSONB NOT NULL DEFAULT '[]'::jsonb,
  rrule TEXT NOT NULL DEFAULT '',
  starts_at TIMESTAMPTZ NOT NULL,
  duration_min INTEGER NOT NULL CHECK (duration_min BETWEEN 1 AND 10080),
  timezone TEXT NOT NULL DEFAULT 'UTC',
  mode TEXT NOT NULL DEFAULT 'mute' CHECK (mode IN ('mute', 'hold')),
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Declarative inhibition: while an alert matching `source_matchers` fires, alerts matching
-- `target_matchers` with the same `equal` labels are held back. project_id NULL: BOSS's own.
CREATE TABLE IF NOT EXISTS inhibit_rules (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  name TEXT NOT NULL,
  source_matchers JSONB NOT NULL,
  target_matchers JSONB NOT NULL,
  equal JSONB NOT NULL DEFAULT '[]'::jsonb,
  origin TEXT NOT NULL DEFAULT 'console' CHECK (origin IN ('builtin', 'code', 'console')),
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
INSERT INTO inhibit_rules (id, project_id, name, source_matchers, target_matchers, equal, origin)
VALUES ('inh_builtin_availability', NULL, 'Down holds back its symptoms',
        '[{"name": "layer", "op": "=", "value": "availability"}]'::jsonb,
        '[{"name": "layer", "op": "=", "value": "symptom"}]'::jsonb,
        '["boss_subject"]'::jsonb, 'builtin')
ON CONFLICT (id) DO NOTHING;

-- Where people are told. kind console | email | slack_webhook | mattermost | webhook. Secrets
-- (a webhook URL, a signing token) are in the secret store by `secret_ref`; `config` holds only
-- what may be shown (an address, a host). A contact point is verified (its test message was
-- acknowledged) before a high-urgency policy may use it.
CREATE TABLE IF NOT EXISTS contact_points (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  name TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('console', 'email', 'slack_webhook', 'mattermost', 'webhook')),
  config JSONB NOT NULL DEFAULT '{}'::jsonb,
  secret_ref TEXT,
  verified_at TIMESTAMPTZ,
  verify_token_hash TEXT,
  rate_per_minute INTEGER NOT NULL DEFAULT 20,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- The routing tree (Alertmanager's): depth first, first match unless `continue`, children
-- inherit. A root per project (parent_id NULL) is made on first use: console + email to the
-- project owner. The rule sheet's Notify column writes a one-level child (`rule_id`).
CREATE TABLE IF NOT EXISTS notification_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  parent_id TEXT REFERENCES notification_policies(id) ON DELETE CASCADE,
  position INTEGER NOT NULL DEFAULT 0,
  name TEXT NOT NULL DEFAULT '',
  matchers JSONB NOT NULL DEFAULT '[]'::jsonb,
  continue_matching BOOLEAN NOT NULL DEFAULT false,
  group_by JSONB,
  group_wait_s INTEGER,
  group_interval_s INTEGER,
  repeat_interval_s INTEGER,
  contact_point_ids JSONB,
  -- {start: "22:00", end: "07:00", timezone: "Europe/London"}; high urgency ignores it.
  quiet_hours JSONB,
  rule_id TEXT,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS idx_notification_policies_root
  ON notification_policies(project_id) WHERE parent_id IS NULL;

-- Project › Settings › Notifications (BOSSAPP-914 §11): who is told when something needs a
-- person, or a pull request is ready, per project (project_experience/notify_routes.py).
-- Incidents use the routing tree's root above; these two events route here.
CREATE TABLE IF NOT EXISTS project_notification_routes (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  event TEXT NOT NULL CHECK (event IN ('needs_you', 'pr_ready')),
  contact_point_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  updated_by TEXT NOT NULL DEFAULT 'boss',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, event)
);

-- One row per (group, contact point): what was last sent and when, so group_interval and
-- repeat_interval apply and an incident is ONE thread.
CREATE TABLE IF NOT EXISTS notification_groups (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  policy_id TEXT NOT NULL,
  contact_point_id TEXT NOT NULL,
  group_key TEXT NOT NULL,
  incident_id TEXT,
  first_seen_at TIMESTAMPTZ NOT NULL,
  last_sent_at TIMESTAMPTZ,
  last_digest TEXT,
  thread_ref TEXT,
  UNIQUE (contact_point_id, group_key)
);

-- THE OUTBOX: every message, before it is sent, with its receipt after. A dead channel never
-- blocks another channel or the evaluator; 6 attempts with backoff, then `dead` (a meta-alert).
CREATE TABLE IF NOT EXISTS notifications (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  group_key TEXT NOT NULL,
  policy_id TEXT,
  contact_point_id TEXT NOT NULL,
  alert_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  incident_id TEXT,
  kind TEXT NOT NULL CHECK (kind IN ('firing', 'resolved', 'ack', 'flapping', 'triage',
                                     'digest', 'test', 'meta')),
  urgency TEXT NOT NULL DEFAULT 'high',
  dedupe_key TEXT NOT NULL UNIQUE,
  subject TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'sent', 'failed', 'dead', 'held')),
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  error_word TEXT,
  receipt TEXT,
  sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_notifications_due ON notifications(status, next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_notifications_project ON notifications(project_id, created_at DESC);

-- Signed single-use links in an email (ack, resolve), valid 24 h. Only the hash is kept.
CREATE TABLE IF NOT EXISTS alert_action_tokens (
  token_hash TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  alert_id TEXT,
  incident_id TEXT,
  action TEXT NOT NULL CHECK (action IN ('ack', 'resolve')),
  contact_point_id TEXT,
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ,
  used_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Synthetic checks: BOSS asks a URL (HTTP), a port (TCP) or a name (DNS) on an interval, and
-- writes blackbox-exporter-named series (probe_success, probe_duration_seconds, ...) to the
-- floor, so one rule works on every topology.
CREATE TABLE IF NOT EXISTS synthetic_checks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  service_id TEXT NOT NULL REFERENCES monitored_services(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('http', 'tcp', 'dns')),
  target TEXT NOT NULL,
  method TEXT NOT NULL DEFAULT 'GET',
  expect JSONB NOT NULL DEFAULT '{}'::jsonb,
  interval_s INTEGER NOT NULL DEFAULT 60 CHECK (interval_s >= 30),
  headers_secret_ref TEXT,
  enabled BOOLEAN NOT NULL DEFAULT true,
  next_run_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_run_at TIMESTAMPTZ,
  last_ok BOOLEAN,
  last_word TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- A deploy whose boss.deploy.yaml lost monitoring rules (PR paramg/boss-sandbox#234): the rule
-- keeps running, is marked with when it went missing, and BOSS raises MonitoringRulesDropped.
ALTER TABLE app_alert_rules ADD COLUMN IF NOT EXISTS dropped_from_manifest_at TIMESTAMPTZ;

-- Email invites: what happened to the last send (sent | failed | not_configured) and the server's
-- reason, so the console can say why an invitation did not arrive. Never the token or a credential.
ALTER TABLE identity_invitations ADD COLUMN IF NOT EXISTS delivery_status TEXT;
ALTER TABLE identity_invitations ADD COLUMN IF NOT EXISTS delivery_error TEXT;
ALTER TABLE identity_invitations ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ;

-- BOSSAPP-622 event-driven ingest (operator decision 2026-10-21; services/knowledge/ingest.py).
-- A run is queued the moment its status becomes completed or failed, and an incident the moment
-- it becomes resolved, whatever code path finished it. The worker drains the queue every 30 s;
-- every 10 minutes the same call also sweeps for anything the triggers missed.
CREATE TABLE IF NOT EXISTS kg_ingest_queue (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('run', 'incident')),
  source_id TEXT NOT NULL,
  finished_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  attempts INTEGER NOT NULL DEFAULT 0,
  last_error TEXT,
  PRIMARY KEY (project_id, source_kind, source_id)
);
CREATE INDEX IF NOT EXISTS idx_kg_ingest_queue_due ON kg_ingest_queue(finished_at) WHERE attempts < 3;
CREATE OR REPLACE FUNCTION kg_queue_finished_run() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status IN ('completed', 'failed') AND OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO kg_ingest_queue (project_id, source_kind, source_id)
    VALUES (NEW.project_id, 'run', NEW.id) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION kg_queue_resolved_incident() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = 'resolved' AND OLD.status IS DISTINCT FROM NEW.status THEN
    INSERT INTO kg_ingest_queue (project_id, source_kind, source_id)
    VALUES (NEW.project_id, 'incident', NEW.id) ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END $$;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'kg_queue_finished_run'
                 AND tgrelid = 'code_task_runs'::regclass) THEN
    CREATE TRIGGER kg_queue_finished_run AFTER UPDATE OF status ON code_task_runs
      FOR EACH ROW EXECUTE FUNCTION kg_queue_finished_run();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'kg_queue_resolved_incident'
                 AND tgrelid = 'incidents'::regclass) THEN
    CREATE TRIGGER kg_queue_resolved_incident AFTER UPDATE OF status ON incidents
      FOR EACH ROW EXECUTE FUNCTION kg_queue_resolved_incident();
  END IF;
END $$;
-- BOSSAPP-622 (operator decision 2026-10-22): a pull request's knowledge source id names its
-- repository, pr-<owner>/<repo>#<n> (knowledge/capture.py pull_request_source_id), so PR 9 of
-- two repositories in one project are two records. This rewrites the old pr-<n> ids wherever
-- the project's runs name exactly one repository for that number. A number two repositories
-- share (the collision itself) is left as it is: nothing says which repository it was. The
-- renamed nodes get last_seen = now(), so the AGE projection re-projects them on its next sync.
CREATE OR REPLACE FUNCTION kg_qualify_pr_source_ids() RETURNS INTEGER LANGUAGE plpgsql AS $$
DECLARE
  renamed INTEGER := 0;
  step INTEGER;
BEGIN
  CREATE TEMP TABLE IF NOT EXISTS kg_pr_rename (project_id TEXT, old_id TEXT, new_id TEXT) ON COMMIT DROP;
  DELETE FROM kg_pr_rename;
  INSERT INTO kg_pr_rename (project_id, old_id, new_id)
  SELECT m.project_id, 'pr-' || m.n, 'pr-' || min(m.repo) || '#' || m.n
  FROM (SELECT r.project_id, r.pull_request_number::text AS n,
               lower(substring(r.pull_request_url from '://[^/]+/([^/]+/[^/]+)/pull/[0-9]+')) AS repo
        FROM code_task_runs r
        WHERE r.pull_request_number IS NOT NULL AND r.pull_request_url IS NOT NULL) m
  WHERE m.repo IS NOT NULL
  GROUP BY m.project_id, m.n
  HAVING count(DISTINCT m.repo) = 1;

  UPDATE kg_captures c SET source_id = x.new_id
  FROM kg_pr_rename x
  WHERE c.project_id = x.project_id AND c.source_kind = 'pull_request' AND c.source_id = x.old_id
    AND NOT EXISTS (SELECT 1 FROM kg_captures d WHERE d.project_id = c.project_id
                      AND d.source_kind = 'pull_request' AND d.source_id = x.new_id
                      AND d.content_hash = c.content_hash);
  GET DIAGNOSTICS step = ROW_COUNT;
  renamed := renamed + step;

  UPDATE kg_change_links l SET source_id = x.new_id
  FROM kg_pr_rename x
  WHERE l.project_id = x.project_id AND l.source_kind = 'pull_request' AND l.source_id = x.old_id
    AND NOT EXISTS (SELECT 1 FROM kg_change_links d WHERE d.project_id = l.project_id
                      AND d.source_kind = 'pull_request' AND d.source_id = x.new_id
                      AND d.symbol_key = l.symbol_key);
  GET DIAGNOSTICS step = ROW_COUNT;
  renamed := renamed + step;

  UPDATE kg_nodes n SET node_key = 'pull_request:' || x.new_id,
                        attrs = jsonb_set(n.attrs, '{source_id}', to_jsonb(x.new_id)),
                        last_seen = now()
  FROM kg_pr_rename x
  WHERE n.project_id = x.project_id AND n.kind = 'pull_request'
    AND n.node_key = 'pull_request:' || x.old_id
    AND NOT EXISTS (SELECT 1 FROM kg_nodes d WHERE d.project_id = n.project_id
                      AND d.kind = 'pull_request' AND d.node_key = 'pull_request:' || x.new_id);
  GET DIAGNOSTICS step = ROW_COUNT;
  renamed := renamed + step;
  RETURN renamed;
END $$;
SELECT kg_qualify_pr_source_ids();

-- THE CODE GRAPH OF EVERY REGISTERED REPOSITORY (services/knowledge/repo_index.py). BOSS's own
-- agent found kg_nodes empty in three projects with a registered repository: the graph was fed
-- only by code BOSS wrote (a finished build) and nothing indexed a repository as it was
-- registered. One row per project repository: what was indexed (commit, counts) and whether an
-- index is due. Registering a repository, or moving its base branch, marks it due through this
-- trigger whatever code path did it; the worker's knowledge tick queues a
-- `knowledge.repository.index` job for each due row, and its sweep re-checks the branch head.
CREATE TABLE IF NOT EXISTS kg_repo_index (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  binding_id TEXT NOT NULL REFERENCES github_repository_bindings(id) ON DELETE CASCADE,
  repo TEXT NOT NULL,
  branch TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'queued', 'running', 'indexed', 'failed', 'too_large')),
  due BOOLEAN NOT NULL DEFAULT true,
  reason TEXT NOT NULL DEFAULT 'registered',
  force BOOLEAN NOT NULL DEFAULT false,
  job_id TEXT,
  indexed_sha TEXT,
  head_sha TEXT,
  files INTEGER,
  parsed INTEGER,
  nodes INTEGER,
  edges INTEGER,
  seconds DOUBLE PRECISION,
  last_run JSONB NOT NULL DEFAULT '{}'::jsonb,
  error TEXT,
  requested_by TEXT,
  last_checked_at TIMESTAMPTZ,
  indexed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, binding_id)
);
CREATE INDEX IF NOT EXISTS idx_kg_repo_index_due ON kg_repo_index(updated_at) WHERE due;
-- The code_index.INDEXER_VERSION that wrote the last successful index: an older one is due again.
ALTER TABLE kg_repo_index ADD COLUMN IF NOT EXISTS indexer_version INTEGER;
CREATE OR REPLACE FUNCTION kg_repo_index_mark_due() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.status = 'active' AND (TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status
       OR OLD.default_branch IS DISTINCT FROM NEW.default_branch
       OR OLD.full_name IS DISTINCT FROM NEW.full_name) THEN
    INSERT INTO kg_repo_index (project_id, binding_id, repo, branch, due, reason)
    VALUES (NEW.project_id, NEW.id, NEW.full_name, COALESCE(NEW.default_branch, ''), true,
            CASE WHEN TG_OP = 'INSERT' OR OLD.status IS DISTINCT FROM NEW.status
                 THEN 'registered' ELSE 'branch_changed' END)
    ON CONFLICT (project_id, binding_id) DO UPDATE SET
      repo = EXCLUDED.repo, branch = EXCLUDED.branch, due = true, reason = EXCLUDED.reason,
      updated_at = now();
  END IF;
  RETURN NEW;
END $$;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'kg_repo_index_mark_due'
                 AND tgrelid = 'github_repository_bindings'::regclass) THEN
    CREATE TRIGGER kg_repo_index_mark_due
      AFTER INSERT OR UPDATE OF status, default_branch, full_name ON github_repository_bindings
      FOR EACH ROW EXECUTE FUNCTION kg_repo_index_mark_due();
  END IF;
END $$;

-- BEGIN projects archive (BOSSAPP-768 S5; KNOWLEDGE_GRAPH_PRODUCT_SPEC.md §2.7) ----------------
-- An archived project is hidden from GET /v1/projects (unless include_archived=true), refuses new
-- work (409 project_archived) and is skipped by every scheduler (services/projects_archive.py,
-- enforced by engine/tests/test_every_scheduler_skips_archived_projects.py). Reads keep working
-- and nothing is deleted; restoring clears both columns.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS archived_at TIMESTAMPTZ;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS archived_by TEXT;
CREATE INDEX IF NOT EXISTS idx_projects_archived ON projects(id) WHERE archived_at IS NOT NULL;
-- END projects archive ---------------------------------------------------------------------------

-- BEGIN project type (BOSSAPP-768 project flow) ---------------------------------------------------
-- What a project is FOR, chosen at creation (POST /v1/projects, the create_project tool): `app`
-- builds apps (every project before this column), `knowledge_graph` maps an existing codebase into
-- a knowledge graph (import code → assign the team → first rules scan → review), guided by the
-- Knowledge Graph area's setup (services/knowledge/project_setup.py). A generic column, not a KG
-- flag: the type decides which guided flow and home card a project gets.
ALTER TABLE projects ADD COLUMN IF NOT EXISTS project_type TEXT NOT NULL DEFAULT 'app';
DO $project_type$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'projects_project_type_check') THEN
    ALTER TABLE projects ADD CONSTRAINT projects_project_type_check
      CHECK (project_type IN ('app', 'knowledge_graph'));
  END IF;
END $project_type$;
-- END project type -------------------------------------------------------------------------------

-- ── BOSSAPP-768 KGV view rollups (KNOWLEDGE_GRAPH_PRODUCT_SPEC.md §2.4) ─────────────────────
-- Derived and rebuildable (services/knowledge/view_rollup.py rebuild): the Graph area's overview
-- and neighbourhood read these instead of aggregating a large code graph live (Fineract: 523 ms
-- ad hoc for the area level against a 300 ms target). Keys: 'area:<repo>:<area>',
-- 'pkg:<repo>:<area>:<package>' (a package name spans areas: 189 of 1,151 on Fineract), and the
-- class/method node_key. Rebuilt at the end of a successful index and by the worker's reconcile
-- when kg_view_sync.nodes differs from the live code count. Rules and Learning are read live.
-- UNLOGGED, all three: derived data needs no WAL, and a crash empties them together, which reads
-- as never built (stale) and the reconcile rebuilds. The tree and edge rows carry no foreign key
-- (a per-row check was a quarter of the 3 s build budget on Fineract's 83k rows): kg_view_sync
-- holds it, and its delete trigger removes the project's rows with it.
CREATE UNLOGGED TABLE IF NOT EXISTS kg_view_tree (
  project_id TEXT NOT NULL,
  key TEXT NOT NULL,
  parent_key TEXT,
  level TEXT NOT NULL CHECK (level IN ('area','package','class','method')),
  node_id TEXT,
  label TEXT NOT NULL,
  symbol_kind TEXT,
  child_count INTEGER NOT NULL DEFAULT 0,
  class_count INTEGER NOT NULL DEFAULT 0,
  sort_key TEXT NOT NULL,
  -- beside the spec's columns: the repo, area and package labels of every row and the methods
  -- under it, so a node's area, an overview bubble's counts and a repo filter need no join
  repo TEXT NOT NULL DEFAULT '',
  area TEXT NOT NULL DEFAULT '',
  package TEXT,
  method_count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (project_id, key)
);
CREATE INDEX IF NOT EXISTS idx_kg_view_tree_parent ON kg_view_tree(project_id, parent_key, sort_key);
CREATE UNLOGGED TABLE IF NOT EXISTS kg_view_edges (
  project_id TEXT NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('area','package','class')),
  src_key TEXT NOT NULL,
  dst_key TEXT NOT NULL,
  kind TEXT NOT NULL,             -- calls (calls+dispatches_to) | imports | extends (extends+implements)
  weight INTEGER NOT NULL,
  PRIMARY KEY (project_id, level, src_key, dst_key, kind)
);
CREATE INDEX IF NOT EXISTS idx_kg_view_edges_dst ON kg_view_edges(project_id, level, dst_key);
CREATE UNLOGGED TABLE IF NOT EXISTS kg_view_sync (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  built_at TIMESTAMPTZ NOT NULL,
  nodes INTEGER NOT NULL,         -- live code nodes when built (the staleness test)
  edges INTEGER NOT NULL,         -- live edges when built (the overview's totals)
  ms INTEGER NOT NULL,
  tree_rows INTEGER NOT NULL DEFAULT 0,
  view_edges INTEGER NOT NULL DEFAULT 0
);
CREATE OR REPLACE FUNCTION kg_view_sync_cleanup() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  DELETE FROM kg_view_tree WHERE project_id = OLD.project_id;
  DELETE FROM kg_view_edges WHERE project_id = OLD.project_id;
  RETURN OLD;
END $$;
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'kg_view_sync_cleanup'
                 AND tgrelid = 'kg_view_sync'::regclass) THEN
    CREATE TRIGGER kg_view_sync_cleanup AFTER DELETE ON kg_view_sync
      FOR EACH ROW EXECUTE FUNCTION kg_view_sync_cleanup();
  END IF;
END $$;

-- ============================================================================================
-- BOSSAPP-KGR rules + usage (BOSSAPP-768, KNOWLEDGE_GRAPH_PRODUCT_SPEC.md §2.1-2.3, §2.5-2.6).
-- ============================================================================================
-- 1. The storage layer gains `rules` (kind 'rule'), so a stage scope can grant or refuse rules
--    on their own. The generated column's CASE changes, and Postgres cannot alter a generation
--    expression, so the column is dropped and added again — but only when the live expression
--    differs from this one: the probe table below asks Postgres how IT spells this CASE, and the
--    live column is compared with that, so the rewrite of kg_nodes (seconds on 5 x 51k rows)
--    happens once, on the upgrade that changes the CASE, never on an ordinary boot. The earlier
--    BOSSAPP-622 block's ADD COLUMN IF NOT EXISTS is then a no-op. Kept in step with
--    scopes.layer_sql_case() by test_knowledge_stage_scopes_db.
DO $kgr_layer$
DECLARE
  want TEXT;
  have TEXT;
BEGIN
  CREATE TEMP TABLE kgr_layer_probe (
    kind TEXT,
    knowledge_layer TEXT GENERATED ALWAYS AS (CASE WHEN kind IN ('config_key', 'endpoint', 'file', 'module', 'queue', 'symbol', 'table') THEN 'code' WHEN kind IN ('agent', 'decision', 'person', 'pull_request', 'release', 'review_finding', 'run', 'spec', 'team') THEN 'lifecycle' WHEN kind IN ('alert_rule', 'datastore', 'deployment', 'external', 'incident', 'repo', 'resource', 'root_cause', 'runbook', 'service') THEN 'ops' WHEN kind IN ('rule') THEN 'rules' WHEN kind IN ('agent_decision', 'coverage_gap') THEN 'context' ELSE 'knowledge' END) STORED
  );
  SELECT generation_expression INTO want FROM information_schema.columns
  WHERE table_name = 'kgr_layer_probe' AND column_name = 'knowledge_layer';
  DROP TABLE kgr_layer_probe;
  SELECT generation_expression INTO have FROM information_schema.columns
  WHERE table_schema = current_schema() AND table_name = 'kg_nodes' AND column_name = 'knowledge_layer';
  -- Only while the column is still GENERATED: the context-layer block at the end of this file
  -- makes it a plain column kept by a trigger (have IS NULL), which must never be rebuilt here.
  IF have IS NOT NULL AND have IS DISTINCT FROM want THEN
    DROP INDEX IF EXISTS idx_kg_nodes_layer;
    DROP INDEX IF EXISTS idx_kg_nodes_search_noncode;
    ALTER TABLE kg_nodes DROP COLUMN IF EXISTS knowledge_layer;
    ALTER TABLE kg_nodes ADD COLUMN knowledge_layer TEXT
      GENERATED ALWAYS AS (CASE WHEN kind IN ('config_key', 'endpoint', 'file', 'module', 'queue', 'symbol', 'table') THEN 'code' WHEN kind IN ('agent', 'decision', 'person', 'pull_request', 'release', 'review_finding', 'run', 'spec', 'team') THEN 'lifecycle' WHEN kind IN ('alert_rule', 'datastore', 'deployment', 'external', 'incident', 'repo', 'resource', 'root_cause', 'runbook', 'service') THEN 'ops' WHEN kind IN ('rule') THEN 'rules' WHEN kind IN ('agent_decision', 'coverage_gap') THEN 'context' ELSE 'knowledge' END) STORED;
  END IF;
END $kgr_layer$;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_layer
  ON kg_nodes(project_id, knowledge_layer, kind) WHERE valid_to IS NULL;
CREATE INDEX IF NOT EXISTS idx_kg_nodes_search_noncode
  ON kg_nodes USING GIN (search_tsv) WHERE knowledge_layer <> 'code';
-- Rules are read by status (the review queue) and by scan; both live in attrs.
CREATE INDEX IF NOT EXISTS idx_kg_nodes_rule_status
  ON kg_nodes(project_id, (attrs->>'status')) WHERE kind = 'rule';
-- 2. Durable "consulted" and "reused" (§2.5). `shown` is today's behaviour (the item was in the
--    injected pack) and draws no edge; consulted / cited / reused do. run_id stays the agent run.
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS use_kind TEXT NOT NULL DEFAULT 'shown';
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS workflow_run_id TEXT;
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS code_task_run_id TEXT;
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS agent_role TEXT;
DO $kgr_usage$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'kg_usage_use_kind_check') THEN
    ALTER TABLE kg_usage ADD CONSTRAINT kg_usage_use_kind_check
      CHECK (use_kind IN ('shown', 'consulted', 'cited', 'reused'));
  END IF;
END $kgr_usage$;
-- "Consulted by N runs" on a node, and the edges ingest derives per item.
CREATE INDEX IF NOT EXISTS idx_kg_usage_fact_kind ON kg_usage(project_id, fact_id, use_kind);
-- 3. Who, not only what kind of actor: a person id or an agent role key on every audited write
--    (rule approve / edit / reject, fact promote / reject / forget).
ALTER TABLE kg_audit ADD COLUMN IF NOT EXISTS actor_ref TEXT;
CREATE INDEX IF NOT EXISTS idx_kg_audit_entity ON kg_audit(project_id, entity_id, created_at);
-- 4. The AGE projection's shape (§2.6: the Rules label, product_layer and status properties).
--    age.PROJECTION_SHAPE names the shape the code writes; a graph projected with an older shape
--    is rebuilt by the next reconcile even when its counts match, so the new properties reach
--    every existing vertex once, after this upgrade. The table itself is age.py's (created on the
--    first projection, with the column); an install that already projected gains it here.
DO $kgr_age$
BEGIN
  IF to_regclass('kg_age_sync') IS NOT NULL THEN
    ALTER TABLE kg_age_sync ADD COLUMN IF NOT EXISTS shape INTEGER NOT NULL DEFAULT 0;
  END IF;
END $kgr_age$;
-- ================================ end BOSSAPP-KGR rules + usage =============================

-- BEGIN run nodes by name (BOSSAPP-768 round 2) ----------------------------------------------------
-- A run node is named for its run (learning_writeback.run_title), never "Run wfr_…": the ones written
-- before that are renamed once from the run's own title and start time. Idempotent.
UPDATE kg_nodes n SET name = left(regexp_replace(coalesce(nullif(r.input->>'title', ''), d.name), '\s+', ' ', 'g'), 90)
       || ' · ' || to_char(r.created_at, 'Mon DD, HH24:MI')
  FROM workflow_runs r LEFT JOIN workflow_definitions d ON d.id = r.workflow_definition_id
 WHERE n.kind = 'run' AND n.name = 'Run ' || r.id AND coalesce(nullif(r.input->>'title', ''), d.name) IS NOT NULL;
UPDATE kg_nodes n SET name = left(regexp_replace(c.title, '\s+', ' ', 'g'), 90) || ' · ' || to_char(c.created_at, 'Mon DD, HH24:MI')
  FROM code_task_runs c
 WHERE n.kind = 'run' AND n.name = 'Run ' || c.id AND nullif(c.title, '') IS NOT NULL;
-- END run nodes by name ------------------------------------------------------------------------------
-- ============================ BOSSAPP-768 S2c: usage in conversations ========================
-- A chat turn that is given rules or learnings uses them as a run does (spec §2.5), with no run:
-- its row names the conversation (agent_threads.id, also run_id: the anchor `run:<thread id>` is
-- a run node whose attrs.subtype is 'conversation'), the turn (agent_acts.act_id) and, once the
-- reply is written, the message that answered (agent_messages.id).
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS agent_thread_id TEXT;
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS act_id TEXT;
ALTER TABLE kg_usage ADD COLUMN IF NOT EXISTS message_id TEXT;
CREATE INDEX IF NOT EXISTS idx_kg_usage_thread ON kg_usage(project_id, agent_thread_id)
  WHERE agent_thread_id IS NOT NULL;
-- ============================ end BOSSAPP-768 S2c ============================================

-- ============================ Build E: lineage sandboxes =====================================
-- One warm sandbox per lineage (boss_engine.services.lineage_sandbox), reused by fetch+reset
-- across repair rounds/follow-ups/retries of the same root_run_id instead of a fresh clone.
CREATE TABLE IF NOT EXISTS lineage_sandboxes (
    lineage_id TEXT PRIMARY KEY,
    project_id TEXT,
    run_dir TEXT NOT NULL,
    uid INTEGER NOT NULL,
    database_name TEXT,
    status TEXT NOT NULL DEFAULT 'warm',
    stage_hashes TEXT NOT NULL DEFAULT '{}',
    dependency_manifest_hash TEXT,
    current_run_id TEXT,
    created_at TEXT,
    last_used_at TEXT,
    purged_at TEXT,
    release_reason TEXT
);
-- A forged cross-lineage claim (wrong uid for a live sandbox) is refused and counted here,
-- never granted — two lineages never share a sandbox.
CREATE TABLE IF NOT EXISTS sandbox_violation_counts (
    lineage_id TEXT PRIMARY KEY,
    count INTEGER NOT NULL DEFAULT 0
);
-- ============================ end Build E: lineage sandboxes =================================

-- ============================ KG P5b: banking_regulatory_compliance ==========================
-- AgentDecision is a `context`-layer kg_nodes row (services/knowledge/context_graph.py), not a
-- table of its own. This view projects those rows under the name a decision is queried by —
-- additive, read-only, and the single place "a step's recorded decision" is read as a row.
CREATE OR REPLACE VIEW agent_decisions AS
  SELECT id,
         project_id,
         attrs->>'decision_type' AS decision_type,
         attrs->>'step_id'       AS step_id,
         attrs->>'run_id'        AS run_id,
         name,
         body AS statement,
         recorded_at AS created_at
  FROM kg_nodes
  WHERE kind = 'agent_decision' AND valid_to IS NULL;

-- ============================ KG P6a: external agents ========================================
-- A bank's own HTTP-hosted agent, registered to run one workflow step under BOSS's contract
-- (services/knowledge/external_agents.py). Migrated here, not by ensure_schema() in the request
-- path: the request path only ever reads/writes rows, never converges the schema.
CREATE TABLE IF NOT EXISTS external_agents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  display_name TEXT NOT NULL,
  endpoint_url TEXT NOT NULL,
  secret_ref TEXT NOT NULL,
  sponsor_principal_id TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'suspended')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_external_agents_project ON external_agents(project_id, status);

-- The per-execution Knowledge-Graph token handed to an external agent
-- (services/knowledge/external_agent_tokens.py): opaque, short TTL, revocable, checked live.
CREATE TABLE IF NOT EXISTS external_agent_kg_tokens (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  run_id TEXT NOT NULL,
  step_id TEXT NOT NULL,
  external_agent_id TEXT NOT NULL,
  token_hash TEXT NOT NULL UNIQUE,
  policy JSONB NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_external_agent_kg_tokens_hash ON external_agent_kg_tokens(token_hash);
CREATE INDEX IF NOT EXISTS idx_external_agent_kg_tokens_expiry ON external_agent_kg_tokens(expires_at);

-- A project's ontology packs (services/knowledge/ontology_packs.py): SEVERAL per project, keyed
-- (project_id, pack_id). It was one per project (key project_id), so adding the DQ pack to a
-- project running the AML and regulatory case studies took their kinds away. An install made
-- with the old key is migrated in place: its one row stays as the project's first pack.
CREATE TABLE IF NOT EXISTS kg_ontology_packs (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  pack_id TEXT NOT NULL,
  version TEXT NOT NULL,
  set_by TEXT NOT NULL,
  set_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, pack_id)
);
DO $$
BEGIN
  IF (SELECT count(*) FROM pg_index i JOIN pg_attribute a
        ON a.attrelid = i.indrelid AND a.attnum = ANY(i.indkey)
      WHERE i.indrelid = 'kg_ontology_packs'::regclass AND i.indisprimary) = 1 THEN
    ALTER TABLE kg_ontology_packs DROP CONSTRAINT kg_ontology_packs_pkey;
    ALTER TABLE kg_ontology_packs ADD PRIMARY KEY (project_id, pack_id);
  END IF;
END $$;
-- ============================================================================================
-- THE CONTEXT LAYER OF PACK KINDS (design §4.2, reference-design conformance P1 #8).
-- ============================================================================================
-- kg_nodes.knowledge_layer was a column GENERATED from a hard-coded CASE, so the context kinds
-- an ontology pack declares (compliance_case, remediation_package, aml_case, resolved_pattern…)
-- were stored as 'knowledge' and every SQL, MCP or kg_search filter by layer missed them. The
-- column becomes a plain one kept by a trigger: a kind named in kg_kind_layers (synced from the
-- packs by ontology_packs.sync_kind_layers, which also backfills existing rows, idempotently)
-- takes that layer; every other kind keeps the core CASE (scopes.layer_sql_case, pinned by
-- test_knowledge_stage_scopes_db). The KGR block above rebuilds the column only while it is
-- still generated, so after this block it never rewrites kg_nodes again.
CREATE TABLE IF NOT EXISTS kg_kind_layers (
  kind TEXT PRIMARY KEY,
  layer TEXT NOT NULL CHECK (layer IN ('code', 'lifecycle', 'ops', 'knowledge', 'rules', 'context')),
  source TEXT NOT NULL DEFAULT 'pack',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE OR REPLACE FUNCTION kg_nodes_set_layer() RETURNS trigger LANGUAGE plpgsql AS $kg_layer$
BEGIN
  NEW.knowledge_layer := COALESCE(
    (SELECT l.layer FROM kg_kind_layers l WHERE l.kind = NEW.kind),
    CASE WHEN NEW.kind IN ('config_key', 'endpoint', 'file', 'module', 'queue', 'symbol', 'table') THEN 'code' WHEN NEW.kind IN ('agent', 'decision', 'person', 'pull_request', 'release', 'review_finding', 'run', 'spec', 'team') THEN 'lifecycle' WHEN NEW.kind IN ('alert_rule', 'datastore', 'deployment', 'external', 'incident', 'repo', 'resource', 'root_cause', 'runbook', 'service') THEN 'ops' WHEN NEW.kind IN ('rule') THEN 'rules' WHEN NEW.kind IN ('agent_decision', 'coverage_gap') THEN 'context' ELSE 'knowledge' END);
  RETURN NEW;
END $kg_layer$;
DO $kg_layer_plain$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.columns
             WHERE table_schema = current_schema() AND table_name = 'kg_nodes'
               AND column_name = 'knowledge_layer' AND is_generated = 'ALWAYS') THEN
    ALTER TABLE kg_nodes ALTER COLUMN knowledge_layer DROP EXPRESSION;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'kg_nodes_layer'
                 AND tgrelid = 'kg_nodes'::regclass) THEN
    CREATE TRIGGER kg_nodes_layer BEFORE INSERT OR UPDATE OF kind ON kg_nodes
      FOR EACH ROW EXECUTE FUNCTION kg_nodes_set_layer();
  END IF;
END $kg_layer_plain$;

-- ============================================================================================
-- AGENT DESIGN REVIEW AND LOCK (design §4.6): one row per (workflow, stage) design version.
-- ============================================================================================
-- not_reviewed → in_review → locked. Locking needs a person who manages the workflow (and a
-- fresh second factor, as every workflow:publish act); a locked stage's contract cannot be
-- published changed until "Revise" opens the next version in review (stage_designs.py). Every
-- transition is a workflow.design_* event.
CREATE TABLE IF NOT EXISTS workflow_stage_designs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  workflow_definition_id TEXT NOT NULL REFERENCES workflow_definitions(id) ON DELETE CASCADE,
  stage_id TEXT NOT NULL,
  design_version INTEGER NOT NULL CHECK (design_version >= 1),
  reference TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('not_reviewed', 'in_review', 'locked')),
  contract_hash TEXT NOT NULL,
  contract JSONB NOT NULL DEFAULT '{}'::jsonb,
  under_revision TEXT,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  sent_for_review_by TEXT,
  sent_for_review_at TIMESTAMPTZ,
  locked_by TEXT,
  locked_by_name TEXT,
  locked_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (workflow_definition_id, stage_id, design_version)
);
CREATE INDEX IF NOT EXISTS idx_workflow_stage_designs_stage
  ON workflow_stage_designs(project_id, workflow_definition_id, stage_id, design_version DESC);

-- ============================================================================================
-- AUTONOMOUS AGENTS: SIGNALS, THE WORK BOARD, THE DECISION LEDGER, AUTONOMY PER TASK CLASS
-- (BOSSAPP-902..912; design: boss-autonomous-agents-design.md §4-§13; contracts:
-- docs/product/AUTONOMOUS_AGENTS_SPEC.md; code: engine/boss_engine/services/ambient/).
-- ============================================================================================
-- ONE SIGNAL INBOX (design §3.3 gap 1, §4 L2). Signals sat in ten stores (alerts, doctor
-- findings, shepherd escalations, failed steps, deadletters, stale PRs ...) with no shared shape
-- and no dedupe across them, so the shepherd, the doctor and the captain could each raise the
-- same problem. Every store keeps its own table; a pull adapter copies what matters into ONE
-- normalised row here. A row is keyed by its FINGERPRINT (a stable hash of kind + subject): a
-- repeat of the same problem counts an occurrence on the open row instead of opening another.
-- `source_refs` lists every source row already folded in, so a sweep that sees the same failed
-- step again is a no-op, and a closed problem is never reopened by its own stale evidence.
-- project_id NULL = install-wide (the system doctor's findings have no project).
CREATE TABLE IF NOT EXISTS signals (
  id TEXT PRIMARY KEY,                       -- 'sig_' + hex
  project_id TEXT,
  source TEXT NOT NULL,                      -- ambient.signals.SOURCES
  kind TEXT NOT NULL,                        -- 'alert.firing', 'workflow.step_failed', ...
  subject_kind TEXT,                         -- app | workflow_run | code_task | pull_request | host ...
  subject_id TEXT,
  app TEXT,
  fingerprint TEXT NOT NULL,
  severity TEXT NOT NULL DEFAULT 'medium'
    CHECK (severity IN ('info', 'low', 'medium', 'high', 'critical')),
  title TEXT NOT NULL,
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,     -- [{kind, ref, note?}]
  source_refs JSONB NOT NULL DEFAULT '[]'::jsonb,  -- ["app_alert:al_1#3", ...] (bounded)
  occurrences INTEGER NOT NULL DEFAULT 1 CHECK (occurrences >= 1),
  dedupe_window_seconds INTEGER NOT NULL DEFAULT 3600 CHECK (dedupe_window_seconds >= 0),
  status TEXT NOT NULL DEFAULT 'new'
    CHECK (status IN ('new', 'triaged', 'merged_into', 'suppressed', 'done')),
  status_reason TEXT,
  merged_into TEXT,
  suppressed_until TIMESTAMPTZ,              -- NULL while suppressed = until the evidence changes
  work_item_id TEXT,
  caused_by_run_id TEXT,                     -- an ambient run whose output raised this (loop guard)
  causal_depth INTEGER NOT NULL DEFAULT 0 CHECK (causal_depth >= 0),
  observed_at TIMESTAMPTZ NOT NULL,
  first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_signals_open_fingerprint
  ON signals (COALESCE(project_id, ''), fingerprint) WHERE status IN ('new', 'triaged', 'suppressed');
CREATE INDEX IF NOT EXISTS idx_signals_fingerprint ON signals (fingerprint, last_seen_at DESC);
CREATE INDEX IF NOT EXISTS idx_signals_project_status ON signals (project_id, status, last_seen_at DESC);
CREATE INDEX IF NOT EXISTS idx_signals_work_item ON signals (work_item_id) WHERE work_item_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_signals_source_refs ON signals USING GIN (source_refs);
-- Where each pull adapter got to: a sweep reads rows changed since (cursor - overlap).
CREATE TABLE IF NOT EXISTS signal_adapter_cursors (
  adapter TEXT PRIMARY KEY,
  cursor_at TIMESTAMPTZ,
  last_run_at TIMESTAMPTZ,
  last_recorded INTEGER NOT NULL DEFAULT 0,
  last_error TEXT
);

-- THE WORK BOARD IS work_items (design §6 "blackboard", §13.1; BOSSAPP-830 makes work_items the
-- canonical node). The ranked portfolio (work_orchestration.upsert_work_item / evaluate_admission
-- / rank_by_value_density) already scores and admits work and "almost nothing feeds it" (§3.2).
-- Ambient work joins it rather than starting a second backlog: an ambient row is an ordinary
-- work item (subject_type 'ambient', subject_id = its own id, status 'active' while live and
-- 'done' after) plus the lifecycle, lease and loop-guard columns below. The REAL subject is
-- subject_ref ('app:order-api'), because one app has many problems over time and the portfolio's
-- UNIQUE(project, subject_type, subject_id) is one row per subject for ever.
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS ambient BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS fingerprint TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS lifecycle TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS task_class TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS autonomy_level TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS risk TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS severity TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS subject_ref TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS app TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS lease_owner TEXT;        -- agent:<role> | person:<id>
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS lease_kind TEXT;         -- agent | person
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS lease_token TEXT;        -- fencing token of the holder
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS lease_expires_at TIMESTAMPTZ;  -- NULL for a person
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS causal_depth INTEGER NOT NULL DEFAULT 0;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS caused_by_run_id TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS attempts INTEGER NOT NULL DEFAULT 0;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS outcome TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS resolved_by TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS resolved_at TIMESTAMPTZ;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS needs_you_at TIMESTAMPTZ;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS needs_you_decision_id TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS answered_at TIMESTAMPTZ;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS cost_usd_micros BIGINT NOT NULL DEFAULT 0;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS squad JSONB NOT NULL DEFAULT '[]'::jsonb;
-- A person's extra squad budget for this item, on top of the default (squad_turns.budget_of):
-- "Give it $1 more" on a spent-budget card raises it. NULL = the default.
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS squad_budget_usd_micros BIGINT;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_lifecycle_check'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_lifecycle_check CHECK (lifecycle IS NULL OR
      lifecycle IN ('proposed', 'claimed', 'in_progress', 'needs_you', 'resolved', 'dismissed',
                    'failed'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_autonomy_level_check'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_autonomy_level_check
      CHECK (autonomy_level IS NULL OR autonomy_level IN ('A0', 'A1', 'A2', 'A3'));
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_lease_kind_check'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_lease_kind_check
      CHECK (lease_kind IS NULL OR lease_kind IN ('agent', 'person'));
  END IF;
END $$;
-- ONE LIVE ITEM PER FINGERPRINT (design §6 rule 1, generalising self_fix._live_claim): the
-- database refuses a second live item for a problem, whichever sensor raised it.
CREATE UNIQUE INDEX IF NOT EXISTS uq_work_items_live_fingerprint ON work_items (project_id, fingerprint)
  WHERE fingerprint IS NOT NULL AND lifecycle IN ('proposed', 'claimed', 'in_progress', 'needs_you');
CREATE INDEX IF NOT EXISTS idx_work_items_ambient
  ON work_items (project_id, lifecycle, updated_at DESC) WHERE ambient;
CREATE INDEX IF NOT EXISTS idx_work_items_fingerprint_history
  ON work_items (project_id, fingerprint, updated_at DESC) WHERE fingerprint IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_work_items_agent_leases
  ON work_items (lease_expires_at) WHERE lease_kind = 'agent';
-- What a work item touched: its signals, runs, builds, decisions, acts, PRs, reservations.
CREATE TABLE IF NOT EXISTS work_item_links (
  work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('signal', 'workflow_run', 'code_task', 'decision', 'act',
                                     'incident', 'meeting', 'pull_request', 'reservation',
                                     'alert', 'recommendation')),
  ref TEXT NOT NULL,
  project_id TEXT NOT NULL,
  note TEXT,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (work_item_id, kind, ref)
);
CREATE INDEX IF NOT EXISTS idx_work_item_links_ref ON work_item_links (kind, ref);

-- THE BOARD'S PROTOCOL (design §13.1, §13.3). Agents change shared state only by typed,
-- validated messages: claim, finding, hypothesis, proposal, critique, vote, decision, handoff,
-- escalate, resolve. A vote is a message, so the vote and its reasons are the same record the
-- Agent Operations diagram draws. Append-only: nothing edits a message once posted (the trigger
-- below); a correction is a new message.
CREATE TABLE IF NOT EXISTS work_item_messages (
  id TEXT PRIMARY KEY,                       -- 'wim_' + ulid-ish (time ordered)
  project_id TEXT NOT NULL,
  work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('claim', 'finding', 'hypothesis', 'proposal', 'critique',
                                     'vote', 'decision', 'handoff', 'escalate', 'resolve',
                                     'squad')),
  sender TEXT NOT NULL,                      -- agent:<role> | person:<id> | policy:<id> | boss
  body JSONB NOT NULL DEFAULT '{}'::jsonb,
  reply_to TEXT REFERENCES work_item_messages(id) ON DELETE CASCADE,
  act_id TEXT,
  -- clock_timestamp, not now(): messages posted in one transaction keep the order they were
  -- posted in (a proposal before its votes), as events.created_at does.
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS idx_work_item_messages_item ON work_item_messages (work_item_id, created_at, id);
-- One vote per voter per proposal: a voter changing its mind posts a critique, not a 2nd vote.
CREATE UNIQUE INDEX IF NOT EXISTS uq_work_item_messages_vote
  ON work_item_messages (reply_to, sender) WHERE kind = 'vote';
-- THE SQUAD ON THE BOARD (BOSSAPP-908, ambient/squads.py): the roster assembled for an item is
-- itself a board message (kind 'squad'), so who was seated, why, and what could not be filled
-- is on the same append-only record the diagram draws. Older installs get the kind added here.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_item_messages_kind_check'
             AND conrelid = 'work_item_messages'::regclass
             AND pg_get_constraintdef(oid) NOT LIKE '%squad%') THEN
    ALTER TABLE work_item_messages DROP CONSTRAINT work_item_messages_kind_check;
    ALTER TABLE work_item_messages ADD CONSTRAINT work_item_messages_kind_check
      CHECK (kind IN ('claim', 'finding', 'hypothesis', 'proposal', 'critique', 'vote',
                      'decision', 'handoff', 'escalate', 'resolve', 'squad'));
  END IF;
END $$;

-- THE DECISION LEDGER (design §11.2; BOSSAPP-906). A decision is an ACT: agent_acts gains the
-- kind 'decision', so who decided, when, at what cost and after whom is the same row every act
-- reader already reads (agent_acts.py was written to end "eight answers in eight tables"; a
-- ninth who-did-this table would undo it). What only a decision has (the question, the options,
-- rationale, evidence, confidence, level, reversibility, consensus, override chain, outcome)
-- lives in this 1:1 detail row keyed by the act. APPEND-ONLY: an override is a NEW row pointing
-- at the row it overrides; the only later write is filling the outcome once.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'agent_acts_kind_check'
             AND conrelid = 'agent_acts'::regclass
             AND pg_get_constraintdef(oid) NOT LIKE '%decision%') THEN
    ALTER TABLE agent_acts DROP CONSTRAINT agent_acts_kind_check;
    ALTER TABLE agent_acts ADD CONSTRAINT agent_acts_kind_check CHECK (kind IN ('run', 'step',
      'stage', 'seat', 'chat', 'approval', 'handoff', 'decision'));
  END IF;
  IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'agent_acts_how_check'
             AND conrelid = 'agent_acts'::regclass
             AND pg_get_constraintdef(oid) NOT LIKE '%signal%') THEN
    ALTER TABLE agent_acts DROP CONSTRAINT agent_acts_how_check;
    ALTER TABLE agent_acts ADD CONSTRAINT agent_acts_how_check CHECK (how IN ('named',
      'only_holder', 'only_candidate', 'model_pick', 'captain', 'run_actor', 'next_stage',
      'seated', 'asked_by_person', 'asked_by_agent', 'approved', 'started', 'signal', 'board'));
  END IF;
END $$;
CREATE TABLE IF NOT EXISTS agent_act_decisions (
  act_id TEXT PRIMARY KEY REFERENCES agent_acts(act_id),
  project_id TEXT NOT NULL,
  work_item_id TEXT,
  signal_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  question TEXT NOT NULL,
  decided_by TEXT NOT NULL CHECK (decided_by ~ '^(agent|policy|squad|person):.+$'),
  chosen TEXT NOT NULL,
  options JSONB NOT NULL DEFAULT '[]'::jsonb,      -- every option considered, chosen included
  rejected JSONB NOT NULL DEFAULT '[]'::jsonb,     -- [{option, why?}]
  rationale TEXT NOT NULL,                         -- at most 3 sentences (ledger.py checks)
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,     -- [{kind, ref, note?}], each checked to exist
  confidence NUMERIC(4, 3) CHECK (confidence IS NULL OR confidence BETWEEN 0 AND 1),
  autonomy_level TEXT CHECK (autonomy_level IS NULL OR autonomy_level IN ('A0', 'A1', 'A2', 'A3')),
  task_class TEXT,
  action TEXT,                                     -- the catalogue action it allows, if any
  reversibility TEXT NOT NULL CHECK (reversibility IN ('reversible', 'compensable', 'irreversible')),
  undo JSONB,                                      -- {action, ...}: required when reversible
  consensus JSONB,                                 -- collab.consensus_record(...)
  proposal_id TEXT,                                -- the board proposal it settles
  cost_usd_micros BIGINT NOT NULL DEFAULT 0 CHECK (cost_usd_micros >= 0),
  overrides_act_id TEXT REFERENCES agent_act_decisions(act_id),
  outcome TEXT CHECK (outcome IS NULL OR outcome IN ('accepted', 'edited', 'dismissed', 'ignored',
                       'merged', 'reverted', 'recurred', 'overridden', 'succeeded', 'failed',
                       'incident_caused')),
  outcome_ref TEXT,
  outcome_at TIMESTAMPTZ,
  -- clock_timestamp: a track record counts decisions AFTER a level change, even when both
  -- happen in one transaction.
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  CHECK (reversibility <> 'reversible' OR undo IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_agent_act_decisions_project ON agent_act_decisions (project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_agent_act_decisions_item ON agent_act_decisions (work_item_id, created_at);
CREATE INDEX IF NOT EXISTS idx_agent_act_decisions_class ON agent_act_decisions (project_id, task_class, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS uq_agent_act_decisions_one_override
  ON agent_act_decisions (overrides_act_id) WHERE overrides_act_id IS NOT NULL;
-- APPEND-ONLY, ENFORCED BY THE DATABASE, not by every caller remembering. The one permitted
-- update fills an outcome that was empty; a purge (retention, a test cleaning its rows) must say
-- so with `SET LOCAL boss.ledger_purge = 'on'`.
CREATE OR REPLACE FUNCTION boss_append_only_ledger() RETURNS trigger LANGUAGE plpgsql AS $ledger$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF COALESCE(current_setting('boss.ledger_purge', true), '') = 'on' THEN
      RETURN OLD;
    END IF;
    RAISE EXCEPTION '% is append-only: rows are never deleted', TG_TABLE_NAME;
  END IF;
  IF TG_TABLE_NAME = 'agent_act_decisions'
     AND OLD.outcome IS NULL AND NEW.outcome IS NOT NULL
     AND (to_jsonb(NEW) - 'outcome' - 'outcome_ref' - 'outcome_at')
         = (to_jsonb(OLD) - 'outcome' - 'outcome_ref' - 'outcome_at') THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION '% is append-only: write a new row instead of changing one', TG_TABLE_NAME;
END $ledger$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'agent_act_decisions_append_only'
                 AND tgrelid = 'agent_act_decisions'::regclass) THEN
    CREATE TRIGGER agent_act_decisions_append_only BEFORE UPDATE OR DELETE ON agent_act_decisions
      FOR EACH ROW EXECUTE FUNCTION boss_append_only_ledger();
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'work_item_messages_append_only'
                 AND tgrelid = 'work_item_messages'::regclass) THEN
    CREATE TRIGGER work_item_messages_append_only BEFORE UPDATE ON work_item_messages
      FOR EACH ROW EXECUTE FUNCTION boss_append_only_ledger();
  END IF;
END $$;

-- AUTONOMY PER TASK CLASS, EARNED (design §4 L5, §5; BOSSAPP-905). One row per (project, task
-- class) the operator or the track record changed; a class with no row runs at its catalogue
-- default (ambient/task_classes.py). `ceiling` is the operator's cap for the class here; the
-- catalogue's own ceiling caps that. Merge, production deploy, external send and payment are
-- never decided by a level (policy.ALWAYS_A_PERSON).
CREATE TABLE IF NOT EXISTS ambient_autonomy (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  task_class TEXT NOT NULL,
  level TEXT NOT NULL CHECK (level IN ('A0', 'A1', 'A2', 'A3')),
  ceiling TEXT NOT NULL CHECK (ceiling IN ('A0', 'A1', 'A2', 'A3')),
  set_by TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, task_class),
  CHECK (level <= ceiling)
);
-- A class's own answer to "review always-on builds before they start" (NULL: the project's).
ALTER TABLE ambient_autonomy ADD COLUMN IF NOT EXISTS review_builds BOOLEAN;
-- Every change of level and every promotion BOSS suggests, with the track record behind it.
CREATE TABLE IF NOT EXISTS ambient_autonomy_changes (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  task_class TEXT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('set', 'ceiling', 'promotion_suggested', 'promoted',
                                     'demoted')),
  from_level TEXT,
  to_level TEXT,
  actor TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  evidence JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS idx_ambient_autonomy_changes
  ON ambient_autonomy_changes (project_id, task_class, created_at DESC);
-- ONE ENVELOPE AND ONE STOP PER PROJECT (design §9): the ambient daily cap (reserved through
-- BudgetGovernor under category 'ambient'), concurrency, the loop guards' limits, and the
-- project's kill switch. The install-wide stop is system_state['ambient'] (+ BOSS_AMBIENT_DISABLED).
CREATE TABLE IF NOT EXISTS ambient_settings (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  daily_cap_usd_micros BIGINT NOT NULL DEFAULT 5000000 CHECK (daily_cap_usd_micros >= 0),
  max_concurrent INTEGER NOT NULL DEFAULT 2 CHECK (max_concurrent >= 0),
  max_spawn_depth INTEGER NOT NULL DEFAULT 2 CHECK (max_spawn_depth >= 0),
  daily_attempt_cap INTEGER NOT NULL DEFAULT 10 CHECK (daily_attempt_cap >= 0),
  cooldown_hours INTEGER NOT NULL DEFAULT 24 CHECK (cooldown_hours >= 0),
  breaker_failure_ratio NUMERIC(4, 3) NOT NULL DEFAULT 0.5
    CHECK (breaker_failure_ratio > 0 AND breaker_failure_ratio <= 1),
  breaker_min_runs INTEGER NOT NULL DEFAULT 4 CHECK (breaker_min_runs >= 1),
  stopped BOOLEAN NOT NULL DEFAULT false,
  stopped_by TEXT,
  stopped_at TIMESTAMPTZ,
  stop_reason TEXT,
  resumed_at TIMESTAMPTZ,                    -- the breaker counts only failures after this
  updated_by TEXT NOT NULL DEFAULT 'boss',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- "Review always-on builds before they start" (Project › Settings › Autonomy & budget): NULL
-- follows the install's default (system_state['ambient_review_builds']), which is off.
ALTER TABLE ambient_settings ADD COLUMN IF NOT EXISTS review_squad_builds BOOLEAN;
-- DISCOVERY DOSSIER (BOSSAPP-909; design §4 L1 "give it a directory and it starts working").
-- When a repository is registered (its first code-graph index) or on request, BOSS reads it with
-- no instructions and keeps ONE current dossier per project repository: stack, structure,
-- test/CI commands, owners, docs and runbooks, TODO clusters, churn × size hotspots, the
-- dependency surface and advisories, the open BOSS work and a knowledge-graph summary. What it
-- finds that is worth doing ("no CI", "a hotspot with no tests") is seeded as signals the
-- Chief of Staff triages, so a new project opens on a ranked list of proposals, not a blank page.
CREATE TABLE IF NOT EXISTS project_dossiers (
  id TEXT PRIMARY KEY,                             -- 'dos_' + ulid
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  repo TEXT NOT NULL,                              -- owner/name
  head_sha TEXT,
  facts JSONB NOT NULL DEFAULT '{}'::jsonb,
  highlights JSONB NOT NULL DEFAULT '[]'::jsonb,   -- badge-sized lines (≤ 4 words each)
  seeded_signals JSONB NOT NULL DEFAULT '[]'::jsonb,
  read_from TEXT NOT NULL DEFAULT 'checkout' CHECK (read_from IN ('checkout', 'graph')),
  version INTEGER NOT NULL DEFAULT 1,
  built_by TEXT NOT NULL DEFAULT 'boss',
  built_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, repo)
);

-- ============================================================================================
-- AUTONOMOUS AGENTS: CONTINUOUS LEARNING -> THE RECOMMENDED ROADMAP (BOSSAPP-911) AND OUTCOMES
-- (BOSSAPP-912). Design §14; contracts: docs/product/AUTONOMOUS_AGENTS_SPEC.md §9;
-- code: engine/boss_engine/services/ambient/{learning,roadmap,outcomes}.py.
-- ============================================================================================
-- A RECOMMENDATION IS A WORK ITEM (task class roadmap_item) — the board's one-live-copy rule,
-- the loop guards, the cooldown after a reject and the ledger all apply unchanged. This 1:1 row
-- holds only what the Recommended roadmap needs and a work item does not carry: which detector
-- saw it, the evidence it rests on, the score's parts (value, evidence strength, freshness,
-- effort, risk, the detector's learned weight), what shape it should take if accepted, and what
-- a person did with it (accepted as what / rejected why / snoozed until when). Outcomes are NOT
-- stored here: they live on the ledger (agent_act_decisions.outcome, spec §9 "no parallel
-- proposal_outcomes table"); proposal_act_id and decision_act_id point at those rows.
CREATE TABLE IF NOT EXISTS ambient_recommendations (
  work_item_id TEXT PRIMARY KEY REFERENCES work_items(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  detector TEXT NOT NULL,                    -- the lead detector (learning.DETECTORS)
  detectors JSONB NOT NULL DEFAULT '[]'::jsonb,  -- every detector whose finding was grouped in
  kind TEXT NOT NULL CHECK (kind IN ('hardening', 'test_gap', 'refactor', 'feature',
                                     'design_fix', 'cost', 'process')),
  fingerprint TEXT NOT NULL,                 -- the work item's fingerprint (one live per fp)
  subject TEXT,                              -- file:repo/path, workflow:key, stage:key ...
  title TEXT NOT NULL,
  why TEXT NOT NULL,                         -- at most three sentences
  proposed_shape TEXT NOT NULL CHECK (proposed_shape IN ('ticket', 'epic', 'prd')),
  squad JSONB NOT NULL DEFAULT '[]'::jsonb,  -- roles that would do it
  evidence JSONB NOT NULL DEFAULT '[]'::jsonb,   -- [{kind, ref, note?, at?}] newest first
  evidence_count INTEGER NOT NULL DEFAULT 0,
  source_kinds JSONB NOT NULL DEFAULT '[]'::jsonb,  -- independent sources (incident, code ...)
  facts JSONB NOT NULL DEFAULT '{}'::jsonb,  -- the detector's numbers, for the drawer
  value NUMERIC(6, 2) NOT NULL DEFAULT 0,
  evidence_strength NUMERIC(5, 3) NOT NULL DEFAULT 0,
  freshness NUMERIC(5, 3) NOT NULL DEFAULT 1,
  effort_units INTEGER NOT NULL DEFAULT 1,
  risk NUMERIC(5, 3) NOT NULL DEFAULT 1,
  detector_weight NUMERIC(5, 3) NOT NULL DEFAULT 1,
  priority_score NUMERIC(7, 2) NOT NULL DEFAULT 0,  -- work_value_scoring.compute_priority_score
  estimated_cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  score NUMERIC(14, 3) NOT NULL DEFAULT 0,   -- value density (rank_by_value_density)
  evidence_at TIMESTAMPTZ,                   -- the newest evidence (freshness decays from it)
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'snoozed', 'accepted', 'rejected', 'resolved_by_change')),
  snoozed_until TIMESTAMPTZ,
  proposal_act_id TEXT,                      -- the ledger row: agent proposed this
  decision_act_id TEXT,                      -- the ledger row: a person accepted/rejected/snoozed
  decided_by TEXT,
  decided_at TIMESTAMPTZ,
  reject_reason TEXT,
  reject_category TEXT,
  accepted_as TEXT CHECK (accepted_as IS NULL OR accepted_as IN ('ticket', 'epic', 'prd')),
  artifact JSONB NOT NULL DEFAULT '{}'::jsonb,   -- {work_item_id?, plane_issue?, meeting_run_id?}
  evidence_count_at_decision INTEGER,
  resurfaced_from TEXT,                      -- the rejected recommendation this one re-opens
  recurred_at TIMESTAMPTZ,                   -- the problem came back after it was accepted
  last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(),  -- the last run that still found it
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_ambient_recommendations_rank
  ON ambient_recommendations (project_id, status, score DESC);
CREATE INDEX IF NOT EXISTS idx_ambient_recommendations_fp
  ON ambient_recommendations (project_id, fingerprint, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_ambient_recommendations_detector
  ON ambient_recommendations (project_id, detector, status);

-- ============================================================================================
-- PROJECT EXPERIENCE (BOSSAPP-913 / 914; docs/product/PROJECT_EXPERIENCE_CONTRACT.md §7, §8).
-- code: engine/boss_engine/services/project_experience/{captain,onboarding}.py
-- ============================================================================================
-- THE PROJECT'S CAPTAIN: the agent that takes a project over once it is created (default the
-- project's engineering_captain, "Helm"); Marshal (chief_of_staff) stays cross-project.
CREATE TABLE IF NOT EXISTS project_captains (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  role_key TEXT NOT NULL,
  assigned_by TEXT NOT NULL DEFAULT 'boss',
  assigned_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- ONE ONBOARDING RUN of a project: the onboarding agent's checklist, each item's state and why,
-- the live discover nodes, the proposed backlog and the first work it suggests. Written stage by
-- stage by the `project.onboarding` job, so the console can draw it while it runs.
CREATE TABLE IF NOT EXISTS project_onboarding_runs (
  id TEXT PRIMARY KEY,                               -- 'onb_' + hex
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  state TEXT NOT NULL DEFAULT 'running'
    CHECK (state IN ('running', 'ready', 'needs_you', 'failed')),
  trigger TEXT NOT NULL DEFAULT 'manual',            -- created | manual | repo_added
  started_by TEXT NOT NULL DEFAULT 'boss',
  job_id TEXT,
  checklist JSONB NOT NULL DEFAULT '{}'::jsonb,      -- key -> {state, owner, detail, sub, action}
  discover JSONB NOT NULL DEFAULT '[]'::jsonb,       -- [{label, state, sub}]
  facts JSONB NOT NULL DEFAULT '{}'::jsonb,          -- {repo, commands, demo_users, secrets, ...}
  backlog JSONB NOT NULL DEFAULT '[]'::jsonb,        -- proposed, ranked
  first_work JSONB,
  error TEXT,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_project_onboarding_runs_project
  ON project_onboarding_runs (project_id, started_at DESC);
-- The Project page's Work tab reads a project's builds by their workflow run and its own
-- builds newest first; both were sequential scans of code_task_runs (39 ms + 28 ms on the
-- laptop's 23-run project).
CREATE INDEX IF NOT EXISTS idx_code_task_runs_workflow_run
  ON code_task_runs ((finalize_ctx->>'workflow_run_id'));
CREATE INDEX IF NOT EXISTS idx_code_task_runs_project_created
  ON code_task_runs (project_id, created_at DESC);

-- FOLDER ON HOST (Add a project, screen 03): a project's source can be a folder on one of the
-- organisation's verified servers. BOSS only READS it (project_experience/host_folder.py: one
-- ssh session of read-only commands); the row records which server, which path and what the
-- read found (git remote without credentials, branch, file count, stack).
CREATE TABLE IF NOT EXISTS project_host_folders (
  id BIGSERIAL PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  host_id TEXT NOT NULL,
  path TEXT NOT NULL,
  facts JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, host_id, path)
);

-- AN ANSWER'S CARDS (screen 09, services/turn_cards.py): the typed "New work" offer a turn made
-- (title, text, estimate, plan strip, Start / Edit / Not now and what was chosen) and the
-- records its reply named (PR / run / file / doc chips). Stored per message, like
-- `proposed_actions`, so a reopened thread shows them.
ALTER TABLE agent_messages ADD COLUMN IF NOT EXISTS proposal JSONB;
ALTER TABLE agent_messages ADD COLUMN IF NOT EXISTS citations JSONB NOT NULL DEFAULT '[]'::jsonb;

-- ADD A PROJECT v2 (new-project-v2 wireframes; services/project_experience/add_project.py):
-- what the person confirmed on the one screen, kept as the project's SEED. `brief` is Helm's
-- rewrite as confirmed (title, problem, who uses it, must-haves, out of scope, done when, open
-- questions with the answers picked); `picks` the six boxes (captain, stack, connectors,
-- workflow, code, staging), the Tell choice and a repository's note to Helm. The PRD meeting
-- reads the brief as the start's directive; onboarding shows the note and hands it to Marshal.
CREATE TABLE IF NOT EXISTS project_seeds (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL DEFAULT 'idea' CHECK (kind IN ('idea', 'repo', 'folder', 'sample')),
  words TEXT NOT NULL DEFAULT '',
  brief JSONB NOT NULL DEFAULT '{}'::jsonb,
  picks JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- WHERE PEOPLE DECIDE (Govern; services/decide_list.py, the ONE source of the compliance list).
-- `decide_rules` is each list entry's rule as a card or "change a rule in plain words" saved it,
-- for the install (scope 'install') or one project (scope = the project id). A rule only ever
-- makes an entry stricter than the backstop in code (decide_list.validate). Every change is
-- kept in `decide_rule_changes`, with who made it, how (card | words) and the words they typed.
CREATE TABLE IF NOT EXISTS decide_rules (
  scope TEXT NOT NULL,
  kind TEXT NOT NULL,
  rule JSONB NOT NULL DEFAULT '{}'::jsonb,
  updated_by TEXT NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (scope, kind)
);
CREATE TABLE IF NOT EXISTS decide_rule_changes (
  id TEXT PRIMARY KEY,
  scope TEXT NOT NULL,
  kind TEXT NOT NULL,
  before JSONB,
  after JSONB NOT NULL,
  actor TEXT NOT NULL,
  via TEXT NOT NULL DEFAULT 'card' CHECK (via IN ('card', 'words')),
  words TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_decide_rule_changes_kind ON decide_rule_changes (kind, created_at DESC);

-- WATCH THIS APP (agentic-factory 2-watch-an-app.html, Project › Health): one row per app the
-- SRE agent was asked to watch. The watches themselves are the app's alert rules
-- (app_alert_rules), the channels its contact points and the routing its notification
-- policies; this row only remembers what the person asked for and the outside channel that
-- waits for its code, so the Health page can draw the landing.
CREATE TABLE IF NOT EXISTS app_watches (
  target_id TEXT PRIMARY KEY REFERENCES deployment_targets(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  words TEXT NOT NULL DEFAULT '',
  night TEXT NOT NULL DEFAULT 'wake' CHECK (night IN ('wake', 'wait', 'alone')),
  alone BOOLEAN NOT NULL DEFAULT true,
  tell_cp_id TEXT,
  plan JSONB NOT NULL DEFAULT '{}'::jsonb,
  started_by TEXT NOT NULL,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_app_watches_project ON app_watches (project_id);

-- LOCAL-FIRST PROJECTS (BOSSAPP-915, services/local_repo.py, services/local_repo_host.py).
-- A repository binding says which host holds the code: github (the default, every existing row),
-- or local — a bare git repository BOSS keeps on this machine, named local_<project_id>/<name>.
-- A local binding has NO connection (there is nothing to authenticate to), so it never shows up
-- as a GitHub account, and every GitHub-only reader (which joins its connection) skips it.
ALTER TABLE github_repository_bindings ADD COLUMN IF NOT EXISTS host TEXT NOT NULL DEFAULT 'github';
ALTER TABLE github_repository_bindings ALTER COLUMN connection_id DROP NOT NULL;
ALTER TABLE github_repository_bindings DROP CONSTRAINT IF EXISTS github_repository_bindings_host_check;
ALTER TABLE github_repository_bindings ADD CONSTRAINT github_repository_bindings_host_check
  CHECK (host IN ('github', 'local') AND (host = 'local' OR connection_id IS NOT NULL));

-- A LOCAL CHANGE SET is a local repository's pull request: a branch, its diff against the base,
-- the review panel's comments, the sandbox checks, and a person's Merge into the default branch.
-- The pipeline opens one through the same create_pull_request call it uses for GitHub; its URL
-- is http://boss-local/<owner>/<repo>/pull/<number>, which every PR-URL reader parses as usual.
-- `pending_push` (BOSSAPP-922): a GitHub project's change made while GitHub was down, held in
-- the repository's local mirror until the push-pending job pushes it and opens the real PR.
CREATE TABLE IF NOT EXISTS local_change_sets (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  repository TEXT NOT NULL,
  number INT NOT NULL,
  branch TEXT NOT NULL,
  base_branch TEXT NOT NULL,
  title TEXT NOT NULL DEFAULT '',
  body TEXT NOT NULL DEFAULT '',
  state TEXT NOT NULL DEFAULT 'open',
  draft BOOLEAN NOT NULL DEFAULT false,
  labels JSONB NOT NULL DEFAULT '[]'::jsonb,
  head_sha TEXT,
  base_sha TEXT,
  merged_sha TEXT,
  merged_by TEXT,
  merged_at TIMESTAMPTZ,
  run_id TEXT,
  pending_push BOOLEAN NOT NULL DEFAULT false,
  github_pr_url TEXT,
  github_pr_number INT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (repository, number),
  CHECK (state IN ('open', 'merged', 'closed', 'published'))
);
CREATE INDEX IF NOT EXISTS idx_local_change_sets_project ON local_change_sets (project_id, state, updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_local_change_sets_branch ON local_change_sets (repository, branch, state);
CREATE TABLE IF NOT EXISTS local_change_set_notes (
  id TEXT PRIMARY KEY,
  change_set_id TEXT NOT NULL REFERENCES local_change_sets(id) ON DELETE CASCADE,
  number INT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'comment',
  event TEXT,
  body TEXT NOT NULL DEFAULT '',
  comments JSONB NOT NULL DEFAULT '[]'::jsonb,
  in_reply_to INT,
  author TEXT NOT NULL DEFAULT 'boss',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind IN ('review', 'comment', 'reply'))
);
CREATE SEQUENCE IF NOT EXISTS local_change_set_note_ids;
CREATE INDEX IF NOT EXISTS idx_local_change_set_notes_cs ON local_change_set_notes (change_set_id, created_at);

-- LOCAL REVIEW COMMENTS (BOSSAPP-948, services/local_review.py): ONE store for the line comments
-- on a local change set, whoever writes them — the console's diff and Code tab, `boss review`,
-- git notes (refs/notes/boss-review) and MCP add_review_comment. Anchored to (commit, path,
-- side, line); `outdated` once the head moved and that line changed (the thread stays visible).
-- A thread is its root (reply_to NULL) and its replies; the root's state is the thread's:
-- open → addressed|disputed (the agent's reply) → resolved (a person) — reopen goes back to open.
-- A person's open thread holds Merge. `github_comment_id` keeps Publish idempotent.
CREATE TABLE IF NOT EXISTS local_change_set_comments (
  id BIGSERIAL PRIMARY KEY,
  change_set_id TEXT NOT NULL REFERENCES local_change_sets(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  path TEXT,
  line INT,
  end_line INT,
  side TEXT NOT NULL DEFAULT 'new',
  commit_sha TEXT,
  author TEXT NOT NULL,
  author_kind TEXT NOT NULL DEFAULT 'human',
  severity TEXT NOT NULL DEFAULT 'major',
  body TEXT NOT NULL,
  state TEXT NOT NULL DEFAULT 'open',
  reply_to BIGINT REFERENCES local_change_set_comments(id) ON DELETE CASCADE,
  origin TEXT NOT NULL DEFAULT 'console',
  outdated BOOLEAN NOT NULL DEFAULT false,
  original_line INT,
  line_text TEXT,
  run_round TEXT,
  response_commit TEXT,
  github_comment_id BIGINT,
  resolved_by TEXT,
  resolved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (side IN ('new', 'old')),
  CHECK (author_kind IN ('human', 'agent')),
  CHECK (severity IN ('blocker', 'major', 'minor', 'nit')),
  CHECK (state IN ('open', 'addressed', 'disputed', 'resolved')),
  CHECK (origin IN ('console', 'cli', 'git_notes', 'mcp', 'agent'))
);
CREATE INDEX IF NOT EXISTS idx_local_cs_comments_cs ON local_change_set_comments (change_set_id, created_at);
CREATE INDEX IF NOT EXISTS idx_local_cs_comments_reply ON local_change_set_comments (reply_to);
-- Where `boss clone` put a working copy of a local repository (the page lists it).
CREATE TABLE IF NOT EXISTS local_working_copies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  repository TEXT NOT NULL,
  path TEXT NOT NULL,
  branch TEXT,
  machine TEXT NOT NULL DEFAULT '',
  recorded_by TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, repository, machine, path)
);
-- A change set opened by a push names who pushed it (`pushed` label; author = the pusher).
ALTER TABLE local_change_sets ADD COLUMN IF NOT EXISTS author TEXT;

-- PUSH PENDING (BOSSAPP-922): a GitHub project's branch whose commits landed in the local mirror
-- while GitHub was down. The worker's push-pending job pushes it and opens the pull request when
-- GitHub answers again, with backoff; the build waits "waiting for GitHub", never failed.
CREATE TABLE IF NOT EXISTS repo_push_pending (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  owner TEXT NOT NULL,
  repo TEXT NOT NULL,
  branch TEXT NOT NULL,
  base_branch TEXT NOT NULL DEFAULT 'main',
  run_id TEXT,
  change_set_id TEXT,
  status TEXT NOT NULL DEFAULT 'waiting',
  attempts INT NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_error TEXT,
  reason TEXT NOT NULL DEFAULT '',
  pull_request_url TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (status IN ('waiting', 'pushing', 'done', 'failed'))
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_repo_push_pending_open
  ON repo_push_pending (owner, repo, branch) WHERE status IN ('waiting', 'pushing');
CREATE INDEX IF NOT EXISTS idx_repo_push_pending_due ON repo_push_pending (status, next_attempt_at);

-- CHANGE REVIEW (BOSSAPP-954): one git-style review page for a local change set and a GitHub pull
-- request (services/change_review.py). GitHub reads are cached briefly and shown stale when GitHub
-- does not answer; comments written then are queued; "Viewed" and "Since my review" are per person;
-- the PR agent's chat is kept per change.
CREATE TABLE IF NOT EXISTS change_review_cache (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  cache_key TEXT NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  fetched_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, cache_key)
);
CREATE TABLE IF NOT EXISTS change_review_outbox (
  id BIGSERIAL PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  change_key TEXT NOT NULL,
  repository TEXT NOT NULL,
  number INT NOT NULL,
  kind TEXT NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  author TEXT NOT NULL,
  person TEXT,
  status TEXT NOT NULL DEFAULT 'queued',
  attempts INT NOT NULL DEFAULT 0,
  last_error TEXT,
  posted_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (kind IN ('comment', 'reply', 'resolve', 'reopen')),
  CHECK (status IN ('queued', 'posted', 'failed'))
);
CREATE INDEX IF NOT EXISTS idx_change_review_outbox_change ON change_review_outbox (project_id, change_key, status);
CREATE TABLE IF NOT EXISTS change_review_viewed (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  change_key TEXT NOT NULL,
  person TEXT NOT NULL,
  path TEXT NOT NULL,
  sha TEXT NOT NULL DEFAULT '',
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (project_id, change_key, person, path)
);
CREATE TABLE IF NOT EXISTS change_review_chat (
  id BIGSERIAL PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  change_key TEXT NOT NULL,
  author TEXT NOT NULL,
  author_kind TEXT NOT NULL DEFAULT 'human',
  body TEXT NOT NULL,
  delivery TEXT NOT NULL DEFAULT 'queued',
  run_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (author_kind IN ('human', 'agent')),
  CHECK (delivery IN ('steered', 'queued', 'sent'))
);
CREATE INDEX IF NOT EXISTS idx_change_review_chat_change ON change_review_chat (project_id, change_key, id);

-- TOOL CALL AUDIT (BOSSAPP-819): one append-only row per receipt-path call.
-- Update and delete raise. The export route and the Activity tab are a later slice.
CREATE TABLE IF NOT EXISTS tool_call_audit (
  id TEXT PRIMARY KEY,
  project_id TEXT,
  run_id TEXT,
  agent TEXT,
  principal TEXT,
  server_id TEXT,
  tool TEXT NOT NULL,
  args_sha256 TEXT,
  args_redacted JSONB NOT NULL DEFAULT '{}'::jsonb,
  decision TEXT NOT NULL,
  matched_policy_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  decision_id TEXT,
  outcome TEXT NOT NULL,
  latency_ms INT NOT NULL DEFAULT 0,
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION tool_call_audit_append_only()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  RAISE EXCEPTION 'tool_call_audit is append-only';
END;
$$;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger WHERE tgname = 'tool_call_audit_no_update'
  ) THEN
    CREATE TRIGGER tool_call_audit_no_update
      BEFORE UPDATE OR DELETE ON tool_call_audit
      FOR EACH ROW
      EXECUTE FUNCTION tool_call_audit_append_only();
  END IF;
END;
$$;

-- ALWAYS-ALLOW (BOSSAPP-817): a revocable always-allow row for one tool.
CREATE TABLE IF NOT EXISTS tool_policies (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL,
  server_id TEXT,
  tool TEXT NOT NULL,
  schema_sha256 TEXT,
  source_decision_id TEXT,
  status TEXT NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  CHECK (status IN ('active', 'revoked'))
);

-- ============================ RUN LEDGER (BOSSAPP-961, K0) ==================================
-- docs/architecture/HARNESS_KERNEL_DESIGN.md §3. The ledger is ONE VIEW over llm_calls (model
-- calls), tool_call_audit (tool calls) and run_events (everything else a run does: findings,
-- verification, decisions, escalations, compaction, workspace snapshots, budget waits,
-- outcomes, native-loop turns). Written only while BOSS_LEDGER_EVENTS is on; read through
-- boss_engine/kernel/ledger_read.py, never by a tool's own SQL.
--
-- SEQ COMES FROM ONE SEQUENCE. A partitioned table cannot hold UNIQUE (run_id, seq) without the
-- partition key, and a per-run counter row would make every writer of a run wait behind the
-- longest open transaction of that run (an agent run's tick is one transaction). nextval never
-- waits and never rolls back, so seq is unique everywhere and increases within every run.
CREATE SEQUENCE IF NOT EXISTS run_ledger_seq;

-- Append-only, range-partitioned by month on recorded_at: retention (30 days of content, 400 of
-- metadata, design D6) drops whole partitions and never deletes a row.
CREATE TABLE IF NOT EXISTS run_events (
  id TEXT NOT NULL,                          -- 'evt_' + a time-ordered id
  project_id TEXT NOT NULL,
  run_id TEXT NOT NULL,                      -- agent_runs.id, code_task_runs.id or a kernel run
  act_id TEXT,                               -- agent_acts span
  root_act_id TEXT,                          -- denormalised for whole-build queries
  seq BIGINT NOT NULL,                       -- from run_ledger_seq: increasing within the run
  step INT NOT NULL DEFAULT 0,
  stage TEXT,                                -- build stage node; NULL for chat
  kind TEXT NOT NULL,                        -- kernel EventKind (kernel/types.py)
  data JSONB NOT NULL DEFAULT '{}'::jsonb,   -- redacted, at most 8 KB, shape per kind (ledger.py)
  content_ref TEXT,                          -- agent_turns.id or an artifact path for big bodies
  input_tokens BIGINT NOT NULL DEFAULT 0,
  output_tokens BIGINT NOT NULL DEFAULT 0,
  cache_read_tokens BIGINT NOT NULL DEFAULT 0,
  cache_write_tokens BIGINT NOT NULL DEFAULT 0,
  cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  included_in_subscription BOOLEAN NOT NULL DEFAULT false,
  latency_ms INT NOT NULL DEFAULT 0,
  engine TEXT,
  model TEXT,
  scaffold_level TEXT,
  policy JSONB NOT NULL DEFAULT '{}'::jsonb, -- the policy versions that produced the event
  workspace_ref TEXT,                        -- git tree or commit sha after this step
  attempt INT NOT NULL DEFAULT 1,            -- position in the retry lineage
  lineage_id TEXT,                           -- the first run of the retry chain
  recorded_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (id, recorded_at)
) PARTITION BY RANGE (recorded_at);
CREATE INDEX IF NOT EXISTS idx_run_events_run ON run_events (run_id, seq);
CREATE INDEX IF NOT EXISTS idx_run_events_root ON run_events (root_act_id, recorded_at);
CREATE INDEX IF NOT EXISTS idx_run_events_lineage ON run_events (lineage_id, kind, recorded_at);
CREATE INDEX IF NOT EXISTS idx_run_events_kind ON run_events (project_id, kind, recorded_at DESC);
CREATE INDEX IF NOT EXISTS idx_run_events_policy ON run_events USING GIN (policy jsonb_path_ops);

-- A row outside every month partition lands here rather than failing its write.
CREATE TABLE IF NOT EXISTS run_events_default PARTITION OF run_events DEFAULT;

-- This month and the next N, made at every boot. A month whose rows already sit in the default
-- partition cannot be split out of it: it stays there, said in a notice, never a failed boot.
CREATE OR REPLACE FUNCTION run_events_ensure_partitions(months_ahead INT) RETURNS INT
LANGUAGE plpgsql AS $parts$
DECLARE
  first_day DATE;
  part TEXT;
  made INT := 0;
BEGIN
  FOR i IN 0..GREATEST(months_ahead, 0) LOOP
    first_day := (date_trunc('month', now()) + make_interval(months => i))::date;
    part := 'run_events_' || to_char(first_day, 'YYYY_MM');
    IF to_regclass(part) IS NULL THEN
      BEGIN
        EXECUTE format('CREATE TABLE %I PARTITION OF run_events FOR VALUES FROM (%L) TO (%L)',
                       part, first_day, (first_day + interval '1 month')::date);
        made := made + 1;
      EXCEPTION WHEN others THEN
        RAISE NOTICE 'run_events partition % not made: %', part, SQLERRM;
      END;
    END IF;
  END LOOP;
  RETURN made;
END $parts$;
SELECT run_events_ensure_partitions(2);

-- Never changed, never deleted row by row: a purge (a test cleaning up, retention of the default
-- partition) says so with SET LOCAL boss.ledger_purge = 'on'. Its own function, not
-- boss_append_only_ledger: that one reads OLD.outcome, a column only agent_act_decisions has.
-- On the partitioned table, so every partition carries it.
CREATE OR REPLACE FUNCTION boss_ledger_rows_are_final() RETURNS trigger
LANGUAGE plpgsql AS $final$
BEGIN
  IF TG_OP = 'DELETE' AND COALESCE(current_setting('boss.ledger_purge', true), '') = 'on' THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION '% is append-only: write a new row instead of changing or deleting one',
    TG_TABLE_NAME;
END $final$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'run_events_append_only'
                 AND tgrelid = 'run_events'::regclass) THEN
    CREATE TRIGGER run_events_append_only BEFORE UPDATE OR DELETE ON run_events
      FOR EACH ROW EXECUTE FUNCTION boss_ledger_rows_are_final();
  END IF;
END $$;

-- Model-call and tool-call rows join the ledger by run, sequence and lineage.
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS run_id TEXT;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS seq BIGINT;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS lineage_id TEXT;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS policy JSONB;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS scaffold_level TEXT;
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS workspace_ref TEXT;
CREATE INDEX IF NOT EXISTS idx_llm_calls_ledger ON llm_calls (run_id, seq) WHERE run_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_llm_calls_lineage ON llm_calls (lineage_id, created_at)
  WHERE lineage_id IS NOT NULL;
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS act_id TEXT;
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS seq BIGINT;
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS lineage_id TEXT;
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS idempotency_key TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS uq_tool_call_idem ON tool_call_audit (idempotency_key)
  WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_tool_call_audit_ledger ON tool_call_audit (run_id, seq)
  WHERE seq IS NOT NULL;

-- llm_calls IS INSERT-ONLY EXCEPT ITS FILL-ONCE COLUMNS. agent_acts back-fills act_id on rebuilt
-- stages (_backfill_build) and the BOSS-280 backfill above fills role: a NULL may be filled, a
-- value is never changed, nothing else is ever rewritten. Deletes (retention, a project going
-- away) are not this trigger's business. A test seeding history says so with
-- SET LOCAL boss.ledger_purge = 'on'.
CREATE OR REPLACE FUNCTION llm_calls_fill_once() RETURNS trigger LANGUAGE plpgsql AS $fill$
BEGIN
  IF COALESCE(current_setting('boss.ledger_purge', true), '') = 'on' THEN
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW) - 'act_id' - 'run_id' - 'seq' - 'lineage_id' - 'role' - 'policy'
        - 'scaffold_level' - 'workspace_ref')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'act_id' - 'run_id' - 'seq' - 'lineage_id' - 'role' - 'policy'
        - 'scaffold_level' - 'workspace_ref') THEN
    RAISE EXCEPTION 'llm_calls is append-only: write a new row instead of changing one';
  END IF;
  IF (OLD.act_id IS NOT NULL AND NEW.act_id IS DISTINCT FROM OLD.act_id)
     OR (OLD.run_id IS NOT NULL AND NEW.run_id IS DISTINCT FROM OLD.run_id)
     OR (OLD.seq IS NOT NULL AND NEW.seq IS DISTINCT FROM OLD.seq)
     OR (OLD.lineage_id IS NOT NULL AND NEW.lineage_id IS DISTINCT FROM OLD.lineage_id)
     OR (OLD.role IS NOT NULL AND NEW.role IS DISTINCT FROM OLD.role)
     OR (OLD.policy IS NOT NULL AND NEW.policy IS DISTINCT FROM OLD.policy)
     OR (OLD.scaffold_level IS NOT NULL AND NEW.scaffold_level IS DISTINCT FROM OLD.scaffold_level)
     OR (OLD.workspace_ref IS NOT NULL AND NEW.workspace_ref IS DISTINCT FROM OLD.workspace_ref)
  THEN
    RAISE EXCEPTION 'llm_calls is append-only: a filled ledger column is never changed';
  END IF;
  RETURN NEW;
END $fill$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'llm_calls_fill_once'
                 AND tgrelid = 'llm_calls'::regclass) THEN
    CREATE TRIGGER llm_calls_fill_once BEFORE UPDATE ON llm_calls
      FOR EACH ROW EXECUTE FUNCTION llm_calls_fill_once();
  END IF;
END $$;

-- What "stop@1" or "prompt:implement@sha256:…" meant when an event named it. Immutable.
CREATE TABLE IF NOT EXISTS policy_versions (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  body JSONB NOT NULL,
  source TEXT NOT NULL,                      -- the defining module, or a file path + git sha
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'policy_versions_append_only'
                 AND tgrelid = 'policy_versions'::regclass) THEN
    CREATE TRIGGER policy_versions_append_only BEFORE UPDATE OR DELETE ON policy_versions
      FOR EACH ROW EXECUTE FUNCTION boss_ledger_rows_are_final();
  END IF;
END $$;

-- THE ONE READ SURFACE. Model and tool calls join once they carry a ledger run (written while
-- BOSS_LEDGER_EVENTS is on); every run event is in it.
CREATE OR REPLACE VIEW run_ledger AS
  SELECT 'model'::text AS src, c.id, c.project_id, c.run_id, c.act_id, c.seq, 0 AS step,
         c.stage, CASE WHEN c.ok THEN 'model.response' ELSE 'model.error' END AS kind,
         jsonb_build_object('turns', c.turns, 'retries', c.retries, 'ok', c.ok,
                            'error', c.error, 'role', c.role) AS data,
         NULL::text AS content_ref,
         c.prompt_tokens::bigint AS input_tokens, c.completion_tokens::bigint AS output_tokens,
         c.cache_read_tokens::bigint AS cache_read_tokens,
         c.cache_write_tokens::bigint AS cache_write_tokens,
         c.cost_usd_micros::bigint AS cost_usd_micros,
         c.included_in_subscription, c.latency_ms, c.engine, c.model, c.scaffold_level,
         COALESCE(c.policy, '{}'::jsonb) AS policy, c.workspace_ref, c.lineage_id,
         c.created_at AS recorded_at
    FROM llm_calls c WHERE c.run_id IS NOT NULL
  UNION ALL
  SELECT 'tool'::text, t.id, t.project_id, t.run_id, t.act_id, t.seq, 0, NULL::text,
         'tool.result'::text,
         jsonb_build_object('tool', t.tool, 'args_sha256', t.args_sha256,
                            'args', t.args_redacted, 'decision', t.decision,
                            'outcome', t.outcome, 'decision_id', t.decision_id,
                            'server_id', t.server_id),
         NULL::text, 0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint, false, t.latency_ms,
         NULL::text, NULL::text, NULL::text, '{}'::jsonb, NULL::text, t.lineage_id,
         t.recorded_at
    FROM tool_call_audit t WHERE t.seq IS NOT NULL AND t.run_id IS NOT NULL
  UNION ALL
  SELECT 'event'::text, e.id, e.project_id, e.run_id, e.act_id, e.seq, e.step, e.stage, e.kind,
         e.data, e.content_ref, e.input_tokens, e.output_tokens, e.cache_read_tokens,
         e.cache_write_tokens, e.cost_usd_micros, e.included_in_subscription, e.latency_ms,
         e.engine, e.model, e.scaffold_level, e.policy, e.workspace_ref, e.lineage_id,
         e.recorded_at
    FROM run_events e;
-- ============================ end RUN LEDGER ================================================
-- THE HARNESS BENCHMARK (BOSSAPP-959; engine/boss_engine/harness_bench, scripts/harness-bench,
-- docs/architecture/HARNESS_BENCHMARK.md). One row per benchmark run: the suite it ran (pinned by
-- sha256), the engine and scaffold level, the BOSS commit and the harness settings it ran under
-- (config + its fingerprint), and its verdict against the baseline it was compared with. Rows are
-- written by the benchmark on a boss_test* database only; the runner refuses any other.
CREATE TABLE IF NOT EXISTS harness_bench_runs (
  id TEXT PRIMARY KEY,
  suite_name TEXT NOT NULL,
  suite_version TEXT NOT NULL,
  suite_sha256 TEXT NOT NULL,
  engine TEXT NOT NULL,                       -- scripted | claude_code | codex | native:<model>
  model TEXT,
  level TEXT NOT NULL DEFAULT 'delegate',     -- delegate (the governed pipeline) | bare (the engine's own loop)
  boss_sha TEXT,
  boss_dirty BOOLEAN NOT NULL DEFAULT false,  -- the checkout had uncommitted changes
  config JSONB NOT NULL DEFAULT '{}'::jsonb,  -- repair retries, review rounds, profile, routing ...
  config_fingerprint TEXT NOT NULL,
  rules JSONB NOT NULL DEFAULT '{}'::jsonb,   -- the noise and guard rules it was judged by
  task_ids JSONB NOT NULL DEFAULT '[]'::jsonb,
  repeat INTEGER NOT NULL DEFAULT 1,
  budget_usd_micros BIGINT,
  status TEXT NOT NULL DEFAULT 'running',     -- running | completed | incomplete | failed
  baseline_name TEXT,                         -- saved as a named baseline (--save-baseline)
  compared_to TEXT,                           -- the baseline it was compared with (--baseline)
  verdict TEXT,                               -- better | same | worse | not_comparable
  comparison JSONB NOT NULL DEFAULT '{}'::jsonb,
  summary JSONB NOT NULL DEFAULT '{}'::jsonb,
  report_path TEXT,
  project_id TEXT,                            -- the throwaway project its builds ran in
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_harness_bench_runs_engine
  ON harness_bench_runs (engine, level, started_at DESC);
CREATE INDEX IF NOT EXISTS idx_harness_bench_runs_baseline
  ON harness_bench_runs (baseline_name, started_at DESC) WHERE baseline_name IS NOT NULL;

-- One row per task run of a benchmark run: the code task it started, whether it succeeded (every
-- component in `components`), and what it cost, read from llm_calls / agent_turns / quality_gates
-- / events / decisions — never from the agent's own account. `detail` is the full result.
CREATE TABLE IF NOT EXISTS harness_bench_results (
  id TEXT PRIMARY KEY,
  bench_run_id TEXT NOT NULL REFERENCES harness_bench_runs(id) ON DELETE CASCADE,
  task_id TEXT NOT NULL,
  task_kind TEXT,                             -- fix | feature | new_app
  iteration INTEGER NOT NULL DEFAULT 1,
  code_task_run_id TEXT,
  success BOOLEAN NOT NULL DEFAULT false,
  skipped BOOLEAN NOT NULL DEFAULT false,     -- not run: the budget was spent
  status TEXT,                                -- the code task's end status
  wall_ms BIGINT NOT NULL DEFAULT 0,
  tokens_in BIGINT NOT NULL DEFAULT 0,
  tokens_out BIGINT NOT NULL DEFAULT 0,
  cache_read_tokens BIGINT NOT NULL DEFAULT 0,
  cache_write_tokens BIGINT NOT NULL DEFAULT 0,
  cost_usd_micros BIGINT NOT NULL DEFAULT 0,
  model_calls INTEGER NOT NULL DEFAULT 0,
  turns INTEGER NOT NULL DEFAULT 0,
  tool_calls INTEGER NOT NULL DEFAULT 0,
  repair_rounds INTEGER NOT NULL DEFAULT 0,
  interventions INTEGER NOT NULL DEFAULT 0,
  components JSONB NOT NULL DEFAULT '{}'::jsonb,
  gates JSONB NOT NULL DEFAULT '{}'::jsonb,
  acceptance JSONB NOT NULL DEFAULT '{}'::jsonb,
  detail JSONB NOT NULL DEFAULT '{}'::jsonb,
  error TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_harness_bench_results_run
  ON harness_bench_results (bench_run_id, iteration, task_id);

-- ── BOSSAPP-999: every model call carries its CLASS ───────────────────────────────────────────
-- call_class is stamped at the recording seam (services/llm_telemetry.record_llm_call) from the
-- stage the call's boundary named, via the total mapping in services/call_classes.py:
-- build_stage | chat | panel | decision | proof | kg | bench | gateway | other. New rows are
-- never NULL ('other' is the mapping's floor); rows that predate this column stay NULL and read
-- as unclassified history. Per-project governance (the `call_classes` project setting) denies a
-- class or caps it by calls/tokens per day, counted over this column.
ALTER TABLE llm_calls ADD COLUMN IF NOT EXISTS call_class TEXT;
CREATE INDEX IF NOT EXISTS idx_llm_calls_class ON llm_calls (project_id, call_class, created_at DESC);

-- ── BOSSAPP-822: the prompt-injection screen's verdict on every delivered tool result ─────────
-- services/tool_result_screen.py screens each result call_tool_with_receipt hands back
-- (BOSS_TOOL_RESULT_SCREEN / project knob tool_result_screen: off | patterns | model). The
-- verdict lands here: {"mode", "verdict": clean|suspicious|unscreened, "rules": [...]}. NULL on
-- a refused call (no result) and on rows that predate the column.
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS screen JSONB;

-- ===========================================================================
-- EXECUTION ENVIRONMENTS (BOSSAPP-824 phase 1): pluggable remote execution.
-- Where a governed build's sandbox runs. A row names a place (a driver plus its
-- config) a build can run: the control-plane box itself ('local'), a machine
-- reached over SSH ('ssh', config.host_id names the deployment_hosts row whose
-- key and pinned host key are reused), the existing micro-VM lane ('microvm'),
-- or a phase-2 driver ('kubernetes', 'e2b', 'daytona' — recognized, refused in
-- words until their drivers land). project_id NULL means org-wide: the row is
-- an instance-level environment every project may resolve to.
-- Secrets NEVER live here: secret_refs holds secret_refs.id references only
-- (kubeconfig/service_account kinds already exist in secrets_service).
-- Resolution precedence (services/sandbox_provider.make_governed_sandbox_provider):
-- explicit spec override -> agent-bound row (config.agents) -> project default
-- (config.default) -> instance default (project_id IS NULL, config.default)
-- -> the BOSS_GOVERNED_SANDBOX_PROVIDER knob. With nothing configured the
-- factory returns the LocalSubprocessProvider exactly as before.
CREATE TABLE IF NOT EXISTS execution_environments (
  id          TEXT PRIMARY KEY,
  project_id  TEXT REFERENCES projects(id) ON DELETE CASCADE,  -- NULL: org-wide
  name        TEXT NOT NULL,
  driver      TEXT NOT NULL
    CHECK (driver IN ('local', 'ssh', 'kubernetes', 'microvm', 'e2b', 'daytona')),
  config      JSONB NOT NULL DEFAULT '{}'::jsonb,
  secret_refs JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- registered: known, not yet probed | verified: probe passed | degraded: last
  -- probe failed | retired: never resolve here again
  status      TEXT NOT NULL DEFAULT 'registered',
  created_by  TEXT,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
-- UNIQUE(project_id, name) would not dedupe org-wide rows (NULLs are distinct),
-- so each scope pins its own partial index.
CREATE UNIQUE INDEX IF NOT EXISTS uq_execution_environments_project_name
  ON execution_environments (project_id, name) WHERE project_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_execution_environments_org_name
  ON execution_environments (name) WHERE project_id IS NULL;
CREATE INDEX IF NOT EXISTS idx_execution_environments_project
  ON execution_environments (project_id, status, created_at DESC);

-- One build's hold on an environment (the shape preview_sandboxes proved: a
-- durable reservation with a TTL and one reaper). acquire() writes a row,
-- teardown releases it, and the resource reaper expires leases whose holder
-- never came back (services/execution_environments.reap_leases, registered on
-- resource_reaper.tick).
CREATE TABLE IF NOT EXISTS environment_leases (
  id             TEXT PRIMARY KEY,
  environment_id TEXT NOT NULL REFERENCES execution_environments(id) ON DELETE CASCADE,
  -- driver+image+cpu/mem of what was asked for — lets a later phase pool and
  -- re-hand matching sandboxes instead of provisioning again.
  fingerprint    TEXT NOT NULL DEFAULT '',
  state          TEXT NOT NULL DEFAULT 'held'
    CHECK (state IN ('held', 'released', 'expired')),
  run_id         TEXT,                                  -- the holder
  acquired_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at     TIMESTAMPTZ,
  released_at    TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS idx_environment_leases_env
  ON environment_leases (environment_id, state, acquired_at DESC);
CREATE INDEX IF NOT EXISTS idx_environment_leases_run
  ON environment_leases (run_id, state);
-- ================================ end EXECUTION ENVIRONMENTS (BOSSAPP-824) ==

-- ===========================================================================
-- BOSSAPP-826
-- WORKSPACE SNAPSHOTS (BOSSAPP-826): a build's working tree survives an ephemeral
-- REMOTE sandbox. At each stage checkpoint the uncommitted tree (and, when no
-- lockfile keys a seed, the dependency dirs) is tarred through the 824 sandbox
-- sync_out seam into BOSS's object store (S3_*, services/object_store.py); a
-- repair round of the same root run restores the latest one (sync_in) before its
-- stage runs. kind='seed' rows hold dependency dirs only (node_modules, venv),
-- keyed by a hash of the repository's lockfiles (seed_key), so a FRESH run of the
-- same repo with the same lockfiles warm-starts its dependencies.
-- Off by default (BOSS_WORKSPACE_SNAPSHOTS=off|remote). Rows past expires_at are
-- reaped with their object by services/workspace_snapshots.reap_expired,
-- registered on resource_reaper.tick (the 824 lease-reaper pattern).
-- Objects live in the store; the row is the index (digest = sha256 of the object).
CREATE TABLE IF NOT EXISTS workspace_snapshots (
  id           TEXT PRIMARY KEY,
  run_id       TEXT NOT NULL,                 -- the run whose sandbox was captured
  root_run_id  TEXT,                          -- the lineage a repair restores from
  project_id   TEXT,
  repo         TEXT NOT NULL DEFAULT '',      -- owner/repo
  kind         TEXT NOT NULL DEFAULT 'full' CHECK (kind IN ('full', 'seed')),
  generation   INTEGER NOT NULL DEFAULT 0,    -- full: 1, 2, ... per root run; seed: 0
  label        TEXT,                          -- the checkpoint label (write_tests, implement…)
  seed_key     TEXT,                          -- seed: the lockfile hash; full: the seed it leans on
  object_key   TEXT NOT NULL,
  digest       TEXT NOT NULL,                 -- sha256 of the stored object
  bytes        BIGINT NOT NULL DEFAULT 0,
  manifest     JSONB NOT NULL DEFAULT '{}'::jsonb,
  expires_at   TIMESTAMPTZ,
  last_used_at TIMESTAMPTZ,
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_workspace_snapshots_generation
  ON workspace_snapshots (root_run_id, generation) WHERE kind = 'full';
CREATE UNIQUE INDEX IF NOT EXISTS uq_workspace_snapshots_seed
  ON workspace_snapshots (project_id, repo, seed_key) WHERE kind = 'seed';
CREATE INDEX IF NOT EXISTS idx_workspace_snapshots_root
  ON workspace_snapshots (root_run_id, kind, generation DESC);
CREATE INDEX IF NOT EXISTS idx_workspace_snapshots_expiry
  ON workspace_snapshots (expires_at);
-- ================================ end WORKSPACE SNAPSHOTS (BOSSAPP-826) ==

-- BOSSAPP-825
-- TOOLCHAIN IMAGES (BOSSAPP-825): a project's own build-sandbox image, built
-- interactively. An operator starts a throwaway setup container, installs what
-- the project needs (a JDK, Go, browsers, private tools) through the console's
-- terminal, and Capture commits it (`docker commit`, then a push to the local
-- registry when one is configured). With BOSS_SANDBOX_COMMAND_RUNTIME=docker a
-- build of that project then runs its commands in the latest READY image
-- instead of BOSS_SANDBOX_CONTAINER_IMAGE (services/toolchain_images.py). No
-- ready row: the default image, exactly as before.
CREATE TABLE IF NOT EXISTS toolchain_images (
  id            TEXT PRIMARY KEY,
  project_id    TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  -- the image the setup container started from
  base          TEXT NOT NULL,
  -- building: the setup session is open (phase 'session') or Capture is
  -- committing/pushing it (phase 'capturing') | ready: builds use it |
  -- failed: capture failed or the session was discarded (error says which)
  status        TEXT NOT NULL DEFAULT 'building'
    CHECK (status IN ('building', 'ready', 'failed')),
  phase         TEXT NOT NULL DEFAULT 'session',
  -- the setup container while the session is open; cleared once captured
  container_id  TEXT,
  -- what a build runs: '<registry>/boss-toolchain/<project>:<id>' or the
  -- daemon-local tag 'boss-toolchain/<project>:<id>' without a registry
  image_ref     TEXT,
  -- sha256 content digest: the registry's manifest digest after a push, else
  -- the local image id
  digest        TEXT,
  -- the setup transcript: every command the operator ran, with exit codes,
  -- and the Dockerfile that reproduces it (FROM base + RUN per command)
  transcript    JSONB NOT NULL DEFAULT '[]'::jsonb,
  dockerfile    TEXT,
  error         TEXT,
  created_by    TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_toolchain_images_project
  ON toolchain_images (project_id, status, created_at DESC);
-- One open setup session per project: a second Start is refused, not stacked.
CREATE UNIQUE INDEX IF NOT EXISTS uq_toolchain_images_open_session
  ON toolchain_images (project_id) WHERE status = 'building';
-- ================================ end TOOLCHAIN IMAGES (BOSSAPP-825) ==

-- BOSSAPP-828
-- boss-runner sessions: a coding-agent turn owned by the runner sidecar instead of the API
-- (apps/runner, services/runner_dispatch.py, services/runner_registry.py). `seq` is the API's
-- cumulative ACK of the runner's outbox, `last_heartbeat` is the runner's last push. The reclaim
-- path (run_liveness.progressing, jobs.reap_lost_leases) asks this registry before it declares a
-- run dead: a turn whose runner still reports its process alive is re-attached, not re-run.
CREATE TABLE IF NOT EXISTS runner_sessions (
    session_id      TEXT PRIMARY KEY,
    run_id          TEXT NOT NULL,                 -- the code-task run (crun_...)
    identity_run_id TEXT NOT NULL,                 -- the run token's boss_task.run
    runner_id       TEXT NOT NULL,
    session_key     TEXT NOT NULL DEFAULT '',
    seq             BIGINT NOT NULL DEFAULT 0,
    state           TEXT NOT NULL DEFAULT 'running',
    alive           BOOLEAN NOT NULL DEFAULT true,
    last_heartbeat  TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_runner_sessions_run ON runner_sessions (run_id, state, last_heartbeat DESC);

-- BOSSAPP-838 ── scheduled self-backups ─────────────────────────────────────────────────────────
-- services/backup_scheduler.py: one API thread (whichever holds backup_scheduler_lease) takes a
-- pg_dump every BOSS_BACKUP_INTERVAL_MINUTES, verifies it with `pg_restore --list`, optionally
-- uploads it (S3_* settings), and prunes by tier (hourly/daily/weekly/monthly). One row per
-- attempt: running -> verified or failed, then pruned once retention lets it go. The doctor
-- raises backup_stale / backup_failed / backup_missing from these rows.
CREATE TABLE IF NOT EXISTS backups (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL DEFAULT 'scheduled',
  path TEXT,
  object_key TEXT,
  bytes BIGINT,
  checksum TEXT,
  started_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at TIMESTAMPTZ,
  verified_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'running'
    CHECK (status IN ('running', 'verified', 'failed', 'pruned')),
  error TEXT
);
CREATE INDEX IF NOT EXISTS idx_backups_status_started ON backups (status, started_at DESC);
CREATE TABLE IF NOT EXISTS backup_scheduler_lease (
  name TEXT PRIMARY KEY,
  holder TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- BOSSAPP-837 ── org/project export and import ─────────────────────────────────────────────────
-- services/portability.py: an import is planned (a dry-run diff, validated by replaying it
-- through the create services and rolling back), then applied chunk by chunk, each chunk its own
-- transaction. chunks_done is the resume point: applying the same import again carries on from
-- there. The bundle is kept so a resume needs only the id, and it never holds a secret value.
CREATE TABLE IF NOT EXISTS portability_imports (
  id TEXT PRIMARY KEY,
  scope TEXT NOT NULL CHECK (scope IN ('project', 'org')),
  target_id TEXT NOT NULL,
  bundle_checksum TEXT NOT NULL,
  bundle JSONB NOT NULL,
  status TEXT NOT NULL DEFAULT 'planned'
    CHECK (status IN ('planned', 'applying', 'applied', 'failed')),
  chunk_size INTEGER NOT NULL DEFAULT 25,
  chunks_total INTEGER NOT NULL DEFAULT 0,
  chunks_done INTEGER NOT NULL DEFAULT 0,
  plan JSONB NOT NULL DEFAULT '{}'::jsonb,
  report JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_portability_imports_target
  ON portability_imports (scope, target_id, created_at DESC);


-- BOSSAPP-841-844
-- ── Skills as a governed supply chain ─────────────────────────────────────────────────────────
-- 842 VERSIONS. Every save of an authored skill appends a row here (skill_versions.record, called
-- from skill_definitions.save_skill — the one writer). History is append-only: a restore is a NEW
-- version copying an old one's content. `current_version_id` names the version the row holds;
-- `role_skills.pinned_version_id` keeps one agent on an older version (NULL = follow current).
CREATE TABLE IF NOT EXISTS skill_versions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  skill_id TEXT NOT NULL REFERENCES skill_definitions(id) ON DELETE CASCADE,
  skill_key TEXT NOT NULL,
  version_no INTEGER NOT NULL,
  -- label, summary, behaviour_kind, knowledge, inputs, produces, config, risk_tier
  content JSONB NOT NULL DEFAULT '{}'::jsonb,
  -- Supporting files a source brought with the skill (path -> text); {} for authored ones.
  files JSONB NOT NULL DEFAULT '{}'::jsonb,
  content_hash TEXT NOT NULL,
  author_kind TEXT NOT NULL DEFAULT 'person'
    CHECK (author_kind IN ('person', 'agent', 'system', 'sync')),
  author_id TEXT NOT NULL DEFAULT '',
  source_note TEXT NOT NULL DEFAULT '',
  restored_from TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (skill_id, version_no)
);
CREATE INDEX IF NOT EXISTS idx_skill_versions_skill
  ON skill_versions (project_id, skill_key, version_no DESC);
ALTER TABLE skill_definitions ADD COLUMN IF NOT EXISTS current_version_id TEXT;
ALTER TABLE role_skills ADD COLUMN IF NOT EXISTS pinned_version_id TEXT;

-- 843 DIFF-BOUND CONSENT. An agent's change to a skill (or a prompt) is written only when a
-- person approved EXACTLY that change: the write recomputes `diff_hash` from what it is about to
-- write and the content it would replace, and consumes one approved row with that hash. A
-- changed base, a changed proposal or a second write finds no row. Console edits are exempt.
CREATE TABLE IF NOT EXISTS change_consents (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('skill', 'prompt')),
  subject_key TEXT NOT NULL,
  diff_hash TEXT NOT NULL,
  base_hash TEXT NOT NULL DEFAULT '',
  diff TEXT NOT NULL DEFAULT '',
  proposed JSONB NOT NULL DEFAULT '{}'::jsonb,
  decision_id TEXT,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'approved', 'rejected', 'consumed')),
  requested_by TEXT NOT NULL DEFAULT '',
  decided_by TEXT,
  decided_at TIMESTAMPTZ,
  consumed_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_change_consents_subject
  ON change_consents (project_id, subject_kind, subject_key, status);
CREATE INDEX IF NOT EXISTS idx_change_consents_decision ON change_consents (decision_id);

-- 841 SOURCES. Where a skill came from outside the project: a GitHub path, a skills.sh entry
-- (resolved to its GitHub repository) or a plain URL. `pinned_sha` is the commit (GitHub) or the
-- sha256 of the body (URL) the skill holds. The sync worker never overwrites: an upstream change
-- becomes a new skill version, applied by itself only when `auto_update` and the skill is
-- trusted, otherwise parked as a change_consent awaiting a person.
CREATE TABLE IF NOT EXISTS skill_sources (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  org_id TEXT,
  scope TEXT NOT NULL DEFAULT 'project' CHECK (scope IN ('project', 'org')),
  kind TEXT NOT NULL CHECK (kind IN ('github', 'url', 'skillsh')),
  locator TEXT NOT NULL,
  ref TEXT NOT NULL DEFAULT '',
  skill_key TEXT NOT NULL,
  pinned_sha TEXT NOT NULL DEFAULT '',
  upstream_sha TEXT NOT NULL DEFAULT '',
  auto_update BOOLEAN NOT NULL DEFAULT false,
  last_sync_at TIMESTAMPTZ,
  last_error TEXT,
  pending_consent_id TEXT,
  created_by TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, skill_key)
);
CREATE INDEX IF NOT EXISTS idx_skill_sources_due ON skill_sources (last_sync_at NULLS FIRST);

-- 844 SAVED TEST CASES and VERSION-PINNED RUNS. A run is one case executed against one version
-- (through eval_harness.run_skill_cases, the same execution and eval_runs record as the suite);
-- `grade` is the typed answer pass|fail, NULL until graded.
CREATE TABLE IF NOT EXISTS skill_test_cases (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  skill_id TEXT NOT NULL REFERENCES skill_definitions(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  input JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_by TEXT NOT NULL DEFAULT '',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (skill_id, name)
);
CREATE TABLE IF NOT EXISTS skill_test_runs (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  case_id TEXT NOT NULL REFERENCES skill_test_cases(id) ON DELETE CASCADE,
  skill_version_id TEXT NOT NULL REFERENCES skill_versions(id) ON DELETE CASCADE,
  eval_run_id TEXT,
  status TEXT NOT NULL DEFAULT 'ran' CHECK (status IN ('ran', 'error', 'skipped')),
  output JSONB NOT NULL DEFAULT '{}'::jsonb,
  grade TEXT CHECK (grade IS NULL OR grade IN ('pass', 'fail')),
  notes TEXT NOT NULL DEFAULT '',
  graded_by TEXT,
  graded_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_skill_test_runs_case
  ON skill_test_runs (case_id, skill_version_id, created_at DESC);


-- ── BOSSAPP-829-832: one work-item graph with execution policy ───────────────────────────────
-- BOSSAPP-830. work_items is THE canonical node for every piece of work: a workflow run, a code
-- task, a PRD meeting and a planning ticket each carry the work_item_id of the node they
-- serve, and the node is made lazily where the run/ticket is made (services/work_items.py
-- ensure_for) — history is not backfilled by migration. The node gains a tree (parent_id), a
-- goal, a human key ("BOSS-12"), who works it (assignee: agent:<role> | person:<id>) and who
-- answers for it (responsible_person). `status` already exists (portfolio 'active'/'done'); the
-- canonical vocabulary adds backlog | todo | blocked | in_review | cancelled beside them.
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS parent_id TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS goal_id TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS human_key TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS assignee TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS responsible_person TEXT;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'active';
-- BOSSAPP-831: the item's execution policy (ordered review/approval stages) and where it is in
-- them ({stage, round, decision_id, origin, worker}); NULL = no stages, done is done.
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS execution_policy JSONB;
ALTER TABLE work_items ADD COLUMN IF NOT EXISTS execution_state JSONB;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_parent_fk'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_parent_fk FOREIGN KEY (parent_id)
      REFERENCES work_items(id) ON DELETE SET NULL;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_not_own_parent'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_not_own_parent
      CHECK (parent_id IS NULL OR parent_id <> id);
  END IF;
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS uq_work_items_human_key
  ON work_items (project_id, human_key) WHERE human_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_work_items_parent ON work_items (parent_id) WHERE parent_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_work_items_goal ON work_items (goal_id) WHERE goal_id IS NOT NULL;
-- The next number of a project's human keys (one row per project; prefix is the project's).
CREATE TABLE IF NOT EXISTS work_item_keys (
  project_id TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,
  prefix TEXT NOT NULL DEFAULT 'WI',
  next_number INTEGER NOT NULL DEFAULT 1 CHECK (next_number >= 1)
);
-- Goals form their own tree; a work item points at the goal it serves.
CREATE TABLE IF NOT EXISTS goals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  parent_id TEXT REFERENCES goals(id) ON DELETE SET NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'achieved', 'dropped')),
  owner TEXT,
  target_date DATE,
  created_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (parent_id IS NULL OR parent_id <> id)
);
CREATE INDEX IF NOT EXISTS idx_goals_project ON goals (project_id, status, created_at);
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'work_items_goal_fk'
                 AND conrelid = 'work_items'::regclass) THEN
    ALTER TABLE work_items ADD CONSTRAINT work_items_goal_fk FOREIGN KEY (goal_id)
      REFERENCES goals(id) ON DELETE SET NULL;
  END IF;
END $$;
-- Relations between items. Only 'blocks' is stored for blocking (from blocks to); "blocked_by"
-- is the same row read the other way, so the two can never disagree.
CREATE TABLE IF NOT EXISTS work_item_relations (
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  from_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  to_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('blocks', 'relates_to', 'duplicates')),
  created_by TEXT NOT NULL DEFAULT 'system',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (from_id, to_id, kind),
  CHECK (from_id <> to_id)
);
CREATE INDEX IF NOT EXISTS idx_work_item_relations_to ON work_item_relations (to_id, kind);
CREATE TABLE IF NOT EXISTS labels (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT NOT NULL DEFAULT 'gray',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);
CREATE TABLE IF NOT EXISTS work_item_labels (
  work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  label_id TEXT NOT NULL REFERENCES labels(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (work_item_id, label_id)
);
CREATE INDEX IF NOT EXISTS idx_work_item_labels_label ON work_item_labels (label_id);
-- Every run, PRD meeting and planning ticket names the node it serves (made lazily at creation).
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS work_item_id TEXT;
ALTER TABLE code_task_runs ADD COLUMN IF NOT EXISTS work_item_id TEXT;
ALTER TABLE meeting_runs ADD COLUMN IF NOT EXISTS work_item_id TEXT;
CREATE INDEX IF NOT EXISTS idx_workflow_runs_work_item ON workflow_runs (work_item_id) WHERE work_item_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_code_task_runs_work_item ON code_task_runs (work_item_id) WHERE work_item_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_meeting_runs_work_item ON meeting_runs (work_item_id) WHERE work_item_id IS NOT NULL;
-- The planning store (services/work_plane.py) creates wp_roadmap_items lazily; its column is
-- added there too, and here when the table already exists.
DO $$ BEGIN
  IF to_regclass('public.wp_roadmap_items') IS NOT NULL THEN
    ALTER TABLE wp_roadmap_items ADD COLUMN IF NOT EXISTS work_item_id TEXT;
  END IF;
END $$;
-- BOSSAPP-831: a run may carry its own policy (it wins over its work item's).
ALTER TABLE workflow_runs ADD COLUMN IF NOT EXISTS execution_policy JSONB;
ALTER TABLE code_task_runs ADD COLUMN IF NOT EXISTS execution_policy JSONB;
-- The stage machine's log: every stage raised, answered, sent back or escalated.
CREATE TABLE IF NOT EXISTS execution_decisions (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  work_item_id TEXT NOT NULL REFERENCES work_items(id) ON DELETE CASCADE,
  origin TEXT,                                 -- workflow_run:<id> | code_task:<id> | ...
  stage_index INTEGER NOT NULL,
  stage_kind TEXT NOT NULL CHECK (stage_kind IN ('review', 'approval')),
  round INTEGER NOT NULL DEFAULT 1,
  event TEXT NOT NULL CHECK (event IN ('raised', 'approved', 'rejected', 'escalated',
                                       'completed', 'skipped')),
  decision_id TEXT,
  participants JSONB NOT NULL DEFAULT '[]'::jsonb,
  actor TEXT NOT NULL DEFAULT 'boss',
  comment TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS idx_execution_decisions_item
  ON execution_decisions (work_item_id, created_at);
-- BOSSAPP-832: a decision can ask a typed form and keep the typed answer it got.
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS form_schema JSONB;
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS answer JSONB;
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS answered_by TEXT;
ALTER TABLE decisions ADD COLUMN IF NOT EXISTS answered_at TIMESTAMPTZ;


-- ── BOSSAPP-833-835: decide from Slack and phone; realtime event push ─────────────────────────
-- services/chat_channels.py (834) and services/event_stream.py (835).
--
-- A CHAT ENDPOINT is one two-way channel BOSS posts decisions to and hears answers from: a Slack
-- app, a Telegram bot (Discord is a stub). Its credentials (Slack's signing secret and bot token,
-- Telegram's bot token and webhook secret) live in the secret store; `secret_refs` holds only
-- {"<name>": "<secret_refs.id>"}, never a value.
CREATE TABLE IF NOT EXISTS chat_endpoints (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  kind TEXT NOT NULL CHECK (kind IN ('slack', 'telegram', 'discord')),
  name TEXT NOT NULL,
  config JSONB NOT NULL DEFAULT '{}'::jsonb,      -- channel / chat id, team id, max_tier
  secret_refs JSONB NOT NULL DEFAULT '{}'::jsonb, -- {"signing_secret": "sref_..", ...}
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_chat_endpoints_project ON chat_endpoints (project_id, status);

-- WHO a chat user is in BOSS. A row is born unverified by a press from an unlinked user (with the
-- hash of a one-time link code DMed to them); it becomes a link only when that person signs in
-- to the console and confirms (`verified_at`, `principal_id`, `person_actor`). Revoked links
-- stay as history. One live row per (endpoint, external user).
CREATE TABLE IF NOT EXISTS chat_identity_links (
  id TEXT PRIMARY KEY,
  endpoint_id TEXT NOT NULL REFERENCES chat_endpoints(id) ON DELETE CASCADE,
  external_user_id TEXT NOT NULL,
  external_name TEXT,
  principal_id TEXT,                 -- identity_principals.id of the person, once confirmed
  person_actor TEXT,                 -- the actor decisions record for them (legacy member id)
  link_code_hash TEXT,               -- sha256 of the one-time code; NULL once spent
  code_expires_at TIMESTAMPTZ,
  verified_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_chat_identity_links_live
  ON chat_identity_links (endpoint_id, external_user_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uq_chat_identity_links_code
  ON chat_identity_links (link_code_hash) WHERE link_code_hash IS NOT NULL;

-- A chat thread bound to BOSS work: the message a decision card was posted as (Slack channel +
-- ts, Telegram chat + message id), so an answer, an update or a reply lands on the right work.
CREATE TABLE IF NOT EXISTS chat_threads (
  id TEXT PRIMARY KEY,
  endpoint_id TEXT NOT NULL REFERENCES chat_endpoints(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  external_channel_id TEXT NOT NULL,
  external_thread_id TEXT NOT NULL,
  decision_id TEXT,
  run_id TEXT,
  work_item_id TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_chat_threads_external
  ON chat_threads (endpoint_id, external_channel_id, external_thread_id);
CREATE INDEX IF NOT EXISTS idx_chat_threads_decision ON chat_threads (decision_id);

-- ONE BUTTON, ONE USE. Each Approve/Reject button carries `<id>.<hmac>`; the row is spent by a
-- compare-and-swap (pending -> used), so a replayed or double press refuses.
CREATE TABLE IF NOT EXISTS chat_actions (
  id TEXT PRIMARY KEY,
  endpoint_id TEXT NOT NULL REFERENCES chat_endpoints(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  decision_id TEXT NOT NULL,
  action TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'used', 'expired')),
  expires_at TIMESTAMPTZ NOT NULL,
  used_at TIMESTAMPTZ,
  used_by_external TEXT,
  used_by_principal TEXT,
  outcome JSONB,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_chat_actions_decision ON chat_actions (decision_id, status);

-- THE CHAT OUTBOX (services/notify.py enqueue_chat / deliver_chat_due): every message to a chat
-- endpoint is a row before it is sent; retried with backoff, dead after MAX_CHAT_ATTEMPTS.
CREATE TABLE IF NOT EXISTS chat_outbox (
  id TEXT PRIMARY KEY,
  endpoint_id TEXT NOT NULL REFERENCES chat_endpoints(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  kind TEXT NOT NULL,                -- decision_card | message | response
  dedupe_key TEXT NOT NULL,
  payload JSONB NOT NULL DEFAULT '{}'::jsonb,
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending', 'failed', 'sent', 'dead')),
  attempts INTEGER NOT NULL DEFAULT 0,
  next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_error TEXT,
  receipt JSONB,
  sent_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_chat_outbox_dedupe ON chat_outbox (dedupe_key);
CREATE INDEX IF NOT EXISTS idx_chat_outbox_due ON chat_outbox (status, next_attempt_at);

-- REALTIME PUSH (835). Every committed event row is announced on the `boss_events` channel. A
-- trigger, not a call in emit_event: a few writers insert events directly (identity/audit.py,
-- ambient/roadmap_demo.py), and a NOTIFY at the one code seam would miss them. NOTIFY is delivered
-- at COMMIT, so a rolled-back event is never announced. The payload is the row's identity only
-- (8000-byte cap); the stream reads the row and authorizes it per viewer before sending a byte.
CREATE OR REPLACE FUNCTION boss_events_notify() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_notify('boss_events', json_build_object(
    'id', NEW.id, 'project_id', NEW.project_id, 'event_type', NEW.event_type,
    'entity_type', NEW.entity_type, 'entity_id', NEW.entity_id)::text);
  RETURN NULL;
END $$;
DO $$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname = 'events_notify_boss_events'
                 AND tgrelid = 'events'::regclass) THEN
    CREATE TRIGGER events_notify_boss_events AFTER INSERT ON events
      FOR EACH ROW EXECUTE FUNCTION boss_events_notify();
  END IF;
END $$;
-- Last-Event-ID replay reads "the events after this one" in (created_at, id) order.
CREATE INDEX IF NOT EXISTS idx_events_created_id ON events (created_at, id);

-- ── BOSSAPP-885: AN ORG CHART THAT CARRIES AUTHORITY (services/org_chain.py) ──────────────────
-- org_assignments.reports_to was display-only. A stall that would interrupt a person is first
-- offered to the responsible agent's manager (an agent) — one row here, one rung at a time, each
-- with a deadline; a pass or a deadline moves it up the chain, and a chain with no agent left
-- falls through to the exact person path the caller would have taken (`fallback`), so work is
-- never stranded. One row per run ever: a run the chain already had its chance on goes to the
-- person. A takeover writes `authority_path` (who acted, under whose chain) here and on the run.
-- No reports_to rows → no row here: the default path is unchanged.
CREATE TABLE IF NOT EXISTS org_chain_escalations (
  id TEXT PRIMARY KEY,                                  -- 'orgesc_…'
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  origin TEXT NOT NULL CHECK (origin IN ('person_wait', 'stuck_work')),
  run_kind TEXT NOT NULL DEFAULT 'code_task',
  run_id TEXT NOT NULL,
  work_item_id TEXT,
  subject TEXT NOT NULL,                                -- agent:<role> whose work stalled
  chain JSONB NOT NULL DEFAULT '[]'::jsonb,             -- the chain of command when it stalled
  rung INTEGER NOT NULL DEFAULT 1,
  offered_to TEXT NOT NULL,                             -- agent:<role> holding the offer now
  reason TEXT NOT NULL DEFAULT '',
  question TEXT NOT NULL DEFAULT '',
  status TEXT NOT NULL DEFAULT 'open'
    CHECK (status IN ('open', 'taken', 'fell_through', 'superseded')),
  deadline TIMESTAMPTZ NOT NULL,
  asked_at TIMESTAMPTZ,                                 -- the offered manager's turn ran
  fallback JSONB NOT NULL DEFAULT '{}'::jsonb,          -- what the person path needs
  taken_by TEXT,
  authority_path JSONB,
  outcome TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  resolved_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_org_chain_escalations_run ON org_chain_escalations (run_id);
CREATE INDEX IF NOT EXISTS idx_org_chain_escalations_open
  ON org_chain_escalations (project_id, status, deadline);
-- BOSSAPP-861 ── general-purpose extensions (boss.extension/v1) ─────────────────────────────────
-- engine/boss_engine/extensions/: one row per installed extension (the APPROVED whole-tree
-- checksum is the trust gate's reference; nonce derives the MCP bearer and webhook secrets, so a
-- reinstall rotates them), its per-project enablement (and the MCP server row its tools ride),
-- its namespaced key-value state (size-capped), its event-feed ack cursor, and the job leases
-- that let exactly one API process fire a scheduled callback (backup_scheduler's lease pattern).
CREATE TABLE IF NOT EXISTS extension_installs (
  extension_id TEXT PRIMARY KEY,
  version TEXT NOT NULL,
  name TEXT NOT NULL,
  directory TEXT NOT NULL,
  approved_checksum TEXT NOT NULL,
  bundle_checksum TEXT NOT NULL,
  manifest JSONB NOT NULL DEFAULT '{}'::jsonb,
  nonce TEXT NOT NULL,
  installed_by TEXT,
  installed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS extension_projects (
  extension_id TEXT NOT NULL REFERENCES extension_installs(extension_id) ON DELETE CASCADE,
  project_id TEXT NOT NULL,
  enabled BOOLEAN NOT NULL DEFAULT false,
  mcp_server_id TEXT,
  updated_by TEXT,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (extension_id, project_id)
);
CREATE TABLE IF NOT EXISTS extension_state (
  extension_id TEXT NOT NULL,
  project_id TEXT NOT NULL DEFAULT '',
  key TEXT NOT NULL,
  value JSONB NOT NULL,
  bytes INTEGER NOT NULL CHECK (bytes >= 0 AND bytes <= 65536),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (extension_id, project_id, key)
);
CREATE TABLE IF NOT EXISTS extension_event_cursors (
  extension_id TEXT NOT NULL,
  project_id TEXT NOT NULL,
  last_created_at TIMESTAMPTZ,
  last_event_id TEXT,
  delivered BIGINT NOT NULL DEFAULT 0,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (extension_id, project_id)
);
CREATE TABLE IF NOT EXISTS extension_job_leases (
  extension_id TEXT NOT NULL,
  job TEXT NOT NULL,
  holder TEXT NOT NULL DEFAULT '',
  expires_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  next_run_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_run_at TIMESTAMPTZ,
  last_status TEXT,
  last_error TEXT,
  runs BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY (extension_id, job)
);
-- BOSSAPP-849-851
-- ── Connector catalog, stdio MCP servers and curated gateways ────────────────────────────────────
-- 850 STDIO TEMPLATES. How BOSS launches a stdio MCP server: the argv, the image it runs in, the
-- environment names it may receive (never secret values: a server's token is resolved by the
-- registry at call time and handed to the container as the env var named in `env_from_auth`), the
-- network it may use ('host' is refused), how long an idle instance lives and how instances are
-- shared. A server row points at one as `stdio://<project_id>/<name>`; the supervisor
-- (services/mcp_stdio_supervisor.py) spawns it in a sandboxed container and bridges it to the
-- streamable-HTTP surface mcp_client already speaks. Writing a template is `host:exec`.
CREATE TABLE IF NOT EXISTS mcp_stdio_templates (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9_-]{0,62}$'),
  description TEXT,
  argv JSONB NOT NULL,
  image TEXT NOT NULL,
  env_allowlist JSONB NOT NULL DEFAULT '[]'::jsonb,
  env_defaults JSONB NOT NULL DEFAULT '{}'::jsonb,
  env_from_auth TEXT,
  network TEXT NOT NULL DEFAULT 'none' CHECK (network <> 'host'),
  idle_ttl_seconds INTEGER NOT NULL DEFAULT 600 CHECK (idle_ttl_seconds BETWEEN 30 AND 86400),
  reuse_key TEXT NOT NULL DEFAULT 'credential' CHECK (reuse_key IN ('credential', 'template')),
  connector_key TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'disabled')),
  created_by TEXT NOT NULL,
  updated_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (project_id, name)
);

-- 851 GATEWAYS. A curated slice of a project's MCP servers served to OUTSIDE MCP clients (Claude
-- Code, Cursor) at /mcp/gw/{id}. `profile` = {"servers": [{"server_id", "tools": [..] | null,
-- "caps": {tool: "allow" | "off"}}]}; a cap may only make a tool stricter than the registry's own
-- policy. Every call is proxied through mcp_registry.call_tool_with_receipt, so review, policy,
-- receipts and the tool_call_audit row are exactly what an inside call gets.
CREATE TABLE IF NOT EXISTS mcp_gateways (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  profile JSONB NOT NULL DEFAULT '{"servers": []}'::jsonb,
  allowed_actions JSONB NOT NULL
    DEFAULT '["tools/list", "tools/call", "search_tools", "run_tool"]'::jsonb,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  revoked_by TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_mcp_gateways_active_name
  ON mcp_gateways (project_id, lower(name)) WHERE status = 'active';

-- A gateway's tokens: only the SHA-256 of each is kept (the token is shown once, at mint), with
-- its last four for telling two apart, an expiry, and a revocation.
CREATE TABLE IF NOT EXISTS mcp_gateway_tokens (
  id TEXT PRIMARY KEY,
  gateway_id TEXT NOT NULL REFERENCES mcp_gateways(id) ON DELETE CASCADE,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,
  last4 TEXT NOT NULL,
  label TEXT,
  expires_at TIMESTAMPTZ,
  revoked_at TIMESTAMPTZ,
  revoked_by TEXT,
  last_used_at TIMESTAMPTZ,
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mcp_gateway_tokens_gateway
  ON mcp_gateway_tokens (gateway_id, created_at DESC);
-- ================================ end CONNECTORS / STDIO / GATEWAYS (BOSSAPP-849-851) ==
-- BOSSAPP-816-819
-- THE TOOL-CALL AUDIT SURFACE (BOSSAPP-819): GET /v1/tool-calls + /export and Activity › Tool
-- calls read tool_call_audit. `explanation` is the policy's own words for the decision, filled
-- by a writer that has them (NULL otherwise, and on every older row). The index is the one the
-- audit's keyset pages read (project, newest first).
ALTER TABLE tool_call_audit ADD COLUMN IF NOT EXISTS explanation TEXT;
CREATE INDEX IF NOT EXISTS idx_tool_call_audit_project_time
  ON tool_call_audit (project_id, recorded_at DESC, id DESC);
-- ================================ end BOSSAPP-816-819 ==
-- ============================ TOOL POLICIES v2 (BOSSAPP-815/817) ============================
-- The ordered tool-policy engine (engine/boss_engine/services/tool_policy_engine.py): rules as
-- data, read by decide() at the MCP gateway, the receipt door and the kernel's tool set. A rule
-- with source='decision' is an "Always allow" a person chose on an approval (BOSSAPP-817).
-- BOSSAPP-815-817
CREATE TABLE IF NOT EXISTS tool_policies_v2 (
  id TEXT PRIMARY KEY,
  org_id TEXT,
  project_id TEXT,
  scope TEXT NOT NULL,
  priority INTEGER NOT NULL DEFAULT 100,
  effect TEXT NOT NULL,
  selector JSONB NOT NULL DEFAULT '{}'::jsonb,
  conditions JSONB NOT NULL DEFAULT '[]'::jsonb,
  rate_limit JSONB,
  source TEXT NOT NULL DEFAULT 'operator',
  source_decision_id TEXT,
  schema_sha256 TEXT,
  note TEXT,
  expires_at TIMESTAMPTZ,
  hit_count BIGINT NOT NULL DEFAULT 0,
  last_hit_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'active',
  created_by TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at TIMESTAMPTZ,
  revoked_by TEXT,
  revoked_reason TEXT,
  CONSTRAINT tool_policies_v2_effect CHECK (effect IN ('allow', 'ask', 'deny', 'rate_limit')),
  CONSTRAINT tool_policies_v2_source CHECK (source IN ('operator', 'decision')),
  CONSTRAINT tool_policies_v2_status CHECK (status IN ('active', 'disabled', 'revoked')),
  CONSTRAINT tool_policies_v2_scope CHECK (
    scope IN ('org', 'project') OR scope LIKE 'agent:_%' OR scope LIKE 'workflow:_%'),
  CONSTRAINT tool_policies_v2_owner CHECK (scope = 'org' OR project_id IS NOT NULL)
);
CREATE INDEX IF NOT EXISTS idx_tool_policies_v2_project
  ON tool_policies_v2 (project_id, status, priority);
CREATE INDEX IF NOT EXISTS idx_tool_policies_v2_org
  ON tool_policies_v2 (org_id, status) WHERE project_id IS NULL;
CREATE INDEX IF NOT EXISTS idx_tool_policies_v2_decision
  ON tool_policies_v2 (source_decision_id) WHERE source_decision_id IS NOT NULL;
-- ============================ end TOOL POLICIES v2 (BOSSAPP-815/817) ========================
-- BOSSAPP-846-848
-- ── Connect the MCP ecosystem, part 1: OAuth for remote servers, whose credential a call uses,
-- and agent-initiated access requests ─────────────────────────────────────────────────────────
-- 846 (services/mcp_oauth.py). An MCP server whose auth is {type: "oauth"} signs in through the
-- MCP authorization spec: RFC 9728 protected-resource metadata, RFC 8414 authorization-server
-- metadata, dynamic client registration (or a client typed in the console) and a PKCE S256 code
-- flow. The tokens are identity vault items (identity_vault_items, provider 'mcp:<server id>'),
-- never in mcp_servers.auth. auth_status is what the console shows: connected | needs_reauth |
-- not_connected (NULL for a server that does not sign in with OAuth).
ALTER TABLE mcp_servers ADD COLUMN IF NOT EXISTS auth_status TEXT;
-- 847 (services/connection_credentials.py): whose credential a call carries. shared = the
-- server's one sign-in; per_user = the acting person's own; per_user_fallback = theirs when they
-- have one (and an agent acting for them may use it), else the shared one; per_agent = the
-- calling agent's own.
ALTER TABLE mcp_servers ADD COLUMN IF NOT EXISTS credential_policy TEXT NOT NULL DEFAULT 'shared';
DO $mcp_cred_policy$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'mcp_servers_credential_policy_check') THEN
    ALTER TABLE mcp_servers ADD CONSTRAINT mcp_servers_credential_policy_check
      CHECK (credential_policy IN ('shared', 'per_user', 'per_user_fallback', 'per_agent'));
  END IF;
END $mcp_cred_policy$;
-- One sign-in in flight: the browser goes to the provider with `state`; BOSS keeps the HASH of the
-- state and the PKCE verifier here, single use, for ten minutes. The callback spends the row.
CREATE TABLE IF NOT EXISTS mcp_oauth_pending (
  state_hash TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  server_id TEXT REFERENCES mcp_servers(id) ON DELETE CASCADE,
  connection_id TEXT,
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('org', 'user', 'agent')),
  subject_id TEXT NOT NULL,
  code_verifier TEXT NOT NULL,
  redirect_uri TEXT NOT NULL,
  created_by TEXT NOT NULL,
  -- The verified principal who pressed Sign in. The callback must come back signed in as the same
  -- one, so a consent link handed to somebody else cannot sign THEIR account in under this state.
  started_by_principal TEXT,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_mcp_oauth_pending_expiry ON mcp_oauth_pending (expires_at);
-- 847: one credential per (server or Kit connection, subject). The secret is a vault item
-- (vault_item_id); this row says whose it is and whether it still works. A replaced credential's
-- row is updated in place and its old vault item revoked (crypto-shredded).
CREATE TABLE IF NOT EXISTS connection_credentials (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  server_id TEXT REFERENCES mcp_servers(id) ON DELETE CASCADE,
  connection_id TEXT,                 -- a Kit connection ('kit:<ability>') when server_id is NULL
  subject_kind TEXT NOT NULL CHECK (subject_kind IN ('org', 'user', 'agent')),
  subject_id TEXT NOT NULL,           -- org id | usr_ principal id | agent role key
  vault_item_id TEXT NOT NULL,
  kind TEXT NOT NULL DEFAULT 'oauth' CHECK (kind IN ('oauth', 'token')),
  connected_as TEXT,                  -- who the provider says signed in, for the console
  scopes TEXT[],
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'needs_reauth', 'revoked')),
  created_by TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (server_id IS NOT NULL OR connection_id IS NOT NULL)
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_connection_credentials_subject
  ON connection_credentials (project_id, (COALESCE(server_id, connection_id)), subject_kind, subject_id);
CREATE INDEX IF NOT EXISTS idx_connection_credentials_server
  ON connection_credentials (server_id, status);
-- 848 (services/tool_access_requests.py): tools an agent asked for and a person granted (a
-- decision with recommendation.action 'grant_tool_access'). One row per tool per agent, pinned to
-- the schema hash the person saw; a schema that changed since DROPS the grant (status 'dropped'),
-- as BOSSAPP-818 quarantines a changed tool. `previously_held` keeps a tool the agent held before
-- the grant when the grant ends. The role_mcp_servers row is the holder grant itself.
CREATE TABLE IF NOT EXISTS mcp_access_grants (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  server_id TEXT NOT NULL REFERENCES mcp_servers(id) ON DELETE CASCADE,
  role_key TEXT NOT NULL,
  tool TEXT NOT NULL,
  tier INTEGER NOT NULL,
  policy TEXT NOT NULL CHECK (policy IN ('allow', 'ask')),
  schema_sha256 TEXT NOT NULL,
  previously_held BOOLEAN NOT NULL DEFAULT false,
  decision_id TEXT,
  reason TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'revoked', 'dropped', 'refused')),
  granted_by TEXT NOT NULL,
  ended_by TEXT,
  ended_reason TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  ended_at TIMESTAMPTZ
);
CREATE UNIQUE INDEX IF NOT EXISTS uq_mcp_access_grants_live
  ON mcp_access_grants (project_id, server_id, role_key, tool) WHERE status = 'active';
CREATE INDEX IF NOT EXISTS idx_mcp_access_grants_role ON mcp_access_grants (project_id, role_key, status);
-- ================================ end BOSSAPP-846-848 ==
